public void render(GumWormSegmentEntity entity, float entityYaw, float partialTicks, PoseStack poseStack, MultiBufferSource bufferIn, int packedLightIn) {
        Entity frontAttachedEntity = entity.getFrontEntity();
        Entity backAttachedEntity = entity.getBackEntity();
        float yRotLerp = Mth.lerp(partialTicks, entity.yRotO, entity.getYRot());
        float xRotLerp = Mth.lerp(partialTicks, entity.xRotO, entity.getXRot());
        poseStack.pushPose();
        poseStack.translate(0.0D, (double) 1F, 0.0D);
        poseStack.mulPose(Axis.YN.rotationDegrees(yRotLerp));
        poseStack.mulPose(Axis.XP.rotationDegrees(xRotLerp + 180));
        poseStack.translate(0.0D, (double) -0.5F, 0.0D);
        MODEL.setGumVisible(frontAttachedEntity != null, backAttachedEntity != null);
        MODEL.setupAnim(entity, 0.0F, 0.0F, entity.tickCount + partialTicks, 0.0F, 0.0F);
        VertexConsumer ivertexbuilder = bufferIn.getBuffer(RenderType.entityCutoutNoCull(getTextureLocation(entity)));
        MODEL.renderToBuffer(poseStack, ivertexbuilder, packedLightIn, getOverlayCoords(entity, 0.0F), 1.0F, 1.0F, 1.0F, 1.0F);
        super.render(entity, entityYaw, partialTicks, poseStack, bufferIn, packedLightIn);
        poseStack.popPose();
        if(frontAttachedEntity != null){
            Vec3 centeredHeight = new Vec3(0, entity.getBbHeight() * 0.5F, 0);
            Vec3 from = new Vec3(0F, 0, -0.9F).xRot((float) Math.toRadians(180 - xRotLerp)).yRot(-(float) Math.toRadians(yRotLerp)).add(centeredHeight);
            Vec3 attachment = frontAttachedEntity.getPosition(partialTicks).add(0F, entity.getBbHeight() * 0.5F, 0);
            float zBack = 0;
            float yUp = 0;
            float theirYRotLerp = Mth.lerp(partialTicks, frontAttachedEntity.yRotO, frontAttachedEntity.getYRot());
            float theirXRotLerp = frontAttachedEntity.getViewXRot(partialTicks);
            if(frontAttachedEntity instanceof GumWormSegmentEntity){
                zBack = -0.9F;
            }else if(frontAttachedEntity instanceof GumWormEntity){
                zBack = -1.7F;
            }
            Vec3 to = attachment.add(new Vec3(0F, yUp, zBack).xRot(-(float) Math.toRadians(theirXRotLerp)).yRot(-(float) Math.toRadians(theirYRotLerp))).subtract(entity.getPosition(partialTicks));
            VertexConsumer gumConsumer = bufferIn.getBuffer(RenderType.entityCutoutNoCull(TEXTURE_CONNECTOR));
            poseStack.pushPose();
            poseStack.translate(from.x, from.y, from.z);
            renderGum(to.subtract(from), poseStack, gumConsumer, packedLightIn, getOverlayCoords(entity, 0.0F));
            poseStack.popPose();
        }
    }

public static void renderGum(Vec3 to, PoseStack poseStack, VertexConsumer gumConsumer, int packedLightIn, int overlayCoords) {
        double d = to.horizontalDistance();
        float rotY = (float) (Mth.atan2(to.x, to.z) * (double) (180F / (float) Math.PI));
        float rotX = (float) (-(Mth.atan2(to.y, d) * (double) (180F / (float) Math.PI))) - 90.0F;
        float length = (float) to.length();
        poseStack.pushPose();
        poseStack.mulPose(Axis.YP.rotationDegrees(rotY));
        poseStack.mulPose(Axis.XP.rotationDegrees(rotX));
        poseStack.translate(0, -length, 0);
        PoseStack.Pose posestack$pose = poseStack.last();
        Matrix4f matrix4f = posestack$pose.pose();
        Matrix3f matrix3f = posestack$pose.normal();
        gumConsumer.vertex(matrix4f, 0, 0, -0.5F).color(255, 255, 255, 255).uv((float) 0, (float) 0).overlayCoords(overlayCoords).uv2(packedLightIn).normal(matrix3f, 0.0F, -1.0F, 0.0F).endVertex();
        gumConsumer.vertex(matrix4f, 0, 0, 0.5F).color(255, 255, 255, 255).uv((float) 1, (float) 0).overlayCoords(overlayCoords).uv2(packedLightIn).normal(matrix3f, 0.0F, -1.0F, 0.0F).endVertex();
        gumConsumer.vertex(matrix4f, 0, length, 0.5F).color(255, 255, 255, 255).uv((float) 1, (float)1).overlayCoords(overlayCoords).uv2(packedLightIn).normal(matrix3f, 0.0F, -1.0F, 0.0F).endVertex();
        gumConsumer.vertex(matrix4f, 0, length, -0.5F).color(255, 255, 255, 255).uv((float) 0, (float)1).overlayCoords(overlayCoords).uv2(packedLightIn).normal(matrix3f, 0.0F, -1.0F, 0.0F).endVertex();
        poseStack.popPose();
    }

public void render(GumballEntity entity, float entityYaw, float partialTicks, PoseStack poseStack, MultiBufferSource multiBufferSource, int packedLight) {
        poseStack.pushPose();
        float explodeAmount = entity.getExplodeProgress(partialTicks);
        float scale = entity.isExplosive() ? 0.5F + explodeAmount * 0.2F : 0.25F;
        poseStack.scale(scale, scale, scale);
        poseStack.mulPose(this.entityRenderDispatcher.cameraOrientation());
        poseStack.mulPose(Axis.YP.rotationDegrees(180.0F));
        PoseStack.Pose posestack$pose = poseStack.last();
        Matrix4f matrix4f = posestack$pose.pose();
        Matrix3f matrix3f = posestack$pose.normal();
        VertexConsumer vertexconsumer = multiBufferSource.getBuffer(RenderType.entityCutout(getTextureLocation(entity)));
        vertex(vertexconsumer, matrix4f, matrix3f, packedLight, 0.0F, 0, 0, 1, 1F);
        vertex(vertexconsumer, matrix4f, matrix3f, packedLight, 1.0F, 0, 1, 1, 1F);
        vertex(vertexconsumer, matrix4f, matrix3f, packedLight, 1.0F, 1, 1, 0, 1F);
        vertex(vertexconsumer, matrix4f, matrix3f, packedLight, 0.0F, 1, 0, 0, 1F);
        if(entity.isExplosive()){
            float explodeColorChange = entity.getBounces() >= entity.getMaximumBounces() ? 1.0F - 0.5F * (1F + Mth.sin((entity.tickCount + partialTicks) * 0.9F)) : 0.0F;
            VertexConsumer vertexconsumer2 = multiBufferSource.getBuffer(RenderType.entityTranslucentEmissive(TEXTURE_EXPLODING));
            vertex(vertexconsumer2, matrix4f, matrix3f, packedLight, 0.0F, 0, 0, 1, explodeColorChange);
            vertex(vertexconsumer2, matrix4f, matrix3f, packedLight, 1.0F, 0, 1, 1, explodeColorChange);
            vertex(vertexconsumer2, matrix4f, matrix3f, packedLight, 1.0F, 1, 1, 0, explodeColorChange);
            vertex(vertexconsumer2, matrix4f, matrix3f, packedLight, 0.0F, 1, 0, 0, explodeColorChange);
        }
        poseStack.popPose();
        super.render(entity, entityYaw, partialTicks, poseStack, multiBufferSource, packedLight);
    }

public static void renderEntireBatch(LevelRenderer levelRenderer, PoseStack posestack, int renderTick, Camera camera, float partialTick) {
        for (LicowitchEntity licowitch : allTeleportingLicowitchOnScreen) {
            Vec3 to = licowitch.getTeleportingToPos();
            float progress = licowitch.getTeleportingProgress(partialTick);
            if (to != null && progress > 0) {
                Vec3 cameraPos = camera.getPosition();
                float scale = 0.9375F;
                float bodyYaw = licowitch.yBodyRotO + (licowitch.yBodyRot - licowitch.yBodyRotO) * partialTick;
                float headYaw = Mth.rotLerp(partialTick, licowitch.yHeadRotO, licowitch.yHeadRot);
                float netHeadYaw = headYaw - bodyYaw;
                float headPitch = Mth.rotLerp(partialTick, licowitch.xRotO, licowitch.getXRot());
                try {
                    posestack.pushPose();
                } catch (Exception e) {
                    throw new RuntimeException(e);
                }
                posestack.translate(-cameraPos.x, -cameraPos.y, -cameraPos.z);
                posestack.translate(to.x, to.y + 1.5F, to.z);
                posestack.scale(-scale, -scale, scale);
                posestack.mulPose(Axis.YN.rotationDegrees(180 - bodyYaw));
                MultiBufferSource.BufferSource bufferSource = Minecraft.getInstance().renderBuffers().bufferSource();
                VertexConsumer textureBuffer = bufferSource.getBuffer(RenderType.entityTranslucentCull(LicowitchRenderer.TEXTURE));
                TELEPORTING_MODEL.setupAnim(licowitch, licowitch.walkAnimation.position(partialTick), licowitch.walkAnimation.speed(partialTick), licowitch.tickCount + partialTick, netHeadYaw, headPitch);
                TELEPORTING_MODEL.renderToBuffer(posestack, textureBuffer, 240, LivingEntityRenderer.getOverlayCoords(licowitch, 0.0F), 1.0F, 1.0F - (1F - progress), 1.0F, progress);
                PostEffectRegistry.renderEffectForNextTick(ClientProxy.PURPLE_WITCH_SHADER);
                VertexConsumer witchEffectBuffer = bufferSource.getBuffer(ACRenderTypes.getPurpleWitch(LicowitchRenderer.TEXTURE));
                TELEPORTING_MODEL.renderToBuffer(posestack, witchEffectBuffer, 240, LivingEntityRenderer.getOverlayCoords(licowitch, 0.0F), 1.0F, 0.0F, 1.0F, progress);
                posestack.popPose();
            }
        }
        allTeleportingLicowitchOnScreen.clear();
    }

@Override
        protected void renderArmWithItem(LivingEntity livingEntity, ItemStack itemStack, ItemDisplayContext displayContext, HumanoidArm humanoidArm, PoseStack poseStack, MultiBufferSource multiBufferSource, int packedLight) {
            if (!itemStack.isEmpty() && livingEntity instanceof LicowitchEntity licowitch) {
                float partialTicks = Minecraft.getInstance().getPartialTick();
                boolean crossedArms = licowitch.areArmsVisuallyCrossed(partialTicks);

                boolean staff = itemStack.is(ACItemRegistry.SUGAR_STAFF.get());
                poseStack.pushPose();
                if (crossedArms) {
                    this.getParentModel().translateToCrossedArms(humanoidArm, poseStack);
                } else {
                    this.getParentModel().translateToHand(humanoidArm, poseStack);
                }
                poseStack.mulPose(Axis.XP.rotationDegrees(-90.0F));
                poseStack.mulPose(Axis.YP.rotationDegrees(180.0F));
                boolean flag = humanoidArm == HumanoidArm.LEFT;
                if (crossedArms) {
                    poseStack.translate(0.0F, 0.125F, -0.125F);
                } else {
                    poseStack.translate((float) (flag ? 1 : -1) * 0.0325F, 0.125F, -0.125F);
                }
                if (staff) {
                    float forwardsBend = 0;
                    if (licowitch.getAnimation() == LicowitchEntity.ANIMATION_SPELL_0) {
                        forwardsBend = 0.66F * ACMath.cullAnimationTick(licowitch.getAnimationTick(), 1, LicowitchEntity.ANIMATION_SPELL_0, partialTicks, 18, 25);
                    }
                    if (licowitch.getAnimation() == LicowitchEntity.ANIMATION_SPELL_1) {
                        forwardsBend = 0.4F * ACMath.cullAnimationTick(licowitch.getAnimationTick(), 1, LicowitchEntity.ANIMATION_SPELL_1, partialTicks, 25, 27);
                    }
                    if (crossedArms) {
                        poseStack.translate(0.0F, 0, 0.1F);
                        poseStack.mulPose(Axis.YP.rotationDegrees(90.0F));
                        poseStack.mulPose(Axis.ZP.rotationDegrees(5F));
                        poseStack.mulPose(Axis.XP.rotationDegrees(flag ? 20.0F : -20.0F));
                        poseStack.translate(0.0F, 0, -0.05F);
                    } else {
                        poseStack.mulPose(Axis.XP.rotationDegrees(-2.5F));
                    }
                    poseStack.translate(0F, -0.25F * forwardsBend, 0F);
                    poseStack.mulPose(Axis.XP.rotationDegrees(forwardsBend * -90F));
                } else {
                    poseStack.mulPose(Axis.XP.rotationDegrees(10.0F));
                }
                if (licowitch.getAnimation() == LicowitchEntity.ANIMATION_EAT) {
                    float animationIntensity = ACMath.cullAnimationTick(licowitch.getAnimationTick(), 4, LicowitchEntity.ANIMATION_EAT, partialTicks, 0);
                    poseStack.mulPose(Axis.XP.rotationDegrees(animationIntensity * 30.0F));
                }
                this.witchItemInHandRenderer.renderItem(livingEntity, itemStack, displayContext, flag, poseStack, multiBufferSource, packedLight);
                poseStack.popPose();
            }
        }

