public void render(NuclearBombEntity entity, float entityYaw, float partialTicks, PoseStack poseStack, MultiBufferSource source, int lightIn) {
        super.render(entity, entityYaw, partialTicks, poseStack, source, lightIn);
        float progress = (entity.getTime() + partialTicks) / NuclearBombEntity.MAX_TIME;
        float expandScale = 1F + (float) Math.sin(progress * progress * Math.PI) * 0.5F;
        poseStack.pushPose();
        poseStack.mulPose(Axis.YP.rotationDegrees((float) (Math.cos((double) entity.tickCount * 3.25D) * 1.2F * progress * Math.PI)));
        poseStack.scale(1F + progress * 0.03F, 1, 1F + progress * 0.03F);
        poseStack.pushPose();
        poseStack.scale(expandScale, expandScale - progress * 0.3F, expandScale);
        poseStack.translate(-0.5D, 0.0D, -0.5D);
        BlockState state = ACBlockRegistry.NUCLEAR_BOMB.get().defaultBlockState();
        BakedModel bakedmodel = Minecraft.getInstance().getBlockRenderer().getBlockModel(state);
        float f = 1.0F - progress * 0.5F;
        float f1 = 1.0F + progress;
        float f2 = 1.0F - progress;
        for (net.minecraft.client.renderer.RenderType rt : bakedmodel.getRenderTypes(state, RandomSource.create(42), ModelData.EMPTY)) {
            renderModel(poseStack.last(), source.getBuffer(net.minecraftforge.client.RenderTypeHelper.getEntityRenderType(rt, false)), state, bakedmodel, f, f1, f2, 240, OverlayTexture.NO_OVERLAY, ModelData.EMPTY, rt);
        }
        poseStack.popPose();
        poseStack.popPose();
    }

public void render(NucleeperEntity entityIn, float entityYaw, float partialTicks, PoseStack poseStack, MultiBufferSource bufferIn, int packedLightIn) {
        float closeProgress = entityIn.getCloseProgress(partialTicks);
        if (closeProgress > 0F && entityIn.isAlive() && !entityIn.isExploding()) {
            float sq = Mth.sqrt(closeProgress);
            float length = sq * 3;
            float width = (1F - sq) * 1.25F;
            Vec3 modelOffset = model.getSirenPosition(new Vec3(0, -0.5F, 0));
            poseStack.pushPose();
            poseStack.translate(modelOffset.x, modelOffset.y, modelOffset.z);
            poseStack.mulPose(Axis.YP.rotationDegrees(entityIn.getSirenAngle(partialTicks)));
            poseStack.pushPose();
            poseStack.mulPose(Axis.ZN.rotationDegrees(90));
            PoseStack.Pose posestack$pose = poseStack.last();
            Matrix4f matrix4f1 = posestack$pose.pose();
            Matrix3f matrix3f1 = posestack$pose.normal();
            VertexConsumer lightConsumer = bufferIn.getBuffer(ACRenderTypes.getNucleeperLights());
            shineOriginVertex(lightConsumer, matrix4f1, matrix3f1, 0, 0);
            shineLeftCornerVertex(lightConsumer, matrix4f1, matrix3f1, length, width, 0, 0);
            shineRightCornerVertex(lightConsumer, matrix4f1, matrix3f1, length, width, 0, 0);
            shineLeftCornerVertex(lightConsumer, matrix4f1, matrix3f1, length, width, 0, 0);
            Matrix4f matrix4f2 = posestack$pose.pose();
            Matrix3f matrix3f2 = posestack$pose.normal();
            poseStack.mulPose(Axis.ZN.rotationDegrees(180));
            shineOriginVertex(lightConsumer, matrix4f2, matrix3f2, 0, 0);
            shineLeftCornerVertex(lightConsumer, matrix4f2, matrix3f2, length, width, 0, 0);
            shineRightCornerVertex(lightConsumer, matrix4f2, matrix3f2, length, width, 0, 0);
            shineLeftCornerVertex(lightConsumer, matrix4f2, matrix3f2, length, width, 0, 0);
            poseStack.popPose();
            poseStack.popPose();
        }
        super.render(entityIn, entityYaw, partialTicks, poseStack, bufferIn, packedLightIn);
    }

