public void render(SpinningPeppermintEntity entity, float entityYaw, float partialTicks, PoseStack poseStack, MultiBufferSource source, int lightIn) {
        super.render(entity, entityYaw, partialTicks, poseStack, source, lightIn);
        PostEffectRegistry.renderEffectForNextTick(ClientProxy.PURPLE_WITCH_SHADER);
        float ageInTicks = partialTicks + entity.tickCount;
        float despawnsIn = entity.getDespawnTime(partialTicks);
        float minAge = Math.min(1F, Math.min(ageInTicks, despawnsIn) / 10F);
        poseStack.pushPose();
        poseStack.scale(minAge, minAge, minAge);
        poseStack.translate(0.0D, 0.5D, 0.0D);
        if(entity.isStraight()){
            poseStack.mulPose(Axis.YN.rotationDegrees(Mth.lerp(partialTicks, entity.yRotO, entity.getYRot()) + 90.0F));
            poseStack.mulPose(Axis.ZN.rotationDegrees((float) (Mth.lerp(partialTicks, entity.xRotO, entity.getXRot()) + 5F * Math.sin(ageInTicks * 0.2F))));
            poseStack.mulPose(Axis.ZP.rotationDegrees(ageInTicks * -4.0F * entity.getSpinSpeed()));
            poseStack.translate(0.0D, 0.0D, -0.25);
        }else{
            poseStack.mulPose(Axis.XP.rotationDegrees(90));
            poseStack.mulPose(Axis.ZP.rotationDegrees(ageInTicks * -4.0F * entity.getSpinSpeed()));
            poseStack.mulPose(Axis.XP.rotationDegrees((float) Math.sin(ageInTicks * 0.8F) * 8));
            poseStack.mulPose(Axis.XP.rotationDegrees((float) Math.cos(ageInTicks * 0.8F) * 8));
        }
        poseStack.translate(-0.5D, -0.5D, -0.5D);
        BakedModel bakedmodel = Minecraft.getInstance().getItemRenderer().getModel(entity.peppermintRenderStack, entity.level(), null, 0);
        int redOverlay = OverlayTexture.pack(OverlayTexture.u(0), OverlayTexture.v(true));
        for (net.minecraft.client.renderer.RenderType rt : bakedmodel.getRenderTypes(entity.peppermintRenderStack, false)) {
            renderModel(poseStack.last(), source.getBuffer(Sheets.translucentItemSheet()), 1.0F, null, bakedmodel, 1.0F, minAge, 1.0F, lightIn, redOverlay, ModelData.EMPTY, rt);
        }
        RenderType purpleWitch = ACRenderTypes.getPurpleWitch(TextureAtlas.LOCATION_BLOCKS);
        renderModel(poseStack.last(), source.getBuffer(purpleWitch), 1.0F, null, bakedmodel, 1.0F, 1.0F, 1.0F, lightIn, redOverlay, ModelData.EMPTY, purpleWitch);
        poseStack.popPose();
    }

public static void renderSubmarine(SubmarineEntity entity, float partialTicks, PoseStack poseStack, MultiBufferSource source, int lightIn, boolean maskWater) {
        Player player = Minecraft.getInstance().player;
        float ageInTicks = entity.tickCount + partialTicks;
        float submarineYaw = entity.getViewYRot(partialTicks);
        float submarinePitch = entity.getViewXRot(partialTicks);
        poseStack.pushPose();
        poseStack.translate(0.0D, 1.5D, 0.0D);
        poseStack.mulPose(Axis.YP.rotationDegrees(180 - submarineYaw));
        poseStack.scale(-1.0F, -1.0F, 1.0F);
        poseStack.mulPose(Axis.XN.rotationDegrees(submarinePitch));
        poseStack.translate(0, 0, 0);
        if (entity.getWaterHeight() > 0 && entity.getWaterHeight() < 1.6F) {
            poseStack.mulPose(Axis.ZP.rotationDegrees((float) (Math.sin(ageInTicks * 0.1F) * 0.5F)));
            poseStack.mulPose(Axis.XP.rotationDegrees((float) (Math.sin(ageInTicks * 0.1F + 1.3F) * 0.5F)));
        }
        poseStack.pushPose();
        MODEL.setupAnim(entity, 0.0F, 0.0F, ageInTicks, 0.0F, 0.0F);
        for (Entity passenger : entity.getPassengers()) {
            if (passenger == player && Minecraft.getInstance().options.getCameraType().isFirstPerson()) {
                continue;
            }
            AlexsCaves.PROXY.releaseRenderingEntity(passenger.getUUID());
            poseStack.pushPose();
            poseStack.translate(0, 0.65F, -0.75F);
            poseStack.mulPose(Axis.XN.rotationDegrees(180F));
            poseStack.mulPose(Axis.YN.rotationDegrees(360 - submarineYaw));
            renderPassenger(passenger, 0, 0, 0, 0, partialTicks, poseStack, source, lightIn);
            poseStack.popPose();
            AlexsCaves.PROXY.blockRenderingEntity(passenger.getUUID());
        }
        VertexConsumer textureBuffer = source.getBuffer(RenderType.entityCutoutNoCull(getSubmarineBaseTexture(entity)));
        MODEL.renderToBuffer(poseStack, textureBuffer, lightIn, OverlayTexture.NO_OVERLAY, 1.0F, 1.0F, 1.0F, 1.0F);
        VertexConsumer damageBuffer = source.getBuffer(RenderType.entityTranslucent(getSubmarineDamageTexture(entity)));
        MODEL.renderToBuffer(poseStack, damageBuffer, lightIn, OverlayTexture.NO_OVERLAY, 1.0F, 1.0F, 1.0F, 1.0F);
        if (entity.getDamageLevel() <= 3) {
            VertexConsumer buttonsBuffer = source.getBuffer(ACRenderTypes.getEyesAlphaEnabled(TEXTURE_BUTTONS));
            MODEL.renderToBuffer(poseStack, buttonsBuffer, lightIn, OverlayTexture.NO_OVERLAY, 1.0F, 1.0F, 1.0F, entity.getSonarFlashAmount(partialTicks));
            if (entity.areLightsOn() && entity.isVehicle()) {
                VertexConsumer glowBuffer = source.getBuffer(RenderType.eyes(TEXTURE_GLOW));
                MODEL.renderToBuffer(poseStack, glowBuffer, lightIn, OverlayTexture.NO_OVERLAY, 1.0F, 1.0F, 1.0F, 1.0F);
            }
        }
        if (maskWater) {
            VertexConsumer waterMask = source.getBuffer(ACRenderTypes.getSubmarineMask());
            MODEL.setupWaterMask(entity, partialTicks);
            MODEL.getWaterMask().render(poseStack, waterMask, lightIn, OverlayTexture.NO_OVERLAY, 1.0F, 1.0F, 1.0F, 1.0F);
        }
        if (!isFirstPersonFloodlightsMode(entity) && entity.areLightsOn() && entity.isVehicle()) {
            Entity first = entity.getFirstPassenger();
            float xRot = 0;
            float yRot = 0;
            if (first instanceof Player firstPlayer) {
                float headYaw = (firstPlayer.yHeadRotO + (firstPlayer.getYHeadRot() - firstPlayer.yHeadRotO) * partialTicks);
                xRot = firstPlayer.getViewXRot(partialTicks) + submarinePitch;
                yRot = Mth.approachDegrees(submarineYaw, headYaw, 60);
            }
            float length = 4.5F;
            float width = 0.45F;
            poseStack.pushPose();
            poseStack.translate(0, 0.75F, -2.4F);
            poseStack.mulPose(Axis.YN.rotationDegrees(submarineYaw));
            poseStack.mulPose(Axis.YP.rotationDegrees(yRot));
            poseStack.mulPose(Axis.XN.rotationDegrees(90 - xRot));
            poseStack.scale(3, 1, 1);
            poseStack.translate(0, -1, 0F);
            PoseStack.Pose posestack$pose = poseStack.last();
            Matrix4f matrix4f1 = posestack$pose.pose();
            Matrix3f matrix3f1 = posestack$pose.normal();
            VertexConsumer lightConsumer = source.getBuffer(ACRenderTypes.getSubmarineLights());
            shineOriginVertex(lightConsumer, matrix4f1, matrix3f1, 0, 0);
            shineLeftCornerVertex(lightConsumer, matrix4f1, matrix3f1, length, width, 0, 0);
            shineRightCornerVertex(lightConsumer, matrix4f1, matrix3f1, length, width, 0, 0);
            shineLeftCornerVertex(lightConsumer, matrix4f1, matrix3f1, length, width, 0, 0);
            poseStack.popPose();
        }

        poseStack.popPose();
        poseStack.popPose();
    }

public static <E extends Entity> void renderPassenger(E entityIn, double x, double y, double z, float yaw, float partialTicks, PoseStack matrixStack, MultiBufferSource bufferIn, int packedLight) {
        EntityRenderer<? super E> render = null;
        EntityRenderDispatcher manager = Minecraft.getInstance().getEntityRenderDispatcher();
        try {
            render = manager.getRenderer(entityIn);

            if (render != null) {
                try {
                    render.render(entityIn, yaw, partialTicks, matrixStack, bufferIn, packedLight);
                } catch (Throwable throwable1) {
                    throw new ReportedException(CrashReport.forThrowable(throwable1, "Rendering entity in world"));
                }
            }
        } catch (Throwable throwable3) {
            CrashReport crashreport = CrashReport.forThrowable(throwable3, "Rendering entity in world");
            CrashReportCategory crashreportcategory = crashreport.addCategory("Entity being rendered");
            entityIn.fillCrashReportCategory(crashreportcategory);
            CrashReportCategory crashreportcategory1 = crashreport.addCategory("Renderer details");
            crashreportcategory1.setDetail("Assigned renderer", render);
            crashreportcategory1.setDetail("Rotation", Float.valueOf(yaw));
            crashreportcategory1.setDetail("Delta", Float.valueOf(partialTicks));
            throw new ReportedException(crashreport);
        }
    }

public void render(SugarStaffHexEntity entity, float entityYaw, float partialTicks, PoseStack poseStack, MultiBufferSource multiBufferSource, int packedLight) {
        PostEffectRegistry.renderEffectForNextTick(ClientProxy.PURPLE_WITCH_SHADER);
        poseStack.pushPose();
        float despawnsIn = entity.getDespawnTime(partialTicks);
        float randomRotation = entity.getId() % 4 * 90;
        float randomYOffset = entity.getYRenderOffset();
        float tickCount = entity.tickCount + partialTicks;
        float minAge = Math.min(1F, Math.min(tickCount, despawnsIn) / 10F);
        float alpha = minAge;
        float alpha2 = alpha * alpha;
        float scale = 4.0F * entity.getHexScale();
        poseStack.translate(0, randomYOffset, 0);
        poseStack.mulPose(Axis.YP.rotationDegrees(randomRotation + 3.0F * tickCount));
        poseStack.scale(scale, scale, scale);
        renderHex(poseStack, multiBufferSource, ACRenderTypes.getPurpleWitch(TEXTURE), 1F, 1F, 1F - alpha2, 1F);
        for(int i = 0; i < 5; i++){
            float f = (1F - i / 5F) * 0.5F;
            float bob = (float) (Math.sin(tickCount * 0.2F + i) * 0.005F);
            renderHex(poseStack, multiBufferSource, ACRenderTypes.getVoidBeingCloud(TEXTURE), 1 * f, 1F, 1F - alpha2 * f, 1F);
            poseStack.translate(0, 0.01F + bob + (1F - alpha2) * 0.03F, 0);
        }
        poseStack.popPose();
        super.render(entity, entityYaw, partialTicks, poseStack, multiBufferSource, packedLight);
    }

public void render(TeletorEntity entityIn, float entityYaw, float partialTicks, PoseStack poseStack, MultiBufferSource bufferIn, int packedLightIn) {
        super.render(entityIn, entityYaw, partialTicks, poseStack, bufferIn, packedLightIn);
        double x = Mth.lerp(partialTicks, entityIn.xOld, entityIn.getX());
        double y = Mth.lerp(partialTicks, entityIn.yOld, entityIn.getY());
        double z = Mth.lerp(partialTicks, entityIn.zOld, entityIn.getZ());
        float yaw = entityIn.yBodyRotO + (entityIn.yBodyRot - entityIn.yBodyRotO) * partialTicks;
        if (entityIn.hasTrail()) {
            poseStack.pushPose();
            poseStack.translate(-x, -y, -z);
            setupRotations(entityIn, poseStack, 0F, 180F, partialTicks);
            Vec3 headModelPos = getModel().translateToHead(new Vec3(0, -0.4F, 0), yaw).scale(-1);
            poseStack.translate(headModelPos.x, headModelPos.y, headModelPos.z);
            renderTrail(entityIn, 0, partialTicks, poseStack, bufferIn, 0.2F, 0.2F, 0.8F, 0.8F, 240);
            renderTrail(entityIn, 1, partialTicks, poseStack, bufferIn, 0.8F, 0.2F, 0.2F, 0.8F, 240);
            poseStack.popPose();
        }
        Entity weapon = entityIn.getWeapon();
        if (weapon != null && entityIn.isAlive() && weapon.isAlive()) {
            poseStack.pushPose();
            poseStack.translate(-x, -y, -z);
            setupRotations(entityIn, poseStack, 0F, 180F, partialTicks);
            Vec3 headModelPos = getModel().translateToHead(new Vec3(0, -0.4F, 0), yaw).scale(-1);
            Vec3 fromVec1 = entityIn.getHelmetPosition(0).add(headModelPos);
            Vec3 fromVec2 = entityIn.getHelmetPosition(1).add(headModelPos);
            Vec3 toVec = weapon.getPosition(partialTicks).add(0F, weapon.getBbHeight() * 0.5F - 0.1F + Math.sin((weapon.tickCount + partialTicks) * 0.1F) * 0.1F, 0F);

            int segCount = Mth.clamp((int) weapon.distanceTo(entityIn) + 2, 3, 30);
            float spreadFactor = Mth.clamp((10 - weapon.distanceTo(entityIn)) / 10F * 0.2F, 0.01F, 0.2F);

            LightningBoltData.BoltRenderInfo blueBoltData = new LightningBoltData.BoltRenderInfo(0.0F, spreadFactor, 0.0F, 0.0F, new Vector4f(0.2F, 0.2F, 0.8F, 0.8F), 0.1F);
            LightningBoltData.BoltRenderInfo redBoltData = new LightningBoltData.BoltRenderInfo(0.0F, spreadFactor, 0.0F, 0.0F, new Vector4f(0.8F, 0.2F, 0.2F, 0.8F), 0.1F);

            LightningBoltData bolt1 = new LightningBoltData(blueBoltData, fromVec1, toVec, segCount)
                    .size(0.1F)
                    .lifespan(1)
                    .spawn(LightningBoltData.SpawnFunction.CONSECUTIVE)
                    .fade(LightningBoltData.FadeFunction.NONE);
            LightningBoltData bolt2 = new LightningBoltData(redBoltData, fromVec2, toVec, segCount)
                    .size(0.1F)
                    .lifespan(1)
                    .spawn(LightningBoltData.SpawnFunction.CONSECUTIVE)
                    .fade(LightningBoltData.FadeFunction.NONE);
            LightningRender lightningRender = getLightingRender(entityIn.getUUID());
            lightningRender.update(entityIn, bolt1, partialTicks);
            lightningRender.update(weapon, bolt2, partialTicks);

            lightningRender.render(partialTicks, poseStack, bufferIn);
            poseStack.popPose();
        }
        if (!entityIn.isAlive() && lightningRenderMap.containsKey(entityIn.getUUID())) {
            lightningRenderMap.remove(entityIn.getUUID());
        }
    }

private void renderTrail(TeletorEntity entityIn, int side, float partialTicks, PoseStack poseStack, MultiBufferSource bufferIn, float trailR, float trailG, float trailB, float trailA, int packedLightIn) {
        int samples = 0;
        int sampleSize = 10;
        float trailHeight = 0.2F;
        float trailZRot = 0;
        Vec3 topAngleVec = new Vec3(0, trailHeight, 0).zRot(trailZRot);
        Vec3 bottomAngleVec = new Vec3(0, -trailHeight, 0).zRot(trailZRot);
        Vec3 drawFrom = entityIn.getTrailPosition(0, side, partialTicks);
        VertexConsumer vertexconsumer = bufferIn.getBuffer(RenderType.entityTranslucent(TRAIL_TEXTURE));
        while (samples < sampleSize) {
            Vec3 sample = entityIn.getTrailPosition(samples + 2, side, partialTicks);
            float u1 = samples / (float) sampleSize;
            float u2 = u1 + 1 / (float) sampleSize;

            Vec3 draw1 = drawFrom;
            Vec3 draw2 = sample;

            PoseStack.Pose posestack$pose = poseStack.last();
            Matrix4f matrix4f = posestack$pose.pose();
            Matrix3f matrix3f = posestack$pose.normal();
            vertexconsumer.vertex(matrix4f, (float) draw1.x + (float) bottomAngleVec.x, (float) draw1.y + (float) bottomAngleVec.y, (float) draw1.z + (float) bottomAngleVec.z).color(trailR, trailG, trailB, trailA).uv(u1, 1F).overlayCoords(NO_OVERLAY).uv2(packedLightIn).normal(matrix3f, 0.0F, 1.0F, 0.0F).endVertex();
            vertexconsumer.vertex(matrix4f, (float) draw2.x + (float) bottomAngleVec.x, (float) draw2.y + (float) bottomAngleVec.y, (float) draw2.z + (float) bottomAngleVec.z).color(trailR, trailG, trailB, trailA).uv(u2, 1F).overlayCoords(NO_OVERLAY).uv2(packedLightIn).normal(matrix3f, 0.0F, 1.0F, 0.0F).endVertex();
            vertexconsumer.vertex(matrix4f, (float) draw2.x + (float) topAngleVec.x, (float) draw2.y + (float) topAngleVec.y, (float) draw2.z + (float) topAngleVec.z).color(trailR, trailG, trailB, trailA).uv(u2, 0).overlayCoords(NO_OVERLAY).uv2(packedLightIn).normal(matrix3f, 0.0F, 1.0F, 0.0F).endVertex();
            vertexconsumer.vertex(matrix4f, (float) draw1.x + (float) topAngleVec.x, (float) draw1.y + (float) topAngleVec.y, (float) draw1.z + (float) topAngleVec.z).color(trailR, trailG, trailB, trailA).uv(u1, 0).overlayCoords(NO_OVERLAY).uv2(packedLightIn).normal(matrix3f, 0.0F, 1.0F, 0.0F).endVertex();
            samples++;
            drawFrom = sample;
        }
    }

