        GlStateManager.translate((float)x, (float)y, (float)z);
        GlStateManager.rotate(entity.prevRotationYaw + (entity.rotationYaw - entity.prevRotationYaw) * partialTicks - 90.0F, 0.0F, 1.0F, 0.0F);
        GlStateManager.rotate(entity.prevRotationPitch + (entity.rotationPitch - entity.prevRotationPitch) * partialTicks, 0.0F, 0.0F, 1.0F);
        float shake = (float)entity.arrowShake - partialTicks;

        if (shake > 0.0F) {
            float f10 = -MathHelper.sin(shake * 3.0F) * shake;
            GlStateManager.rotate(f10, 0.0F, 0.0F, 1.0F);
        }

        GlStateManager.rotate(-90.0F, 0.0F, 1.0F, 0.0F);
        GlStateManager.scale(-1F, -1F, 1F);
        GlStateManager.translate(0F, -1.5F, 0F);

        if (this.renderOutlines) {
            GlStateManager.enableColorMaterial();
            GlStateManager.enableOutlineMode(this.getTeamColor(entity));
        }

        //render the worm arrow model
        WORM_MODEL.render();

        if (this.renderOutlines) {
            GlStateManager.disableOutlineMode();
            GlStateManager.disableColorMaterial();
        }

        GlStateManager.enableLighting();
        GlStateManager.popMatrix();
	}

public void doRender(EntityBLFishHook entity, double x, double y, double z, float entityYaw, float partialTicks) {
		EntityPlayer entityplayer = entity.getAngler();
		if (entityplayer != null && !this.renderOutlines) {
			GlStateManager.pushMatrix();
			GlStateManager.translate((float) x, (float) y + 1.1F, (float) z);
			GlStateManager.scale(-0.8F, -0.8F, 0.8F);
			bindTexture(HOOK_TEXTURE);
			//causes janky rotationrendering atm
			//GlStateManager.rotate(180.0F - this.renderManager.playerViewY, 0.0F, 1.0F, 0.0F);
			//GlStateManager.rotate((float) (this.renderManager.options.thirdPersonView == 2 ? -1 : 1) * -this.renderManager.playerViewX, 1.0F, 0.0F, 0.0F);

			if (this.renderOutlines) {
				GlStateManager.enableColorMaterial();
				GlStateManager.enableOutlineMode(this.getTeamColor(entity));
			}

			HOOK_MODEL.render();

			if (this.renderOutlines) {
				GlStateManager.disableOutlineMode();
				GlStateManager.disableColorMaterial();
			}
			GlStateManager.popMatrix();

	///////	
			Tessellator tessellator = Tessellator.getInstance();
			BufferBuilder bufferbuilder = tessellator.getBuffer();
			int k = entityplayer.getPrimaryHand() == EnumHandSide.RIGHT ? 1 : -1;
			ItemStack itemstack = entityplayer.getHeldItemMainhand();

			if (!(itemstack.getItem() instanceof ItemBLFishingRod)) {
				k = -k;
			}

			float f7 = entityplayer.getSwingProgress(partialTicks);
			float f8 = MathHelper.sin(MathHelper.sqrt(f7) * (float) Math.PI);
			float f9 = (entityplayer.prevRenderYawOffset + (entityplayer.renderYawOffset - entityplayer.prevRenderYawOffset) * partialTicks) * 0.017453292F;
			double d0 = (double) MathHelper.sin(f9);
			double d1 = (double) MathHelper.cos(f9);
			double d2 = (double) k * 0.35D;
			double d3 = 0.8D;
			double d4;
			double d5;
			double d6;
			double d7;

			if ((this.renderManager.options == null || this.renderManager.options.thirdPersonView <= 0)
					&& entityplayer == Minecraft.getMinecraft().player) {
				float f10 = this.renderManager.options.fovSetting;
				f10 = f10 / 100.0F;
				Vec3d vec3d = new Vec3d((double) k * -0.36D * (double) f10, -0.045D * (double) f10, 0.4D);
				vec3d = vec3d.rotatePitch(-(entityplayer.prevRotationPitch + (entityplayer.rotationPitch - entityplayer.prevRotationPitch) * partialTicks) * 0.017453292F);
				vec3d = vec3d.rotateYaw(-(entityplayer.prevRotationYaw + (entityplayer.rotationYaw - entityplayer.prevRotationYaw) * partialTicks) * 0.017453292F);
				vec3d = vec3d.rotateYaw(f8 * 0.5F);
				vec3d = vec3d.rotatePitch(-f8 * 0.7F);
				d4 = entityplayer.prevPosX + (entityplayer.posX - entityplayer.prevPosX) * (double) partialTicks + vec3d.x;
				d5 = entityplayer.prevPosY + (entityplayer.posY - entityplayer.prevPosY) * (double) partialTicks + vec3d.y;
				d6 = entityplayer.prevPosZ + (entityplayer.posZ - entityplayer.prevPosZ) * (double) partialTicks + vec3d.z;
				d7 = (double) entityplayer.getEyeHeight();
			} else {
				d4 = entityplayer.prevPosX + (entityplayer.posX - entityplayer.prevPosX) * (double) partialTicks - d1 * d2 - d0 * 0.95D;
				d5 = entityplayer.prevPosY + (double) entityplayer.getEyeHeight() + (entityplayer.posY - entityplayer.prevPosY) * (double) partialTicks - 0.625D;
				d6 = entityplayer.prevPosZ + (entityplayer.posZ - entityplayer.prevPosZ) * (double) partialTicks - d0 * d2 + d1 * 0.95D;
				d7 = entityplayer.isSneaking() ? -0.1875D : 0.0D;
			}

			double d13 = entity.prevPosX + (entity.posX - entity.prevPosX) * (double) partialTicks;
			double d8 = entity.prevPosY + (entity.posY - entity.prevPosY) * (double) partialTicks + 0.235D;
			double d9 = entity.prevPosZ + (entity.posZ - entity.prevPosZ) * (double) partialTicks;
			double d10 = (double) ((float) (d4 - d13));
			double d11 = (double) ((float) (d5 - d8)) + d7;
			double d12 = (double) ((float) (d6 - d9));

			GlStateManager.disableTexture2D();
			GlStateManager.disableLighting();
			GlStateManager.disableCull();

			bufferbuilder.begin(5, DefaultVertexFormats.POSITION_COLOR);

			for (int count = 0; count <= 48; ++count) {
				float fx = 0.9764F;
				float f1x = 0.9215F;
				float f2x = 0.8F;

				if (count % 2 == 0) {
					fx = 0.7882F;
					f1x = 0.7529F;
					f2x = 0.6353F;
				}

				float f3x = (float) count / 48.0F;
				bufferbuilder.pos(x + d10 * (double) f3x - 0.0125D, y + d11 * (double) (f3x * f3x + f3x) * 0.5D + 0.2375D, z + d12 * (double) f3x).color(fx, f1x, f2x, 1.0F).endVertex();
				bufferbuilder.pos(x + d10 * (double) f3x + 0.0125D, y + d11 * (double) (f3x * f3x + f3x) * 0.5D + 0.2625D, z + d12 * (double) f3x).color(fx, f1x, f2x, 1.0F).endVertex();
			}

			tessellator.draw();

			bufferbuilder.begin(5, DefaultVertexFormats.POSITION_COLOR);

			for (int count2 = 0; count2 <= 48; ++count2) {
				float f4x = 0.9764F;
				float f5x = 0.9215F;
				float f6x = 0.8F;

				if (count2 % 2 == 0) {
					f4x = 0.7882F;
					f5x = 0.7529F;
					f6x = 0.6353F;
				}

				float f7x = (float) count2 / 48.0F;
				bufferbuilder.pos(x + d10 * (double) f7x - 0.0125D, y + d11 * (double) (f7x * f7x + f7x) * 0.5D + 0.2625D, z + d12 * (double) f7x).color(f4x, f5x, f6x, 1.0F).endVertex();
				bufferbuilder.pos(x + d10 * (double) f7x + 0.0125D, y + d11 * (double) (f7x * f7x + f7x) * 0.5D + 0.2375D, z + d12 * (double) f7x).color(f4x, f5x, f6x, 1.0F).endVertex();
			}

			tessellator.draw();

			GlStateManager.enableLighting();
			GlStateManager.enableTexture2D();
			GlStateManager.enableCull();
			super.doRender(entity, x, y, z, entityYaw, partialTicks);
		}
	}

@Override
    public void doRender(EntityItemFrame entity, double x, double y, double z, float entityYaw, float partialTicks) {
        EntityBLItemFrame blItemFrame = (EntityBLItemFrame)entity;

        GlStateManager.pushMatrix();
        BlockPos blockpos = entity.getHangingPosition();
        double d0 = (double)blockpos.getX() - entity.posX + x;
        double d1 = (double)blockpos.getY() - entity.posY + y;
        double d2 = (double)blockpos.getZ() - entity.posZ + z;
        GlStateManager.translate(d0 + 0.5D, d1 + 0.5D, d2 + 0.5D);

        if(blItemFrame.realFacingDirection.getAxis() == EnumFacing.Axis.Y) {
            GlStateManager.rotate(blItemFrame.realFacingDirection == EnumFacing.DOWN ? -90.0F : 90.0F, 1.0F, 0.0F, 0.0F);
            GlStateManager.rotate(blItemFrame.realFacingDirection == EnumFacing.UP ? 180.0F : 0.0F, 0.0F, 0.0F, 1.0F);
        } else {
            GlStateManager.rotate(180.0F - entity.rotationYaw, 0.0F, 1.0F, 0.0F);
        }

        this.renderManager.renderEngine.bindTexture(TextureMap.LOCATION_BLOCKS_TEXTURE);

        GlStateManager.pushMatrix();
        GlStateManager.translate(-0.5F, -0.5F, -0.5F);

        if (this.renderOutlines)
        {
            GlStateManager.enableColorMaterial();
            GlStateManager.enableOutlineMode(this.getTeamColor(entity));
        }

        renderModel(entity, mc);

        if (this.renderOutlines)
        {
            GlStateManager.disableOutlineMode();
            GlStateManager.disableColorMaterial();
        }

        if(blItemFrame.IsFrameGlowing()) {
            GlStateManager.enableLighting();
        }

        GlStateManager.popMatrix();
        GlStateManager.translate(0.0F, 0.0F, 0.4375F);

        boolean flipItem = blItemFrame.realFacingDirection == EnumFacing.DOWN && !blItemFrame.getDisplayedItem().isEmpty() && blItemFrame.getDisplayedItem().getItem() instanceof ItemCompass;
        GlStateManager.rotate(flipItem ? -180.0F : 0.0F, 0.0F, 1.0F, 0.0F);

        this.renderItem(entity);
        GlStateManager.popMatrix();
    }

private void renderItem(EntityItemFrame itemFrame)
    {
        EntityBLItemFrame blItemFrame = (EntityBLItemFrame)itemFrame;

        ItemStack itemstack = itemFrame.getDisplayedItem();

        if (!itemstack.isEmpty())
        {
            GlStateManager.pushMatrix();
            GlStateManager.disableLighting();

            boolean flag = itemstack.getItem() instanceof net.minecraft.item.ItemMap;
            int i = flag ? itemFrame.getRotation() % 4 * 2 : itemFrame.getRotation();
            GlStateManager.rotate((float)i * 360.0F / 8.0F, 0.0F, 0.0F, 1.0F);

            net.minecraftforge.client.event.RenderItemInFrameEvent event = new net.minecraftforge.client.event.RenderItemInFrameEvent(itemFrame, this);
            if (!net.minecraftforge.common.MinecraftForge.EVENT_BUS.post(event))
            {
                if (flag)
                {
                    this.renderManager.renderEngine.bindTexture(MAP_BACKGROUND_TEXTURES);
                    GlStateManager.rotate(180.0F, 0.0F, 0.0F, 1.0F);
                    float f = 0.0078125F;
                    GlStateManager.scale(0.0078125F, 0.0078125F, 0.0078125F);
                    GlStateManager.translate(-64.0F, -64.0F, 0.0F);
                    MapData mapdata = ((net.minecraft.item.ItemMap) itemstack.getItem()).getMapData(itemstack, itemFrame.world);
                    GlStateManager.translate(0.0F, 0.0F, -1.0F);

                    if (mapdata != null)
                    {
                        this.mc.entityRenderer.getMapItemRenderer().renderMap(mapdata, true);
                    }
                }
                else
                {
                    GlStateManager.scale(0.5F, 0.5F, 0.5F);

                    GlStateManager.pushAttrib();
                    RenderHelper.enableStandardItemLighting();

                    if(itemstack.getItem() instanceof ItemMob) {
                        ItemMob itemMob = (ItemMob)itemstack.getItem();
                        Entity entity = itemMob.createCapturedEntity(itemFrame.world, 0, 0, 0, itemstack, false);

                        if (entity != null && !(entity instanceof IEntityMultiPart)) {
                            float horizontalOffset = 0;

                            if(entity instanceof EntityAnadia) {
                                horizontalOffset = entity.width / 4;
                            }

                            entity.setPositionAndRotation(0, 0, 0, 0, 0);

                            if(blItemFrame.realFacingDirection.getAxis().equals(EnumFacing.Axis.Y)) {
                                GlStateManager.rotate(-90F, 1F, 0F, 0F);
                            } else {
                                GlStateManager.translate(horizontalOffset, -entity.height / 2D, -0.05D);
                            }

                            GlStateManager.rotate(90, 0, 1, 0);
                            entity.rotationPitch = 0F;
                            entity.ticksExisted = 0;
                            Minecraft.getMinecraft().getRenderManager().renderEntity(entity, 0D, 0D, 0D, 0F, 0F, true);
                        } else {
                            this.itemRenderer.renderItem(itemstack, ItemCameraTransforms.TransformType.FIXED);
                        }
                    } else {
                        this.itemRenderer.renderItem(itemstack, ItemCameraTransforms.TransformType.FIXED);
                    }

                    RenderHelper.disableStandardItemLighting();
                    GlStateManager.popAttrib();
                }
            }

            GlStateManager.enableLighting();
            GlStateManager.popMatrix();
        }
    }

protected void renderModel(EntityItemFrame entity, Minecraft mc) {
        EntityBLItemFrame itemFrame = (EntityBLItemFrame)entity;

        if(itemFrame.IsFrameInvisible() && !itemFrame.getDisplayedItem().isEmpty()) {
            if(itemFrame.IsFrameGlowing()) {
                GlStateManager.disableLighting();
                OpenGlHelper.setLightmapTextureCoords(OpenGlHelper.lightmapTexUnit, 240f, 240f);
            }

            return;
        }

        BlockRendererDispatcher blockrendererdispatcher = this.mc.getBlockRendererDispatcher();
        ModelManager modelmanager = blockrendererdispatcher.getBlockModelShapes().getModelManager();

        if (entity.getDisplayedItem().getItem() instanceof net.minecraft.item.ItemMap) {
            if(itemFrame.IsFrameGlowing()) {
                GlStateManager.disableLighting();
                OpenGlHelper.setLightmapTextureCoords(OpenGlHelper.lightmapTexUnit, 240f, 240f);
            }

            IBakedModel model = modelmanager.getModel(RenderDraeton.FRAME_MAP_MODEL);
            blockrendererdispatcher.getBlockModelRenderer().renderModelBrightnessColor(model, 1.0F, 1.0F, 1.0F, 1.0F);
        } else {
            IBakedModel woodModel, coloredModel;

            woodModel = modelmanager.getModel(FRAME_MODEL);
            coloredModel = modelmanager.getModel(FRAME_BG_MODEL);

            blockrendererdispatcher.getBlockModelRenderer().renderModelBrightnessColor(woodModel, 1.0F, 1.0F, 1.0F, 1.0F);

            int color = EnumBLDyeColor.byMetadata(((EntityBLItemFrame) entity).getColor()).getColorValue();
            float r = (color >> 16 & 0xFF) / 255F;
            float g = (color >> 8 & 0xFF) / 255F;
            float b = (color & 0xFF) / 255F;

            if(itemFrame.IsFrameGlowing()) {
                GlStateManager.disableLighting();
                OpenGlHelper.setLightmapTextureCoords(OpenGlHelper.lightmapTexUnit, 240f, 240f);
            }

            blockrendererdispatcher.getBlockModelRenderer().renderModelBrightnessColor(coloredModel, 1.0F, r, g, b);
        }
    }

