private void renderShine(float rotation, int iterations) {
		Random random = new Random(432L);
		GlStateManager.disableTexture2D();
		GL11.glShadeModel(GL11.GL_SMOOTH);
		GlStateManager.enableBlend();
		GlStateManager.blendFunc(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE);
		GlStateManager.disableAlpha();
		GlStateManager.enableCull();
		GlStateManager.depthMask(false);
		GlStateManager.pushMatrix();
		float f1 = rotation;
		float f2 = 0.0f;
		if (f1 > 0.8F) {
			f2 = (f1 - 0.8F) / 0.2F;
		}
		Tessellator tessellator = Tessellator.getInstance();
		BufferBuilder buffer = tessellator.getBuffer();
		for (int i = 0; (float) i < iterations; ++i) {
			GlStateManager.rotate(random.nextFloat() * 360.0F, 1.0F, 0.0F, 0.0F);
			GlStateManager.rotate(random.nextFloat() * 360.0F, 0.0F, 1.0F, 0.0F);
			GlStateManager.rotate(random.nextFloat() * 360.0F, 0.0F, 0.0F, 1.0F);
			GlStateManager.rotate(random.nextFloat() * 360.0F, 1.0F, 0.0F, 0.0F);
			GlStateManager.rotate(random.nextFloat() * 360.0F, 0.0F, 1.0F, 0.0F);
			GlStateManager.rotate(random.nextFloat() * 360.0F + f1 * 90.0F, 0.0F, 0.0F, 1.0F);
			float pos1 = random.nextFloat() * 20.0F + 5.0F + f2 * 10.0F;
			float pos2 = random.nextFloat() * 2.0F + 1.0F + f2 * 2.0F;
			buffer.begin(GL11.GL_TRIANGLE_FAN, DefaultVertexFormats.POSITION_COLOR);
			buffer.pos(0.0D, 0.0D, 0.0D).color(0, 0, 0, (int) (255.0F * (1.0F - f2))).endVertex();
			buffer.pos(-0.866D * (double) pos2, (double) pos1, (double) (-0.5F * pos2)).color(0, 0, 255, 0).endVertex();
			buffer.pos(0.866D * (double) pos2, (double) pos1, (double) (-0.5F * pos2)).color(0, 0, 255, 0).endVertex();
			buffer.pos(0.0D, (double) pos1, (double) (1.0F * pos2)).color(0, 0, 255, 0).endVertex();
			buffer.pos(-0.866D * (double) pos2, (double) pos1, (double) (-0.5F * pos2)).color(0, 0, 255, 0).endVertex();
			tessellator.draw();
		}
		GlStateManager.popMatrix();
		GlStateManager.depthMask(true);
		GlStateManager.disableCull();
		GlStateManager.disableBlend();
		GL11.glShadeModel(GL11.GL_FLAT);
		GlStateManager.color(1.0F, 1.0F, 1.0F, 1.0F);
		GlStateManager.enableTexture2D();
		GlStateManager.enableAlpha();
		RenderHelper.enableStandardItemLighting();
	}

@Override
    public void doRender(EntityDecayPitTarget entity, double x, double y, double z, float entityYaw, float partialTicks) {
		int frameCounter = RenderUtils.getFrameCounter();

		if(entity.renderedFrame != frameCounter) {
			entity.renderedFrame = frameCounter;


			this.renderBeams(entity, x, y, z, entityYaw, partialTicks, true);

			double smoothedMainX = entity.prevPosX + (entity.posX - entity.prevPosX ) * partialTicks;
			double smoothedMainY = entity.prevPosY + (entity.posY - entity.prevPosY ) * partialTicks;
			double smoothedMainZ = entity.prevPosZ + (entity.posZ - entity.prevPosZ ) * partialTicks;

			GlStateManager.enableBlend();
			GlStateManager.blendFunc(SourceFactor.SRC_ALPHA, DestFactor.ONE_MINUS_SRC_ALPHA);
			GlStateManager.color(1, 1, 1, 1);

			GlStateManager.disableCull();

			GlStateManager.pushMatrix();
			GlStateManager.translate(x, y + 1.5F, z);
			GlStateManager.scale(-1F, -1F, 1F);

			bindTexture(PLUG_TEXTURE);
			PLUG_MODEL.render(0.0625F);

			renderPlugGlowLayer(entity, 0.0625F);

			GlStateManager.popMatrix();	

			EntityDecayPitTargetPart hitPart = null;

			if(this.getRenderManager().isDebugBoundingBox()) {
				hitPart = entity.rayTraceShields(Minecraft.getMinecraft().player.getPositionEyes(partialTicks), Minecraft.getMinecraft().player.getLook(partialTicks));
			}

			for (EntityDecayPitTargetPart part : entity.parts) {
				float floatate = part.prevRotationYaw + (part.rotationYaw - part.prevRotationYaw) * partialTicks;
				double smoothedX = part.prevPosX  + (part.posX - part.prevPosX ) * partialTicks;
				double smoothedY = part.prevPosY  + (part.posY - part.prevPosY ) * partialTicks;
				double smoothedZ = part.prevPosZ  + (part.posZ - part.prevPosZ ) * partialTicks;
				if (part != entity.target_north  && part != entity.target_east && part != entity.target_south && part != entity.target_west && part != entity.bottom) {
					if(hitPart == part) {
						GlStateManager.color(1, 0, 0, 1);
					}

					renderCogShield(part, x + smoothedX - smoothedMainX, y + smoothedY - smoothedMainY, z + smoothedZ - smoothedMainZ, floatate);

					GlStateManager.color(1, 1, 1, 1);
				}
			}

			GlStateManager.enableBlend();
			GlStateManager.blendFunc(SourceFactor.SRC_ALPHA, DestFactor.ONE_MINUS_SRC_ALPHA);
			GlStateManager.color(1, 1, 1, 1);

			GlStateManager.pushMatrix();
			GlStateManager.translate(x, y + 4.5F, z);
			GlStateManager.scale(-1F, -1F, 1F);

			bindTexture(TARGET_TEXTURE);
			TARGET_MODEL.render(0.0625F);

			renderTargetGlowLayer(entity, 0.0625F);

			GlStateManager.popMatrix();	

			GlStateManager.disableBlend();
		}
	}

private void renderBeams(EntityDecayPitTarget entity, double x, double y, double z, float entityYaw, float partialTicks, boolean innerBeams) {
		double yStart = entity.height - 1D;

		for(int i = 0; i < 4; i++) {
			float beamAlpha = entity.beamTransparencyTicks[i] / 15.0F;

			double diffX2 = i == 0 ? 1.7D : i == 1 ? -1.7D : 0;
			double diffY2 = 0;
			double diffZ2 = i == 2 ? 1.7D : i == 3 ? -1.7D : 0;

			double diffX = i == 0 ? 12 : i == 1 ? -12 : 0;
			double diffY = 2.5D + entity.getProgress() * entity.MOVE_UNIT - yStart;
			double diffZ = i == 2 ? 12 : i == 3 ? -12 : 0;

			LightingUtil.INSTANCE.setLighting(255);

			GlStateManager.disableLighting();
			GlStateManager.enableBlend();
			GlStateManager.blendFunc(SourceFactor.SRC_ALPHA, DestFactor.ONE);
			GlStateManager.alphaFunc(GL11.GL_GREATER, 0.0f);
			GlStateManager.disableCull();

			this.bindTexture(BEAM_TEXTURE);

			GlStateManager.pushMatrix();
			GlStateManager.translate(x, y + yStart, z);

			Tessellator tessellator = Tessellator.getInstance();
			BufferBuilder buffer = tessellator.getBuffer();

			GlStateManager.depthMask(false);

			buffer.begin(GL11.GL_QUADS, DefaultVertexFormats.POSITION_TEX_COLOR);

			if(innerBeams) {
				ParticleBeam.buildBeam(diffX2, diffY2, diffZ2, new Vec3d(-diffX2, -diffY2, -diffZ2), 0.4F, 0, 4F,
						ActiveRenderInfo.getRotationX(), ActiveRenderInfo.getRotationZ(), ActiveRenderInfo.getRotationYZ(), ActiveRenderInfo.getRotationXY(), ActiveRenderInfo.getRotationXZ(),
						(vx, vy, vz, u, v) -> {
							buffer.pos(vx, vy, vz).tex(u + (entity.ticksExisted + partialTicks) * 0.15F, v).color(255, 255, 255, (int)(beamAlpha * 255)).endVertex();
						});
			} else {
				ParticleBeam.buildBeam(diffX, diffY, diffZ, new Vec3d(-(diffX - diffX2), -(diffY - diffY2), -(diffZ - diffZ2)), 0.4F, 0, 4F,
						ActiveRenderInfo.getRotationX(), ActiveRenderInfo.getRotationZ(), ActiveRenderInfo.getRotationYZ(), ActiveRenderInfo.getRotationXY(), ActiveRenderInfo.getRotationXZ(),
						(vx, vy, vz, u, v) -> {
							buffer.pos(vx, vy, vz).tex(u + (entity.ticksExisted + partialTicks) * 0.15F, v).color(255, 255, 255, (int)(beamAlpha * 255)).endVertex();
						});
			}

			tessellator.draw();

			GlStateManager.alphaFunc(GL11.GL_GREATER, Math.max(0, 0.5f + (beamAlpha - 1) * 0.5f));

			GlStateManager.depthMask(true);
			GlStateManager.colorMask(false, false, false, false);

			buffer.begin(GL11.GL_QUADS, DefaultVertexFormats.POSITION_TEX_COLOR);

			if(innerBeams) {
				ParticleBeam.buildBeam(diffX2, diffY2, diffZ2, new Vec3d(-diffX2, -diffY2, -diffZ2), 0.4F, 0, 4F,
						ActiveRenderInfo.getRotationX(), ActiveRenderInfo.getRotationZ(), ActiveRenderInfo.getRotationYZ(), ActiveRenderInfo.getRotationXY(), ActiveRenderInfo.getRotationXZ(),
						(vx, vy, vz, u, v) -> {
							buffer.pos(vx, vy, vz).tex(u + (entity.ticksExisted + partialTicks) * 0.15F, v).color(255, 255, 255, (int)(beamAlpha * 255)).endVertex();
						});
			} else {
				ParticleBeam.buildBeam(diffX, diffY, diffZ, new Vec3d(-(diffX - diffX2), -(diffY - diffY2), -(diffZ - diffZ2)), 0.4F, 0, 4F,
						ActiveRenderInfo.getRotationX(), ActiveRenderInfo.getRotationZ(), ActiveRenderInfo.getRotationYZ(), ActiveRenderInfo.getRotationXY(), ActiveRenderInfo.getRotationXZ(),
						(vx, vy, vz, u, v) -> {
							buffer.pos(vx, vy, vz).tex(u + (entity.ticksExisted + partialTicks) * 0.15F, v).color(255, 255, 255, (int)(beamAlpha * 255)).endVertex();
						});
			}

			tessellator.draw();

			GlStateManager.colorMask(true, true, true, true);

			GlStateManager.popMatrix();

			GlStateManager.enableCull();
			GlStateManager.alphaFunc(GL11.GL_GREATER, 0.1f);
			GlStateManager.enableLighting();

			GlStateManager.enableBlend();
			GlStateManager.blendFunc(SourceFactor.SRC_ALPHA, DestFactor.ONE_MINUS_SRC_ALPHA);
			GlStateManager.color(1, 1, 1, 1);

			LightingUtil.INSTANCE.revert();
		}
	}

private void renderCogShield(EntityDecayPitTargetPart entity, double x, double y, double z, float angle) {
		GlStateManager.pushMatrix();
		bindTexture(SHIELD_TEXTURE);
		GlStateManager.translate(x, y + 1.5F, z);
		GlStateManager.scale(-1F, -1F, 1F);
		GlStateManager.rotate(angle, 0F, 1F, 0F);
		SHIELD_MODEL.render(0.0625F);
		GlStateManager.popMatrix();
	}

@Override
	public void doRender(EntityDraeton entity, double x, double y, double z, float entityYaw, float partialTicks) {
		GlStateManager.pushMatrix();
		GlStateManager.translate(x, y, z);
		GlStateManager.enableRescaleNormal();

		GlStateManager.color(1, 1, 1, 1);
		GlStateManager.disableBlend();
		GlStateManager.depthMask(true);

		if (this.renderOutlines) {
			GlStateManager.enableColorMaterial();
			GlStateManager.enableOutlineMode(this.getTeamColor(entity));
		}

		Tessellator tessellator = Tessellator.getInstance();
		BufferBuilder buffer = tessellator.getBuffer();

		if(this.renderManager.isDebugBoundingBox()) {
			GlStateManager.depthMask(false);
			GlStateManager.disableTexture2D();
			GlStateManager.disableLighting();
			GlStateManager.disableCull();
			GlStateManager.disableBlend();

			for(DraetonPhysicsPart part : entity.physicsParts) {
				double pinterpX = part.prevX + (part.x - part.prevX) * partialTicks - this.renderManager.renderPosX;
				double pinterpY = part.prevY + (part.y - part.prevY) * partialTicks - this.renderManager.renderPosY;
				double pinterpZ = part.prevZ + (part.z - part.prevZ) * partialTicks - this.renderManager.renderPosZ;

				AxisAlignedBB aabb = part.getAabb().offset(pinterpX - x - part.x, pinterpY - y - part.y, pinterpZ - z - part.z);

				RenderGlobal.drawBoundingBox(aabb.minX, aabb.minY, aabb.minZ, aabb.maxX, aabb.maxY, aabb.maxZ, 0, 1, 0, 1);
			}

			Vec3d balloonPos = entity.getBalloonPos(partialTicks);

			double binterpX = balloonPos.x - this.renderManager.renderPosX;
			double binterpY = balloonPos.y - this.renderManager.renderPosY;
			double binterpZ = balloonPos.z - this.renderManager.renderPosZ;

			AxisAlignedBB balloonAabb = new AxisAlignedBB(-0.3f, -0.3f, -0.3f, 0.3f, 0.3f, 0.3f).offset(binterpX - x, binterpY - y, binterpZ - z);
			RenderGlobal.drawBoundingBox(balloonAabb.minX, balloonAabb.minY, balloonAabb.minZ, balloonAabb.maxX, balloonAabb.maxY, balloonAabb.maxZ, 0, 0, 1, 1);

			GlStateManager.enableTexture2D();
			GlStateManager.enableLighting();
			GlStateManager.enableCull();
			GlStateManager.disableBlend();
			GlStateManager.depthMask(true);
		}


		for(int i = 0; i < 8; i++) {
			GlStateManager.pushMatrix();

			Vec3d balloonPos = entity.getBalloonRopeConnection(i, partialTicks);

			double binterpX = balloonPos.x - this.renderManager.renderPosX;
			double binterpY = balloonPos.y - this.renderManager.renderPosY;
			double binterpZ = balloonPos.z - this.renderManager.renderPosZ;

			Vec3d connectionPoint = entity.getCarriageRopeConnection(i, partialTicks);

			GlStateManager.translate(connectionPoint.x, connectionPoint.y, connectionPoint.z);

			this.renderConnection(tessellator, buffer, 0, 0, 0, binterpX - x - connectionPoint.x, binterpY - y - connectionPoint.y + 0.05f, binterpZ - z - connectionPoint.z);

			GlStateManager.popMatrix();
		}

		for(DraetonPhysicsPart part : entity.physicsParts) {
			GlStateManager.pushMatrix();

			Vec3d pullPoint = entity.getPullPoint(part, partialTicks);
			GlStateManager.translate(pullPoint.x, pullPoint.y, pullPoint.z);

			if(part.type == DraetonPhysicsPart.Type.PULLER) {
				Entity pullerEntity = part.getEntity();
				if(pullerEntity != null) {
					double dinterpX = pullerEntity.lastTickPosX + (pullerEntity.posX - pullerEntity.lastTickPosX) * partialTicks - this.renderManager.renderPosX;
					double dinterpY = pullerEntity.lastTickPosY + (pullerEntity.posY - pullerEntity.lastTickPosY) * partialTicks - this.renderManager.renderPosY;
					double dinterpZ = pullerEntity.lastTickPosZ + (pullerEntity.posZ - pullerEntity.lastTickPosZ) * partialTicks - this.renderManager.renderPosZ;

					this.renderConnection(tessellator, buffer, 0, 0, 0, dinterpX - x - pullPoint.x, dinterpY - y - pullPoint.y + 0.25f, dinterpZ - z - pullPoint.z);
				}
			} else if(entity.upgradeAnchorPart.isEnabled()) {
				double dinterpX = part.prevX + (part.x - part.prevX) * partialTicks - this.renderManager.renderPosX;
				double dinterpY = part.prevY + (part.y - part.prevY) * partialTicks - this.renderManager.renderPosY;
				double dinterpZ = part.prevZ + (part.z - part.prevZ) * partialTicks - this.renderManager.renderPosZ;

				this.renderConnection(tessellator, buffer, 0, 0, 0, dinterpX - x - pullPoint.x, dinterpY - y - pullPoint.y + 0.25f, dinterpZ - z - pullPoint.z);

				GlStateManager.translate(dinterpX - x - pullPoint.x, dinterpY - y - pullPoint.y + 0.3f, dinterpZ - z - pullPoint.z);
				GlStateManager.scale(-1, -1, 1);

				this.bindTexture(TEXTURE_ANCHOR);
				this.modelAnchor.render(entity, 0, 0, 0, 0, 0, 0.0625F);
			}

			GlStateManager.popMatrix();
		}

		Vec3d balloonPos = entity.getBalloonPos(partialTicks);

		double binterpX = balloonPos.x - this.renderManager.renderPosX;
		double binterpY = balloonPos.y - this.renderManager.renderPosY;
		double binterpZ = balloonPos.z - this.renderManager.renderPosZ;

		GlStateManager.color(1, 1, 1, 1);
		GlStateManager.enableBlend();
		GlStateManager.blendFunc(SourceFactor.SRC_ALPHA, DestFactor.ONE_MINUS_SRC_ALPHA);

		GlStateManager.pushMatrix();
		GlStateManager.translate(binterpX - x, binterpY - y, binterpZ - z);
		GlStateManager.scale(-1, -1, 1);

		GlStateManager.rotate(entityYaw, 0, 1, 0);
		GlStateManager.rotate(entity.prevRotationPitch + (entity.rotationPitch - entity.prevRotationPitch) * partialTicks, 1, 0, 0);
		GlStateManager.rotate(entity.prevRotationRoll + (entity.rotationRoll - entity.prevRotationRoll) * partialTicks, 0, 0, 1);


		GlStateManager.pushMatrix();
		GlStateManager.translate(0, 22.0f / 16.0f, 0);

		this.bindTexture(TEXTURE_BALLOON);
		this.modelBalloon.render(0.0625f);

		GlStateManager.popMatrix();



		GlStateManager.depthMask(false);

		this.bindTexture(TEXTURE_LEAKAGE_HOLE);

		for(DraetonLeakage leakage : entity.getLeakages()) {
			GlStateManager.pushMatrix();

			GlStateManager.translate(-leakage.pos.x, -leakage.pos.y, leakage.pos.z);

			Vec3d up = new Vec3d(0, 0.7071f, 0.7071f);

			Vec3d normal = new Vec3d(-leakage.dir.x, -leakage.dir.y, leakage.dir.z);

			Vec3d side = normal.crossProduct(up).normalize();
			Vec3d side2 = side.crossProduct(normal).normalize();

			side = side.scale(0.5f);
			side2 = side2.scale(0.5f);

			buffer.begin(GL11.GL_QUADS, DefaultVertexFormats.POSITION_TEX_NORMAL);

			buffer.pos(-side.x - side2.x, -side.y - side2.y, -side.z - side2.z).tex(0, 0).normal((float)-normal.x, (float)-normal.y, (float)normal.z).endVertex();
			buffer.pos(-side.x + side2.x, -side.y + side2.y, -side.z + side2.z).tex(0, 1).normal((float)-normal.x, (float)-normal.y, (float)normal.z).endVertex();
			buffer.pos(side.x+- side2.x, side.y + side2.y, side.z + side2.z).tex(1, 1).normal((float)-normal.x, (float)-normal.y, (float)normal.z).endVertex();
			buffer.pos(side.x - side2.x, side.y - side2.y, side.z - side2.z).tex(1, 0).normal((float)-normal.x, (float)-normal.y, (float)normal.z).endVertex();

			tessellator.draw();

			GlStateManager.popMatrix();
		}

		GlStateManager.depthMask(true);


		GlStateManager.popMatrix();

		GlStateManager.translate(0, 1.5F, 0);
		GlStateManager.scale(-1, -1, 1);

		GlStateManager.rotate(entityYaw, 0, 1, 0);
		GlStateManager.rotate(entity.prevRotationPitch + (entity.rotationPitch - entity.prevRotationPitch) * partialTicks, 1, 0, 0);
		GlStateManager.rotate(entity.prevRotationRoll + (entity.rotationRoll - entity.prevRotationRoll) * partialTicks, 0, 0, 1);

		float timeSinceHit = entity.getTimeSinceHit() - partialTicks;
		float damageTaken = entity.getDamageTaken() - partialTicks;

		if (damageTaken < 0.0F) {
			damageTaken = 0.0F;
		}

		if (timeSinceHit > 0.0F) {
			GlStateManager.rotate(MathHelper.sin(timeSinceHit) * timeSinceHit * damageTaken / 10.0F, 0, 0, 1);
		}


		GlStateManager.rotate(180, 0, 1, 0);

		this.bindEntityTexture(entity);
		this.modelCarriage.renderCarriage(0.0625F);


		GlStateManager.disableBlend();
		GlStateManager.color(1, 1, 1, 1);

		IInventory upgrades = entity.getUpgradesInventory();
		for(int i = 0; i < 5; i++) {
			ItemStack upgrade = upgrades.getStackInSlot(i);
			if(!upgrade.isEmpty()) {
				Vec3d upgradePos = entity.getUpgradePoint(i, 0);

				ModelBase upgradeModel = null;

				if(entity.isAnchorUpgrade(upgrade)) {
					GlStateManager.pushMatrix();

					float ropeOffset = ((entity.prevPulleyRotation + (entity.pulleyRotation - entity.prevPulleyRotation) * partialTicks) * 0.0015f) % (1 / 24.0f * 0.7f * 2);

					GlStateManager.translate(upgradePos.x - 0.015f, upgradePos.y - ropeOffset, -upgradePos.z + 0.1f);

					this.renderConnection(tessellator, buffer, 0, 0, 0, 0, -0.7f, 0);

					GlStateManager.popMatrix();

					upgradeModel = this.modelPulley;
					this.bindTexture(TEXTURE_PULLEY);
				} else if(entity.isFurnaceUpgrade(upgrade)) {
					upgradeModel = this.modelFurnace;
					this.bindTexture(TEXTURE_FURNACE);
				} else if(entity.isStorageUpgrade(upgrade)) {
					upgradeModel = this.modelStorage;
					this.bindTexture(TEXTURE_STORAGE);
				} else if(entity.isCraftingUpgrade(upgrade)) {
					upgradeModel = this.modelCrafting;
					this.bindTexture(TEXTURE_CRAFTING);
				}


				if(upgradeModel != null) {
					entity.upgradeCounterRoll = entity.getUpgradeCounterRoll(i, partialTicks);
					entity.upgradeOpenTicks = entity.getUpgradeOpenTicks(i, partialTicks);

					GlStateManager.pushMatrix();
					GlStateManager.translate(upgradePos.x, upgradePos.y, -upgradePos.z);
					GlStateManager.rotate(entity.getUpgradeRotY(i), 0, 1, 0);

					upgradeModel.render(entity, 0.0f, 0.0f, entity.ticksExisted + partialTicks, 0.0f, 0.0f, 0.0625f);

					GlStateManager.popMatrix();
				}
			}
		}

		ItemStack displayStack = entity.getUpgradesInventory().getStackInSlot(5);
		if(!displayStack.isEmpty()) {
			GlStateManager.scale(-1, -1, 1);
			GlStateManager.translate(0, -0.35f, -0.84f);
			GlStateManager.rotate(180.0F, 0.0F, 1.0F, 0.0F);
			GlStateManager.scale(0.5f, 0.5f, 0.5f);

			Entity controller = entity.getControllingPassenger();

			this.renderFrame(entity.world, displayStack, controller instanceof EntityLivingBase ? (EntityLivingBase)controller : null);
		}

		GlStateManager.popMatrix();

		if (this.renderOutlines) {
			GlStateManager.disableOutlineMode();
			GlStateManager.disableColorMaterial();
		}

		GlStateManager.disableRescaleNormal();

		super.doRender(entity, x, y, z, entityYaw, partialTicks);
	}

protected void renderFrame(World world, ItemStack stack, @Nullable EntityLivingBase entity) {
		this.renderManager.renderEngine.bindTexture(TextureMap.LOCATION_BLOCKS_TEXTURE);
		BlockRendererDispatcher blockrendererdispatcher = this.mc.getBlockRendererDispatcher();
		ModelManager modelmanager = blockrendererdispatcher.getBlockModelShapes().getModelManager();
		IBakedModel model;

		GlStateManager.pushMatrix();

		if (stack.getItem() instanceof net.minecraft.item.ItemMap) {
			model = modelmanager.getModel(FRAME_MAP_MODEL);
		} else {
			model = modelmanager.getModel(FRAME_MODEL);

			GlStateManager.scale(1.3f, 1.3f, 1.3f);
			GlStateManager.translate(0, 0, -0.115f);
		}

		GlStateManager.pushMatrix();
		GlStateManager.translate(-0.5F, -0.5F, -0.5F);
		blockrendererdispatcher.getBlockModelRenderer().renderModelBrightnessColor(model, 1.0F, 1.0F, 1.0F, 1.0F);
		GlStateManager.popMatrix();

		GlStateManager.pushMatrix();
		GlStateManager.translate(0.0F, 0.0F, 0.4375F);
		this.renderItem(world, stack, entity);
		GlStateManager.popMatrix();

		GlStateManager.popMatrix();
	}

protected void renderItem(World world, ItemStack itemstack, @Nullable EntityLivingBase entity)
	{
		if (!itemstack.isEmpty())
		{
			GlStateManager.pushMatrix();
			GlStateManager.disableLighting();
			boolean isMap = itemstack.getItem() instanceof net.minecraft.item.ItemMap;

			if (isMap)
			{
				this.renderManager.renderEngine.bindTexture(MAP_BACKGROUND_TEXTURES);
				GlStateManager.rotate(180.0F, 0.0F, 0.0F, 1.0F);
				GlStateManager.scale(0.0078125F, 0.0078125F, 0.0078125F);
				GlStateManager.translate(-64.0F, -64.0F, 0.0F);
				MapData mapdata = ((net.minecraft.item.ItemMap) itemstack.getItem()).getMapData(itemstack, world);
				GlStateManager.translate(0.0F, 0.0F, -1.0F);

				if (mapdata != null)
				{
					this.mc.entityRenderer.getMapItemRenderer().renderMap(mapdata, false);
				}
			}
			else
			{
				GlStateManager.scale(0.5F, 0.5F, 0.5F);
				GlStateManager.pushAttrib();
				RenderHelper.enableStandardItemLighting();

				if(entity != null) {
					this.mc.getRenderItem().renderItem(itemstack, entity, ItemCameraTransforms.TransformType.FIXED, false);
				} else {
					this.mc.getRenderItem().renderItem(itemstack, ItemCameraTransforms.TransformType.FIXED);
				}

				RenderHelper.disableStandardItemLighting();
				GlStateManager.popAttrib();
			}

			GlStateManager.enableLighting();
			GlStateManager.popMatrix();
		}
	}

protected void renderConnection(Tessellator tessellator, BufferBuilder buffer, double x1, double y1, double z1, double x2, double y2, double z2) {
		double x = 0;
		double y = 0;
		double z = 0;

		double startX = x1;
		double startY = y1;
		double startZ = z1;
		double endX = x2;
		double endY = y2;
		double endZ = z2;

		double diffX = (double)((float)(endX - startX));
		double diffY = (double)((float)(endY - startY));
		double diffZ = (double)((float)(endZ - startZ));

		GlStateManager.disableTexture2D();
		GlStateManager.disableLighting();
		GlStateManager.disableCull();

		buffer.begin(GL11.GL_TRIANGLE_STRIP, DefaultVertexFormats.POSITION_COLOR);
		for (int i = 0; i <= 24; ++i) {
			float r;
			float g;
			float b;

			if (i % 2 == 0) {
				r = 29.0f / 255.0f;
				g = 72.0f / 255.0f;
				b = 29.0f / 255.0f;
			} else {
				r = 21.0f / 255.0f;
				g = 52.0f / 255.0f;
				b = 21.0f / 255.0f;
			}

			float percentage = (float)i / 24.0F;
			double yMult = endY < startY ? percentage*Math.sqrt(percentage) : percentage * percentage;

			buffer.pos(x + diffX * (double)percentage + 0.0D, y + diffY * (double)(yMult + percentage) * 0.5D, z + diffZ * (double)percentage).color(r, g, b, 1).endVertex();
			buffer.pos(x + diffX * (double)percentage + 0.025D, y + diffY * (double)(yMult + percentage) * 0.5D + 0.025D, z + diffZ * (double)percentage).color(r, g, b, 1).endVertex();
		}
		tessellator.draw();

		buffer.begin(GL11.GL_TRIANGLE_STRIP, DefaultVertexFormats.POSITION_COLOR);
		for (int i = 0; i <= 24; ++i) {
			float r;
			float g;
			float b;

			if (i % 2 == 0) {
				r = 29.0f / 255.0f;
				g = 72.0f / 255.0f;
				b = 29.0f / 255.0f;
			} else {
				r = 21.0f / 255.0f;
				g = 52.0f / 255.0f;
				b = 21.0f / 255.0f;
			}

			float percentage = (float)i / 24.0F;
			double yMult = endY < startY ? percentage*Math.sqrt(percentage) : percentage * percentage;

			buffer.pos(x + diffX * (double)percentage + 0.0D, y + diffY * (double)(yMult + percentage) * 0.5D + 0.025D, z + diffZ * (double)percentage).color(r, g, b, 1).endVertex();
			buffer.pos(x + diffX * (double)percentage + 0.025D, y + diffY * (double)(yMult + percentage) * 0.5D, z + diffZ * (double)percentage + 0.025D).color(r, g, b, 1).endVertex();
		}
		tessellator.draw();

		GlStateManager.enableLighting();
		GlStateManager.enableTexture2D();
		GlStateManager.enableCull();
	}

@Override
	public void doRender(EntityFirefly entity, double x, double y, double z, float yaw, float partialTicks) {
		double glowStrength = (float)entity.getEntityAttribute(EntityFirefly.GLOW_STRENGTH_ATTRIB).getAttributeValue();
		double scale = entity.getGlowTicks(partialTicks) / 20.0F * glowStrength;

		if(MinecraftForgeClient.getRenderPass() == 0) {

			this.glow.setAlpha(entity.getGlowTicks(partialTicks) / 20.0F * (float)Math.min(glowStrength, 1.0D));

			GlStateManager.pushMatrix();
			GlStateManager.translate(0, Math.sin((entity.ticksExisted + partialTicks) / 10.0F) * 0.15F, 0);
			super.doRender(entity, x, y, z, yaw, partialTicks);
			GlStateManager.popMatrix();

			if (ShaderHelper.INSTANCE.isWorldShaderActive()) {
				float radius = (float) scale * 7.0F;

				if(radius > 0.1F) {
					double interpX = entity.lastTickPosX + (entity.posX - entity.lastTickPosX) * partialTicks;
					double interpY = entity.lastTickPosY + (entity.posY - entity.lastTickPosY) * partialTicks - 0.5D;
					double interpZ = entity.lastTickPosZ + (entity.posZ - entity.lastTickPosZ) * partialTicks;
					addFireflyLight(interpX, interpY, interpZ, radius);
				}
			}
		} else {
			GlStateManager.disableLighting();
			renderFireflyGlow(x, y + 0.25D + Math.sin((entity.ticksExisted + partialTicks) / 10.0F) * 0.15F, z, scale);
			GlStateManager.enableLighting();
		}
	}

public static void renderFireflyGlow(double x, double y, double z, double scale) {
		Tessellator tessellator = Tessellator.getInstance();
		BufferBuilder buffer = tessellator.getBuffer();

		GlStateManager.pushMatrix();
		GlStateManager.depthMask(false);
		GlStateManager.enableBlend();
		GlStateManager.color(1, 1, 1, 1);
		GlStateManager.blendFunc(GL11.GL_SRC_ALPHA, GL11.GL_ONE);
		GlStateManager.alphaFunc(GL11.GL_GREATER, 0.003921569F);

		Minecraft.getMinecraft().getTextureManager().bindTexture(GLOW_TEXTURE);

		buffer.begin(GL11.GL_QUADS, DefaultVertexFormats.POSITION_TEX_COLOR);

		float rx = ActiveRenderInfo.getRotationX();
		float rxz = ActiveRenderInfo.getRotationXZ();
		float rz = ActiveRenderInfo.getRotationZ();
		float ryz = ActiveRenderInfo.getRotationYZ();
		float rxy = ActiveRenderInfo.getRotationXY();

		float red = 0.4F;
		float green = 0.2F;
		float blue = 0.0F;
		float alpha = 0.3F;

		if (RANDOM.nextInt(10) <= 2) {
			red = 0.4F + RANDOM.nextFloat() * 0.3F;
		}

		double currentScale = scale;

		for (int i = 0; i < 10; i++) {
			currentScale -= scale * 0.15D;
			buffer.pos(x - rx * currentScale - ryz * currentScale, y - rxz * currentScale, z - rz * currentScale - rxy * currentScale).tex(0.0, 1.0).color(red, green, blue, alpha).endVertex();
			buffer.pos(x - rx * currentScale + ryz * currentScale, y + rxz * currentScale, z - rz * currentScale + rxy * currentScale).tex(1.0D, 1.0D).color(red, green, blue, alpha).endVertex();
			buffer.pos(x + rx * currentScale + ryz * currentScale, y + rxz * currentScale, z + rz * currentScale + rxy * currentScale).tex(1.0D, 0.0D).color(red, green, blue, alpha).endVertex();
			buffer.pos(x + rx * currentScale - ryz * currentScale, y - rxz * currentScale, z + rz * currentScale - rxy * currentScale).tex(0.0D, 0.0D).color(red, green, blue, alpha).endVertex();
		}

		red = 0.6F;
		green = 0.6F;
		blue = 0.6F;

		currentScale = scale / 4.0D;
		for (int i = 0; i < 10; i++) {
			currentScale -= scale * 0.15D / 4.0D;
			buffer.pos(x - rx * currentScale - ryz * currentScale, y - rxz * currentScale, z - rz * currentScale - rxy * currentScale).tex(0.0D, 1.0D).color(red, green, blue, alpha).endVertex();
			buffer.pos(x - rx * currentScale + ryz * currentScale, y + rxz * currentScale, z - rz * currentScale + rxy * currentScale).tex(1.0D, 1.0D).color(red, green, blue, alpha).endVertex();
			buffer.pos(x + rx * currentScale + ryz * currentScale, y + rxz * currentScale, z + rz * currentScale + rxy * currentScale).tex(1.0D, 0.0D).color(red, green, blue, alpha).endVertex();
			buffer.pos(x + rx * currentScale - ryz * currentScale, y - rxz * currentScale, z + rz * currentScale - rxy * currentScale).tex(0.0D, 0.0D).color(red, green, blue, alpha).endVertex();
		}

		tessellator.draw();

		GlStateManager.depthMask(false);
		GlStateManager.popMatrix();

		GlStateManager.blendFunc(GL11.GL_SRC_ALPHA, GL11.GL_ONE_MINUS_SRC_ALPHA);
	}

@Override
	public void doRender(EntityFishingSpear entity, double x, double y, double z, float entityYaw, float partialTicks) {
		bindEntityTexture(entity);
		GlStateManager.color(1.0F, 1.0F, 1.0F, 1.0F);
		GlStateManager.pushMatrix();
		GlStateManager.disableLighting();
		GlStateManager.translate((float) x, (float) y, (float) z);
		GlStateManager.rotate(entity.prevRotationYaw + (entity.rotationYaw - entity.prevRotationYaw) * partialTicks - 90.0F, 0.0F, 1.0F, 0.0F);
		GlStateManager.rotate(entity.prevRotationPitch + (entity.rotationPitch - entity.prevRotationPitch) * partialTicks - 45.0F, 0.0F, 0.0F, 1.0F);
		float shake = (float) entity.arrowShake - partialTicks;

		if (shake > 0.0F) {
			float f10 = -MathHelper.sin(shake * 3.0F) * shake;
			GlStateManager.rotate(f10, 0.0F, 0.0F, 1.0F);
		}

		GlStateManager.rotate(-90.0F, 0.0F, 1.0F, 0.0F);
		GlStateManager.rotate(-45.0F, 1.0F, 0.0F, 0.0F);
		GlStateManager.scale(-1F, -1F, 1F);
		GlStateManager.translate(0F, 0.25F, 0F);

		if (this.renderOutlines) {
			GlStateManager.enableColorMaterial();
			GlStateManager.enableOutlineMode(this.getTeamColor(entity));
		}

		switch (entity.getType()) {
		case 0:
			SPEAR_MODEL.renderBasic(entity, partialTicks);
			break;
		case 1:
			SPEAR_MODEL.renderAmphibious(entity, partialTicks);
			break;
		case 2:
			SPEAR_MODEL.renderRobustAmphibious(entity, partialTicks);
			break;
		}

		if (this.renderOutlines) {
			GlStateManager.disableOutlineMode();
			GlStateManager.disableColorMaterial();
		}

		GlStateManager.enableLighting();
		GlStateManager.popMatrix();
		super.doRender(entity, x, y, z, entityYaw, partialTicks);

	}

@Override
	public void doRender(EntityFortressBoss entity, double x, double y, double z, float yaw, float partialTicks) {
		EntityFortressBoss boss = (EntityFortressBoss) entity;

		if(ShaderHelper.INSTANCE.isWorldShaderActive()) {
			WorldShader shader = ShaderHelper.INSTANCE.getWorldShader();
			if(boss.hurtResistantTime == 0) {
				float lightIntensity = 0.0F;
				for(int i = 0; i <= 19; i++) {
					float shieldAnimationTicks = boss.shield.getAnimationTicks(i) - 1.0F + partialTicks;
					if(shieldAnimationTicks > 0 && shieldAnimationTicks <= 20) {
						lightIntensity += shieldAnimationTicks / 20.0F * 2.0F;
					}
				}
				if(lightIntensity > 0.0F) {
					ShaderHelper.INSTANCE.require();
					shader.addLight(new LightSource(boss.posX, boss.posY, boss.posZ, 16.0F, 3.4F / 4.0F * MathHelper.clamp(lightIntensity, 0.0F, 4.0F), 0.0F / 4.0F * MathHelper.clamp(lightIntensity, 0.0F, 4.0F), 3.6F / 4.0F * MathHelper.clamp(lightIntensity, 0.0F, 4.0F)));
				}
			} else {
				ShaderHelper.INSTANCE.require();
				shader.addLight(new LightSource(boss.posX, boss.posY, boss.posZ, 16.0F, 1.5F / boss.maxHurtResistantTime * (boss.hurtResistantTime + partialTicks), 0, 0));
			}
		}

		/*if(this.getRenderManager().isDebugBoundingBox()) {
			GlStateManager.depthMask(false);
			GlStateManager.disableTexture2D();
			GlStateManager.disableCull();
			GlStateManager.disableBlend();
			RenderGlobal.func_189697_a(boss.coreBoundingBox.offset(boss.posX - x, boss.posY - y, boss.posZ - z), 1, 1, 1, 1);
			GlStateManager.enableLighting();
			GlStateManager.enableCull();
			GlStateManager.disableBlend();
			GlStateManager.depthMask(true);
		}*/

		GlStateManager.enableBlend();
		GlStateManager.pushMatrix();
		GlStateManager.enableTexture2D();
		GlStateManager.translate(x, y + (boss.coreBoundingBox.maxY-boss.coreBoundingBox.minY) / 2.0D + 0.15D, z);

		GlStateManager.blendFunc(SourceFactor.SRC_ALPHA, DestFactor.ONE_MINUS_SRC_ALPHA);
		GlStateManager.color(1, 1, 1, 1);
		this.bindTexture(MODEL_TEXTURE);
		GlStateManager.rotate(180, 1, 0, 0);
		GlStateManager.rotate(entity.prevRotationYaw + (entity.rotationYaw - entity.prevRotationYaw) * partialTicks, 0, 1, 0);
		GlStateManager.rotate(entity.prevRotationPitch + (entity.rotationPitch - entity.prevRotationPitch) * partialTicks, 1, 0, 0);
		GlStateManager.translate(0, -0.2D, 0);
		GlStateManager.translate(Math.sin((entity.ticksExisted + partialTicks)/5.0D) * 0.1F, Math.cos((entity.ticksExisted + partialTicks)/7.0D) * 0.1F, Math.cos((entity.ticksExisted + partialTicks)/6.0D) * 0.1F);
		GlStateManager.scale(0.55F, 0.55F, 0.55F);
		GlStateManager.disableCull();
		LightingUtil.INSTANCE.setLighting(255);
		MODEL.render(entity, entity.distanceWalkedModified, 360, entity.ticksExisted + partialTicks, 0, 0, 0.065F);
		LightingUtil.INSTANCE.revert();
		GlStateManager.enableCull();
		GlStateManager.popMatrix();

		GlStateManager.color(1, 1, 1, 1);
		GlStateManager.blendFunc(SourceFactor.SRC_ALPHA, DestFactor.ONE);

		GlStateManager.pushMatrix();
		GlStateManager.translate(x + EntityFortressBoss.SHIELD_OFFSET_X, y + EntityFortressBoss.SHIELD_OFFSET_Y, z + EntityFortressBoss.SHIELD_OFFSET_Z);

		renderShield(boss.shield,
				new Vec3d(boss.posX + EntityFortressBoss.SHIELD_OFFSET_X, boss.posY + EntityFortressBoss.SHIELD_OFFSET_Y, boss.posZ + EntityFortressBoss.SHIELD_OFFSET_Z),
				boss.getShieldRotationYaw(partialTicks), boss.getShieldRotationPitch(partialTicks), boss.getShieldRotationRoll(partialTicks), boss.getShieldExplosion(partialTicks),
				boss.ticksExisted, partialTicks,
				true, true, 1.0f, 1.0f, 1.0f, true);

		GlStateManager.popMatrix();

		if(boss.getGroundAttackTicks() > 0) {
			GlStateManager.pushMatrix();
			GlStateManager.translate(x, y - 2.8D, z);
			GlStateManager.enableTexture2D();
			this.bindTexture(SHIELD_TEXTURE);
			GlStateManager.matrixMode(GL11.GL_TEXTURE);
			GlStateManager.loadIdentity();
			float interpTicks = entity.ticksExisted + partialTicks;
			float uOffsetAttack = interpTicks * 0.01F;
			float vOffsetAttack = interpTicks * 0.01F;
			GlStateManager.translate(uOffsetAttack, vOffsetAttack, 0.0F);
			GlStateManager.matrixMode(GL11.GL_MODELVIEW);
			GlStateManager.enableBlend();
			GlStateManager.disableLighting();
			GlStateManager.blendFunc(SourceFactor.ONE, DestFactor.ONE);
			GlStateManager.scale(3.8D, 3.8D, 3.8D);
			GlStateManager.color(0.8F / 20.0F * boss.getGroundAttackTicks(), 0.6F / 20.0F * boss.getGroundAttackTicks(), 0.4F / 20.0F * boss.getGroundAttackTicks(), 1.0F);
			BULLET_MODEL.render(0.0625F);
			GlStateManager.enableCull();
			GlStateManager.matrixMode(GL11.GL_TEXTURE);
			GlStateManager.loadIdentity();
			GlStateManager.matrixMode(GL11.GL_MODELVIEW);
			GlStateManager.enableLighting();
			GlStateManager.disableBlend();
			GlStateManager.popMatrix();
		}

		LightingUtil.INSTANCE.revert();

		GlStateManager.enableLighting();
		GL11.glDisable(GL11.GL_LINE_SMOOTH);
		GlStateManager.blendFunc(SourceFactor.SRC_ALPHA, DestFactor.ONE_MINUS_SRC_ALPHA);
		GlStateManager.enableTexture2D();
	}

public static void renderShield(ProtectionShield shield, Vec3d centerPos, float shieldRotationYaw, float shieldRotationPitch, float shieldRotationRoll, float shieldExplosion, int tick, float partialTicks, boolean renderOutlines, boolean renderInside, float lineAlpha, float insideAlpha, float alpha, boolean depthMask) {
		GlStateManager.enableBlend();
		GlStateManager.enableTexture2D();

		GlStateManager.color(1, 1, 1, 1);
		GlStateManager.blendFunc(SourceFactor.SRC_ALPHA, DestFactor.ONE);
		GlStateManager.alphaFunc(GL11.GL_GREATER, 0.01f);

		GlStateManager.pushMatrix();

		//Rotate shield
		GlStateManager.rotate(shieldRotationPitch, 1, 0, 0);
		GlStateManager.rotate(shieldRotationYaw, 0, 1, 0);
		GlStateManager.rotate(shieldRotationRoll, 0, 0, 1);

		GlStateManager.disableTexture2D();		
		GlStateManager.disableLighting();
		GlStateManager.enableBlend();

		Tessellator tessellator = Tessellator.getInstance();
		BufferBuilder buffer = tessellator.getBuffer();

		LightingUtil.INSTANCE.setLighting(255);

		double explode = shieldExplosion;

		Minecraft.getMinecraft().getTextureManager().bindTexture(SHIELD_TEXTURE);

		float ticks = tick + partialTicks;

		GlStateManager.matrixMode(GL11.GL_TEXTURE);
		GlStateManager.loadIdentity();
		GlStateManager.pushMatrix();
		float uOffset = (ticks * 0.01F) % 1.0F;
		float vOffset = (ticks * 0.01F) % 1.0F;
		GlStateManager.translate(uOffset, vOffset, 0.0F);
		GlStateManager.matrixMode(GL11.GL_MODELVIEW);
		GlStateManager.enableTexture2D();

		GlStateManager.depthMask(false);
		for(int i = 0; i <= 19; i++) {
			if(!shield.isActive(i)) {
				continue;
			}

			float shieldAnimationTicks = shield.getAnimationTicks(i) - 1.0F + partialTicks;
			float r, g, b, a;
			if(shieldAnimationTicks > 0 && shieldAnimationTicks <= 20) {
				GlStateManager.blendFunc(SourceFactor.SRC_ALPHA, DestFactor.ONE_MINUS_SRC_ALPHA);
				r = 1F / 20 * (shieldAnimationTicks); g = 00.5F - 0.5F / 20 * (shieldAnimationTicks); b = 1F - 1F / 20 * (shieldAnimationTicks); a = 1F;
			} else if(shieldAnimationTicks > 20 && shieldAnimationTicks <= 40) {
				GlStateManager.blendFunc(SourceFactor.SRC_ALPHA, DestFactor.ONE);
				r = 0.4F; g = 1F; b = 1F - 0.9F / 20 * (shieldAnimationTicks-20); a = 0.95F;
			} else {
				GlStateManager.blendFunc(SourceFactor.SRC_ALPHA, DestFactor.ONE);
				r = 0.4F; g = 0.8F; b = 0.9F; a = 0.25F;
			}
			double v3[] = vertices[indices[i][0]];
			double v2[] = vertices[indices[i][1]];
			double v1[] = vertices[indices[i][2]];
			double centerX = (v1[0]+v2[0]+v3[0])/3;
			double centerY = (v1[1]+v2[1]+v3[1])/3;
			double centerZ = (v1[2]+v2[2]+v3[2])/3;
			double len = Math.sqrt(centerX*centerX + centerY*centerY + centerZ*centerZ);
			double textureScale = 4.0D;
			double cu = textureScale / 2.0D;
			double cv = textureScale * Math.sqrt(2) / 2.0D;
			int layers = 8;

			buffer.begin(GL11.GL_TRIANGLES, DefaultVertexFormats.POSITION_TEX_COLOR);

			for(int l = 0; l < ((shieldAnimationTicks > 0 && shieldAnimationTicks <= 20) ? 4 : layers); l++) {
				double cos = Math.cos(2.0D * Math.PI / layers * l);
				double sin = 1+Math.sin(2.0D * Math.PI / layers * l);
				double tu1 = 0.0D - cu;
				double tv1 = 0.0D - cv;
				double tu2 = textureScale / 2.0D / layers * l - cu;
				double tv2 = textureScale / layers * l * Math.sqrt(2) - cv;
				double tu3 = textureScale / layers * l - cu;
				double tv3 = 0.0D - cv;
				tu1 = cu + tu1 * sin;
				tv1 = cv + tv1 * cos;
				tu2 = cu + tu2 * sin;
				tv2 = cv + tv2 * cos;
				tu3 = cu + tu3 * sin;
				tv3 = cv + tv3 * cos;
				buffer.pos(v1[0]+centerX/len*explode, v1[1]+centerY/len*explode, v1[2]+centerZ/len*explode).tex(tu1, tv1).color(r, g, b, a * alpha).endVertex();
				buffer.pos(v2[0]+centerX/len*explode, v2[1]+centerY/len*explode, v2[2]+centerZ/len*explode).tex(tu2, tv2).color(r, g, b, a * alpha).endVertex();
				buffer.pos(v3[0]+centerX/len*explode, v3[1]+centerY/len*explode, v3[2]+centerZ/len*explode).tex(tu3, tv3).color(r, g, b, a * alpha).endVertex();
			}

			tessellator.draw();
		}
		if(depthMask) GlStateManager.depthMask(true);

		GlStateManager.disableTexture2D();
		GlStateManager.matrixMode(GL11.GL_TEXTURE);
		GlStateManager.loadIdentity();
		GlStateManager.popMatrix();
		GlStateManager.matrixMode(GL11.GL_MODELVIEW);
		GlStateManager.blendFunc(SourceFactor.SRC_ALPHA, DestFactor.ONE);

		buffer.begin(GL11.GL_TRIANGLES, DefaultVertexFormats.POSITION_COLOR);
		for(int i = 0; i <= 19; i++) {
			if(!shield.isActive(i))
				continue;
			double v3[] = vertices[indices[i][0]];
			double v2[] = vertices[indices[i][1]];
			double v1[] = vertices[indices[i][2]];
			double centerX = (v1[0]+v2[0]+v3[0])/3;
			double centerY = (v1[1]+v2[1]+v3[1])/3;
			double centerZ = (v1[2]+v2[2]+v3[2])/3;
			double len = Math.sqrt(centerX*centerX + centerY*centerY + centerZ*centerZ);
			buffer.pos(v1[0]+centerX/len*explode, v1[1]+centerY/len*explode, v1[2]+centerZ/len*explode).color(0.5F, 0.6F, 1F, 0.5F * alpha).endVertex();
			buffer.pos(v2[0]+centerX/len*explode, v2[1]+centerY/len*explode, v2[2]+centerZ/len*explode).color(0.5F, 0.6F, 1F, 0.5F * alpha).endVertex();
			buffer.pos(v3[0]+centerX/len*explode, v3[1]+centerY/len*explode, v3[2]+centerZ/len*explode).color(0.5F, 0.6F, 1F, 0.5F * alpha).endVertex();
		}
		tessellator.draw();

		GlStateManager.blendFunc(SourceFactor.SRC_ALPHA, DestFactor.ONE_MINUS_SRC_ALPHA);

		for(int p = 0; p < (renderInside ? 2 : 1); p++) {
			if(p == 1) {
				GlStateManager.cullFace(CullFace.FRONT);
				GlStateManager.depthMask(false);
			}
			buffer.begin(GL11.GL_TRIANGLES, DefaultVertexFormats.POSITION_COLOR);
			for(int i = 0; i <= 19; i++) {
				if(!shield.isActive(i))
					continue;
				double v3[] = vertices[indices[i][0]];
				double v2[] = vertices[indices[i][1]];
				double v1[] = vertices[indices[i][2]];
				double centerX = (v1[0]+v2[0]+v3[0])/3;
				double centerY = (v1[1]+v2[1]+v3[1])/3;
				double centerZ = (v1[2]+v2[2]+v3[2])/3;
				double len = Math.sqrt(centerX*centerX + centerY*centerY + centerZ*centerZ);
				double a = len + explode;
				Vec3d center = new Vec3d(centerX, centerY, centerZ);
				Vec3d vert1 = new Vec3d(v1[0], v1[1], v1[2]);
				double b = vert1.dotProduct(center);
				double d = a * Math.tan(b);
				double vertexExplode = Math.sqrt(a*a + d*d) - 1;
				Vec3d v1Normalized = new Vec3d(v1[0], v1[1], v1[2]).normalize();
				Vec3d v2Normalized = new Vec3d(v2[0], v2[1], v2[2]).normalize();
				Vec3d v3Normalized = new Vec3d(v3[0], v3[1], v3[2]).normalize();
				buffer.pos(v1[0]+v1Normalized.x*vertexExplode, v1[1]+v1Normalized.y*vertexExplode, v1[2]+v1Normalized.z*vertexExplode).color(0.05F, 0.05F, 0.05F, (p == 0 ? 0.45F : insideAlpha) * alpha).endVertex();
				buffer.pos(v2[0]+v2Normalized.x*vertexExplode, v2[1]+v2Normalized.y*vertexExplode, v2[2]+v2Normalized.z*vertexExplode).color(0.05F, 0.05F, 0.05F, (p == 0 ? 0.45F : insideAlpha) * alpha).endVertex();
				buffer.pos(v3[0]+v3Normalized.x*vertexExplode, v3[1]+v3Normalized.y*vertexExplode, v3[2]+v3Normalized.z*vertexExplode).color(0.05F, 0.05F, 0.05F, (p == 0 ? 0.45F : insideAlpha) * alpha).endVertex();
			}
			tessellator.draw();
		}

		GlStateManager.cullFace(CullFace.BACK);
		if(depthMask) GlStateManager.depthMask(true);

		GlStateManager.blendFunc(SourceFactor.SRC_ALPHA, DestFactor.ONE);

		if(Minecraft.getMinecraft().getRenderManager().isDebugBoundingBox()) {
			buffer.begin(GL11.GL_LINES, DefaultVertexFormats.POSITION_COLOR);
			for(int i = 0; i <= 19; i++) {
				if(!shield.isActive(i))
					continue;
				double v3[] = vertices[indices[i][0]];
				double v2[] = vertices[indices[i][1]];
				double v1[] = vertices[indices[i][2]];
				double centerX = (v1[0]+v2[0]+v3[0])/3;
				double centerY = (v1[1]+v2[1]+v3[1])/3;
				double centerZ = (v1[2]+v2[2]+v3[2])/3;
				double len = Math.sqrt(centerX*centerX + centerY*centerY + centerZ*centerZ);
				Vec3d vec1 = new Vec3d(v1[0]+centerX/len*explode, v1[1]+centerY/len*explode, v1[2]+centerZ/len*explode);
				Vec3d vec2 = new Vec3d(v2[0]+centerX/len*explode, v2[1]+centerY/len*explode, v2[2]+centerZ/len*explode);
				Vec3d vec3 = new Vec3d(v3[0]+centerX/len*explode, v3[1]+centerY/len*explode, v3[2]+centerZ/len*explode);
				Vec3d normal = vec2.subtract(vec1).crossProduct(vec3.subtract(vec1));
				buffer.pos(centerX+centerX/len*explode, centerY+centerY/len*explode, centerZ+centerZ/len*explode).color(0.8F, 0.0F, 1F, 0.5F).endVertex();
				buffer.pos(normal.x+centerX+centerX/len*explode, normal.y+centerY+centerY/len*explode, normal.z+centerZ+centerZ/len*explode).color(0.8F, 0.0F, 1F, 0.5F).endVertex();
			}
			tessellator.draw();
		}

		if(renderOutlines) {
			GL11.glEnable(GL11.GL_LINE_SMOOTH);
			GL11.glLineWidth(1.0F);

			buffer.begin(GL11.GL_LINES, DefaultVertexFormats.POSITION_COLOR);
			for(int i = 0; i <= 19; i++) {
				if(!shield.isActive(i))
					continue;
				double v3[] = vertices[indices[i][0]];
				double v2[] = vertices[indices[i][1]];
				double v1[] = vertices[indices[i][2]];
				double centerX = (v1[0]+v2[0]+v3[0])/3;
				double centerY = (v1[1]+v2[1]+v3[1])/3;
				double centerZ = (v1[2]+v2[2]+v3[2])/3;
				double len = Math.sqrt(centerX*centerX + centerY*centerY + centerZ*centerZ);
				buffer.pos(v1[0]+centerX/len*explode, v1[1]+centerY/len*explode, v1[2]+centerZ/len*explode).color(0.5F, 0.75F, 1F, lineAlpha * alpha).endVertex();
				buffer.pos(v2[0]+centerX/len*explode, v2[1]+centerY/len*explode, v2[2]+centerZ/len*explode).color(0.5F, 0.75F, 1F, lineAlpha * alpha).endVertex();
				buffer.pos(v2[0]+centerX/len*explode, v2[1]+centerY/len*explode, v2[2]+centerZ/len*explode).color(0.5F, 0.75F, 1F, lineAlpha * alpha).endVertex();
				buffer.pos(v3[0]+centerX/len*explode, v3[1]+centerY/len*explode, v3[2]+centerZ/len*explode).color(0.5F, 0.75F, 1F, lineAlpha * alpha).endVertex();
				buffer.pos(v3[0]+centerX/len*explode, v3[1]+centerY/len*explode, v3[2]+centerZ/len*explode).color(0.5F, 0.75F, 1F, lineAlpha * alpha).endVertex();
				buffer.pos(v1[0]+centerX/len*explode, v1[1]+centerY/len*explode, v1[2]+centerZ/len*explode).color(0.5F, 0.75F, 1F, lineAlpha * alpha).endVertex();
			}
			tessellator.draw();

			GL11.glDisable(GL11.GL_LINE_SMOOTH);
		}

		if(Minecraft.getMinecraft().getRenderManager().isDebugBoundingBox()) {
			GlStateManager.blendFunc(SourceFactor.SRC_ALPHA, DestFactor.ONE_MINUS_SRC_ALPHA);
			GlStateManager.disableCull();
			Vec3d pos = Minecraft.getMinecraft().player.getPositionEyes(partialTicks);
			Vec3d ray = Minecraft.getMinecraft().player.getLook(partialTicks);
			ray = ray.scale(64.0D);

			int hitShield = EntityFortressBoss.rayTraceShield(shield, centerPos, shieldRotationYaw, shieldRotationPitch, shieldRotationRoll, shieldExplosion, pos, ray, false);
			if(hitShield >= 0) {
				double v3[] = vertices[indices[hitShield][0]];
				double v2[] = vertices[indices[hitShield][1]];
				double v1[] = vertices[indices[hitShield][2]];
				double centerX = (v1[0]+v2[0]+v3[0])/3;
				double centerY = (v1[1]+v2[1]+v3[1])/3;
				double centerZ = (v1[2]+v2[2]+v3[2])/3;
				double len = Math.sqrt(centerX*centerX + centerY*centerY + centerZ*centerZ);
				Vec3d vec1 = new Vec3d(v1[0]+centerX/len*explode, v1[1]+centerY/len*explode, v1[2]+centerZ/len*explode);
				Vec3d vec2 = new Vec3d(v2[0]+centerX/len*explode, v2[1]+centerY/len*explode, v2[2]+centerZ/len*explode);
				Vec3d vec3 = new Vec3d(v3[0]+centerX/len*explode, v3[1]+centerY/len*explode, v3[2]+centerZ/len*explode);
				vec1 = vec1.add(centerPos);
				vec2 = vec2.add(centerPos);
				vec3 = vec3.add(centerPos);
				buffer.begin(GL11.GL_TRIANGLES, DefaultVertexFormats.POSITION_COLOR);
				buffer.pos(v1[0]+centerX/len*explode, v1[1]+centerY/len*explode, v1[2]+centerZ/len*explode).color(0F, 0F, 0F, 1.0F).endVertex();
				buffer.pos(v2[0]+centerX/len*explode, v2[1]+centerY/len*explode, v2[2]+centerZ/len*explode).color(0F, 0F, 0F, 1.0F).endVertex();
				buffer.pos(v3[0]+centerX/len*explode, v3[1]+centerY/len*explode, v3[2]+centerZ/len*explode).color(0F, 0F, 0F, 1.0F).endVertex();
				tessellator.draw();
			}
			GlStateManager.enableCull();
			GlStateManager.blendFunc(SourceFactor.SRC_ALPHA, DestFactor.ONE);
		}

		GlStateManager.popMatrix();

		GlStateManager.enableCull();
