            GlStateManager.popMatrix();
        }
    }

private void calculateGrip(EntityWeedwoodRowboat rowboat, ShipSide side, float delta) {
        int dir = side == ShipSide.PORT ? 1 : -1;
        matrix.setIdentity();
        float yaw = (rowboat.prevRotationYaw + (rowboat.rotationYaw - rowboat.prevRotationYaw) * delta) * MathUtils.DEG_TO_RAD;
        double pelvis = 0.75;
        matrix.translate(0, pelvis - 1.5, 0);
        matrix.rotate(yaw , 0, 1, 0);
        matrix.rotate(rowboat.getRotation(delta));
        matrix.rotate(-yaw, 0, 1, 0);
        matrix.translate(0, 1.5, 0);
        matrix.scale(-1, -1, 1);
        matrix.translate(-9 / 16D * dir, pelvis + 10 / 16D, -7 / 16D);
        createOarTransformationMatrix(side);
        grips.put(side, matrix.transform(new Vec3d(0, -6 / 16D, 0)));
    }

private void articulateArm(ShipSide side, float yaw) {
        int dir = side == ShipSide.PORT ? 1 : -1;
        createBodyTransformationMatrix();
        // move to shoulder joint
        matrix.translate(-6 / 16F * dir, -10 / 16F, shoulderZ.get(side));
        Vec3d arm = matrix.transform(Vec3d.ZERO);
        Vec3d grip = grips.get(side);
        float targetX = (float) (grip.x - arm.x);
        float targetY = (float) (grip.y - arm.y);
        float targetZ = (float) (grip.z - arm.z);
        float horizontalDistSq = targetX * targetX + targetZ * targetZ;
        float targetPitch = (float) Math.atan2(targetY, MathHelper.sqrt(horizontalDistSq));
        float targetLen = MathHelper.sqrt(horizontalDistSq + targetY * targetY);
        float upperArmLen = 4 / 16F, lowerArmLen = 4.25F / 16;
        float shoulderAngle = (float) Math.acos((upperArmLen * upperArmLen + targetLen * targetLen - lowerArmLen * lowerArmLen) / (2 * upperArmLen * targetLen));
        float flexionAngle = (float) Math.acos((upperArmLen * upperArmLen + lowerArmLen * lowerArmLen - targetLen * targetLen) / (2 * upperArmLen * lowerArmLen));
        ArmArticulation armArt = arms.get(side);
        // If shoulderAngle is NaN then the target is out of reach so the arm should simply point in that direction.
        armArt.shoulderAngleX = (shoulderAngle != shoulderAngle ? -MathUtils.PI / 2 - targetPitch : (shoulderAngle - MathUtils.PI / 2 - targetPitch)) - bodyRotateAngleX;
        armArt.shoulderAngleY = (float) Math.atan2(targetZ, targetX) + MathUtils.PI / 2 - bodyRotateAngleY;
        armArt.flexionAngle = shoulderAngle != shoulderAngle ? 0 : (flexionAngle - MathUtils.PI) * MathUtils.RAD_TO_DEG;
        armArt.shoulderZ = shoulderZ.get(side);
    }

private void createBodyTransformationMatrix() {
        matrix.setIdentity();
        // player yOffset
        matrix.translate(0, -1.62, 0);
        // regular scale
        matrix.scale(-1, -1, 1);
        // player scale
        matrix.scale(15 / 16F, 15 / 16F, 15 / 16F);
        // regular translate
        matrix.translate(0, -24 / 16F - 0.0078125, 0);
        // body rotation point
        matrix.translate(0, 12 / 16F, 0);
        matrix.rotate(bodyRotateAngleY, 0, 1, 0);
        matrix.rotate(bodyRotateAngleX, 1, 0, 0);
    }

private void renderWaterMask() {
        if (maskId == -1) {
            maskId = GLAllocation.generateDisplayLists(1);
            Tessellator tessellator = Tessellator.getInstance();
            BufferBuilder vb = tessellator.getBuffer();
            vb.begin(GL11.GL_QUADS, DefaultVertexFormats.POSITION);
            double y = 0.813;
            double midWidth = 0.55;
            double midDepth = 0.65;
            double endWidth = 0.4;
            double endDepth = 0.16;
            double endOffset = 0.81;
            vb.pos(-midWidth, y, midDepth).endVertex();
            vb.pos(midWidth, y, midDepth).endVertex();
            vb.pos(midWidth, y, -midDepth).endVertex();
            vb.pos(-midWidth, y, -midDepth).endVertex();
            vb.pos(-endWidth, y, endDepth - endOffset).endVertex();
            vb.pos(endWidth, y, endDepth - endOffset).endVertex();
            vb.pos(endWidth, y, -endDepth - endOffset).endVertex();
            vb.pos(-endWidth, y, -endDepth - endOffset).endVertex();
            vb.pos(-endWidth, y, endDepth + endOffset).endVertex();
            vb.pos(endWidth, y, endDepth + endOffset).endVertex();
            vb.pos(endWidth, y, -endDepth + endOffset).endVertex();
            vb.pos(-endWidth, y, -endDepth + endOffset).endVertex();
            GlStateManager.glNewList(maskId, GL11.GL_COMPILE_AND_EXECUTE);
            GlStateManager.disableTexture2D();
            GlStateManager.colorMask(false, false, false, false);
            tessellator.draw();
            GlStateManager.colorMask(true, true, true, true);
            GlStateManager.enableTexture2D();
            GlStateManager.glEndList();
        } else {
            GlStateManager.callList(maskId);
        }
    }

@Override
	protected void preRenderCallback(EntityWight entity, float partialTicks) {
		if (ShaderHelper.INSTANCE.isWorldShaderActive()) {
			ShaderHelper.INSTANCE.require();
			ShaderHelper.INSTANCE.getWorldShader().addLight(new LightSource(entity.posX, entity.posY, entity.posZ, 10.0f, -1, -1, -1));
		}

		float scale = 0.9F / 40F * (entity.getGrowthFactor(partialTicks));
		GlStateManager.scale(0.9F, scale, 0.9F);

		if(entity.isVolatile()) {
			GlStateManager.scale(0.5D, 0.5D, 0.5D);
			GlStateManager.translate(0, 1.0D, 0);
		}
	}

@Override
	public void doRender(EntityWight entity, double x, double y, double z, float entityYaw, float partialTicks) {
		if(!entity.isVolatile()) {
			GlStateManager.pushMatrix();
			GlStateManager.disableBlend();
			GlStateManager.colorMask(false, false, false, false);
			GlStateManager.color(1, 1, 1, 1);

			super.doRender(entity, x, y, z, entityYaw, partialTicks);

			GlStateManager.colorMask(true, true, true, true);
			GlStateManager.enableBlend();
			GlStateManager.blendFunc(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA);
			GlStateManager.color(1F, 1F, 1F, 1F - entity.getHidingAnimation(partialTicks) * 0.5F);

			super.doRender(entity, x, y, z, entityYaw, partialTicks);

			GlStateManager.popMatrix();
		} else {
			this.mainModel = MODEL_HEAD_ONLY;

			GlStateManager.pushMatrix();
			GlStateManager.disableBlend();
			GlStateManager.colorMask(false, false, false, false);
			GlStateManager.color(1, 1, 1, 1);

			if (entity.getRidingEntity() != null) {
				GlStateManager.translate(x, y, z);
				GlStateManager.enableRescaleNormal();
				GlStateManager.scale(-1.0F, -1.0F, 1.0F);
				GlStateManager.rotate((float) (entity.ticksExisted + partialTicks) / 30.0F * 360.0F, 0, 1, 0);
				GlStateManager.rotate(180, 0, 1, 0);
				GlStateManager.translate(0, -entity.getRidingEntity().getEyeHeight() + 1.65D, 0.8D);
				GlStateManager.scale(0.5D, 0.5D, 0.5D);

				this.bindEntityTexture(entity);

				MODEL_HEAD_ONLY.render(entity, 0.0F, 0.0F, entity.ticksExisted + partialTicks, 0.0F, 0.0F, 0.0625F);

				GlStateManager.colorMask(true, true, true, true);
				GlStateManager.enableBlend();
				GlStateManager.blendFunc(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA);
				GlStateManager.color(1F, 1F, 1F, 0.4F);

				MODEL_HEAD_ONLY.render(entity, 0.0F, 0.0F, entity.ticksExisted + partialTicks, 0.0F, 0.0F, 0.0625F);
			} else {
				super.doRender(entity, x, y, z, entityYaw, partialTicks);

				GlStateManager.colorMask(true, true, true, true);
				GlStateManager.enableBlend();
				GlStateManager.blendFunc(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA);
				GlStateManager.color(1F, 1F, 1F, 0.4F);

				super.doRender(entity, x, y, z, entityYaw, partialTicks);
			}

			GlStateManager.popMatrix();

			this.mainModel = MODEL;
		}
	}

@Override
	public void doRenderLayer(T entity, float limbSwing, float limbSwingAmount, float partialTicks, float ageInTicks, float netHeadYaw, float headPitch, float scale) {
		GlStateManager.pushMatrix();
		GlStateManager.enableBlend();
		GlStateManager.enableAlpha();
		GlStateManager.blendFunc(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA);
		GlStateManager.depthMask(!entity.isInvisible());

		float scrollTimer = entity.ticksExisted + partialTicks;
		this.renderer.bindTexture(this.overlay);
		GlStateManager.matrixMode(GL11.GL_TEXTURE);
		GlStateManager.loadIdentity();
		float yScroll = scrollTimer * 0.002F;
		GlStateManager.translate(0F, -yScroll, 0.0F);
		GlStateManager.matrixMode(GL11.GL_MODELVIEW);
		float colour = 0.5F;
		GlStateManager.color(colour, colour, colour, 1.0F);

		GlStateManager.enablePolygonOffset();
		GlStateManager.doPolygonOffset(0.0F, -5.0F);

		ModelBase mainModel = this.renderer.getMainModel();
		mainModel.setLivingAnimations(entity, limbSwing, limbSwingAmount, partialTicks);
		mainModel.setRotationAngles(limbSwing, limbSwingAmount, ageInTicks, netHeadYaw, headPitch, scale, entity);
		mainModel.render(entity, limbSwing, limbSwingAmount, ageInTicks, netHeadYaw, headPitch, scale);

		GlStateManager.disablePolygonOffset();

		GlStateManager.matrixMode(GL11.GL_TEXTURE);
		GlStateManager.loadIdentity();
		GlStateManager.matrixMode(GL11.GL_MODELVIEW);
		GlStateManager.depthMask(true);
		GlStateManager.disableBlend();
		GlStateManager.popMatrix();
	}

@Override
	public void doRenderLayer(T entity, float limbSwing, float limbSwingAmount, float partialTicks, float ageInTicks, float netHeadYaw, float headPitch, float scale) {
		int index = 0;

		for(ModelBase model : this.getModels(entity)) {
			ResourceLocation texture = this.getTexture(entity, index);

			if(texture != null) {
				this.renderer.bindTexture(texture);

				float alpha = this.getAlpha();
				float red = this.getRed();
				float green = this.getGreen();
				float blue = this.getBlue();

				renderOverlay(entity, () -> {
					this.renderOverlay(entity, model, limbSwing, limbSwingAmount, partialTicks, ageInTicks, netHeadYaw, headPitch, scale);
				}, this.getGlow(), red, green, blue, alpha);
			}

			index++;
		}
	}

public static void renderOverlay(@Nullable Entity entity, Runnable renderer, boolean glow, float red, float green, float blue, float alpha) {
		GlStateManager.doPolygonOffset(-0.01F, -3.0F);
		GlStateManager.enablePolygonOffset();

		GlStateManager.enableBlend();
		GlStateManager.enableAlpha();
		GlStateManager.depthMask(false);
		GlStateManager.blendFunc(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA);
		GlStateManager.color(red, green, blue, alpha);

		if(glow) {
			int i = 61680;
			int j = i % 65536;
			int k = i / 65536;
			OpenGlHelper.setLightmapTextureCoords(OpenGlHelper.lightmapTexUnit, (float)j, (float)k);
			GlStateManager.disableLighting();
	    }

		renderer.run();

		if(glow) {
			GlStateManager.depthMask(entity == null || !entity.isInvisible());
			GlStateManager.color(red * alpha, green * alpha, blue * alpha, alpha);
			GlStateManager.blendFunc(GlStateManager.SourceFactor.ONE, GlStateManager.DestFactor.ONE);

			renderer.run();

			if(entity != null) {
				setLightmap(entity);
			}
		}

		GlStateManager.enableLighting();

		GlStateManager.depthMask(true);
		GlStateManager.disableBlend();
		GlStateManager.blendFunc(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA);
		GlStateManager.color(1.0F, 1.0F, 1.0F, 1.0F);

		GlStateManager.doPolygonOffset(0.0F, 0.0F);
		GlStateManager.disablePolygonOffset();
	}

@Override
	public void doRenderLayer(EntityLivingBase entity, float limbSwing, float limbSwingAmount, float partialTicks, float ageInTicks, float netHeadYaw, float headPitch, float scale) {
		IPuppetCapability cap = entity.getCapability(CapabilityRegistry.CAPABILITY_PUPPET, null);
		if(cap != null && cap.hasPuppeteer()) {
			GlStateManager.pushMatrix();
			GlStateManager.enableBlend();
			GlStateManager.enableAlpha();
			GlStateManager.alphaFunc(GL11.GL_GREATER, 0.0f);
			GlStateManager.blendFunc(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE);
			GlStateManager.depthMask(false);
			GlStateManager.enableCull();

			float animationTimer = (entity.ticksExisted + partialTicks);

			float colorSine = (MathHelper.cos(animationTimer * 0.1f) + 1) * 0.3f;

			float alpha = 0.1f * (MathHelper.sin(animationTimer * 0.0333333f) + 1) * 0.5f + 0.08f;

			GlStateManager.color(colorSine, 1.25f - colorSine, 2.0f, alpha);

			GlStateManager.enablePolygonOffset();
			GlStateManager.doPolygonOffset(-0.1F, -5.0F);


			this.renderer.bindTexture(OVERLAY_TEXTURE);

			//Set up UV generator
			GlStateManager.texGen(GlStateManager.TexGen.S, GL11.GL_OBJECT_LINEAR);
			GlStateManager.texGen(GlStateManager.TexGen.T, GL11.GL_OBJECT_LINEAR);
			GlStateManager.texGen(GlStateManager.TexGen.S, GL11.GL_OBJECT_PLANE, this.getBuffer4f(0.0F, 1.0F, 0.0F, 0.0F));
			GlStateManager.texGen(GlStateManager.TexGen.T, GL11.GL_OBJECT_PLANE, this.getBuffer4f(1.0F, 0.0F, 1.0F, 0.0F));
			GlStateManager.enableTexGenCoord(GlStateManager.TexGen.S);
			GlStateManager.enableTexGenCoord(GlStateManager.TexGen.T);

			GlStateManager.matrixMode(GL11.GL_TEXTURE);
			GlStateManager.pushMatrix();
			GlStateManager.loadIdentity();
			GlStateManager.translate(0.5F, 0.5F, 0.0F);

			GlStateManager.scale(0.25f, 0.25f, 1);

			GlStateManager.translate(animationTimer * 0.01f, -animationTimer * 0.015f, 0);
			GlStateManager.rotate(animationTimer * 0.25f, 0, 0, 1);

			GlStateManager.matrixMode(GL11.GL_MODELVIEW);

			//Render projection
			ModelBase mainModel = this.renderer.getMainModel();
			mainModel.setLivingAnimations(entity, limbSwing, limbSwingAmount, partialTicks);
			mainModel.setRotationAngles(limbSwing, limbSwingAmount, ageInTicks, netHeadYaw, headPitch, scale, entity);
			mainModel.render(entity, limbSwing, limbSwingAmount, ageInTicks, netHeadYaw, headPitch, scale);

			GlStateManager.matrixMode(GL11.GL_TEXTURE); //Make sure texture matrix is popped
			GlStateManager.popMatrix();
			GlStateManager.matrixMode(GL11.GL_MODELVIEW);

			GlStateManager.disableTexGenCoord(GlStateManager.TexGen.S);
			GlStateManager.disableTexGenCoord(GlStateManager.TexGen.T);



			GlStateManager.matrixMode(GL11.GL_TEXTURE);
			GlStateManager.loadIdentity();
			GlStateManager.matrixMode(GL11.GL_MODELVIEW);


			GlStateManager.disablePolygonOffset();

			GlStateManager.alphaFunc(GL11.GL_GREATER, 0.1f);
			GlStateManager.blendFunc(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA);
			GlStateManager.disableCull();
			GlStateManager.depthMask(true);
			GlStateManager.disableBlend();
			GlStateManager.popMatrix();
		}
	}

private void renderArmorLayer(EntityLivingBase living, float limbSwing, float limbSwingAmount, float delta, float age, float headYaw, float headPitch, float scale, EntityEquipmentSlot slot) {
		ItemStack stack = living.getItemStackFromSlot(slot);
		Item item = stack.getItem();
		if (item instanceof ItemArmor) {
			ItemArmor itemarmor = (ItemArmor) item;
			if (itemarmor.getEquipmentSlot() == slot) {
				ArmorRenderer armor = getModel(living, stack, slot, getModelFromSlot(slot));
				armor.setup(living, limbSwing, limbSwingAmount, delta, slot);
				//noinspection ConstantConditions
				rower.bindTexture(getArmorResource(living, stack, slot, null));
				if (itemarmor.hasOverlay(stack)) {
					int rgb = itemarmor.getColor(stack);
					float r = (float) (rgb >> 16 & 255) / 255.0F;
					float g = (float) (rgb >> 8 & 255) / 255.0F;
					float b = (float) (rgb & 255) / 255.0F;
					GlStateManager.color(r, g, b, 1.0F);
					armor.render(living, limbSwing, limbSwingAmount, age, headYaw, headPitch, scale, slot);
					rower.bindTexture(getArmorResource(living, stack, slot, "overlay"));
				}
				GlStateManager.color(1.0F, 1.0F, 1.0F, 1.0F);
				armor.render(living, limbSwing, limbSwingAmount, age, headYaw, headPitch, scale, slot);
				if (stack.hasEffect()) {
					glint.render(living, armor, limbSwing, limbSwingAmount, delta, age, headYaw, headPitch, scale, slot);
				}
			}
		}
	}

@Override
		void render(EntityLivingBase living, float limbSwing, float limbSwingAmount, float age, float headYaw, float headPitch, float scale, EntityEquipmentSlot slot) {
			// Construct's Armory does initialization of model in render
			if (init) {
				GlStateManager.pushMatrix();
				GlStateManager.translate(0.0D, -10000.0D, 0.0D);
				GlStateManager.scale(0.0D, 0.0D, 0.0D);
				model.render(living, limbSwing, limbSwing, age, headYaw, headPitch, scale);
				GlStateManager.popMatrix();
				init = false;
			}
			model.setRotationAngles(0.0F, 0.0F, age, 0.0F, 0.0F, scale, living);
			GlStateManager.pushMatrix();
			switch (slot) {
				case HEAD:
					transform(modelArmor.bipedBody, scale);
					renderHead(modelArmor.bipedBody, modelArmor.bipedHead, model.bipedHead, scale);
					break;
				case CHEST:
					render(modelArmor.bipedBody, model.bipedBody, scale);
					transform(modelArmor.bipedBody, scale);
					renderArm(modelArmor.bipedBody, modelArmor.bipedLeftArm, initialPose.bipedLeftArm, getChest().leftForearm, model.bipedLeftArm, scale);
					renderArm(modelArmor.bipedBody, modelArmor.bipedRightArm, initialPose.bipedRightArm, getChest().rightForearm, model.bipedRightArm, scale);
					break;
				case LEGS:
					render(modelLeggings.bipedBody, model.bipedBody, scale);
				case FEET:
					render(modelArmor.bipedLeftLeg, model.bipedLeftLeg, scale);
					render(modelArmor.bipedRightLeg, model.bipedRightLeg, scale);
					break;
			}
			GlStateManager.popMatrix();
		}

private void renderArm(ModelRenderer body, ModelRenderer upperArm, ModelRenderer initialArm, ModelRenderer lowerArm, ModelRenderer model, float scale) {
			GlStateManager.pushMatrix();
			transform(upperArm, scale);
			GlStateManager.pushMatrix();
			GlStateManager.translate(
				(-initialArm.rotationPointX) * scale,
				(-initialArm.rotationPointY - body.rotationPointY) * scale,
				(-initialArm.rotationPointZ) * scale
			);
			List<ModelRenderer> forearmModels = getForearmModels(model);
			renderExcluding(model, forearmModels, scale);
			GlStateManager.popMatrix();
			transform(lowerArm, scale);
			GlStateManager.translate((model.rotationPointX - initialArm.rotationPointX) * scale, -lowerArm.rotationPointY * scale, 0.0F);
			for (ModelRenderer m : forearmModels) {
				m.render(scale);
			}
			GlStateManager.popMatrix();
		}

@Override
	public void doRenderLayer(EntityTarBeast entity, float limbSwing, float limbSwingAmount, float partialTicks, float ageInTicks, float netHeadYaw, float headPitch, float scale) {
		GlStateManager.enableBlend();
		GlStateManager.enableAlpha();
		GlStateManager.blendFunc(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA);
		GlStateManager.depthMask(!entity.isInvisible());

		float scrollTimer = entity.ticksExisted + partialTicks;
		this.renderer.bindTexture(OVERLAY_TEXTURE);
		GlStateManager.matrixMode(GL11.GL_TEXTURE);
		GlStateManager.loadIdentity();
		float yScroll = scrollTimer * 0.002F;
		GlStateManager.translate(0F, -yScroll, 0.0F);
		GlStateManager.matrixMode(GL11.GL_MODELVIEW);
		float colour = 0.5F;
		GlStateManager.color(colour, colour, colour, 1.0F);

		ModelTarBeast mainModel = (ModelTarBeast) this.renderer.getMainModel();
		mainModel.drippingtar1_keepstraight.showModel = false;
		mainModel.drippingtar2_keepstraight.showModel = false;
		mainModel.teeth_keepstraight.showModel = false;
		mainModel.setLivingAnimations(entity, limbSwing, limbSwingAmount, partialTicks);
		mainModel.setRotationAngles(limbSwing, limbSwingAmount, ageInTicks, netHeadYaw, headPitch, scale, entity);
		mainModel.render(entity, limbSwing, limbSwingAmount, ageInTicks, netHeadYaw, headPitch, scale);
		mainModel.drippingtar1_keepstraight.showModel = true;
		mainModel.drippingtar2_keepstraight.showModel = true;
		mainModel.teeth_keepstraight.showModel = true;

		GlStateManager.matrixMode(GL11.GL_TEXTURE);
		GlStateManager.loadIdentity();
		GlStateManager.matrixMode(GL11.GL_MODELVIEW);

		this.renderer.bindTexture(this.renderer.getEntityTexture(entity));

		if(entity.isShedding()) {
			float sheddingScale = (float)(entity.getSheddingProgress() * entity.getSheddingProgress() * 0.002F) + 1.0F;

			GlStateManager.color(1, 1, 1, 0.6F);

			GlStateManager.pushMatrix();
			GlStateManager.scale(sheddingScale, sheddingScale, sheddingScale);

			this.renderer.getMainModel().render(entity, limbSwing, limbSwingAmount, ageInTicks, netHeadYaw, headPitch, scale);

			GlStateManager.popMatrix();

			sheddingScale = (float)(entity.getSheddingProgress() * entity.getSheddingProgress() * 0.004F) + 1.0F;

			GlStateManager.color(1, 1, 1, 0.3F);

			GlStateManager.pushMatrix();
			GlStateManager.scale(sheddingScale, sheddingScale, sheddingScale);

			this.renderer.getMainModel().render(entity, limbSwing, limbSwingAmount, ageInTicks, netHeadYaw, headPitch, scale);

			GlStateManager.popMatrix();
		}

		if(entity.isPreparing()) {
			float sheddingScale = (float)((1.0F - (entity.ticksExisted % 8) / 8.0F) * 0.15F + 1.0F);

			GlStateManager.color(1, 1, 1, 0.6F);

			GlStateManager.pushMatrix();
			GlStateManager.scale(sheddingScale, sheddingScale, sheddingScale);

			this.renderer.getMainModel().render(entity, limbSwing, limbSwingAmount, ageInTicks, netHeadYaw, headPitch, scale);

			GlStateManager.popMatrix();

			sheddingScale = (float)((1.0F - (entity.ticksExisted % 8) / 8.0F) * 0.2F + 1.05F);

			GlStateManager.color(1, 1, 1, 0.3F);

			GlStateManager.pushMatrix();
			GlStateManager.scale(sheddingScale, sheddingScale, sheddingScale);

			this.renderer.getMainModel().render(entity, limbSwing, limbSwingAmount, ageInTicks, netHeadYaw, headPitch, scale);

			GlStateManager.popMatrix();
		}

		GlStateManager.depthMask(true);
		GlStateManager.disableBlend();
	}

@Override
	public void renderParticle(BufferBuilder buffer, Entity entityIn, float partialTicks, float rotationX,
			float rotationZ, float rotationYZ, float rotationXY, float rotationXZ) {
		float rx = (float)(this.prevPosX + (this.posX - this.prevPosX) * (double)partialTicks - interpPosX);
		float ry = (float)(this.prevPosY + (this.posY - this.prevPosY) * (double)partialTicks - interpPosY);
		float rz = (float)(this.prevPosZ + (this.posZ - this.prevPosZ) * (double)partialTicks - interpPosZ);

		float renderScale = 0.1F * this.particleScale;

		int i = this.getBrightnessForRender(partialTicks);
		int j = i >> 16 & 65535;
		int k = i & 65535;

		float texUOffset = this.prevTexUOffset + (this.texUOffset - this.prevTexUOffset) * partialTicks;

		buildBeam(rx, ry, rz, this.end, renderScale, texUOffset, this.texUScale, rotationX, rotationZ, rotationYZ, rotationXY, rotationXZ,
				(vx, vy, vz, u, v) -> {
					buffer.pos(vx, vy, vz).tex(u, v).color(this.particleRed, this.particleGreen, this.particleBlue, this.particleAlpha).lightmap(j, k).endVertex();
				});
	}

public static void buildBeam(double rx, double ry, double rz, Vec3d end, float scale, float texUOffset, float texUScale,
			float rotationX, float rotationZ, float rotationYZ, float rotationXY, float rotationXZ, BeamVertexConsumer consumer) {
		double len = end.length();

		Vec3d v1 = new Vec3d((double)(-rotationX - rotationXY), (double)(-rotationZ), (double)(-rotationYZ - rotationXZ));
		Vec3d v2 = new Vec3d((double)(-rotationX + rotationXY), (double)(rotationZ), (double)(-rotationYZ + rotationXZ));

		Vec3d facing = v1.crossProduct(v2);

		Vec3d perpendicularDir = end.crossProduct(facing).normalize();

		if(perpendicularDir.length() < 1.0E-4D) {
			//Special case where facing and particle direction perfectly match.
			//Instead of using the crossproduct we can just directly use the v1 and v2 vectors
			//to get the correct result
			facing = v2.subtract(v1).normalize();
			perpendicularDir = end.crossProduct(facing).normalize();
		}

		Vec3d perpendicularDir2 = perpendicularDir.crossProduct(end).normalize();

		Vec3d[] offsets = new Vec3d[] { perpendicularDir.scale(scale), perpendicularDir.scale(-scale) };
		Vec3d[] offsets2 = new Vec3d[] { perpendicularDir2.scale(scale), perpendicularDir2.scale(-scale) };

		double x1 = rx;
		double y1 = ry;
		double z1 = rz;

		double x2 = rx + end.x;
		double y2 = ry + end.y;
		double z2 = rz + end.z;

		//br
		consumer.emit((double)x2 + offsets[0].x, (double)y2 + offsets[0].y, (double)z2 + offsets[0].z, texUOffset + len / (0.2 * texUScale), 0);
		//tr                                                                                    
		consumer.emit((double)x2 + offsets[1].x, (double)y2 + offsets[1].y, (double)z2 + offsets[1].z, texUOffset + len / (0.2 * texUScale), 1);
		//tl                                                                                    
