@Override
	public void renderParticle(BufferBuilder buffer, Entity entityIn, float partialTicks, float rotationX, float rotationZ, float rotationYZ, float rotationXY, float rotationXZ) {
		if(this.particleAge > this.particleMaxAge - 10) {
			this.particleAlpha = (this.particleMaxAge - this.particleAge) / 10.0F;
		} else if(this.particleAge < 10) {
			this.particleAlpha = this.particleAge / 10.0F;
		} else {
			this.particleAlpha = 1.0F;
		}

		double px = this.posX;
		double py = this.posY;
		double pz = this.posZ;
		double ppx = this.prevPosX;
		double ppy = this.prevPosY;
		double ppz = this.prevPosZ;

		float interval = (float)(Math.PI) * 2.0F / this.particles;
		float prevAngle = (this.rotationTicks - 1) / 120.0F * (float)(Math.PI) * 2.0F;
		float angle = this.rotationTicks / 120.0F * (float)(Math.PI) * 2.0F;

		float scale = (float) (this.radius) * 2.0F * (0.25F + this.particles / (float)MAX_PARTICLES * 0.75F);

		for(int i = 0; i < this.particles; i++) {
			double prevXo = Math.cos(prevAngle + interval * i) * this.radius;
			double prevYo = Math.cos(prevAngle + interval * i * 5.678F) * 0.05F;
			double prevZo = Math.sin(prevAngle + interval * i) * this.radius;
			double xo = Math.cos(angle + interval * i) * this.radius;
			double yo = Math.cos(angle + interval * i * 5.678F) * 0.05F;
			double zo = Math.sin(angle + interval * i) * this.radius;

			this.prevPosX = ppx + prevXo;
			this.prevPosZ = ppz + prevZo;
			this.posX = px + xo;
			this.posZ = pz + zo;

			this.prevPosY = ppy + prevYo - scale * 0.025f;
			this.posY = py + yo - scale * 0.025f;

			this.particleRed = 0.1F;
			this.particleGravity = 0.1F;
			this.particleBlue = 1.0F;
			this.particleScale = scale * 2.5F;
			this.particleTexture = this.glowSprite;
			float prevAlpha = this.particleAlpha;
			this.particleAlpha *= 0.05F;

			super.renderParticle(buffer, entityIn, partialTicks, rotationX, rotationZ, rotationYZ, rotationXY, rotationXZ);

			this.particleAlpha *= 2.0F;
			this.particleRed = 1.0F;
			this.particleGravity = 1.0F;
			this.particleBlue = 1.0F;
			this.particleScale = scale * 1.25F;

			super.renderParticle(buffer, entityIn, partialTicks, rotationX, rotationZ, rotationYZ, rotationXY, rotationXZ);

			this.particleRed = this.particleGreen = this.particleBlue = 1.0F;
			this.particleAlpha = prevAlpha;

			this.prevPosY = ppy + prevYo;
			this.posY = py + yo;

			this.particleScale = scale;
			this.particleTexture = this.animations[i].getCurrentSprite();

			super.renderParticle(buffer, entityIn, partialTicks, rotationX, rotationZ, rotationYZ, rotationXY, rotationXZ);
		}

		this.posX = px;
		this.posY = py;
		this.posZ = pz;
		this.prevPosX = ppx;
		this.prevPosY = ppy;
		this.prevPosZ = ppz;
	}

@Override
	public void renderParticle(BufferBuilder buffer, Entity entityIn, float partialTicks, float rotationX, float rotationZ, float rotationYZ, float rotationXY, float rotationXZ) {
		float rx = (float)(this.prevPosX + (this.posX - this.prevPosX) * (double)partialTicks - interpPosX);
		float ry = (float)(this.prevPosY + (this.posY - this.prevPosY) * (double)partialTicks - interpPosY);
		float rz = (float)(this.prevPosZ + (this.posZ - this.prevPosZ) * (double)partialTicks - interpPosZ);

		int light = this.getBrightnessForRender(partialTicks);
		int lightmapX = light >> 16 & 65535;
		int lightmapY = light & 65535;

		float scale = ((MathHelper.sin((this.particleAge + partialTicks) * 0.8f) + 1) * 0.5f * 0.5f + 0.5f) * this.baseSize * (1 - (this.particleAge - 1 + partialTicks) / this.particleMaxAge);

		for(Arc arc : this.arcs) {

			ParticleBeam.buildBeam(rx + arc.from.x, ry + arc.from.y, rz + arc.from.z, arc.dir, scale * arc.size, 0, 0, rotationX, rotationZ, rotationYZ, rotationXY, rotationXZ, (x, y, z, u, v) -> {
				buffer.pos(x, y, z).tex(u, v).color(this.particleRed, this.particleGreen, this.particleBlue, this.particleAlpha).lightmap(lightmapX, lightmapY).endVertex();
			});

		}

		if(this.lighting && ShaderHelper.INSTANCE.isWorldShaderActive()) {
			double distFromCam = entityIn.getDistance(this.target.x, this.target.y, this.target.z);
			if(distFromCam < 40) {
	        	ShaderHelper.INSTANCE.require();

	        	float strength = (1 - this.particleAge / (float)this.particleMaxAge) * this.particleAlpha * 50.0f;

	            ShaderHelper.INSTANCE.getWorldShader().addLight(new LightSource(this.target.x, this.target.y, this.target.z,
	                    1.0f + 5.0f * this.baseSize, this.particleRed * strength, this.particleGreen * strength, this.particleBlue * strength));
			}
        }
	}

@Override
	public void renderParticle(BufferBuilder buffer, Entity entityIn, float partialTicks, float rotationX,
			float rotationZ, float rotationYZ, float rotationXY, float rotationXZ) {
		if(this.particleRed > 1) {
			this.particleRed /= 255.0f;
		}

		if(this.particleGreen > 1) {
			this.particleGreen /= 255.0f;
		}

		if(this.particleBlue > 1) {
			this.particleBlue /= 255.0f;
		}

		if(this.particleAge > this.particleMaxAge - 10) {
			this.particleAlpha = (this.particleMaxAge - this.particleAge) / 10.0F * this.initAlpha;
		} else if(this.particleAge < 10) {
			this.particleAlpha = this.particleAge / 10.0F * this.initAlpha;
		} else {
			this.particleAlpha = this.initAlpha;
		}

		if(ShaderHelper.INSTANCE.isWorldShaderActive()) {
			double distFromCam = entityIn.getDistance(this.posX, this.posY, this.posZ);
			if(distFromCam < 8) {
	        	ShaderHelper.INSTANCE.require();

	        	float strength = 1.0f * Math.min(1, (2.0f - (float)(distFromCam - 6.0f)) / 2.0f) * this.particleAlpha * 3.5f;

	        	double rx = this.prevPosX + (this.posX - this.prevPosX) * partialTicks;
				double ry = this.prevPosY + (this.posY - this.prevPosY) * partialTicks;
				double rz = this.prevPosZ + (this.posZ - this.prevPosZ) * partialTicks;
	            ShaderHelper.INSTANCE.getWorldShader().addLight(new LightSource(rx, ry, rz,
	                    2.6f, this.particleRed * strength, this.particleGreen * strength, this.particleBlue * strength));
			}
        }

		super.renderParticle(buffer, entityIn, partialTicks, rotationX, rotationZ, rotationYZ, rotationXY, rotationXZ);
	}

@Override
	public void renderParticle(BufferBuilder buffer, Entity entityIn, float partialTicks, float rotationX, float rotationZ, float rotationYZ, float rotationXY, float rotationXZ) {
		if(this.renderer == null) {
			this.renderer = new SpikeRenderer(this.length, this.width, 1.0F, 1, this.seed).build(DefaultVertexFormats.OLDMODEL_POSITION_TEX_NORMAL, Minecraft.getMinecraft().getTextureMapBlocks().getAtlasSprite(SPRITE.toString()));
		}

		int i = this.getBrightnessForRender(partialTicks);
		int j = i % 65536;
		int k = i / 65536;

		RenderHelper.enableStandardItemLighting();
		GlStateManager.enableLighting();

		OpenGlHelper.setLightmapTextureCoords(OpenGlHelper.lightmapTexUnit, (float)j, (float)k);

		Minecraft.getMinecraft().getTextureManager().bindTexture(TextureMap.LOCATION_BLOCKS_TEXTURE);

		float rx = (float)(this.prevPosX + (this.posX - this.prevPosX) * (double)partialTicks - interpPosX);
		float ry = (float)(this.prevPosY + (this.posY - this.prevPosY) * (double)partialTicks - interpPosY);
		float rz = (float)(this.prevPosZ + (this.posZ - this.prevPosZ) * (double)partialTicks - interpPosZ);

		GlStateManager.pushMatrix();

		float alpha = 1.0F;

		if((this.particleAge + partialTicks) >= this.particleMaxAge - 10) {
			alpha = 1.0F - ((this.particleAge + partialTicks) - (this.particleMaxAge - 10)) / 10.0F;
		}

		GlStateManager.enableBlend();
		GlStateManager.blendFunc(SourceFactor.CONSTANT_ALPHA, DestFactor.ONE_MINUS_CONSTANT_ALPHA);
		GL14.glBlendColor(1, 1, 1, alpha);
		GlStateManager.color(1.0F, 1.0F, 1.0F, alpha);

		GlStateManager.translate(rx, ry, rz);

		double mx = this.prevMotionX + (this.motionX - this.prevMotionX) * partialTicks;
		double my = this.prevMotionY + (this.motionY - this.prevMotionY) * partialTicks;
		double mz = this.prevMotionZ + (this.motionZ - this.prevMotionZ) * partialTicks;

		GlStateManager.rotate(-(float)Math.toDegrees(Math.atan2(mz, mx)), 0, 1, 0);
		GlStateManager.rotate((float)Math.toDegrees(Math.atan2(Math.sqrt(mx * mx + mz * mz), -my)) + 180, 0, 0, 1);

		GlStateManager.translate(0, -0.5F * this.scale, 0);

		GlStateManager.scale(this.scale, this.scale, this.scale);

		Minecraft.getMinecraft().getTextureManager().bindTexture(TextureMap.LOCATION_BLOCKS_TEXTURE);

		this.renderer.render();

		GlStateManager.blendFunc(SourceFactor.SRC_ALPHA, DestFactor.ONE_MINUS_SRC_ALPHA);
		GL14.glBlendColor(1, 1, 1, 1);

		GlStateManager.popMatrix();
	}

@Override
	public void renderParticle(BufferBuilder buff, Entity entityIn, float partialTicks, float rx, float rz, float ryz, float rxy, float rxz) {
		float minU = (float)this.particleTextureIndexX / 16.0F;
		float maxU = minU + 0.0624375F;
		float minV = (float)this.particleTextureIndexY / 16.0F;
		float maxV = minV + 0.0624375F;

		float scale = 0.1F * this.particleScale * 2 * (this.particleAge / (float)this.particleMaxAge);

		if (this.particleTexture != null) {
			minU = this.particleTexture.getMinU();
			maxU = this.particleTexture.getMaxU();
			minV = this.particleTexture.getMinV();
			maxV = this.particleTexture.getMaxV();
		}

		float tw = maxU - minU;
		float th = maxV - minV;
		float oneTexelU = tw / 128.0f;
		float oneTexelV = th / 128.0f;

		minU += oneTexelU;
		maxU -= oneTexelU;
		minV += oneTexelV;
		maxV -= oneTexelV;

		float rpx = (float)(this.prevPosX + (this.posX - this.prevPosX) * (double)partialTicks - interpPosX);
		float rpy = (float)(this.prevPosY + (this.posY - this.prevPosY) * (double)partialTicks - interpPosY);
		float rpz = (float)(this.prevPosZ + (this.posZ - this.prevPosZ) * (double)partialTicks - interpPosZ);
		int brightness = this.getBrightnessForRender(partialTicks);
		int lightmapX = brightness >> 16 & 65535;
		int lightmapY = brightness & 65535;

		Vec3d normal = this.dir;
		Vec3d perpendicular = this.up;
		Vec3d perpendicular2 = perpendicular.crossProduct(normal);

		double yOffset = 0.125D;
		Vec3d[] vertices = new Vec3d[] {perpendicular.add(perpendicular2.scale(-1)).add(perpendicular.scale(yOffset)).scale(scale), perpendicular.scale(-1).add(perpendicular2.scale(-1)).add(perpendicular.scale(yOffset)).scale(scale), perpendicular.scale(-1).add(perpendicular2).add(perpendicular.scale(yOffset)).scale(scale), perpendicular.add(perpendicular2).add(perpendicular.scale(yOffset)).scale(scale)};

		if (this.particleAngle != 0.0F) {
			float f8 = this.particleAngle + (this.particleAngle - this.prevParticleAngle) * partialTicks;
			float f9 = MathHelper.cos(f8 * 0.5F);
			float f10 = MathHelper.sin(f8 * 0.5F) * (float)this.dir.x;
			float f11 = MathHelper.sin(f8 * 0.5F) * (float)this.dir.y;
			float f12 = MathHelper.sin(f8 * 0.5F) * (float)this.dir.z;
			Vec3d vec3d = new Vec3d((double)f10, (double)f11, (double)f12);

			for (int l = 0; l < 4; ++l) {
				vertices[l] = vec3d.scale(2.0D * vertices[l].dotProduct(vec3d)).add(vertices[l].scale((double)(f9 * f9) - vec3d.dotProduct(vec3d))).add(vec3d.crossProduct(vertices[l]).scale((double)(2.0F * f9)));
			}
		}

		buff.pos((double)rpx + vertices[0].x, (double)rpy + vertices[0].y, (double)rpz + vertices[0].z).tex((double)maxU, (double)maxV).color(this.particleRed, this.particleGreen, this.particleBlue, this.particleAlpha).lightmap(lightmapX, lightmapY).endVertex();
		buff.pos((double)rpx + vertices[1].x, (double)rpy + vertices[1].y, (double)rpz + vertices[1].z).tex((double)maxU, (double)minV).color(this.particleRed, this.particleGreen, this.particleBlue, this.particleAlpha).lightmap(lightmapX, lightmapY).endVertex();
		buff.pos((double)rpx + vertices[2].x, (double)rpy + vertices[2].y, (double)rpz + vertices[2].z).tex((double)minU, (double)minV).color(this.particleRed, this.particleGreen, this.particleBlue, this.particleAlpha).lightmap(lightmapX, lightmapY).endVertex();
		buff.pos((double)rpx + vertices[3].x, (double)rpy + vertices[3].y, (double)rpz + vertices[3].z).tex((double)minU, (double)maxV).color(this.particleRed, this.particleGreen, this.particleBlue, this.particleAlpha).lightmap(lightmapX, lightmapY).endVertex();

		buff.pos((double)rpx + vertices[1].x, (double)rpy + vertices[1].y, (double)rpz + vertices[1].z).tex((double)maxU, (double)minV).color(this.particleRed, this.particleGreen, this.particleBlue, this.particleAlpha).lightmap(lightmapX, lightmapY).endVertex();
		buff.pos((double)rpx + vertices[0].x, (double)rpy + vertices[0].y, (double)rpz + vertices[0].z).tex((double)maxU, (double)maxV).color(this.particleRed, this.particleGreen, this.particleBlue, this.particleAlpha).lightmap(lightmapX, lightmapY).endVertex();
		buff.pos((double)rpx + vertices[3].x, (double)rpy + vertices[3].y, (double)rpz + vertices[3].z).tex((double)minU, (double)maxV).color(this.particleRed, this.particleGreen, this.particleBlue, this.particleAlpha).lightmap(lightmapX, lightmapY).endVertex();
		buff.pos((double)rpx + vertices[2].x, (double)rpy + vertices[2].y, (double)rpz + vertices[2].z).tex((double)minU, (double)minV).color(this.particleRed, this.particleGreen, this.particleBlue, this.particleAlpha).lightmap(lightmapX, lightmapY).endVertex();
	}

@Override
	public void renderParticle(BufferBuilder vertexBuffer, Entity entity, float partialTicks, float rotationX, float rotationZ, float rotationYZ, float rotationXY, float rotationXZ) {
		if(!this.spawnMore) {
			Minecraft.getMinecraft().getTextureManager().bindTexture(TEXTURE);

			float umin = 0;
			float umax = 1;
			float vmin = 0;
			float vmax = 1;

			float scale = this.particleScale * ((this.particleAge + partialTicks) / (float)this.particleMaxAge);

			Vec3d camPos = ActiveRenderInfo.getCameraPosition();

			float ipx = (float)(this.prevPosX + (this.posX - this.prevPosX) * (double)partialTicks - (interpPosX + camPos.x));
			float ipy = (float)(this.prevPosY + (this.posY - this.prevPosY) * (double)partialTicks - (interpPosY + camPos.y));
			float ipz = (float)(this.prevPosZ + (this.posZ - this.prevPosZ) * (double)partialTicks - (interpPosZ + camPos.z));

			float len = (float)Math.sqrt(ipx*ipx + ipy*ipy + ipz*ipz);

			if(len > 0) {
				ipx /= len;
				ipy /= len;
				ipz /= len;
			}

			ipx += camPos.x;
			ipy += camPos.y;
			ipz += camPos.z;

			Vec3d[] rotation = new Vec3d[] {new Vec3d((double)(-rotationX * scale - rotationXY * scale), (double)(-rotationZ * scale), (double)(-rotationYZ * scale - rotationXZ * scale)), new Vec3d((double)(-rotationX * scale + rotationXY * scale), (double)(rotationZ * scale), (double)(-rotationYZ * scale + rotationXZ * scale)), new Vec3d((double)(rotationX * scale + rotationXY * scale), (double)(rotationZ * scale), (double)(rotationYZ * scale + rotationXZ * scale)), new Vec3d((double)(rotationX * scale - rotationXY * scale), (double)(-rotationZ * scale), (double)(rotationYZ * scale - rotationXZ * scale))};

			if (this.particleAngle != 0.0F) {
				float interpolatedRoll = this.particleAngle + (this.particleAngle - this.prevParticleAngle) * partialTicks;
				float cos = MathHelper.cos(interpolatedRoll * 0.5F);
				float lookX = MathHelper.sin(interpolatedRoll * 0.5F) * (float)cameraViewDir.x;
				float lookY = MathHelper.sin(interpolatedRoll * 0.5F) * (float)cameraViewDir.y;
				float lookZ = MathHelper.sin(interpolatedRoll * 0.5F) * (float)cameraViewDir.z;
				Vec3d look = new Vec3d((double)lookX, (double)lookY, (double)lookZ);

				for (int l = 0; l < 4; ++l) {
					rotation[l] = look.scale(2.0D * rotation[l].dotProduct(look)).add(rotation[l].scale((double)(cos * cos) - look.dotProduct(look))).add(look.crossProduct(rotation[l]).scale((double)(2.0F * cos)));
				}
			}

			float alpha = MathHelper.clamp((this.particleMaxAge - (this.particleAge + partialTicks)) / 10.0F, 0, 1);

			GlStateManager.color(1, 1, 1, 1);

			GlStateManager.disableLighting();
			GlStateManager.alphaFunc(GL11.GL_GREATER, 0);
			GlStateManager.disableDepth();
			GlStateManager.enableTexture2D();
			GlStateManager.enableBlend();
			GlStateManager.blendFunc(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA);

			vertexBuffer.begin(GL11.GL_QUADS, DefaultVertexFormats.PARTICLE_POSITION_TEX_COLOR_LMAP);
			vertexBuffer.pos((double)ipx + rotation[0].x, (double)ipy + rotation[0].y, (double)ipz + rotation[0].z).tex((double)umax, (double)vmax).color(this.particleRed, this.particleGreen, this.particleBlue, alpha).lightmap(240, 240).endVertex();
			vertexBuffer.pos((double)ipx + rotation[1].x, (double)ipy + rotation[1].y, (double)ipz + rotation[1].z).tex((double)umax, (double)vmin).color(this.particleRed, this.particleGreen, this.particleBlue, alpha).lightmap(240, 240).endVertex();
			vertexBuffer.pos((double)ipx + rotation[2].x, (double)ipy + rotation[2].y, (double)ipz + rotation[2].z).tex((double)umin, (double)vmin).color(this.particleRed, this.particleGreen, this.particleBlue, alpha).lightmap(240, 240).endVertex();
			vertexBuffer.pos((double)ipx + rotation[3].x, (double)ipy + rotation[3].y, (double)ipz + rotation[3].z).tex((double)umin, (double)vmax).color(this.particleRed, this.particleGreen, this.particleBlue, alpha).lightmap(240, 240).endVertex();
			Tessellator.getInstance().draw();

			GlStateManager.disableBlend();
			GlStateManager.enableDepth();
			GlStateManager.alphaFunc(GL11.GL_GREATER, 0.1F);
		}
	}

@Override
	public void onUpdate() {
		super.onUpdate();

		int brightness = this.getBrightnessForRender(1);
		this.lightmapX = (brightness >> 16) & 65535;
		this.lightmapY = brightness & 65535;

		if(this.onGround) {
			this.motionX /= 0.699999988079071D;
			this.motionZ /= 0.699999988079071D;
		}


		double speed = MathHelper.sqrt(this.motionX * this.motionX + this.motionY * this.motionY + this.motionZ * this.motionZ);

		Vec3d dir = this.end.get().subtract(this.start);
		if(dir.lengthSquared() > 0.1f) {
			dir = dir.normalize();
		} else {
			dir = Vec3d.ZERO;
		}
		Vec3d normal = new Vec3d(this.face.getDirectionVec());
		Vec3d motion = new Vec3d(this.motionX, this.motionY, this.motionZ);
		Vec3d side = motion.normalize().crossProduct(normal);

		if(this.rand.nextInt(20) == 0) {
			this.rotateBias = ((float)this.rand.nextFloat() - 0.5f) * 0.5f;
		}

		Vec3d newMotion = motion.add(side.scale(speed * ((this.rand.nextFloat() - 0.5f) * 0.5f + this.rotateBias))).add(dir.scale(speed * this.rand.nextFloat() * 0.85f)).normalize().scale(speed);
		this.motionX = newMotion.x;
		this.motionY = newMotion.y;
		this.motionZ = newMotion.z;

		double dirX = this.motionX / speed;
		double dirY = this.motionY / speed;
		double dirZ = this.motionZ / speed;

		double ahead = this.particleScale * 0.2f * 0.125f * 8;

		BlockPos pos = new BlockPos(this.posX + dirX * ahead - this.face.getXOffset() * 0.1f, this.posY + dirY * ahead - this.face.getYOffset() * 0.1f, this.posZ + dirZ * ahead - this.face.getZOffset() * 0.1f);

		IBlockState state = this.world.getBlockState(pos);

		if(!state.isFullCube()) {
			this.particleAge = this.particleMaxAge;
		}

		Vec3d perpendicular;
		switch(this.face) {
		case UP:
			perpendicular = new Vec3d(1, 0, 0);
			break;
		case DOWN:
			perpendicular = new Vec3d(-1, 0, 0);
			break;
		default:
			perpendicular = new Vec3d(0, 1, 0);
		}
		Vec3d perpendicular2 = perpendicular.crossProduct(normal);

		double y = perpendicular.dotProduct(motion);
		double x = perpendicular2.dotProduct(motion);

		this.prevParticleAngle = this.particleAngle;
		this.particleAngle = (float) MathHelper.atan2(y, x) + (float)Math.PI * 0.5f;
	}

@Override
	public void renderParticle(BufferBuilder buff, Entity entityIn, float partialTicks, float rx, float rz, float ryz, float rxy, float rxz) {
		float minU = (float)this.particleTextureIndexX / 16.0F;
		float maxU = minU + 0.0624375F;
		float minV = (float)this.particleTextureIndexY / 16.0F;
		float maxV = minV + 0.0624375F;
		float scale = 0.1F * this.particleScale * 2;

		if(this.particleTexture != null) {
			minU = this.particleTexture.getMinU();
			maxU = this.particleTexture.getMaxU();
			minV = this.particleTexture.getMinV();
			maxV = this.particleTexture.getMaxV();
		}

		float rpx = (float)(this.prevPosX + (this.posX - this.prevPosX) * (double)partialTicks - interpPosX);
		float rpy = (float)(this.prevPosY + (this.posY - this.prevPosY) * (double)partialTicks - interpPosY);
		float rpz = (float)(this.prevPosZ + (this.posZ - this.prevPosZ) * (double)partialTicks - interpPosZ);

		Vec3i normal = this.face.getDirectionVec();

		float pp1x = 0, pp1y = 0, pp1z = 0;
		switch(this.face) {
		case UP:
			pp1x = 1;
			break;
		case DOWN:
			pp1x = -1;
			break;
		default:
			pp1y = 1;
			break;
		}

		float pp2x = crossX(pp1x, pp1y, pp1z, (float) normal.getX(), (float) normal.getY(), (float) normal.getZ());
		float pp2y = crossY(pp1x, pp1y, pp1z, (float) normal.getX(), (float) normal.getY(), (float) normal.getZ());
		float pp2z = crossZ(pp1x, pp1y, pp1z, (float) normal.getX(), (float) normal.getY(), (float) normal.getZ());

		float yOffset = 0.125f;

		float v1x = (pp1x - pp2x + pp1x * yOffset) * scale;
		float v1y = (pp1y - pp2y + pp1y * yOffset) * scale;
		float v1z = (pp1z - pp2z + pp1z * yOffset) * scale;
		float v2x = (-pp1x - pp2x + pp1x * yOffset) * scale;
		float v2y = (-pp1y - pp2y + pp1y * yOffset) * scale;
		float v2z = (-pp1z - pp2z + pp1z * yOffset) * scale;
		float v3x = (-pp1x + pp2x + pp1x * yOffset) * scale;
		float v3y = (-pp1y + pp2y + pp1y * yOffset) * scale;
		float v3z = (-pp1z + pp2z + pp1z * yOffset) * scale;
		float v4x = (pp1x + pp2x + pp1x * yOffset) * scale;
		float v4y = (pp1y + pp2y + pp1y * yOffset) * scale;
		float v4z = (pp1z + pp2z + pp1z * yOffset) * scale;

		if(this.particleAngle != 0.0F) {
			float angle = this.particleAngle + (this.particleAngle - this.prevParticleAngle) * partialTicks;
			float cos = MathHelper.cos(angle * 0.5F);
			float rdx = MathHelper.sin(angle * 0.5F) * this.face.getXOffset();
			float rdy = MathHelper.sin(angle * 0.5F) * this.face.getYOffset();
			float rdz = MathHelper.sin(angle * 0.5F) * this.face.getZOffset();

			float dotrdrd = cos * cos - dot(rdx, rdy, rdz, rdx, rdy, rdz);

			float dotvrd = 2 * dot(v1x, v1y, v1z, rdx, rdy, rdz);
			float nx = rdx * dotvrd + v1x * dotrdrd + crossX(rdx, rdy, rdz, v1x, v1y, v1z) * 2 * cos;
			float ny = rdy * dotvrd + v1y * dotrdrd + crossY(rdx, rdy, rdz, v1x, v1y, v1z) * 2 * cos;
			float nz = rdz * dotvrd + v1z * dotrdrd + crossZ(rdx, rdy, rdz, v1x, v1y, v1z) * 2 * cos;
			v1x = nx;
			v1y = ny;
			v1z = nz;

			dotvrd = 2 * dot(v2x, v2y, v2z, rdx, rdy, rdz);
			nx = rdx * dotvrd + v2x * dotrdrd + crossX(rdx, rdy, rdz, v2x, v2y, v2z) * 2 * cos;
			ny = rdy * dotvrd + v2y * dotrdrd + crossY(rdx, rdy, rdz, v2x, v2y, v2z) * 2 * cos;
			nz = rdz * dotvrd + v2z * dotrdrd + crossZ(rdx, rdy, rdz, v2x, v2y, v2z) * 2 * cos;
			v2x = nx;
			v2y = ny;
			v2z = nz;

			dotvrd = 2 * dot(v3x, v3y, v3z, rdx, rdy, rdz);
			nx = rdx * dotvrd + v3x * dotrdrd + crossX(rdx, rdy, rdz, v3x, v3y, v3z) * 2 * cos;
			ny = rdy * dotvrd + v3y * dotrdrd + crossY(rdx, rdy, rdz, v3x, v3y, v3z) * 2 * cos;
			nz = rdz * dotvrd + v3z * dotrdrd + crossZ(rdx, rdy, rdz, v3x, v3y, v3z) * 2 * cos;
			v3x = nx;
			v3y = ny;
			v3z = nz;

			dotvrd = 2 * dot(v4x, v4y, v4z, rdx, rdy, rdz);
			nx = rdx * dotvrd + v4x * dotrdrd + crossX(rdx, rdy, rdz, v4x, v4y, v4z) * 2 * cos;
			ny = rdy * dotvrd + v4y * dotrdrd + crossY(rdx, rdy, rdz, v4x, v4y, v4z) * 2 * cos;
			nz = rdz * dotvrd + v4z * dotrdrd + crossZ(rdx, rdy, rdz, v4x, v4y, v4z) * 2 * cos;
			v4x = nx;
			v4y = ny;
			v4z = nz;
		}

		float alpha;
		if(this.particleAge >= this.particleMaxAge - 5) {
			alpha = this.particleAlpha * (this.particleMaxAge - this.particleAge) / 5.0f;
		} else if(this.particleAge <= 5) {
			alpha = this.particleAlpha * this.particleAge / 5.0f;
		} else {
			alpha = this.particleAlpha;
		}

		buff.pos((double)rpx + v1x, (double)rpy + v1y, (double)rpz + v1z).tex((double)maxU, (double)maxV).color(this.particleRed, this.particleGreen, this.particleBlue, alpha).lightmap(this.lightmapX, this.lightmapY).endVertex();
