                        float d3 = blockpos.getZ() + (float) (aabb.minZ - ez);
                        float d4 = blockpos.getZ() + (float) (aabb.maxZ - ez);
                        if (d0 < minX) d0 = (float) minX;
                        if (d1 > maxX) d1 = (float) maxX;
                        if (d3 < minZ) d3 = (float) minZ;
                        if (d4 > maxZ) d4 = (float) maxZ;
                        Vec2 corners[] = new Vec2[] {
