        ModelPart activeRoot = slim ? this.statue_slim : this.statue;
        this.bindParts(activeRoot);
        pStack.pushPose();
        pStack.scale(-1.0F, -1.0F, 1.0F);
        pStack.translate(-0.5D, 0.0D, 0.5D);
