public static void render(TrailEffect effect, VertexConsumer consumer, PoseStack stack, TrailEffect.TrailOffsetFunction function, boolean solid, boolean particleFormat, float r, float g, float b, float a, float u0, float u1, float v0, float v1, int light) {
        int size = effect.renderPoints.size();
        if (size < 2) return;

        Camera camera = Minecraft.getInstance().gameRenderer.getMainCamera();
        float halfWidth = effect.getWidth() / 2;

        Vec3[] tangents = new Vec3[size];
        for (int i = 0; i < size; i++) {
            if (i == 0) {
                Vec3 delta = effect.renderPoints.get(1).pos().subtract(effect.renderPoints.get(0).pos());
                tangents[i] = delta.lengthSqr() < 1e-8 ? new Vec3(0, 0, 1) : delta.normalize();
            } else if (i == size - 1) {
                Vec3 delta = effect.renderPoints.get(size - 1).pos().subtract(effect.renderPoints.get(size - 2).pos());
                tangents[i] = delta.lengthSqr() < 1e-8 ? tangents[i - 1] : delta.normalize();
            } else {
                Vec3 prevToNext = effect.renderPoints.get(i + 1).pos().subtract(effect.renderPoints.get(i - 1).pos());
                tangents[i] = prevToNext.lengthSqr() < 1e-8 ? tangents[i - 1] : prevToNext.normalize();
            }
        }

        Vec3[] upperOffsets = new Vec3[size];
        Vec3[] lowerOffsets = new Vec3[size];
        for (int i = 0; i < size; i++) {
            Vec3 tangent = tangents[i];
            if (tangent.lengthSqr() < 0.5) {
                tangent = new Vec3(0, 1, 0);
            }
            Vec3 offsetDir = function.calculateTrailOffset(effect.renderPoints.get(i).pos().subtract(camera.getPosition()), camera.getXRot(), camera.getYRot(), tangent).normalize();
            if (offsetDir.lengthSqr() < 0.5) {
                offsetDir = new Vec3(0, 1, 0);
            }
            upperOffsets[i] = offsetDir.scale(halfWidth);
            lowerOffsets[i] = offsetDir.scale(-halfWidth);
            if (i > 0 && upperOffsets[i].normalize().dot(upperOffsets[i - 1].normalize()) < 0) {
                upperOffsets[i] = upperOffsets[i].reverse();
                lowerOffsets[i] = lowerOffsets[i].reverse();
            }
        }

        PoseStack.Pose pose = stack.last();
        for (int i = 0; i < size - 1; i++) {
            TrailEffect.TrailPoint from = effect.renderPoints.get(i);
            TrailEffect.TrailPoint to = effect.renderPoints.get(i + 1);

            Vec3 fromUpper = from.pos().add(upperOffsets[i]);
            Vec3 toUpper = to.pos().add(upperOffsets[i + 1]);
            Vec3 toLower = to.pos().add(lowerOffsets[i + 1]);
            Vec3 fromLower = from.pos().add(lowerOffsets[i]);

            float fromAlpha = solid ? 1 : Mth.clamp(a * from.progressFactor(), 0, 1);
            float toAlpha = solid ? 1 : Mth.clamp(a * to.progressFactor(), 0, 1);

            vertex(consumer, pose, fromUpper, Mth.lerp(from.progressFactor(), u0, u1), v0, r, g, b, fromAlpha, light, particleFormat);
            vertex(consumer, pose, toUpper, Mth.lerp(to.progressFactor(), u0, u1), v0, r, g, b, toAlpha, light, particleFormat);
            vertex(consumer, pose, toLower, Mth.lerp(to.progressFactor(), u0, u1), v1, r, g, b, toAlpha, light, particleFormat);
            vertex(consumer, pose, fromLower, Mth.lerp(from.progressFactor(), u0, u1), v1, r, g, b, fromAlpha, light, particleFormat);
        }
    }

private static void vertex(VertexConsumer consumer, PoseStack.Pose pose, Vec3 pos, float u, float v, float r, float g, float b, float alpha, int light, boolean particleFormat) {
        if (particleFormat) {
            consumer.vertex(pose.pose(), (float) pos.x(), (float) pos.y(), (float) pos.z())
                    .uv(u, v).color(r, g, b, alpha).uv2(light).endVertex();
        } else {
            consumer.vertex(pose.pose(), (float) pos.x(), (float) pos.y(), (float) pos.z())
                    .color(r, g, b, alpha).uv(u, v).overlayCoords(OverlayTexture.NO_OVERLAY).uv2(light).normal(pose.normal(), 0, 1, 0).endVertex();
        }
    }

@Override
	public void submit(TntRenderState state, PoseStack stack, SubmitNodeCollector collector, CameraRenderState camera) {
		stack.pushPose();
		stack.translate(0.0D, 0.5D, 0.0D);
		float fuse = state.fuseRemainingInTicks;
		if (fuse < 10.0F) {
			float f = 1.0F - fuse / 10.0F;
			f = Mth.clamp(f, 0.0F, 1.0F);
			f *= f;
			f *= f;
			float f1 = 1.0F + f * 0.3F;
			stack.scale(f1, f1, f1);
		}
		stack.mulPose(Axis.YP.rotationDegrees(-90.0F));
		stack.translate(-0.5D, -0.5D, 0.5D);
		stack.mulPose(Axis.YP.rotationDegrees(90.0F));
		if (!state.blockState.isEmpty()) {
			TntMinecartRenderer.submitWhiteSolidBlock(state.blockState, stack, collector, state.lightCoords, (int)fuse / 5 % 2 == 0, state.outlineColor);
		}
		stack.popPose();
		super.submit(state, stack, collector, camera);
	}

@Override
	protected void setupRotations(ForgottenGuardianRenderState state, PoseStack poseStack, float bodyRot, float entityScale) {
		super.setupRotations(state, poseStack, bodyRot, entityScale);
		if (!(state.walkAnimationSpeed < 0.01D)) {
			float wp = state.walkAnimationPos + 6.0F;
			float triangleWave = (Math.abs(wp % 13.0F - 6.5F) - 3.25F) / 3.25F;
			poseStack.mulPose(Axis.ZP.rotationDegrees(6.5F * triangleWave));
		}
	}

@Override
	protected void setupRotations(LivingEntityRenderState state, PoseStack stack, float bodyRot, float entityScale) {
		super.setupRotations(state, stack, bodyRot, entityScale);
		float f = 4.3F * Mth.sin(0.6F * state.ageInTicks);
		stack.mulPose(Axis.YP.rotationDegrees(f));
		if (!state.isInWater) {
			stack.translate(0.1F, 0.1F, -0.1F);
			stack.mulPose(Axis.ZP.rotationDegrees(90.0F));
		}
	}

@Override
	public void submit(MysteriousPotRenderState state, PoseStack stack, SubmitNodeCollector collector, CameraRenderState camera) {
		if (!state.active) {
			stack.pushPose();
			stack.scale(-1.0F, -1.0F, 1.0F);
			stack.translate(-0.5F, 0.0F, -0.5F);
			float wiggle = state.wiggleTicks / 10.0F;
			float f5 = Mth.sin(-wiggle * 4.0F * Mth.PI) * 0.125F;
			float f6 = 1.0F - wiggle;
			stack.rotateAround(Axis.YP.rotation(f5 * f6), 0.5F, 0.0F, 0.5F);
			stack.translate(0.5F, -1.501F, 0.5F);
			collector.submitModel(this.inactiveModel, Unit.INSTANCE, stack, RenderTypes.entitySolid(DepthrockPotRenderer.TEXTURE), state.lightCoords, OverlayTexture.NO_OVERLAY, -1, null, 0, null);
			stack.popPose();
		} else {
			super.submit(state, stack, collector, camera);
		}
	}

@Override
	public void submit(SlingshotProjectileRenderState state, PoseStack poseStack, SubmitNodeCollector submitNodeCollector, CameraRenderState camera) {
		poseStack.pushPose();

		if (state.isBlock) {
			poseStack.scale(3.0F, 3.0F, 3.0F);
			poseStack.mulPose(Axis.YP.rotationDegrees(state.ageInTicks * 20));
		} else {
			poseStack.mulPose(camera.orientation);
		}
		state.item.submit(poseStack, submitNodeCollector, state.lightCoords, OverlayTexture.NO_OVERLAY, state.outlineColor);
		poseStack.popPose();
		super.submit(state, poseStack, submitNodeCollector, camera);
	}

@SuppressWarnings("deprecation")
    @Override
    public void render(Shoal shoal, float entityYaw, float partialTicks, PoseStack poseStack, MultiBufferSource buffer, int packedLight)
    {
        poseStack.pushPose();
        var ageInTicks = shoal.tickCount + partialTicks;
        var list = shoal.getShoalFishClient();
        var level = shoal.level();
        var blockPos = shoal.blockPosition();

        var offsetPerFish = 360F / list.size();
        var modifier = 15F;
        var rotationModifier = 0.25F;
        var radiusBase = 1.0F;
        var radiusMod = 0.1F;
        var v = 1F / 8F;

        poseStack.translate(-0.05F, 0F, 0F);

        if (level.getBlockState(blockPos.above()).isSolid())
        {
            packedLight = LightTexture.pack(this.getBlockLightLevel(shoal, blockPos.below(2)), this.getSkyLightLevel(shoal, blockPos.below(2)));
        }

        for (var index = 0; index < list.size(); index++)
        {
            var entity = list.get(index);
            var offset = offsetPerFish * index;
            float deg = (int) (ageInTicks / rotationModifier % 360F + offset);
            var rad = (float) (deg / 180F * Math.PI);
            var radiusX = (float) (radiusBase + radiusMod * Math.sin(ageInTicks / modifier));
            var radiusZ = (float) (radiusBase + radiusMod * Math.cos(ageInTicks / modifier));
            var x = (float) (radiusX * Math.cos(rad));
            var z = (float) (radiusZ * Math.sin(rad));
            var y = (float) Math.cos((ageInTicks + 50 * index) / 5F) / 10F;

            poseStack.pushPose();
            poseStack.translate(x, y, z);
            var yRotate = Math.max(0.6F, Mth.sin(ageInTicks * 0.1f) / 4.0F);
            var zRotate = (float) Math.cos(0.1f * ageInTicks) / 16F;

            v /= 2F;
            poseStack.translate(v, v, v);
            poseStack.mulPose(new Quaternionf().rotateAxis(-rad, 0, yRotate, zRotate));
            poseStack.translate(-v, -v, -v);
            v *= 2F;

            this.renderEntityInShoal(entity, ageInTicks, entityYaw, partialTicks, poseStack, buffer, packedLight);
            poseStack.popPose();
        }

        poseStack.popPose();
        super.render(shoal, entityYaw, partialTicks, poseStack, buffer, packedLight);
    }

@SuppressWarnings({ "rawtypes", "unchecked" })
    private void renderEntityInShoal(Entity entity, float ageInTicks, float entityYaw, float partialTicks, PoseStack poseStack, MultiBufferSource buffer, int packedLight)
    {
        var renderer = (EntityRenderer<? super Entity>) ((EntityRenderDispatcherAccessor) this.entityRenderDispatcher).getRenderers().get(entity.getType());
        renderer.render(entity, entityYaw, ageInTicks, poseStack, buffer, packedLight);

        if (entity instanceof LivingEntity livingEntity && renderer instanceof LivingEntityRenderer livingEntityRenderer)
        {
            var yBodyRot = Mth.rotLerp(partialTicks, livingEntity.yBodyRotO, livingEntity.yBodyRot);
            var yHeadRot = Mth.rotLerp(partialTicks, livingEntity.yHeadRotO, livingEntity.yHeadRot);
            var netHeadYaw = yHeadRot - yBodyRot;
            var limbSwingAmount = 0.0F;
            var limbSwing = 0.0F;
            var headPitch = Mth.lerp(partialTicks, livingEntity.xRotO, livingEntity.getXRot());

            if (LivingEntityRenderer.isEntityUpsideDown(livingEntity))
            {
                headPitch *= -1.0F;
                netHeadYaw *= -1.0F;
            }

            if (!livingEntity.isPassenger() && livingEntity.isAlive())
            {
                limbSwingAmount = livingEntity.walkAnimation.speed(partialTicks);
                limbSwing = livingEntity.walkAnimation.position(partialTicks);

                if (livingEntity.isBaby())
                {
                    limbSwing *= 3.0F;
                }

                if (limbSwingAmount > 1.0F)
                {
                    limbSwingAmount = 1.0F;
                }
            }

            var model = livingEntityRenderer.getModel();
            model.prepareMobModel(livingEntity, limbSwing, limbSwingAmount, partialTicks);
            model.setupAnim(livingEntity, limbSwing, limbSwingAmount, ageInTicks, netHeadYaw, headPitch);
        }
    }

