@Override
    public void renderRecursively(GeoBone bone, PoseStack poseStack, VertexConsumer buffer, int packedLight, int packedOverlay, float red, float green, float blue, float alpha) {
        poseStack.pushPose();
        RenderUtils.translateMatrixToBone(poseStack, bone);
        RenderUtils.translateToPivotPoint(poseStack, bone);

        boolean rotOverride = bone.rotMat != null;

        if (rotOverride) {
            poseStack.last().pose().multiply(bone.rotMat);
            poseStack.last().normal().mul(new Matrix3f(bone.rotMat));
        } else {
            RenderUtils.rotateMatrixAroundBone(poseStack, bone);
        }

        RenderUtils.scaleMatrixForBone(poseStack, bone);

        if (bone.isTrackingXform()) {
            Matrix4f poseState = poseStack.last().pose().copy();
            Matrix4f localMatrix = RenderUtils.invertAndMultiplyMatrices(poseState, this.dispatchedMat);

            bone.setModelSpaceXform(RenderUtils.invertAndMultiplyMatrices(poseState, this.renderEarlyMat));
            localMatrix.translate(new Vector3f(getRenderOffset(this.animatable, 1)));
            bone.setLocalSpaceXform(localMatrix);

            Matrix4f worldState = localMatrix.copy();

            worldState.translate(new Vector3f(this.animatable.position()));
            bone.setWorldSpaceXform(worldState);
        }

        RenderUtils.translateAwayFromPivotPoint(poseStack, bone);

        if (!bone.isHidden) {
            if (!bone.cubesAreHidden()) {
                for (GeoCube geoCube : bone.childCubes) {
                    poseStack.pushPose();
                    renderCube(geoCube, poseStack, buffer, packedLight, packedOverlay, red, green, blue, alpha);
                    poseStack.popPose();
                }
            }

            for (GeoBone childBone : bone.childBones) {
                renderRecursively(childBone, poseStack, buffer, packedLight, packedOverlay, red, green, blue, alpha);
            }
        }

        poseStack.popPose();
    }

@Override
    public void render(StoneTablet entity, float entityYaw, float partialTick, PoseStack poseStack, MultiBufferSource buffer, int packedLight) {
        poseStack.pushPose();
        poseStack.mulPose(Vector3f.YP.rotationDegrees(180.0f - entityYaw));
        StoneTablet.Variant variant = entity.variant;
        poseStack.scale(0.0625f, 0.0625f, 0.0625f);
        VertexConsumer vertexConsumer = buffer.getBuffer(RenderType.entityCutout(getTextureLocation(entity)));
        renderTablet(poseStack, vertexConsumer, entity, variant.sizeX, variant.sizeY, variant.offsetX, variant.offsetY);
        poseStack.popPose();
        super.render(entity, entityYaw, partialTick, poseStack, buffer, packedLight);
    }

private void renderTablet(PoseStack poseStack, VertexConsumer vertexConsumer, StoneTablet entity, int width, int height, int texU, int texV) {
        PoseStack.Pose pose = poseStack.last();
        Matrix4f matrix4f = pose.pose();
        Matrix3f matrix3f = pose.normal();
        float offsetX = -width / 2.0f;
        float offsetY = -height / 2.0f;
        for (int blockX = 0; blockX < width / 16; ++blockX) {
            for (int blockZ = 0; blockZ < height / 16; ++blockZ) {
                float minX = offsetX + (blockX * 16);
                float maxX = offsetX + ((blockX + 1) * 16);
                float minY = offsetY + (blockZ * 16);
                float maxY = offsetY + ((blockZ + 1) * 16);
                int light = getLightColor(entity, (maxX + minX) / 2.0f, (maxY + minY) / 2.0f);
                //texture coordinates go bottom -> top and right -> left
                //vertex coordinates map the textures onto the block with 0 in the middle and go bottom -> top and right -> left
                float minTexX = (texU + width - blockX * 16) / 256f;
                float maxTexX = (texU + width - (blockX + 1) * 16) / 256f;
                float minTexY = (texV + height - blockZ * 16) / 256f;
                float maxTexY = (texV + height - (blockZ + 1) * 16) / 256f;
                //Front
                vertex(matrix4f, matrix3f, vertexConsumer, maxX, minY, maxTexX, minTexY, 0.4f, 0, 0, -1, light);//z=-0.5f
                vertex(matrix4f, matrix3f, vertexConsumer, minX, minY, minTexX, minTexY, 0.4f, 0, 0, -1, light);
                vertex(matrix4f, matrix3f, vertexConsumer, minX, maxY, minTexX, maxTexY, 0.4f, 0, 0, -1, light);
                vertex(matrix4f, matrix3f, vertexConsumer, maxX, maxY, maxTexX, maxTexY, 0.4f, 0, 0, -1, light);

                minTexY = (texV + (height + 128) - blockZ * 16) / 256f;
                maxTexY = (texV + (height + 128) - (blockZ + 1) * 16) / 256f;
                vertex(matrix4f, matrix3f, vertexConsumer, maxX, maxY, maxTexX, maxTexY, 0.5f, 0, 0, 1, light);//z=0.5f
                vertex(matrix4f, matrix3f, vertexConsumer, minX, maxY, minTexX, maxTexY, 0.5f, 0, 0, 1, light);
                vertex(matrix4f, matrix3f, vertexConsumer, minX, minY, minTexX, minTexY, 0.5f, 0, 0, 1, light);
                vertex(matrix4f, matrix3f, vertexConsumer, maxX, minY, maxTexX, minTexY, 0.5f, 0, 0, 1, light);
            }
        }
    }

@Override
    public void render(T entity, float entityYaw, float partialTicks, PoseStack poseStack, MultiBufferSource buffer, int packedLight) {
        poseStack.pushPose();
        model.riding = entity.isPassenger();
        float yBodyRotDiff = Mth.rotLerp(partialTicks, entity.yRotO, entity.getYRot());
        float xRotDiff = Mth.lerp(partialTicks, entity.xRotO, entity.getXRot());
        setupRotations(poseStack, yBodyRotDiff);
        poseStack.scale(-1, -1, 1);
        poseStack.translate(0.0, -1.501f, 0.0);
        model.prepareMobModel(entity, 0, 0, partialTicks);
        model.setupAnim(entity, partialTicks, 0, 0, 0, xRotDiff);
        VertexConsumer vertexConsumer = buffer.getBuffer(model.renderType(_getTextureLocation(entity)));
        int m = OverlayTexture.pack(OverlayTexture.u(0), OverlayTexture.v(false));
        model.renderToBuffer(poseStack, vertexConsumer, packedLight, m, 1, 1, 1, 1);
        poseStack.popPose();
        super.render(entity, entityYaw, partialTicks, poseStack, buffer, packedLight);
    }

@Override
	public void submit(BlockChainGoblinRenderState state, PoseStack stack, SubmitNodeCollector collector, CameraRenderState camera) {
		super.submit(state, stack, collector, camera);

		stack.pushPose();

		double blockInX = (state.chainBlockPos.x() - state.x);
		double blockInY = (state.chainBlockPos.y() - state.y);
		double blockInZ = (state.chainBlockPos.z() - state.z);

		stack.translate(blockInX, blockInY, blockInZ);

		stack.mulPose(Axis.YP.rotationDegrees(180 - Mth.wrapDegrees(state.yRot)));
		stack.mulPose(Axis.XP.rotationDegrees(state.xRot));

		stack.scale(-1.0F, -1.0F, 1.0F);
		collector.submitModel(this.model, state, stack, this.model.renderType(BLOCK_AND_CHAIN_TEXTURE), state.lightCoords, OverlayTexture.NO_OVERLAY, state.outlineColor, null);
		stack.popPose();

		if (state.deathTime <= 0) {
			stack.pushPose();
			stack.translate(0.0D, state.eyeHeight, 0.0D);
			Vec3 xyz = state.chainStartPos;
			BlockChainRenderer.renderChain(false, xyz, stack, collector, state.lightCoords, state.outlineColor, this.chainModel);
			BlockChainRenderer.renderChain(false, xyz, stack, collector, state.lightCoords, state.outlineColor, this.chainModel);
			BlockChainRenderer.renderChain(false, xyz, stack, collector, state.lightCoords, state.outlineColor, this.chainModel);
			BlockChainRenderer.renderChain(false, xyz, stack, collector, state.lightCoords, state.outlineColor, this.chainModel);
			stack.popPose();
		}
	}

@Override
	public void submit(ChainBlockRenderState state, PoseStack stack, SubmitNodeCollector submitNodeCollector, CameraRenderState camera) {
		super.submit(state, stack, submitNodeCollector, camera);
		stack.pushPose();
		RenderType foilRenderType = ItemFeatureRenderer.getFoilRenderType(chainModel.renderType(TEXTURE), false);
		stack.mulPose(Axis.YP.rotationDegrees(state.yRot - 90.0F));
		stack.mulPose(Axis.ZP.rotationDegrees(state.xRot));

		stack.scale(-1.0F, -1.0F, 1.0F);
		submitNodeCollector.order(0).submitModel(this.model, state, stack, this.model.renderType(TEXTURE), state.lightCoords, OverlayTexture.NO_OVERLAY, state.outlineColor, null);
		if (state.isFoil) {
			submitNodeCollector.order(1).submitModel(this.model, state, stack, foilRenderType, state.lightCoords, OverlayTexture.NO_OVERLAY, state.outlineColor, null);
		}
		stack.popPose();
		if (state.chainStartPos != null) {
			stack.pushPose();
			stack.translate(0.0D, state.blockHeight * 0.5D, 0.0D);
			Vec3 xyz = state.chainStartPos;
			double linksPerMeter = 1.5F; // Defines how many chain links per meter. 2.0F there will be two per meter, 0.5F will be one per two meters, etc.
			double links = xyz.length() / linksPerMeter;
			Vec3 offset = xyz.normalize().scale(-linksPerMeter);
			for (int i = 1; i < links; i++) {
				renderChain(state.isFoil, xyz.add(offset.scale(links - i)), stack, submitNodeCollector, Math.max(state.lightCoords, state.ownerLight), state.outlineColor, this.chainModel);
			}
			stack.popPose();
		}
	}

public static void renderChain(boolean renderFoil, Vec3 offset, PoseStack stack, SubmitNodeCollector collector, int light, int outlineColor, ChainModel model) {
		stack.pushPose();
		RenderType foilRenderType = ItemFeatureRenderer.getFoilRenderType(model.renderType(TEXTURE), false);

		stack.translate(offset.x(), offset.y(), offset.z());

		stack.scale(-1.0F, -1.0F, 1.0F);
		collector.submitModel(model, Unit.INSTANCE, stack, model.renderType(TEXTURE), light, OverlayTexture.NO_OVERLAY, outlineColor, null);

		if (renderFoil) {
			collector.submitModel(model, Unit.INSTANCE, stack, foilRenderType, light, OverlayTexture.NO_OVERLAY, outlineColor, null);
		}
		stack.popPose();
	}

