@Override
	public void submit(NagaSegmentRenderState state, PoseStack stack, SubmitNodeCollector buffer, CameraRenderState cameraRenderState) {
		if (!state.isInvisible) {
			stack.pushPose();

			float yawDiff = state.yRot - state.yRotO;
			if (yawDiff > 180) {
				yawDiff -= 360;
			} else if (yawDiff < -180) {
				yawDiff += 360;
			}
			float yaw2 = state.yRotO + yawDiff * state.partialTick;

			stack.mulPose(Axis.YP.rotationDegrees(yaw2));
			stack.mulPose(Axis.XP.rotationDegrees(state.xRot));

			stack.scale(2.0F, 2.0F, 2.0F);
			stack.translate(0.0D, -1.25F, 0.0D);

			super.submit(state, stack, buffer, cameraRenderState);

			stack.popPose();
		}
	}

@Override
	protected void setupRotations(RisingZombieRenderState state, PoseStack stack, float bodyRot, float scale) {
		super.setupRotations(state, stack, bodyRot, scale);
		var tick = state.risingTicks;
		stack.translate(0.0F, -(80.0F - Math.min(80.0F, tick)) / 80.0F, 0.0F);
		stack.translate(0.0F, -(40.0F - Math.clamp(tick - 80.0F, 0.0F, 40.0F)) / 40.0F, 0.0F);
		final float yOff = 1.0F;
		stack.translate(0.0F, yOff, 0.0F);
		stack.mulPose(Axis.XP.rotationDegrees(120.0F * (80.0F - Math.min(80.0F, tick)) / 80.0F));
		stack.mulPose(Axis.XP.rotationDegrees(-30.0F * (40.0F - Math.clamp(tick - 80.0F, 0.0F, 40.0F)) / 40.0F));
		stack.translate(0.0F, -yOff, 0.0F);

	}

