private static void onWorldRender(final RenderLevelStageEvent ev) {
		if (ev.getStage() != RenderLevelStageEvent.Stage.AFTER_PARTICLES || OCCULT_BLOCKS.isEmpty())
			return;

		Minecraft mc = Minecraft.getInstance();
		boolean rendered = false;
		PoseStack poseStack = ev.getPoseStack();
		Vec3 cameraPos = mc.gameRenderer.getMainCamera().getPosition();
		VertexConsumer buffer = mc.renderBuffers().bufferSource().getBuffer(CUSTOM_LINES_RENDER_TYPE);

		poseStack.pushPose();
		poseStack.translate(-cameraPos.x, -cameraPos.y, -cameraPos.z);

		PoseStack.Pose pose = poseStack.last();

		RenderSystem.disableDepthTest();
		RenderSystem.depthMask(false);
		RenderSystem.blendFunc(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA);
		RenderSystem.enableBlend();

		OCCULT_BLOCKS.removeIf(entry -> GlobalEvents.tick >= entry.leftInt());

		for (IntObjectPair<List<OccultPickaxe.LocatedBlock>> entry : OCCULT_BLOCKS) {
			for (Iterator<OccultPickaxe.LocatedBlock> iterator = entry.right().iterator(); iterator.hasNext();) {
				OccultPickaxe.LocatedBlock block = iterator.next();

				if (GlobalEvents.tick % 2 == 1 && mc.player.level().getBlockState(block.pos()) != block.state()) {
					iterator.remove();

					continue;
				}

				BlockPos pos = block.pos();
				VoxelShape shape = block.state().getShape(mc.level, pos, CollisionContext.of(mc.player));
				ColourUtil.Colour colour = block.colour();
				rendered = true;

				shape.forAllEdges((minX, minY, minZ, maxX, maxY, maxZ) -> {
					float lengthX = (float)(maxX - minX);
					float lengthY = (float)(maxY - minY);
					float lengthZ = (float)(maxZ - minZ);
					float length = Mth.sqrt(lengthX * lengthX + lengthY * lengthY + lengthZ * lengthZ);
					lengthX /= length;
					lengthY /= length;
					lengthZ /= length;

					buffer.addVertex(pose.pose(), (float)minX + pos.getX(), (float)minY + pos.getY(), (float)minZ + pos.getZ()).setColor(colour.red(), colour.green(), colour.blue(), colour.alpha()).setNormal(pose, lengthX, lengthY, lengthZ);
					buffer.addVertex(pose.pose(), (float)maxX + pos.getX(), (float)maxY + pos.getY(), (float)maxZ + pos.getZ()).setColor(colour.red(), colour.green(), colour.blue(), colour.alpha()).setNormal(pose, lengthX, lengthY, lengthZ);
				});
			}
		}

		poseStack.popPose();
		RenderSystem.polygonMode(GL11.GL_FRONT_AND_BACK, GL11.GL_FILL);
		RenderSystem.disableBlend();
		RenderSystem.enableDepthTest();
		RenderSystem.depthMask(true);

		if (rendered)
			mc.renderBuffers().bufferSource().endBatch();
	}

@Override
	public void render(T entity, float yaw, float partialTicks, PoseStack matrix, MultiBufferSource buffer, int packedLight) {
		matrix.pushPose();
		matrix.scale(-1.0F, -1.0F, 1.0F);
		preRenderCallback(entity, matrix, partialTicks);

		float pitch = Mth.lerp(partialTicks, entity.xRotO, entity.getXRot());

		model.prepareMobModel(entity, 0, 0, partialTicks);
		model.setupAnim(entity, 0, partialTicks, entity.tickCount, 0, pitch);
		matrix.translate(0.0D, -1.6f, 0.0D);

		boolean visible = !entity.isInvisible();
		boolean shade = !visible && !entity.isInvisibleTo(Minecraft.getInstance().player);
		RenderType rendertype = getRenderType(entity, visible, shade);

		if (rendertype != null) {
			VertexConsumer vertexConsumer = buffer.getBuffer(rendertype);

			this.model.renderToBuffer(matrix, vertexConsumer, packedLight, OverlayTexture.NO_OVERLAY, ColourUtil.ARGB(1f, 1f, 1f, shade ? 0.15f : 1f));
		}

		matrix.popPose();
		super.render(entity, yaw, partialTicks, matrix, buffer, packedLight);
	}

@Override
	public void render(T entity, float yaw, float partialTick, PoseStack poseStack, MultiBufferSource buffer, int packedLight) {
		poseStack.pushPose();
		poseStack.scale(this.scale, this.scale, this.scale);
		poseStack.mulPose(this.entityRenderDispatcher.cameraOrientation());
		poseStack.mulPose(Axis.YP.rotationDegrees(180));

		PoseStack.Pose poseState = poseStack.last();
		Matrix4f pose = poseState.pose();
		VertexConsumer vertexConsumer = buffer.getBuffer(this.renderType);

		vertex(vertexConsumer, pose, poseState, packedLight, 0, 0, 0, 1);
		vertex(vertexConsumer, pose, poseState, packedLight, 1, 0, 1, 1);
		vertex(vertexConsumer, pose, poseState, packedLight, 1, 1, 1, 0);
		vertex(vertexConsumer, pose, poseState, packedLight, 0, 1, 0, 0);
		poseStack.popPose();

		super.render(entity, yaw, partialTick, poseStack, buffer, packedLight);
	}

@Override
	public void render(ShoeShotEntity entity, float yaw, float partialTick, PoseStack poseStack, MultiBufferSource buffer, int packedLight) {
		poseStack.pushPose();
		poseStack.scale(this.scale, this.scale, this.scale);
		poseStack.mulPose(this.entityRenderDispatcher.cameraOrientation());
		poseStack.mulPose(Axis.YP.rotationDegrees(180));
		poseStack.mulPose(Axis.XP.rotationDegrees(((entity.tickCount + partialTick) / 0.3f) * (180f / (float)Math.PI)));

		PoseStack.Pose poseState = poseStack.last();
		Matrix4f pose = poseState.pose();
		VertexConsumer vertexConsumer = buffer.getBuffer(this.renderType);

		vertex(vertexConsumer, pose, poseState, packedLight, 0, 0, 0, 1);
		vertex(vertexConsumer, pose, poseState, packedLight, 1, 0, 1, 1);
		vertex(vertexConsumer, pose, poseState, packedLight, 1, 1, 1, 0);
		vertex(vertexConsumer, pose, poseState, packedLight, 0, 1, 0, 0);
		poseStack.popPose();

		RenderNameTagEvent renderNameTagEvent = new RenderNameTagEvent(entity, entity.getDisplayName(), this, poseStack, buffer, packedLight, partialTick);
		NeoForge.EVENT_BUS.post(renderNameTagEvent);

		if (renderNameTagEvent.canRender() != TriState.FALSE && (renderNameTagEvent.canRender() == TriState.TRUE || shouldShowName(entity)))
			renderNameTag(entity, renderNameTagEvent.getContent(), poseStack, buffer, packedLight, partialTick);
	}

