@Override
	protected void applyRotations(BasicLavaFishEntity entityLiving, MatrixStack matrixStackIn, float ageInTicks, float rotationYaw, float partialTicks) {
		super.applyRotations(entityLiving, matrixStackIn, ageInTicks, rotationYaw, partialTicks);

		matrixStackIn.mulPose(Vector3f.YP.rotationDegrees(4.3f * MathHelper.sin(0.6f * ageInTicks)));

		if (!entityLiving.isInLava()) {
			matrixStackIn.translate(0.2f, 0.1f, 0);
			matrixStackIn.mulPose(Vector3f.ZP.rotationDegrees(90));
		}
	}

@Override
	protected void applyRotations(BasicFishEntity entityLiving, MatrixStack matrixStackIn, float ageInTicks, float rotationYaw, float partialTicks) {
		super.applyRotations(entityLiving, matrixStackIn, ageInTicks, rotationYaw, partialTicks);

		matrixStackIn.mulPose(Vector3f.YP.rotationDegrees(4.3f * MathHelper.sin(0.6f * ageInTicks)));

		if (!entityLiving.isInWater()) {
			matrixStackIn.translate(0.2f, 0.1f, 0);
			matrixStackIn.mulPose(Vector3f.ZP.rotationDegrees(90));
		}
	}

@Override
	protected void scale(MeganeuropsisEntity entity, MatrixStack matrix, float partialTicks) {
		if (entity.isLanded() && entity.isPassenger())
			matrix.translate(0, -entity.getBbHeight() * 0.75f, 0);

		if (entity.getStartLandingTicks() > 0 && entity.getLandingDirection() != Direction.UP) {
			float landPercentage = (float)MathHelper.clamp(entity.tickCount - entity.getStartLandingTicks(), 0, 10) / 10;
			float rotAmount = 90 * landPercentage;

			switch (entity.getLandingDirection()) {
				case NORTH:
					matrix.mulPose(new Quaternion(Vector3f.XP, -rotAmount, true));
					matrix.translate(0, entity.getBbWidth() * 0.65f * landPercentage,0);
					break;
				case SOUTH:
					matrix.mulPose(new Quaternion(Vector3f.XP, -rotAmount, true));
					//matrix.rotate(new Quaternion(rotAmount * 2, 0, 1, 0);
					matrix.translate(0, entity.getBbWidth() * 0.65f * landPercentage,0);
					break;
				case EAST:
					matrix.mulPose(new Quaternion(Vector3f.XP, -rotAmount, true));
					//matrix.rotate(rotAmount, 0, 0, 1);
					matrix.translate(0, entity.getBbWidth() * 0.65f * landPercentage,0);
					break;
				case WEST:
					matrix.mulPose(new Quaternion(Vector3f.XP, -rotAmount, true));
					matrix.mulPose(new Quaternion(Vector3f.ZP, -rotAmount, true));
					matrix.translate(0, entity.getBbWidth() * 0.65f * landPercentage,0);
					break;
				default:
					break;
			}
		}
	}

@Override
	public void render(MatrixStack matrix, IRenderTypeBuffer buffer, int packedLightIn, AbstractClientPlayerEntity player, float limbSwing, float limbSwingAmount, float partialTicks, float ageInTicks, float netHeadYaw, float headPitch) {
		if (player.isCapeLoaded() && !player.isInvisible() && AoAConfig.CLIENT.showPlayerHalos.get()) {
			AoAHaloUtil.Type chosenHalo = AoAHaloUtil.getHalo(player.getUUID());
			float red = 0;
			float green = 0;
			float blue = 0;

			if (chosenHalo == null)
				return;

			switch (chosenHalo) {
				case Donator:
					red = 1;
					green = 1;
					break;
				case Super_Donator:
				case Crazy_Donator:
					red = 1;
					break;
				case Tslat:
					red = 0.1647f;
					green = 1;
					break;
				case Staff:
					red = 0.6f;
					green = 1;
					blue = 1;
					break;
				case Wiki_Editor:
					blue = 1;
					break;
			}

			getParentModel().halo.copyFrom(renderer.getModel().head);
			IVertexBuilder vertexBuilder = buffer.getBuffer(getRenderType(getTextureLocation(player)));
			getParentModel().renderToBuffer(matrix, vertexBuilder, 15728640, OverlayTexture.NO_OVERLAY, red, green, blue, 1f);
		}
	}

private static RenderType getRenderType(ResourceLocation texture) {
		RenderState.TextureState renderState = new RenderState.TextureState(texture, false, false);
		RenderState.TransparencyState transparencyState = new RenderState.TransparencyState("additive_transparency", () -> {
			RenderSystem.enableBlend();
			RenderSystem.blendFunc(GlStateManager.SourceFactor.ONE, GlStateManager.DestFactor.ONE);
		}, () -> {
			RenderSystem.disableBlend();
			RenderSystem.defaultBlendFunc();
		});
		RenderState.FogState fogState = new RenderState.FogState("black_fog", () -> {
			RenderSystem.fog(2918, 0.0F, 0.0F, 0.0F, 1.0F);
			RenderSystem.enableFog();
		}, () -> {
			FogRenderer.levelFogColor();
			RenderSystem.disableFog();
		});

		return RenderType.create("halo", DefaultVertexFormats.NEW_ENTITY, 7, 256, false, true, RenderType.State.builder().setTextureState(renderState).setTransparencyState(transparencyState).setWriteMaskState(new RenderState.WriteMaskState(true, false)).setDepthTestState(new RenderState.DepthTestState("==", 515)).setDiffuseLightingState(new RenderState.DiffuseLightingState(true)).setFogState(fogState).createCompositeState(false));
	}

@Override
	public void render(BaronBombEntity entity, float entityYaw, float partialTicks, MatrixStack matrix, IRenderTypeBuffer buffer, int packedLight) {
		matrix.pushPose();
		matrix.mulPose(Vector3f.XP.rotationDegrees(180));
		matrix.scale(-1, 1, -1);

		IVertexBuilder vertexBuilder = buffer.getBuffer(RenderType.entityCutoutNoCull(TEXTURE));

		model.setupAnim(entity, 0, 0, entity.tickCount, entityYaw, 0);
		model.renderToBuffer(matrix, vertexBuilder, packedLight, OverlayTexture.NO_OVERLAY, 1, 1, 1, 1);

		matrix.popPose();

		super.render(entity, entityYaw, partialTicks, matrix, buffer, packedLight);
	}

@Override
	public void render(FishingCageEntity entity, float entityYaw, float partialTicks, MatrixStack matrix, IRenderTypeBuffer buffer, int packedLight) {
		matrix.pushPose();
		matrix.translate(0, 1.5d, 0);
		matrix.mulPose(Vector3f.XP.rotationDegrees(180));
		matrix.mulPose(Vector3f.YP.rotationDegrees(entityYaw));
		matrix.scale(-1, 1, -1);

		IVertexBuilder vertexBuilder = buffer.getBuffer(RenderType.entityCutoutNoCull(texture));

		model.setupAnim(entity, 0, 0, entity.tickCount, entityYaw, 0);
		model.renderToBuffer(matrix, vertexBuilder, packedLight, OverlayTexture.NO_OVERLAY, 1, 1, 1, 1);

		matrix.translate(0, 1.4d, 0.1d);
		matrix.mulPose(Vector3f.XP.rotationDegrees(90));

		ItemRenderer itemRenderer = Minecraft.getInstance().getItemRenderer();

		for (ItemStack stack : entity.getLoot()) {
			itemRenderer.renderStatic(stack, ItemCameraTransforms.TransformType.GROUND, packedLight, OverlayTexture.NO_OVERLAY, matrix, buffer);
			matrix.translate(0, -0.15d, 0);
		}

		matrix.popPose();

		super.render(entity, entityYaw, partialTicks, matrix, buffer, packedLight);
	}

@Override
	public void render(GyrocopterEntity entity, float yaw, float partialTicks, MatrixStack matrix, IRenderTypeBuffer buffer, int packedLight) {
		matrix.pushPose();
		matrix.scale(-1.0F, -1.0F, 1.0F);

		float pitch = MathHelper.lerp(partialTicks, entity.xRotO, entity.xRot);

		model.prepareMobModel(entity, 0, 0, partialTicks);
		model.setupAnim(entity, 0, 0, entity.tickCount, 0, pitch);
		matrix.translate(0.0D, -1.5f, 0.0D);

		boolean visible = !entity.isInvisible();
		boolean shade = !visible && !entity.isInvisibleTo(Minecraft.getInstance().player);
		RenderType rendertype = getRenderType(entity, visible, shade);

		if (rendertype != null) {
			IVertexBuilder ivertexbuilder = buffer.getBuffer(rendertype);

			this.model.renderToBuffer(matrix, ivertexbuilder, packedLight, ColourUtil.WHITE, 1f, 1f, 1f, shade ? 0.15f : 1f);
			entity.level.addParticle(new CustomisableParticleType.Data(AoAParticleTypes.FLICKERING_SPARKLER.get(), 0.5f, 3, ColourUtil.CYAN), entity.getX(), entity.getY() + 0.3f, entity.getZ(), 0, 0, 0);
		}

		matrix.popPose();
		super.render(entity, yaw, partialTicks, matrix, buffer, packedLight);
	}

public void render(FishingBobberEntity bobber, float yaw, float partialTicks, MatrixStack matrixStack, IRenderTypeBuffer renderTypeBuffer, int packedLight) {
		PlayerEntity player = bobber.getPlayerOwner();

		if (player != null) {
			ResourceLocation texture = getTextureLocation(bobber);

			if (renderType == null || texture != TEXTURE)
				renderType = RenderType.entityCutout(getTextureLocation(bobber));

			matrixStack.pushPose();
			matrixStack.pushPose();
			matrixStack.scale(0.5F, 0.5F, 0.5F);
			matrixStack.mulPose(this.entityRenderDispatcher.cameraOrientation());
			matrixStack.mulPose(Vector3f.YP.rotationDegrees(180.0F));

			MatrixStack.Entry lastPose = matrixStack.last();
			Matrix4f pose = lastPose.pose();
			Matrix3f normalisedPose = lastPose.normal();
			IVertexBuilder vertexBuilder = renderTypeBuffer.getBuffer(renderType);

			vertex(vertexBuilder, pose, normalisedPose, packedLight, 0, 0, 0, 1);
			vertex(vertexBuilder, pose, normalisedPose, packedLight, 1, 0, 1, 1);
			vertex(vertexBuilder, pose, normalisedPose, packedLight, 1, 1, 1, 0);
			vertex(vertexBuilder, pose, normalisedPose, packedLight, 0, 1, 0, 0);

			matrixStack.popPose();

			int armSideMod = player.getMainArm() == HandSide.RIGHT ? 1 : -1;
			ItemStack heldStack = player.getMainHandItem();

			if (!(heldStack.getItem() instanceof FishingRodItem))
				armSideMod = -armSideMod;

			double rodTipPosX;
			double rodTipPosY;
			double rodTipPosZ;
			float playerPoseAdjust;

			if ((this.entityRenderDispatcher.options == null || this.entityRenderDispatcher.options.getCameraType().isFirstPerson()) && player == Minecraft.getInstance().player) {
				double fov = this.entityRenderDispatcher.options.fov / 100d;
				float attackAnimRot = MathHelper.sin(MathHelper.sqrt(player.getAttackAnim(partialTicks)) * (float)Math.PI);
				Vector3d lineSideVec = new Vector3d((double)armSideMod * -0.36D * fov, -0.045D * fov, 0.4D);
				lineSideVec = lineSideVec.xRot(-MathHelper.lerp(partialTicks, player.xRotO, player.xRot) * ((float)Math.PI / 180F));
				lineSideVec = lineSideVec.yRot(-MathHelper.lerp(partialTicks, player.yRotO, player.yRot) * ((float)Math.PI / 180F));
				lineSideVec = lineSideVec.yRot(attackAnimRot * 0.5F);
				lineSideVec = lineSideVec.xRot(-attackAnimRot * 0.7F);
				rodTipPosX = MathHelper.lerp(partialTicks, player.xo, player.getX()) + lineSideVec.x;
				rodTipPosY = MathHelper.lerp(partialTicks, player.yo, player.getY()) + lineSideVec.y;
				rodTipPosZ = MathHelper.lerp(partialTicks, player.zo, player.getZ()) + lineSideVec.z;
				playerPoseAdjust = player.getEyeHeight();
			}
			else {
				float bodyRotPos = MathHelper.lerp(partialTicks, player.yBodyRotO, player.yBodyRot) * ((float)Math.PI / 180F);
				double rodTipBodyRotXAdjust = MathHelper.sin(bodyRotPos);
				double rodTipBodyRotZAdjust = MathHelper.cos(bodyRotPos);
				double armSideAdjust = (double)armSideMod * 0.35d;
				rodTipPosX = MathHelper.lerp(partialTicks, player.xo, player.getX()) - rodTipBodyRotZAdjust * armSideAdjust - rodTipBodyRotXAdjust * 0.8D;
				rodTipPosY = player.yo + (double)player.getEyeHeight() + (player.getY() - player.yo) * (double)partialTicks - 0.45D;
				rodTipPosZ = MathHelper.lerp(partialTicks, player.zo, player.getZ()) - rodTipBodyRotXAdjust * armSideAdjust + rodTipBodyRotZAdjust * 0.8D;
				playerPoseAdjust = player.isCrouching() ? -0.1875F : 0.0F;
			}

			float lineStartX = (float)(rodTipPosX - MathHelper.lerp(partialTicks, bobber.xo, bobber.getX()));
			float lineStartY = (float)(rodTipPosY - (MathHelper.lerp(partialTicks, bobber.yo, bobber.getY()) + 0.25D)) + playerPoseAdjust;
			float lineStartZ = (float)(rodTipPosZ - MathHelper.lerp(partialTicks, bobber.zo, bobber.getZ()));
			IVertexBuilder lineVertexBuilder = renderTypeBuffer.getBuffer(RenderType.lines());
			Matrix4f prevPose = matrixStack.last().pose();

			for(int i = 0; i < 16; ++i) {
				stringVertex(lineStartX, lineStartY, lineStartZ, lineVertexBuilder, prevPose, i / 16f);
				stringVertex(lineStartX, lineStartY, lineStartZ, lineVertexBuilder, prevPose, (i + 1) / 16f);
			}

			matrixStack.popPose();

			RenderNameplateEvent renderNameplateEvent = new RenderNameplateEvent(bobber, bobber.getDisplayName(), this, matrixStack, renderTypeBuffer, packedLight, partialTicks);

			MinecraftForge.EVENT_BUS.post(renderNameplateEvent);

			if (renderNameplateEvent.getResult() != Event.Result.DENY && (renderNameplateEvent.getResult() == Event.Result.ALLOW || this.shouldShowName(bobber)))
				this.renderNameTag(bobber, renderNameplateEvent.getContent(), matrixStack, renderTypeBuffer, packedLight);
		}
	}

@Override
	public void render(Entity entity, float entityYaw, float partialTicks, MatrixStack matrix, IRenderTypeBuffer buffer, int packedLight) {
		matrix.pushPose();
		matrix.translate(0, 1.5d, 0);
		matrix.mulPose(Vector3f.XP.rotationDegrees(180));
		matrix.scale(-1, 1, -1);

		IVertexBuilder vertexBuilder = buffer.getBuffer(RenderType.entityCutoutNoCull(texture));

		model.setupAnim(entity, 0, 0, entity.tickCount, entityYaw, 0);
		model.renderToBuffer(matrix, vertexBuilder, packedLight, OverlayTexture.NO_OVERLAY, 1, 1, 1, 1);

		matrix.popPose();

		super.render(entity, entityYaw, partialTicks, matrix, buffer, packedLight);
	}

private static void onWorldRender(final RenderWorldLastEvent ev) {
		if (occultBlockMap.isEmpty())
			return;

		ArrayList<Integer> expiredBlocks = null;

		for (Map.Entry<Integer, ArrayList<Pair<BlockPos, BlockState>>> entry : occultBlockMap.entrySet()) {
			if (GlobalEvents.tick >= entry.getKey()) {
				if (expiredBlocks == null)
					expiredBlocks = new ArrayList<Integer>();

				expiredBlocks.add(entry.getKey());
			}
			else {
				ArrayList<Pair<BlockPos, BlockState>> invalidBlocks = null;
				Minecraft mc = Minecraft.getInstance();
				MatrixStack matrix = ev.getMatrixStack();
				Vector3d cameraPos = mc.gameRenderer.getMainCamera().getPosition();
				Tessellator tess = Tessellator.getInstance();
				BufferBuilder buff = tess.getBuilder();

				matrix.pushPose();
				matrix.translate(-cameraPos.x(), -cameraPos.y(), -cameraPos.z());

				RenderSystem.pushMatrix();
				RenderSystem.multMatrix(matrix.last().pose());

				RenderSystem.disableTexture();
				RenderSystem.disableDepthTest();
				RenderSystem.depthMask(false);
				RenderSystem.polygonMode(GL11.GL_FRONT_AND_BACK, GL11.GL_LINE);
				RenderSystem.blendFunc(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA);
				RenderSystem.enableBlend();
				RenderSystem.lineWidth(4f);

				for (Pair<BlockPos, BlockState> block : entry.getValue()) {
					if (GlobalEvents.tick % 2 == 1 && mc.player.level.getBlockState(block.getFirst()) != block.getSecond()) {
						if (invalidBlocks == null)
							invalidBlocks = new ArrayList<Pair<BlockPos, BlockState>>();

						invalidBlocks.add(block);

						continue;
					}

					Vector4f colour = getColourForBlock(block.getSecond());
					BlockPos pos = block.getFirst();

					RenderSystem.pushMatrix();
					RenderSystem.translated(pos.getX(), pos.getY(), pos.getZ());
					buff.begin(GL_LINES, DefaultVertexFormats.POSITION_COLOR);
					RenderUtil.renderBlockOutline(buff, colour.x(), colour.y(), colour.z(), colour.w());
					tess.end();
					RenderSystem.popMatrix();
				}

				RenderSystem.polygonMode(GL11.GL_FRONT_AND_BACK, GL11.GL_FILL);
				RenderSystem.disableBlend();
				RenderSystem.enableDepthTest();
				RenderSystem.depthMask(true);
				RenderSystem.enableTexture();

				RenderSystem.popMatrix();
				matrix.popPose();

				if (invalidBlocks != null)
					entry.getValue().removeAll(invalidBlocks);
			}
		}

		if (expiredBlocks != null) {
			for (Integer tick : expiredBlocks) {
				occultBlockMap.remove(tick);
			}
		}
	}

@Override
	protected void setupRotations(DoppelgangerEntity doppelganger, MatrixStack matrixStack, float age, float yawRot, float partialTicks) {
		if (doppelganger.isFallFlying()) {
			super.setupRotations(doppelganger, matrixStack, age, yawRot, partialTicks);

			float lerpFallTicks = (float)doppelganger.getFallFlyingTicks() + partialTicks;

			if (!doppelganger.isAutoSpinAttack())
				matrixStack.mulPose(Vector3f.XP.rotationDegrees(MathHelper.clamp(lerpFallTicks * lerpFallTicks / 100.0F, 0.0F, 1.0F) * (-90.0F - doppelganger.xRot)));

			Vector3d viewVec = doppelganger.getViewVector(partialTicks);
			Vector3d velocity = doppelganger.getDeltaMovement();
			double velocityScaleOffset = Entity.getHorizontalDistanceSqr(velocity);
			double viewScaleOffset = Entity.getHorizontalDistanceSqr(viewVec);

			if (velocityScaleOffset > 0 && viewScaleOffset > 0)
				matrixStack.mulPose(Vector3f.YP.rotation((float)(Math.signum(velocity.x * viewVec.z - velocity.z * viewVec.x) * Math.acos((velocity.x * viewVec.x + velocity.z * viewVec.z) / Math.sqrt(velocityScaleOffset * viewScaleOffset)))));
		}
		else if (doppelganger.getSwimAmount(partialTicks) > 0) {
			super.setupRotations(doppelganger, matrixStack, age, yawRot, partialTicks);

			matrixStack.mulPose(Vector3f.XP.rotationDegrees(MathHelper.lerp(doppelganger.getSwimAmount(partialTicks), 0, doppelganger.isInWater() ? -90 - doppelganger.xRot : -90)));

			if (doppelganger.isVisuallySwimming())
				matrixStack.translate(9, -1, 0.3f);
		}
		else {
			super.setupRotations(doppelganger, matrixStack, age, yawRot, partialTicks);
		}
	}

@Override
	public void render(MobEntity entity, float entityYaw, float partialTicks, MatrixStack matrix, IRenderTypeBuffer buffer, int packedLight) {
		super.render(entity, entityYaw, partialTicks, matrix, buffer, packedLight);

		CopyOnWriteArrayList<Pair<Integer, Vector3d>> clones = ((OcculentEntity)entity).clones;
		BlockPos.Mutable mutablePos = new BlockPos.Mutable();

		if (!clones.isEmpty())
			clones.removeIf(clone -> clone.getFirst() <= GlobalEvents.tick);

		for (Pair<Integer, Vector3d> clone : clones) {
			Vector3d cloneOffset = clone.getSecond();
			double lerpX = MathHelper.lerp(partialTicks, entity.xOld, entity.getX());
			double lerpZ = MathHelper.lerp(partialTicks, entity.zOld, entity.getZ());

			if (!entity.level.getBlockState(mutablePos.set(lerpX + cloneOffset.x(), entity.blockPosition().getY() - 1, lerpZ + cloneOffset.z())).entityCanStandOn(entity.level, mutablePos, entity))
				continue;

			if (entity.level.getBlockState(mutablePos.move(Direction.UP)).getMaterial().blocksMotion())
				continue;

			matrix.pushPose();
			matrix.translate(cloneOffset.x(), 0, cloneOffset.z());

			super.render(entity, entityYaw, partialTicks, matrix, buffer, packedLight);

			matrix.popPose();
		}
	}

@Override
	public void render(DryadSpriteEntity entity, float entityYaw, float partialTicks, MatrixStack stack, IRenderTypeBuffer bufferIn, int packedLightIn) {
		stack.pushPose();
		boolean shouldSit = entity.isPassenger() && (entity.getVehicle() != null && entity.getVehicle().shouldRiderSit());
		EntityModelData entityModelData = new EntityModelData();
		entityModelData.isSitting = shouldSit;
		entityModelData.isChild = entity.isBaby();

		float lerpBodyRot = MathHelper.rotLerp(partialTicks, entity.yBodyRotO, entity.yBodyRot);
		float lerpHeadRot = MathHelper.rotLerp(partialTicks, entity.yHeadRotO, entity.yHeadRot);
		float netHeadYaw = lerpHeadRot - lerpBodyRot;

		if (shouldSit && entity.getVehicle() instanceof LivingEntity) {
			LivingEntity vehicle = (LivingEntity) entity.getVehicle();
			lerpBodyRot = MathHelper.rotLerp(partialTicks, vehicle.yBodyRotO, vehicle.yBodyRot);
			netHeadYaw = lerpHeadRot - lerpBodyRot;
			float finalHeadYaw = MathHelper.clamp(MathHelper.wrapDegrees(netHeadYaw), -85, 85);

			lerpBodyRot = lerpHeadRot - finalHeadYaw;

			if (finalHeadYaw * finalHeadYaw > 2500)
				lerpBodyRot += finalHeadYaw * 0.2F;

			netHeadYaw = lerpHeadRot - lerpBodyRot;
		}

		float headPitch = MathHelper.lerp(partialTicks, entity.xRotO, entity.xRot);

		if (entity.getPose() == Pose.SLEEPING) {
			Direction direction = entity.getBedOrientation();

			if (direction != null) {
				float eyeHeight = entity.getEyeHeight(Pose.STANDING) - 0.1F;

				stack.translate((float) (-direction.getStepX()) * eyeHeight, 0.0D, (float) (-direction.getStepZ()) * eyeHeight);
			}
		}

		float lerpAge = this.handleRotationFloat(entity, partialTicks);
		this.applyRotations(entity, stack, lerpAge, lerpBodyRot, partialTicks);

		float limbSwingAmount = 0;
		float limbSwing = 0;

		if (!shouldSit && entity.isAlive()) {
			limbSwingAmount = MathHelper.lerp(partialTicks, entity.animationSpeedOld, entity.animationSpeed);
			limbSwing = entity.animationPosition - entity.animationSpeed * (1.0F - partialTicks);

			if (entity.isBaby())
				limbSwing *= 3;

			if (limbSwingAmount > 1)
				limbSwingAmount = 1;
		}

		entityModelData.headPitch = -headPitch;
		entityModelData.netHeadYaw = -netHeadYaw;

		AnimationEvent<DryadSpriteEntity> predicate = new AnimationEvent<DryadSpriteEntity>(entity, limbSwing, limbSwingAmount, partialTicks, !(limbSwingAmount > -0.15F && limbSwingAmount < 0.15F), Collections.singletonList(entityModelData));
		GeoModelProvider<DryadSpriteEntity> modelProvider = getGeoModelProvider();
		GeoModel model = modelProvider.getModel(modelProvider.getModelLocation(entity));

		if (modelProvider instanceof IAnimatableModel)
			((IAnimatableModel<DryadSpriteEntity>) modelProvider).setLivingAnimations(entity, this.getUniqueID(entity), predicate);

		stack.translate(0, 0.01f, 0);

		Minecraft.getInstance().textureManager.bind(getTextureLocation(entity));

		Color renderColor = getRenderColor(entity, partialTicks, stack, bufferIn, null, packedLightIn);
		RenderType renderType = getRenderType(entity, partialTicks, stack, bufferIn, null, packedLightIn, getTextureLocation(entity));
		float red = renderColor.getRed() / 255f;
		float green = renderColor.getGreen() / 255f;
		float blue = renderColor.getBlue() / 255f;
		float alpha = entity.isInvisibleTo(Minecraft.getInstance().player) ? 0 : renderColor.getAlpha() / 255f;

		render(model, entity, partialTicks, renderType, stack, bufferIn, null, packedLightIn, getOverlay(entity, 0), red, green, blue, alpha);

		if (!entity.isSpectator()) {
			for (GeoLayerRenderer<DryadSpriteEntity> layerRenderer : this.layerRenderers) {
				layerRenderer.render(stack, bufferIn, packedLightIn, entity, limbSwing, limbSwingAmount, partialTicks, lerpAge, netHeadYaw, headPitch);
			}
		}

		if (ModList.get().isLoaded("patchouli"))
			PatchouliCompat.patchouliLoaded(stack);

		stack.popPose();

		RenderNameplateEvent renderNameplateEvent = new RenderNameplateEvent(entity, entity.getDisplayName(), this, stack, bufferIn, packedLightIn, partialTicks);
		MinecraftForge.EVENT_BUS.post(renderNameplateEvent);

		if (renderNameplateEvent.getResult() != Event.Result.DENY && (renderNameplateEvent.getResult() == Event.Result.ALLOW || this.shouldShowName(entity)))
			renderNameTag(entity, renderNameplateEvent.getContent(), stack, bufferIn, packedLightIn);
	}

