private void smolder(int amount) {
        for (int i = 0; i < amount; i++) {
            final float velocity = 1.5F;
            float yaw = (float) (random.nextFloat() * 2 * Math.PI);

            float r = random.nextFloat() * 0.7F;
            float x = r * Mth.cos(yaw);
            float z = r * Mth.sin(yaw);

            float motionY = random.nextFloat() * 0.8F;
            float motionX = velocity * Mth.cos(yaw);
            float motionZ = velocity * Mth.sin(yaw);
            level().addParticle((new LightningParticleOptions(this.getR(), this.getG(), this.getB())), this.getX() + x, this.getY() + 0.1, this.getZ() + z, motionX, motionY, motionZ);
        }

    }

private void smolder(int amount) {
        for (int i = 0; i < amount; i++) {
            final float velocity = 0.25F * this.getSize();
            float yaw = (float) (random.nextFloat() * 2 * Math.PI);

            float r = random.nextFloat() * 0.7F;
            float x = r * Mth.cos(yaw);
            float z = r * Mth.sin(yaw);

            float motionY = random.nextFloat() * 0.8F;
            float motionX = velocity * Mth.cos(yaw);
            float motionZ = velocity * Mth.sin(yaw);
            level().addParticle((new LightningParticleOptions(99,194,201)), this.getX() + x, this.getY() + 0.1, this.getZ() + z, motionX, motionY, motionZ);
        }

    }

public void tick() {
        super.tick();
        if (this.tickCount == 1) {
            if(this.getLifespan() == 0){
                this.setLifespan(60);
            }
            if (level().isClientSide) {
                owner = (LivingEntity) level().getEntity(getCasterID());
            }
        }
        if(!madeOpenNoise){
            this.gameEvent(GameEvent.ENTITY_PLACE);
            this.playSound(SoundEvents.END_PORTAL_SPAWN, 1.0F, 1 + random.nextFloat() * 0.2F);
            madeOpenNoise = true;
        }

        if(Math.min(tickCount, this.getLifespan()) >= 16){
            if(level().isClientSide) {
                float r = 0.4F;
                float g = 0.1f;
                float b = 0.8f;

                this.level().addParticle((new Rising_Trail_Options(r, g, b,2.5f + random.nextFloat() * 0.25f,0.08F)), this.getX(), this.getY() +5, this.getZ() , 0, -0.3, 0);



            }
            AABB screamBox = new AABB(this.getX() - 3f, this.getY(), this.getZ() - 3, this.getX() + 3, this.getY() + 15F, this.getZ() + 3F);

            for (LivingEntity entity : this.level().getEntitiesOfClass(LivingEntity.class, screamBox)) {
                if (!isAlliedTo(entity) && (owner == null || !owner.equals(entity) && !owner.isAlliedTo(entity))) {
                    if (!(entity instanceof Player player && player.getAbilities().invulnerable)) {
                        Vec3 diff = entity.position().subtract(position().add(0, 0, 0));
                        diff = diff.normalize().scale(0.075);
                        entity.setDeltaMovement(entity.getDeltaMovement().add(0, -2, 0).subtract(diff));
                    }
                }
            }
        }

        this.setLifespan(this.getLifespan() - 1);
        if(this.getLifespan() <= 16){
            if(!madeCloseNoise){
                this.gameEvent(GameEvent.ENTITY_PLACE);
                madeCloseNoise = true;
            }


        }
        if (this.getLifespan() <= 0) {
            this.level().explode(this.owner, this.getX(), this.getY(), this.getZ(), 2.0F, false, Level.ExplosionInteraction.NONE);
            this.remove(RemovalReason.DISCARDED);
        }
    }

public void tick() {
        super.tick();
        if (!this.isNoGravity() && !this.isInWaterOrBubble()) {
            this.setDeltaMovement(this.getDeltaMovement().add(0.0D, (double) -0.04F, 0.0D));
        }
        if(this.getState() == 1) {
            if (this.getLifespan() >= 5) {
                this.setState(2);
            }
        }
        if(this.getState() == 2) {
            if(this.getLifespan() >= this.getMaxTicks() - 30) {
                if (!this.sentEvent) {
                    this.level().broadcastEntityEvent(this, (byte)4);
                    this.sentEvent = true;
                }
            }
            if(this.getLifespan() >= this.getMaxTicks() - 10) {
                this.setState(3);
            }
        }


        this.setLifespan(this.getLifespan() + 1);

        if (this.getLifespan() >= this.getMaxTicks()) {
            //Cataclysm.PROXY.clearSoundCacheFor(this);
            this.remove(RemovalReason.DISCARDED);
        }
        float f = Math.max(1F - (this.getLifespan() / (1F * getMaxTicks())), 0F);
        Vec3 directionVec = new Vec3(0, 0, f * f * 0.1F).yRot((float) Math.toRadians(-this.getYRot()));
        if (this.level().isClientSide) {
            if (this.lSteps > 0) {
                double d5 = this.getX() + (this.lx - this.getX()) / (double) this.lSteps;
                double d6 = this.getY() + (this.ly - this.getY()) / (double) this.lSteps;
                double d7 = this.getZ() + (this.lz - this.getZ()) / (double) this.lSteps;
                this.setYRot(Mth.wrapDegrees((float) this.lyr));
                this.setXRot(this.getXRot() + (float) (this.lxr - (double) this.getXRot()) / (float) this.lSteps);
                --this.lSteps;
                this.setPos(d5, d6, d7);
            } else {
                this.reapplyPosition();
            }
            if (!this.clientSideAttackEnded) {
                for (int particleCount = 0; particleCount < 2; particleCount++) {
                    for (int i = 0; i < 2; i++) {
                        float xOffset = (float) (i - 1) / 2.0F + 0.25F + (random.nextFloat() - 0.5F) * 0.2F;
                        int rand = this.random.nextInt(20);
                        spawnParticleAt((0.1F + random.nextFloat() * 0.2F), 0.7F, xOffset * 3.5F, new CustomPoofParticleOptions(76 + rand, 147 + rand, 173 + rand, 0.1F));
                    }
                }
            }
        } else {
            this.reapplyPosition();
            this.setRot(this.getYRot(), this.getXRot());
            attackEntities(1.5,Mth.sin(this.getYRot() * ((float) Math.PI / 180F)), (-Mth.cos(this.getYRot() * ((float) Math.PI / 180F))));
        }



        Vec3 vec3 = this.getDeltaMovement().scale(0.9F).add(directionVec);
        this.move(MoverType.SELF, vec3);
        this.setDeltaMovement(vec3.multiply((double) 0.99F, (double) 0.98F, (double) 0.99F));
    }

@Override
    public void render(T entity, float entityYaw, float partialTicks, PoseStack matrixStack, MultiBufferSource buffer, int packedLight) {
        float h;
        matrixStack.pushPose();
        matrixStack.translate(0.0f, 0.375f, 0.0f);
        matrixStack.mulPose(Axis.YP.rotationDegrees(180.0f - entityYaw));
        float f = (float)entity.getHurtTime() - partialTicks;
        float g = entity.getDamage() - partialTicks;
        if (g < 0.0f) {
            g = 0.0f;
        }
        if (f > 0.0f) {
            matrixStack.mulPose(Axis.XP.rotationDegrees(Mth.sin(f) * f * g / 10.0f * (float)entity.getHurtDir()));
        }
        if (!Mth.equal(h = entity.getBubbleAngle(partialTicks), 0.0f)) {
            matrixStack.mulPose(new Quaternionf().setAngleAxis(entity.getBubbleAngle(partialTicks) * ((float)Math.PI / 180), 1.0f, 0.0f, 1.0f));
        }
        Pair<ResourceLocation, ListModel<Boat>> pair = this.boatResources.get(entity.getWoodType());
        ResourceLocation resourceLocation = pair.getFirst();
        ListModel<Boat> listModel = pair.getSecond();
        matrixStack.scale(-1.0f, -1.0f, 1.0f);
        matrixStack.mulPose(Axis.YP.rotationDegrees(90.0f));
        listModel.setupAnim(entity, partialTicks, 0.0f, -0.1f, 0.0f, 0.0f);
        VertexConsumer vertexConsumer = buffer.getBuffer(listModel.renderType(resourceLocation));
        listModel.renderToBuffer(matrixStack, vertexConsumer, packedLight, OverlayTexture.NO_OVERLAY, 1.0f, 1.0f, 1.0f, 1.0f);
        if (!entity.isUnderWater()) {
            VertexConsumer vertexConsumer2 = buffer.getBuffer(RenderType.waterMask());
            if (listModel instanceof WaterPatchModel waterPatchModel) {
                waterPatchModel.waterPatch().render(matrixStack, vertexConsumer2, packedLight, OverlayTexture.NO_OVERLAY);
            }
        }
        matrixStack.popPose();
        super.render(entity, entityYaw, partialTicks, matrixStack, buffer, packedLight);
    }

@Override
    public void render(PoseStack matrixStack, MultiBufferSource buffer, int packedLight, Penguin livingEntity, float limbSwing, float limbSwingAmount, float partialTicks, float ageInTicks, float netHeadYaw, float headPitch) {
        matrixStack.pushPose();
        this.getParentModel().head.translateAndRotate(matrixStack);
        matrixStack.translate(0.1f, -0.05f, -0.2f);
        matrixStack.mulPose(Axis.XP.rotationDegrees(90f));
        matrixStack.mulPose(Axis.ZP.rotationDegrees(135f));
        ItemStack itemStack = livingEntity.getItemBySlot(EquipmentSlot.MAINHAND);
        this.itemInHandRenderer.renderItem(livingEntity, itemStack, ItemTransforms.TransformType.GROUND, false, matrixStack, buffer, packedLight);
        matrixStack.popPose();
    }

@Override
	public void render(T entity, float entityYaw, float partialTicks, PoseStack poseStack, MultiBufferSource buffer, int packedLight) {
		poseStack.pushPose();
		poseStack.mulPose(Axis.YP.rotationDegrees(180.0F - entity.getYRot()));
		this.getModel().setupAnim(entity, partialTicks, 0.0F, entity.tickCount + partialTicks, 0.0F, 0.0F);
		poseStack.popPose();

		VertexConsumer vertexConsumer = buffer.getBuffer(this.model.renderType(this.getTextureLocation(entity)));

		this.getModel().renderToBuffer(poseStack, vertexConsumer, packedLight, OverlayTexture.NO_OVERLAY);
		this.layer.render(poseStack, buffer, packedLight, entity, 0.0F, 0.0F, partialTicks, 0.0F, 0.0F, 0.0F);

		super.render(entity, entityYaw, partialTicks, poseStack, buffer, packedLight);
	}

@Override
	public void render(PassionFruitSeed entityIn, float entityYaw, float partialTicks, PoseStack poseStack, MultiBufferSource buffer, int packedLight) {
		if (entityIn.tickCount >= 2 || !(this.entityRenderDispatcher.camera.getEntity().distanceToSqr(entityIn) < 9.0D)) {
			poseStack.pushPose();
			poseStack.translate(0.0D, 0.1825F, 0.0D);
			poseStack.mulPose(Axis.YP.rotationDegrees(Mth.lerp(partialTicks, entityIn.yRotO, entityIn.getYRot()) - 90.0F));
			poseStack.mulPose(Axis.ZP.rotationDegrees(Mth.lerp(partialTicks, entityIn.xRotO, entityIn.getXRot())));
			this.model.setupAnim(entityIn, partialTicks, 0.0F, -0.1F, 0.0F, 0.0F);
			this.model.renderToBuffer(poseStack, buffer.getBuffer(this.model.renderType(PASSION_FRUIT_SEED_TEXTURE)), packedLight, OverlayTexture.NO_OVERLAY);
			poseStack.popPose();
			super.render(entityIn, entityYaw, partialTicks, poseStack, buffer, packedLight);
		}
	}

