private static void renderVoltmeterOverlay(GuiGraphics graphics, Player player, int scaledWidth, int scaledHeight)
	{
		HitResult rrt = ClientUtils.mc().hitResult;
		Either<BlockPos, Integer> pos = null;
		if(rrt instanceof BlockHitResult mop)
			pos = Either.left(mop.getBlockPos());
		else if(rrt instanceof EntityHitResult ehr)
			pos = Either.right(ehr.getEntity().getId());

		if(pos==null)
			return;

		ArrayList<Component> text = new ArrayList<>();

		boolean matches = VoltmeterItem.lastEnergyUpdate.pos().equals(pos);
		long sinceLast = player.level().getGameTime()-VoltmeterItem.lastEnergyUpdate.measuredInTick();
		if(!matches||sinceLast > 20)
			PacketDistributor.sendToServer(new MessageRequestEnergyUpdate(pos));

		if(VoltmeterItem.lastEnergyUpdate.isValid()&&matches)
		{
			int maxStorage = VoltmeterItem.lastEnergyUpdate.capacity();
			int storage = VoltmeterItem.lastEnergyUpdate.stored();
			String storageText = Utils.toScientificNotation(storage, "0##", 100000);
			String capacityText = Utils.toScientificNotation(maxStorage, "0##", 100000);
			text.add(Component.translatable(Lib.DESC_INFO+"energyStored", storageText+" / "+capacityText));
		}

		if(rrt instanceof BlockHitResult mop)
		{
			matches = VoltmeterItem.lastRedstoneUpdate.pos().equals(mop.getBlockPos());
			sinceLast = player.level().getGameTime()-VoltmeterItem.lastRedstoneUpdate.measuredInTick();
			if(!matches||sinceLast > 20)
				PacketDistributor.sendToServer(new MessageRequestRedstoneUpdate(mop.getBlockPos()));

			if(VoltmeterItem.lastRedstoneUpdate.isSignalSource()&&matches)
				VoltmeterItem.lastRedstoneUpdate.rsLevels().consume(
						aByte -> text.add(Component.translatable(Lib.DESC_INFO+"redstone_level", String.valueOf(aByte))),
						pairs -> {
							if(pairs.length > 0)
							{
								text.add(Component.translatable(Lib.DESC_INFO+"redstone_level", ""));
								for(Pair<DyeColor, Byte> p : pairs)
								{
									Component c = Component.translatable(Lib.DESC_INFO+"redstone_level_on_channel",
											p.getSecond(),
											getRedstoneColorComponent(p.getFirst())
									);
									// if the value is less than 10, we want a space before it which has the same width as a digit
									text.add(p.getSecond() < 10?new SpacerComponent("0").append(c): c);
								}
							}
						}
				);
		}

		BlockOverlayUtils.drawBlockOverlayText(graphics, text, scaledWidth, scaledHeight);
	}

@Override
	public void handlePerspective(Key key, LivingEntity holder, ItemDisplayContext cameraTransformType, PoseStack mat)
	{
		if(holder instanceof Bulwark bulwark&&(cameraTransformType==ItemDisplayContext.THIRD_PERSON_RIGHT_HAND||cameraTransformType==ItemDisplayContext.THIRD_PERSON_LEFT_HAND))
			if(bulwark.getArmPose()==IllagerArmPose.CELEBRATING)
			{
				mat.translate(-2, -1.25, -0);
				mat.mulPose(new Quaternionf().rotateY(-1.65806f));
				mat.mulPose(new Quaternionf().rotateZ(-0.523599f));
				mat.mulPose(new Quaternionf().rotateX(0.349066f));
			}
			else
			{
				mat.mulPose(new Quaternionf().rotateXYZ(0.0349066f, -0.174533f, -0.174533f));
				mat.translate(-.875, -.75, .3);
			}
	}

@Override
	public void handlePerspective(Key key, LivingEntity holder, ItemDisplayContext cameraTransformType, PoseStack mat)
	{
		if(ZoomHandler.isZooming && (cameraTransformType==ItemDisplayContext.FIRST_PERSON_LEFT_HAND||cameraTransformType==ItemDisplayContext.FIRST_PERSON_RIGHT_HAND))
		{
			// hide the item in first person when zooming
			mat.scale(0f,0f,0f);
			return;
		}

		if(holder instanceof Fusilier fusilier&&(cameraTransformType==ItemDisplayContext.THIRD_PERSON_RIGHT_HAND||cameraTransformType==ItemDisplayContext.THIRD_PERSON_LEFT_HAND))
		{
			switch(fusilier.getArmPose())
			{
				case CROSSBOW_HOLD ->
				{
					mat.mulPose(new Quaternionf().rotateXYZ(-0.174533f, -0.261799f, -0.698132f));
					mat.translate(.5, -2.5, .75);
				}
				case CELEBRATING ->
				{
					mat.translate(-4.5, -4, 2);
					mat.mulPose(new Quaternionf().rotateY(-1.65806f));
					mat.mulPose(new Quaternionf().rotateZ(-0.872665f));
					mat.mulPose(new Quaternionf().rotateX(0.349066f));
				}
				default ->
				{
					mat.mulPose(new Quaternionf().rotateXYZ(-0.139626f, 0, 1.91986f));
					mat.translate(4.75, 4, 0);
				}
			}
		}
	}

@Override
	public void handlePerspective(Key key, LivingEntity holder, ItemDisplayContext cameraItemDisplayContext, PoseStack mat)
	{
		if(ZoomHandler.isZooming && (cameraItemDisplayContext==ItemDisplayContext.FIRST_PERSON_LEFT_HAND||cameraItemDisplayContext==ItemDisplayContext.FIRST_PERSON_RIGHT_HAND))
		{
			// hide the item in first person when zooming
			mat.scale(0f,0f,0f);
			return;
		}

		if(holder instanceof Player player&&(cameraItemDisplayContext==ItemDisplayContext.FIRST_PERSON_RIGHT_HAND||cameraItemDisplayContext==ItemDisplayContext.FIRST_PERSON_LEFT_HAND||cameraItemDisplayContext==ItemDisplayContext.THIRD_PERSON_RIGHT_HAND||cameraItemDisplayContext==ItemDisplayContext.THIRD_PERSON_LEFT_HAND))
		{
			boolean main = (cameraItemDisplayContext==ItemDisplayContext.FIRST_PERSON_RIGHT_HAND||cameraItemDisplayContext==ItemDisplayContext.THIRD_PERSON_RIGHT_HAND)==(holder.getMainArm()==HumanoidArm.RIGHT);
			boolean left = cameraItemDisplayContext==ItemDisplayContext.FIRST_PERSON_LEFT_HAND||cameraItemDisplayContext==ItemDisplayContext.THIRD_PERSON_LEFT_HAND;
			if(key.fancyAnimation()&&main)
			{
				float f = player.getAttackStrengthScale(ClientUtils.mc().getTimer().getGameTimeDeltaTicks());
				if(f < 1)
				{
					float angle = f*-6.28318f;
					if(left)
						angle *= -1;
					mat.translate(0, 1.5-f, 0);
					mat.mulPose(new Quaternionf().rotateXYZ(0, 0, angle));
				}
			}

			//Re-grab stack because the other one doesn't do reloads properly
			if(key.reload() > 0)
			{
				float f = 3-key.reload/20f; //Reload time in seconds, for coordinating with audio
				if(f > .35&&f < 1.95)
					if(f < .5)
					{
						mat.translate((.35-f)*2, 0, 0);
						mat.mulPose(new Quaternionf().rotateAxis(2.64F*(f-.35F), new Vector3f(0, 0, 1)));
					}
					else if(f < .6)
					{
						mat.translate((f-.5)*6, (.5-f)*1, 0);
						mat.mulPose(new Quaternionf().rotateAxis(.87266F, new Vector3f(0, 0, 1)));
					}
					else if(f < 1.7)
					{
						mat.translate(0, -.6, 0);
						mat.mulPose(new Quaternionf().rotateAxis(.87266F, new Vector3f(0, 0, 1)));
					}
					else if(f < 1.8)
					{
						mat.translate((1.8-f)*6, (f-1.8)*1, 0);
						mat.mulPose(new Quaternionf().rotateAxis(.87266F, new Vector3f(0, 0, 1)));
					}
					else
					{
						mat.translate((f-1.95f)*2, 0, 0);
						mat.mulPose(new Quaternionf().rotateAxis(2.64F*(1.95F-f), new Vector3f(0, 0, 1)));
					}
			}
			else if(player.containerMenu instanceof RevolverContainer)
			{
				mat.translate(left?.4: -.4, .4, 0);
				mat.mulPose(new Quaternionf().rotateAxis(.87266F, 0, 0, 1));
			}
		}
	}

@Override
	public void handlePerspective(Key key, LivingEntity holder, ItemDisplayContext cameraItemDisplayContext, PoseStack mat)
	{
		if(holder==null||!holder.isUsingItem())
			return;
		boolean leftHand = cameraItemDisplayContext==FIRST_PERSON_LEFT_HAND||cameraItemDisplayContext==THIRD_PERSON_LEFT_HAND;
		boolean rightHand = cameraItemDisplayContext==FIRST_PERSON_RIGHT_HAND||cameraItemDisplayContext==THIRD_PERSON_RIGHT_HAND;
		if(!leftHand&&!rightHand)
			return;
		boolean leftIsMain = holder.getMainArm()==HumanoidArm.LEFT;
		InteractionHand inHand = (leftIsMain==leftHand)?InteractionHand.MAIN_HAND: InteractionHand.OFF_HAND;
		if(holder.getUsedItemHand()!=inHand)
			return;

		if(cameraItemDisplayContext==FIRST_PERSON_RIGHT_HAND)
		{
			mat.mulPose(new Quaternionf().rotateXYZ(-.15F, 0, 0));
			mat.translate(-.25, .5, -.4375);
		}
		else if(cameraItemDisplayContext==THIRD_PERSON_RIGHT_HAND)
		{
			mat.mulPose(new Quaternionf().rotateXYZ(0.52359F, 0, 0));
			mat.mulPose(new Quaternionf().rotateXYZ(0, 0.78539F, 0));
			mat.translate(.40625, -.125, -.125);
		}
		if(cameraItemDisplayContext==FIRST_PERSON_LEFT_HAND)
		{
			mat.mulPose(new Quaternionf().rotateXYZ(.15F, 0, 0));
			mat.translate(-.25, .375, .4375);
		}
		else if(cameraItemDisplayContext==THIRD_PERSON_LEFT_HAND)
		{
			mat.mulPose(new Quaternionf().rotateX(-0.52359F).rotateY(-0.78539F));
			mat.translate(-.1875, .3125, .4375);
		}
	}

private void renderSpyglass(LivingEntity entity, ItemStack stack, HumanoidArm arm, PoseStack poseStack, MultiBufferSource vertexConsumers, int light) {
		poseStack.pushPose();
		ModelPart modelPart = getParentModel().getHead();
		float pitch = modelPart.xRot;
		modelPart.xRot = Mth.clamp(modelPart.xRot, HEAD_YAW, HEAD_ROLL);
		modelPart.translateAndRotate(poseStack);
		modelPart.xRot = pitch;
		CustomHeadLayer.translateToHead(poseStack, false);
		boolean bl = arm == HumanoidArm.LEFT;
		poseStack.translate((bl ? -2.5f : 2.5f) / 16f, -0.0625, 0);
		itemRenderer.renderItem(entity, stack, ItemDisplayContext.HEAD, false, poseStack, vertexConsumers, light);
		poseStack.popPose();
	}

