@SubscribeEvent
  public void onScreenRenderPost(ScreenEvent.Render.Post event) {
    if (!(event.getScreen() instanceof HorseInventoryScreen horseScreen)) {
      return;
    }
    AbstractHorse horse = horseScreen.horse;
    if (horse == null) {
      return;
    }
    List<Entry> entries = collect(horse);
    if (entries.isEmpty()) {
      return;
    }
    AbstractContainerScreen<?> cs = horseScreen;
    int panelX = cs.getGuiLeft() + cs.getXSize() + PANEL_PAD_X;
    int panelY = cs.getGuiTop();
    GuiGraphics g = event.getGuiGraphics();
    int mouseX = event.getMouseX();
    int mouseY = event.getMouseY();
    Entry hovered = null;
    int rowH = ICON_SIZE + ROW_GAP;
    for (int i = 0; i < entries.size(); i++) {
      Entry e = entries.get(i);
      int x = panelX;
      int y = panelY + i * rowH;
      g.renderItem(e.stack, x, y);
      if (e.count > 1) {
        g.renderItemDecorations(Minecraft.getInstance().font, e.stack, x, y, String.valueOf(e.count));
      }
      if (mouseX >= x && mouseX < x + ICON_SIZE && mouseY >= y && mouseY < y + ICON_SIZE) {
        hovered = e;
      }
    }
    if (hovered != null) {
      List<Component> lines = new ArrayList<>();
      lines.add(hovered.stack.getHoverName().copy().withStyle(ChatFormatting.AQUA));
      lines.add(Component.translatable(hovered.descriptionKey).withStyle(ChatFormatting.GRAY));
      g.renderComponentTooltip(Minecraft.getInstance().font, lines, mouseX, mouseY);
    }
  }

@SubscribeEvent
    public static void renderBossBeams(net.neoforged.neoforge.client.event.SubmitCustomGeometryEvent e) {
        if (BOSS_SPAWNS.isEmpty()) {
            return;
        }

        net.minecraft.world.phys.Vec3 camPos = e.getLevelRenderState().cameraRenderState.pos;
        com.mojang.blaze3d.vertex.PoseStack poseStack = e.getPoseStack();
        net.minecraft.client.renderer.SubmitNodeCollector collector = e.getSubmitNodeCollector();
        float animTime = e.getLevelRenderState().gameTime;

        for (BossSpawnData data : BOSS_SPAWNS) {
            BlockPos pos = data.pos();
            int color = 0xFF000000 | data.rarity().color().getValue();

            poseStack.pushPose();
            poseStack.translate(pos.getX() - camPos.x, pos.getY() - camPos.y, pos.getZ() - camPos.z);
            net.minecraft.client.renderer.blockentity.BeaconRenderer.submitBeaconBeam(
                poseStack, collector,
                net.minecraft.client.renderer.blockentity.BeaconRenderer.BEAM_LOCATION,
                1.0F, animTime, 0, 1024, color, 0.2F, 0.25F);
            poseStack.popPose();
        }
    }

@SubscribeEvent
    public static void submitBeams(SubmitCustomGeometryEvent e) {
        if (!AdventureConfig.enableAffixItemEffects) {
            return;
        }

        Minecraft mc = Minecraft.getInstance();
        if (mc.level == null) {
            return;
        }

        Vec3 camPos = e.getLevelRenderState().cameraRenderState.pos;
        PoseStack pose = e.getPoseStack();
        SubmitNodeCollector collector = e.getSubmitNodeCollector();
        float partials = mc.getDeltaTracker().getGameTimeDeltaPartialTick(false);
        long gameTime = mc.level.getGameTime();

        for (Entity ent : mc.level.entitiesForRendering()) {
            if (!(ent instanceof ItemEntity item)) {
                continue;
            }

            ItemStack stack = item.getItem();
            DynamicHolder<LootRarity> rarityHolder = AffixHelper.getRarity(stack);
            if (!rarityHolder.isBound() || !item.onGround()) {
                item.setData(Apoth.Attachments.AFFIX_EFFECT_RENDER_STARTED, false);
                continue;
            }

            if (!item.getData(Apoth.Attachments.AFFIX_EFFECT_RENDER_STARTED)) {
                item.setData(Apoth.Attachments.AFFIX_EFFECT_RENDER_STARTED, true);
                item.setData(Apoth.Attachments.AFFIX_EFFECT_START_TIME, item.tickCount);
            }

            LootRarity rarity = rarityHolder.get();
            RarityRenderData renderData = rarity.renderData();
            int color = rarity.color().getValue();

            float progress = Mth.clamp(item.tickCount - item.getData(Apoth.Attachments.AFFIX_EFFECT_START_TIME) + partials, 0, GROW_IN_TICKS) / GROW_IN_TICKS;

            double x = Mth.lerp(partials, item.xOld, item.getX());
            double y = Mth.lerp(partials, item.yOld, item.getY());
            double z = Mth.lerp(partials, item.zOld, item.getZ());

            // Translate to the item entity in camera space; shadow rendering relies on this outer translation.
            pose.pushPose();
            pose.translate(x - camPos.x, y - camPos.y, z - camPos.z);

            float beamHeight = renderData.beamHeight();
            if (beamHeight > 0) {
                // Center the beam under the item (the beam origin is at the NW corner of a 1x1 block).
                pose.pushPose();
                pose.translate(-item.getBbWidth() * 2, 0, -item.getBbWidth() * 2);

                float beamRadius = renderData.beamRadius();
                float glowRadius = renderData.glowRadius();
                float height = beamHeight * progress;

                // Render four segments of the beam to produce a transparency gradient (fade in, ramp up, solid, fade out).
                BeamRenderer.renderBeaconBeam(pose, collector, renderData.beamTexture(), renderData.glowTexture(), partials, 1, gameTime,
                    0.0F, Math.min(height, 0.5F), color(ALPHA_ZERO, color), color(ALPHA_LOW, color), beamRadius, glowRadius);
                height -= 0.5F;

                BeamRenderer.renderBeaconBeam(pose, collector, renderData.beamTexture(), renderData.glowTexture(), partials, 1, gameTime,
                    0.5F, Mth.clamp(height, 0, 0.5F), color(ALPHA_LOW, color), color(ALPHA_MAX, color), beamRadius, glowRadius);
                height -= 0.5F;

                BeamRenderer.renderBeaconBeam(pose, collector, renderData.beamTexture(), renderData.glowTexture(), partials, 1, gameTime,
                    1.0F, Mth.clamp(height, 0, 0.5F), color(ALPHA_MAX, color), color(ALPHA_MAX, color), beamRadius, glowRadius);
                height -= 0.5F;

                BeamRenderer.renderBeaconBeam(pose, collector, renderData.beamTexture(), renderData.glowTexture(), partials, 1, gameTime,
                    1.5F, Mth.clamp(height, 0, beamHeight), color(ALPHA_MAX, color), color(ALPHA_ZERO, color), beamRadius, glowRadius);

                pose.popPose();
            }

            ShadowData shadow = renderData.shadow();
            ShadowRenderer.renderShadow(pose, collector, item, partials, mc.level, shadow, ARGB.color(shadow.alpha(), color));

            pose.popPose();
        }
    }

public static void renderBeaconBeam(
        PoseStack poseStack, SubmitNodeCollector collector, Identifier beamLocation, Identifier glowLocation, float partialTick, float textureScale,
        long gameTime, float yOffset, float height, int colorBot, int colorTop, float beamRadius, float glowRadius) {

        if (height < 0) {
            return;
        }

        final float maxY = yOffset + height;
        poseStack.pushPose();
        poseStack.translate(0.5, 0.0, 0.5);
        float f = Math.floorMod(gameTime, 40) + partialTick;
        float f1 = height < 0 ? f : -f;
        float f2 = Mth.frac(f1 * 0.2F - Mth.floor(f1 * 0.1F));
        poseStack.pushPose();
        poseStack.mulPose(Axis.YP.rotationDegrees(f * 2.25F - 45.0F));
        final float f6 = -beamRadius;
        final float f9 = -beamRadius;
        final float f12 = -1.0F + f2;
        final float f13 = height * textureScale * (0.5F / beamRadius) + f12;
        collector.submitCustomGeometry(poseStack, ApothRenderTypes.affixBeam(beamLocation, true), (pose, buffer) -> renderPart(
            pose, buffer, colorBot, colorTop, yOffset, maxY,
            0.0F, beamRadius, beamRadius, 0.0F, f6, 0.0F, 0.0F, f9,
            0.0F, 1.0F, f13, f12));
        poseStack.popPose();
        final float g3 = -glowRadius;
        final float g4 = -glowRadius;
        final float g5 = -glowRadius;
        final float g6 = -glowRadius;
        final float g12 = -1.0F + f2;
        final float g13 = height * textureScale + g12;
        final int glowBot = ARGB.alpha(colorBot) / 2 << 24 | colorBot & 0x00FFFFFF;
        final int glowTop = ARGB.alpha(colorTop) / 2 << 24 | colorTop & 0x00FFFFFF;
        collector.submitCustomGeometry(poseStack, ApothRenderTypes.affixBeam(glowLocation, true), (pose, buffer) -> renderPart(
            pose, buffer, glowBot, glowTop, yOffset, maxY,
            g3, g4, glowRadius, g5, g6, glowRadius, glowRadius, glowRadius,
            0.0F, 1.0F, g13, g12));
        poseStack.popPose();
    }

private static void addVertex(
        PoseStack.Pose pose, VertexConsumer consumer, int color, float y, float x, float z, float u, float v) {
        consumer.addVertex(pose, x, y, z)
            .setColor(color)
            .setUv(u, v)
            .setOverlay(OverlayTexture.NO_OVERLAY)
            .setLight(15728880)
            .setNormal(pose, 0.0F, 1.0F, 0.0F);
    }

@SubscribeEvent
    public static void submitOutlines(SubmitCustomGeometryEvent e) {
        Set<BlockPos> blocks = getAOEBlocks();
        if (blocks.isEmpty()) {
            return;
        }

        Minecraft mc = Minecraft.getInstance();
        Level level = mc.level;
        if (level == null) {
            return;
        }

        Vec3 camPos = e.getLevelRenderState().cameraRenderState.pos;
        PoseStack pose = e.getPoseStack();
        SubmitNodeCollector collector = e.getSubmitNodeCollector();

        for (BlockPos pos : blocks) {
            BlockState state = level.getBlockState(pos);
            if (state.isAir()) {
                continue;
            }

            VoxelShape shape = state.getShape(level, pos);
            if (shape.isEmpty()) {
                continue;
            }

            double x = pos.getX() - camPos.x;
            double y = pos.getY() - camPos.y;
            double z = pos.getZ() - camPos.z;

            collector.submitCustomGeometry(pose, RenderTypes.lines(), (p, buffer) -> {
                shape.forAllEdges((x1, y1, z1, x2, y2, z2) -> {
                    org.joml.Vector3f normal = new org.joml.Vector3f((float) (x2 - x1), (float) (y2 - y1), (float) (z2 - z1)).normalize();
                    buffer.addVertex(p, (float) (x1 + x), (float) (y1 + y), (float) (z1 + z))
                        .setColor(0, 0, 0, 102).setNormal(p, normal).setLineWidth(2F);
                    buffer.addVertex(p, (float) (x2 + x), (float) (y2 + y), (float) (z2 + z))
                        .setColor(0, 0, 0, 102).setNormal(p, normal).setLineWidth(2F);
                });
            });
        }

        submitCrumbling(e, blocks, mc, level, camPos, pose, collector);
    }

static void renderShadow(
        PoseStack poseStack, SubmitNodeCollector collector, Entity entity, float partialTicks, LevelReader level, ShadowData data, int color) {
        // Discard the render if the size is zero, since we call this even when the shadow doesn't need to render.
        float size = data.size();
        if (size <= 0) {
            return;
        }

        final double x = Mth.lerp(partialTicks, entity.xOld, entity.getX());
        final double y = Mth.lerp(partialTicks, entity.yOld, entity.getY());
        final double z = Mth.lerp(partialTicks, entity.zOld, entity.getZ());
        final int xMin = Mth.floor(x - size);
        final int xMax = Mth.floor(x + size);
        final int yMin = Mth.floor(y - 2); // Discard the concept of weight and always check 2 blocks down.
        final int yMax = Mth.floor(y);
        final int zMin = Mth.floor(z - size);
        final int zMax = Mth.floor(z + size);

        // Use a custom render type instead of SHADOW_RENDER_TYPE to replace the texture
        collector.submitCustomGeometry(poseStack, ApothRenderTypes.affixShadow(data.texture()), (pose, vtx) -> {
            BlockPos.MutableBlockPos pos = new BlockPos.MutableBlockPos();
            for (int zi = zMin; zi <= zMax; zi++) {
                for (int xi = xMin; xi <= xMax; xi++) {
                    pos.set(xi, 0, zi);
                    ChunkAccess chunkaccess = level.getChunk(pos);

                    for (int yi = yMin; yi <= yMax; yi++) {
                        pos.setY(yi);
                        renderBlockShadow(pose, vtx, entity, chunkaccess, partialTicks, level, pos, x, y, z, data, color);
                    }
                }
            }
        });
    }

private static void renderBlockShadow(
        PoseStack.Pose pose,
        VertexConsumer vertexConsumer,
        Entity entity,
        ChunkAccess chunk,
        float partialTicks,
        LevelReader level,
        BlockPos pos,
        double x,
        double y,
        double z,
        ShadowData data,
        int color) {
        BlockPos blockpos = pos;
        BlockState blockstate = chunk.getBlockState(blockpos);
        if (blockstate.getRenderShape() != RenderShape.INVISIBLE) { // Removed the brightness check here
            VoxelShape voxelshape = blockstate.getShape(chunk, blockpos);
            if (!voxelshape.isEmpty() && Block.isFaceFull(voxelshape, Direction.DOWN)) { // Use isFaceFull instead of isCollisionShapeFullBlock to render on top of flat blocks
                // Animation support logic (vanilla shadows are not animated)
                final int frames = data.frames();
                final float frameTime = data.frameTime();
                final float frame = (int) ((Minecraft.getInstance().level.getGameTime() + partialTicks) / frameTime % frames);

                float size = data.size();
                AABB aabb = voxelshape.bounds();
                // So, vanilla cheats to render the shadow. They actually render a bunch of quads outside of the texture space, which renders blank.
                // That works, until you add animation frames into the texture, at which point those off-texture quads are no longer off-texture.
                // This call locks the AABB into the intersection of the top of the block with the entity's BB, so only the real shadow is drawn.
                aabb = aabb.intersect(new AABB(entity.getX() - pos.getX() - size, 0, entity.getZ() - pos.getZ() - size, entity.getX() - pos.getX() + size, aabb.maxY, entity.getZ() - pos.getZ() + size));
                double minX = pos.getX() + aabb.minX;
                double maxX = pos.getX() + aabb.maxX;
                double minY = pos.getY() + aabb.maxY;
                double minZ = pos.getZ() + aabb.minZ;
                double maxZ = pos.getZ() + aabb.maxZ;
                float xi = (float) (minX - x);
                float xp = (float) (maxX - x);
                float yi = (float) (minY - y) + 0.001F; // Apply a slight offset to avoid Z-clipping with the block [Fixes flickering with BSL]
                float zi = (float) (minZ - z);
                float zp = (float) (maxZ - z);

                float u1 = -xi / 2.0F / size + 0.5F;
                float u2 = -xp / 2.0F / size + 0.5F;
                float v1 = -zi / 2.0F / size + 0.5F;
                float v2 = -zp / 2.0F / size + 0.5F;

                shadowVertex(pose, vertexConsumer, color, xi, yi, zi, u1, v1 / frames + frame / frames);
                shadowVertex(pose, vertexConsumer, color, xi, yi, zp, u1, v2 / frames + frame / frames);
                shadowVertex(pose, vertexConsumer, color, xp, yi, zp, u2, v2 / frames + frame / frames);
                shadowVertex(pose, vertexConsumer, color, xp, yi, zi, u2, v1 / frames + frame / frames);
            }
        }
    }

@Override
    public void extractRenderState(GuiGraphicsExtractor gfx, int mouseX, int mouseY, float partialTick) {
        super.extractRenderState(gfx, mouseX, mouseY, partialTick);

        int leftPos = (this.width - WorldTierSelectScreen.IMAGE_WIDTH) / 2 + 26;
        int topPos = (this.height - WorldTierSelectScreen.IMAGE_HEIGHT) / 2 + 30;

        LocalPlayer player = Minecraft.getInstance().player;
        AttributeTooltipContext ctx = AttributeTooltipContext.of(player, TooltipContext.of(player.level()), net.minecraft.world.item.component.TooltipDisplay.DEFAULT, ApothicAttributes.getTooltipFlag());
        float effectiveLuck = Minecraft.getInstance().hasShiftDown() ? 0 : player.getLuck(); // Show default values on shift, "real" values otherwise.

        for (int i = 0; i < 3; i++) {

            if (i == 2) {
                int x = leftPos + i * (BOX_WIDTH + 16);
                int y = topPos;

                Component header = Apotheosis.lang("text", "monster_augments").withStyle(ChatFormatting.RED, ChatFormatting.BOLD);
                drawCenteredString(gfx, this.font, header, x + BOX_WIDTH / 2, y + 12, 0xFF000000);

                y += 20;

                for (TierAugment aug : TierAugmentRegistry.getAugments(this.tier, Target.MONSTERS)) {
                    y += 12;
                    Component comp = aug.getDescription(ctx).plainCopy().withStyle(ChatFormatting.RED);
                    this.drawScrollingStringWithoutMoving(gfx, this.font, comp, x + 12, x + BOX_WIDTH - 12, y, 0xFF000000);
                }

            }
            else if (i == 1) {
                int x = leftPos + i * (BOX_WIDTH + 16);
                int y = topPos;

                Component header = Apotheosis.lang("text", "player_augments").withColor(0x00AAFF).withStyle(ChatFormatting.BOLD);
                drawCenteredString(gfx, this.font, header, x + BOX_WIDTH / 2, y + 12, 0xFF000000);

                y += 20;

                for (TierAugment aug : TierAugmentRegistry.getAugments(this.tier, Target.PLAYERS)) {
                    y += 12;
                    Component comp = aug.getDescription(ctx).plainCopy().withColor(0x00AAFF);
                    this.drawScrollingStringWithoutMoving(gfx, this.font, comp, x + 12, x + BOX_WIDTH - 12, y, 0xFF000000);
                }

            }
            else if (i == 0) {
                int x = leftPos + i * (BOX_WIDTH + 16);
                int y = topPos;

                Component header = Apotheosis.lang("text", "drop_chances").withStyle(ChatFormatting.GOLD).withStyle(ChatFormatting.BOLD);
                drawCenteredString(gfx, this.font, header, x + BOX_WIDTH / 2, y + 12, 0xFF000000);

                Component rarityHeader = Apotheosis.lang("text", "rarities").withStyle(ChatFormatting.GOLD).withStyle(ChatFormatting.UNDERLINE);
                drawCenteredString(gfx, this.font, rarityHeader, x + BOX_WIDTH / 2, y + 33, 0xFF000000);

                y += 35;

                int totalWeight = RarityRegistry.INSTANCE.getValues().stream().mapToInt(r -> r.weights().getWeight(this.tier, effectiveLuck)).sum();
                for (LootRarity rarity : RarityRegistry.getSortedRarities()) {
                    y += 12;
                    float percent = rarity.weights().getWeight(this.tier, effectiveLuck) / (float) totalWeight;
                    MutableComponent comp = rarity.toComponent();
                    comp.append(Component.translatable(": %s", Affix.fmt(100 * percent) + "%").withStyle(s -> s.withColor(rarity.color())));
                    this.drawScrollingStringWithoutMoving(gfx, this.font, comp, x + 12, x + BOX_WIDTH - 12, y, 0xFFFFFFFF);
                }

                Component purityHeader = Apotheosis.lang("text", "purities").withStyle(ChatFormatting.GOLD).withStyle(ChatFormatting.UNDERLINE);
                drawCenteredString(gfx, this.font, purityHeader, x + BOX_WIDTH / 2, y + 13, 0xFF000000);

                y += 15;

                Purity[] values = Purity.values();
                totalWeight = Arrays.stream(values).mapToInt(r -> r.weights().getWeight(this.tier, effectiveLuck)).sum();
                for (Purity purity : values) {
                    y += 12;
                    float percent = purity.weights().getWeight(this.tier, effectiveLuck) / (float) totalWeight;
                    MutableComponent comp = purity.toComponent();
                    comp.append(Component.translatable(": %s", Affix.fmt(100 * percent) + "%").withStyle(s -> s.withColor(purity.getColor())));
                    this.drawScrollingStringWithoutMoving(gfx, this.font, comp, x + 12, x + BOX_WIDTH - 12, y, 0xFFFFFFFF);
                }
            }

        }
    }

@Override
  public boolean applyForgeHandTransform(PoseStack poseStack, LocalPlayer player, HumanoidArm arm, ItemStack stack, float partialTicks, float equipProgress, float swingProgress) {
    // forge: why don't you give me the arm that is used on the next line???
    InteractionHand hand = arm == player.getMainArm() ? InteractionHand.MAIN_HAND : InteractionHand.OFF_HAND;
    // this code is copied from ItemInHandRenderer#renderArmWithItem with changes made for Tinker tools
    // to avoid redundant operations, we copied even methods that are unmodified, changes are noted below
    int sideOffset = arm == HumanoidArm.RIGHT ? 1 : -1;
    if (player.isUsingItem() && player.getUseItemRemainingTicks() > 0 && player.getUsedItemHand() == hand) {
      UseAnim anim = stack.getUseAnimation();
      switch (anim) {
        // merged BLOCK and NONE - same code
        case NONE, BLOCK:
          applyItemArmTransform(poseStack, equipProgress, sideOffset);
          break;

        case EAT:
        case DRINK:
          // start: applyEatTransform
          float timeLeft = player.getUseItemRemainingTicks() - partialTicks + 1;
          float percentage = timeLeft / stack.getUseDuration();
          if (percentage < 0.8f) {
            poseStack.translate(0, Mth.abs(Mth.cos(timeLeft / 4f * PI) * 0.1f), 0);
          }

          float speed = 1 - (float)Math.pow(percentage, 27);
          int sideOffset1 = arm == HumanoidArm.RIGHT ? 1 : -1;
          poseStack.translate(speed * 0.6F * (float) sideOffset1, speed * -0.5f, speed * 0);
          poseStack.mulPose(Axis.YP.rotationDegrees(sideOffset1 * speed * 90));
          poseStack.mulPose(Axis.XP.rotationDegrees(speed * 10));
          poseStack.mulPose(Axis.ZP.rotationDegrees(sideOffset1 * speed * 30));
          // end: applyEatTransform
          applyItemArmTransform(poseStack, equipProgress, sideOffset);
          break;

        // crossbow is moved from the vanilla special case to a general animation
        case BOW:
        case CROSSBOW: {
          boolean isBow = anim == UseAnim.BOW;
          applyItemArmTransform(poseStack, equipProgress, sideOffset);
          // change: merged in crossbow
          if (isBow) {
            poseStack.translate(sideOffset * -0.2785682f, 0.18344387f, 0.15731531f);
            poseStack.mulPose(Axis.XP.rotationDegrees(-13.935f));
            poseStack.mulPose(Axis.YP.rotationDegrees(sideOffset * 35.3f));
          } else {
            poseStack.translate(sideOffset * -0.4785682f, -0.094387f, 0.05731531f);
            poseStack.mulPose(Axis.XP.rotationDegrees(-11.935f));
            poseStack.mulPose(Axis.YP.rotationDegrees(sideOffset * 65.3f));
          }
          poseStack.mulPose(Axis.ZP.rotationDegrees(sideOffset * -9.785f));

          float remainingTime = (float) stack.getUseDuration() - ((float) player.getUseItemRemainingTicks() - partialTicks + 1);
          // change: scale charge by drawtime instead of a flat 20f or the crossbow enchantment
          float charge = remainingTime / ModifierUtil.getPersistentInt(stack, GeneralInteractionModifierHook.KEY_DRAWTIME, 20);
          // only bows do this weird charge formula
          if (isBow) {
            charge = (charge * charge + charge * 2) / 3;
          }
          if (charge > 1) {
            charge = 1;
          }

          if (charge > 0.1f) {
            // change: inlined expressions, replaced (value * 0) with 0
            poseStack.translate(0, Mth.sin((remainingTime - 0.1f) * 1.3f) * (charge - 0.1f) * 0.004f, 0);
          }
          // change: replaced (value * 0) with 0
          poseStack.translate(0, 0, charge * 0.04f);
          poseStack.scale(1, 1, 1 + charge * 0.2f);
          poseStack.mulPose(Axis.YN.rotationDegrees(sideOffset * 45));
          break;
        }

        case SPEAR:
          applyItemArmTransform(poseStack, equipProgress, sideOffset);
          poseStack.translate(sideOffset * -0.5f, 0.7f, 0.1f);
          // change: added 45 degrees to take into account tools being diagonal
          poseStack.mulPose(Axis.XP.rotationDegrees(-90));
          poseStack.mulPose(Axis.YP.rotationDegrees(sideOffset * 35.3f));
          poseStack.mulPose(Axis.ZP.rotationDegrees(sideOffset * -9.785f));
          float sRemainingTime = stack.getUseDuration() - (player.getUseItemRemainingTicks() - partialTicks + 1);
          // change: scale charge by drawtime instead of a flat 10f, tridents have 2.0 drawspeed I decided
          float sCharge = sRemainingTime / ModifierUtil.getPersistentInt(stack, GeneralInteractionModifierHook.KEY_DRAWTIME, 20);
          if (sCharge > 1) {
            sCharge = 1;
          }

          if (sCharge > 0.1F) {
            // change: inlined expressions, replaced (value * 0) with 0
            poseStack.translate(0, Mth.sin((sRemainingTime - 0.1F) * 1.3F) * (sCharge - 0.1F) * 0.004F, 0);
          }
          poseStack.translate(0, 0, sCharge * 0.2f);
          poseStack.scale(1, 1, 1 + sCharge * 0.2f);
          poseStack.mulPose(Axis.YN.rotationDegrees(sideOffset * 45));
          break;

        case BRUSH:
          // start: applyBrushTransform
          applyItemArmTransform(poseStack, equipProgress, sideOffset);
          float xRot = -15 + 75 * Mth.cos((1 - ((float) (player.getUseItemRemainingTicks() % 10) - partialTicks + 1) / 10) * 2 * PI);
          if (arm != HumanoidArm.RIGHT) {
            poseStack.translate(0.1, 0.83, 0.35);
            poseStack.mulPose(Axis.XP.rotationDegrees(-80));
            poseStack.mulPose(Axis.YP.rotationDegrees(-90));
            poseStack.mulPose(Axis.XP.rotationDegrees(xRot));
            poseStack.translate(-0.3, 0.22, 0.35);
          } else {
            poseStack.translate(-0.25, 0.22, 0.35);
            poseStack.mulPose(Axis.XP.rotationDegrees(-80));
            poseStack.mulPose(Axis.YP.rotationDegrees(90));
            poseStack.mulPose(Axis.ZP.rotationDegrees(0));
            poseStack.mulPose(Axis.XP.rotationDegrees(xRot));
          }
          // end: applyBrushTransform
      }
    } else if (player.isAutoSpinAttack()) {
      applyItemArmTransform(poseStack, equipProgress, sideOffset);
      poseStack.translate(sideOffset * -0.4f, 0.8f, 0.3f);
      poseStack.mulPose(Axis.YP.rotationDegrees(sideOffset * 105));
      poseStack.mulPose(Axis.ZP.rotationDegrees(sideOffset * -85));
    } else {
      poseStack.translate(
        sideOffset * -0.4f * Mth.sin(Mth.sqrt(swingProgress) * PI),
        0.2f * Mth.sin(Mth.sqrt(swingProgress) * PI * 2),
        -0.2f * Mth.sin(swingProgress * PI));
      applyItemArmTransform(poseStack, equipProgress, sideOffset);
      // begin: applyItemArmAttackTransform
      poseStack.mulPose(Axis.YP.rotationDegrees(sideOffset * (45 + Mth.sin(swingProgress * swingProgress * (float)Math.PI) * -20)));
      float rotation = Mth.sin(Mth.sqrt(swingProgress) * PI);
      poseStack.mulPose(Axis.ZP.rotationDegrees(sideOffset * rotation * -20));
      poseStack.mulPose(Axis.XP.rotationDegrees(rotation * -80));
      poseStack.mulPose(Axis.YP.rotationDegrees(sideOffset * -45));
      // end: applyItemArmAttackTransform
    }
    return true;
  }

@Override
    public void submit(PoseStack poseStack, SubmitNodeCollector submitNodeCollector, int lightCoords, int overlayCoords, boolean hasFoil, int outlineColor) {
        poseStack.pushPose();
        poseStack.translate(0.5, 0, 0.5);
        poseStack.mulPose(Axis.ZP.rotationDegrees(180));
        poseStack.translate(0.0F, -1.701F, 0.0F);
        float f1 = RotationSegment.convertToDegrees(0);
        poseStack.mulPose(Axis.YP.rotationDegrees(f1));
        submitNodeCollector.submitModel(this.model, new GhostRenderer.GhostRenderState(), poseStack, RenderTypes.entityTranslucentCullItemTarget(GhostRenderer.TEXTURE), lightCoords, overlayCoords, 0, null);
        poseStack.popPose();
    }

private void renderCrosshair(RenderGuiLayerEvent.Pre event) {
        if (WerewolvesConfig.CLIENT.disableFangCrosshairRendering.get()) return;
        if (Helper.isWerewolf(this.mc.player)) {
            HitResult result = Minecraft.getInstance().hitResult;
            LivingEntity entity = result instanceof EntityHitResult entityResult ? entityResult.getEntity() instanceof LivingEntity living ? living : null : null;
            if (entity != null && WerewolfPlayer.get(mc.player).canBite()) {
                renderFangs(event.getGuiGraphics(), this.mc.getWindow().getGuiScaledWidth(), this.mc.getWindow().getGuiScaledHeight(), entity);
                event.setCanceled(true);
            }
        }
    }

public boolean renderArm(AbstractClientPlayer player, PoseStack stack, MultiBufferSource bufferSource, int pCombinedLight, HumanoidArm arm) {
        return render(player, form -> {
            if (form == WerewolfForm.SURVIVALIST) {
                if (arm == HumanoidArm.LEFT) {
                    survivalistRenderer.renderLeftHand(stack, bufferSource, pCombinedLight, player);
                } else {
                    survivalistRenderer.renderRightHand(stack, bufferSource, pCombinedLight, player);
                }
                return true;
            } else if (form == WerewolfForm.BEAST) {
                if (arm == HumanoidArm.LEFT) {
                    beastRenderer.renderLeftHand(stack, bufferSource, pCombinedLight, player);
                } else {
                    beastRenderer.renderRightHand(stack, bufferSource, pCombinedLight, player);
                }
                return true;
            }
            return false;
        });
    }

@Override
    public void render(@Nonnull PoseStack matrixStack, @Nonnull MultiBufferSource bufferIn, int packedLightIn, @Nonnull WerewolfBaseEntity werewolf, float limbSwing, float limbSwingAmount, float partialTicks, float ageInTicks, float netHeadYaw, float headPitch) {
        if (werewolf.isInvisible()) {
            return;
        }
        int s = werewolf.getEyeType();
        int eyeType = Math.max(0, s) % (eyeOverlays.length);
        RenderType renderType = RenderType.eyes(eyeOverlays[eyeType]);
        VertexConsumer vertexBuilderEye = bufferIn.getBuffer(renderType);
        int packerOverlay = LivingEntityRenderer.getOverlayCoords(werewolf, 0);
        this.getParentModel().getModelRenderer().render(matrixStack, vertexBuilderEye, packedLightIn, packerOverlay);
    }

@Override
    public void render(@Nonnull PoseStack matrixStack, @Nonnull MultiBufferSource bufferIn, int packedLightIn, @Nonnull T entity, float limbSwing, float limbSwingAmount, float partialTicks, float ageInTicks, float netHeadYaw, float headPitch) {
        if (entity.isInvisible()) {
            return;
        }
        IWerewolf werewolf = entity instanceof IWerewolf ? (IWerewolf) entity : WerewolfPlayer.get(((Player) entity));
        int eyeType = Math.max(0, Math.min(getEyeType(werewolf), eyeOverlays.length - 1));
        ResourceLocation eyeTexture = eyeOverlays[eyeType];
        // Non-glowing eyes share the body's render type (entityTranslucent for PlayerModel) so they are drawn in the
        // same pass as the body; a cutout type can be flushed before the translucent body and get painted over.
        RenderType eyeRenderType = hasGlowingEyes(werewolf) ? RenderType.eyes(eyeTexture) : this.getParentModel().renderType(eyeTexture);
        VertexConsumer vertexBuilderEye = bufferIn.getBuffer(eyeRenderType);
        this.getParentModel().renderToBuffer(matrixStack, vertexBuilderEye, packedLightIn, OverlayTexture.NO_OVERLAY);
    }

