            builder.addVertex(posMat, button.posX + 0.5F, button.posY + 0.5F, Z_OFFSET)
                    .setColor(button.red, button.green, button.blue, 0.1F)
                    .setLight(0x00F000A0);
            builder.addVertex(posMat, button.posX + 0.5F, button.posY + button.height + 0.5F, Z_OFFSET)
                    .setColor(button.red, button.green, button.blue, 0.1F)
                    .setLight(0x00F000A0);
            builder.addVertex(posMat, button.posX + button.width + 0.5F, button.posY + button.height + 0.5F, Z_OFFSET)
                    .setColor(button.red, button.green, button.blue, 0.1F)
                    .setLight(0x00F000A0);
            builder.addVertex(posMat, button.posX + button.width + 0.5F, button.posY + 0.5F, Z_OFFSET)
                    .setColor(button.red, button.green, button.blue, 0.1F)
                    .setLight(0x00F000A0);

            // button text
            matrixStackIn.pushPose();
            matrixStackIn.translate(button.posX + 0.5D, button.posY + 0.5D, 0.498);
            matrixStackIn.translate(button.width / 2, button.height / 2, 0);
            float textScale = Math.min(button.width / 10F, button.height / 10F);
            matrixStackIn.scale(textScale, textScale, textScale);
            font.drawInBatch(button.buttonText, -font.width(button.buttonText) / 2f, -font.lineHeight / 2f + 1, 0xFFFFFFFF, false, matrixStackIn.last().pose(), bufferIn, Font.DisplayMode.NORMAL, 50, 0x00F000A0);
            matrixStackIn.popPose();
        }

        matrixStackIn.popPose();
    }

@Override
    void renderModel(ManualCompressorBlockEntity te, float partialTicks, PoseStack matrixStackIn, MultiBufferSource bufferIn, int combinedLightIn, int combinedOverlayIn) {
        VertexConsumer builder = bufferIn.getBuffer(RenderType.entityCutout(Textures.MODEL_MANUAL_COMPRESSOR));

        // Rotates the pumprod to match the rotation of the compressor
        matrixStackIn.translate(0, -9 / 16F, 0);

        switch (te.getRotation()) {
            case NORTH -> matrixStackIn.mulPose(Axis.YN.rotationDegrees(0));
            case EAST -> matrixStackIn.mulPose(Axis.YN.rotationDegrees(270));
            case SOUTH -> matrixStackIn.mulPose(Axis.YN.rotationDegrees(180));
            case WEST -> matrixStackIn.mulPose(Axis.YN.rotationDegrees(90));
        }

        matrixStackIn.translate(0, 9 / 16F, 0);

        // Renders the intermediate offsets of the pump rod during its animation
        if (te.getLevel().getGameTime() <= te.pumpStepStartTick + ManualCompressorBlockEntity.TICKS_PER_PUMP_STEP) {
            double offset = Mth.lerp(partialTicks, te.pumprodVerticalOffsetPreviousTick, te.pumprodVerticalOffsetCurrentTick);
            matrixStackIn.translate(0, offset / 16F, 0);
        }

        // Renders the final stationary offset of the pump rod after animation is complete
        else {
            matrixStackIn.translate(0, te.pumprodVerticalOffsetCurrent / 16F, 0);
        }

        pumprod.render(matrixStackIn, builder, combinedLightIn, combinedOverlayIn);
    }

@Override
    public void renderModel(PneumaticDoorBaseBlockEntity te, float partialTicks, PoseStack matrixStackIn, MultiBufferSource bufferIn, int combinedLightIn, int combinedOverlayIn) {
        VertexConsumer builder = bufferIn.getBuffer(RenderType.entityCutout(Textures.MODEL_PNEUMATIC_DOOR_BASE));

        float progress = Mth.lerp(partialTicks, te.oldProgress, te.progress);

        float cosinus = (float) Math.sin(Math.toRadians((1 - progress) * 90)) * 12 / 16F;
        float sinus = 9 / 16F - (float) Math.cos(Math.toRadians((1 - progress) * 90)) * 9 / 16F;
        double extension = Math.sqrt(Math.pow(sinus, 2) + Math.pow(cosinus + 4 / 16F, 2));

        RenderUtils.rotateMatrixForDirection(matrixStackIn, te.getRotation());

        matrixStackIn.translate(((te.rightGoing ? -4 : 0) + 2.5) / 16F, 0, -6 / 16F);
        float cylinderAngle = (float) Math.toDegrees(Math.atan(sinus / (cosinus + 14 / 16F)));
        matrixStackIn.mulPose(te.rightGoing ? Axis.YP.rotationDegrees(cylinderAngle) : Axis.YN.rotationDegrees(cylinderAngle));
        matrixStackIn.translate(((te.rightGoing ? -3 : 0) - 2.5) / 16F, 0, 6 / 16F);
        double extensionPart = extension * 0.5D;
        int l = ClientUtils.getLightAt(te.getBlockPos().relative(te.getRotation()));  // avoid cylinders rendering unlit
        cylinder1.render(matrixStackIn, builder, l, combinedOverlayIn);
        matrixStackIn.translate(0, 0, extensionPart);
        cylinder2.render(matrixStackIn, builder, l, combinedOverlayIn, 0xFFCCCCCC);
        matrixStackIn.translate(0, 0, extensionPart);
        cylinder3.render(matrixStackIn, builder, l, combinedOverlayIn, 0xFF989898);
    }

@Override
    public void renderModel(PneumaticDoorBlockEntity te, float partialTicks, PoseStack matrixStackIn, MultiBufferSource bufferIn, int combinedLightIn, int combinedOverlayIn) {
        if (te.getBlockState().getValue(PneumaticDoorBlock.TOP_DOOR)) return;

        VertexConsumer builder = bufferIn.getBuffer(RenderType.entityCutout(Textures.MODEL_PNEUMATIC_DOOR_DYNAMIC));

        float rotation = Mth.lerp(partialTicks, te.oldRotationAngle, te.rotationAngle);
        boolean rightGoing = te.rightGoing;

        RenderUtils.rotateMatrixForDirection(matrixStackIn, te.getRotation());

        matrixStackIn.translate((rightGoing ? -1 : 1) * 6.5F / 16F, 0, -6.5F / 16F);
        matrixStackIn.mulPose(rightGoing ? Axis.YN.rotationDegrees(rotation) : Axis.YP.rotationDegrees(rotation));
        matrixStackIn.translate((rightGoing ? -1 : 1) * -6.5F / 16F, 0, 6.5F / 16F);

        if (rightGoing) {
            matrixStackIn.translate(0, 0, -6.5/16F);
            matrixStackIn.mulPose(Axis.YP.rotationDegrees(180));
            matrixStackIn.translate(0, 0, 6.5/16F);
        }
        door.render(matrixStackIn, builder, combinedLightIn, combinedOverlayIn, 0xFF000000 | te.getColor().getTextureDiffuseColor());
    }

@Override
    public void renderModel(PressureChamberInterfaceBlockEntity te, float partialTicks, PoseStack matrixStackIn, MultiBufferSource bufferIn, int combinedLightIn, int combinedOverlayIn) {
        VertexConsumer builder = bufferIn.getBuffer(RenderType.entityCutout(Textures.MODEL_PRESSURE_CHAMBER_INTERFACE));

        RenderUtils.rotateMatrixForDirection(matrixStackIn, te.getRotation());

        float inputProgress = Mth.lerp(partialTicks, te.oldInputProgress, te.inputProgress) / MAX_PROGRESS;
        float outputProgress = Mth.lerp(partialTicks, te.oldOutputProgress, te.outputProgress) / MAX_PROGRESS;
        if (inputProgress <= 1f) {
            // REMOVED:           matrixStackIn.scale(1F - inputProgress, 1, 1);
            matrixStackIn.pushPose();
            matrixStackIn.translate((1F - (float) Math.cos(inputProgress * Math.PI)) * 0.122F + 0.25, 0, 0);
            inputLeft.render(matrixStackIn, builder, combinedLightIn, combinedOverlayIn);
            matrixStackIn.popPose();

            matrixStackIn.pushPose();
            matrixStackIn.translate((-1F + (float) Math.cos(inputProgress * Math.PI)) * 0.122F - 0.25, 0, 0);
            inputRight.render(matrixStackIn, builder, combinedLightIn, combinedOverlayIn);
            matrixStackIn.popPose();

            matrixStackIn.pushPose();
            matrixStackIn.translate(0, (1F - (float) Math.cos(inputProgress * Math.PI)) * 0.122F, 0);
            inputBottom.render(matrixStackIn, builder, combinedLightIn, combinedOverlayIn);
            matrixStackIn.popPose();

            matrixStackIn.pushPose();
            matrixStackIn.translate(0, (-1F + (float) Math.cos(inputProgress * Math.PI)) * 0.122F, 0);
            inputTop.render(matrixStackIn, builder, combinedLightIn, combinedOverlayIn);
            matrixStackIn.popPose();
        }
        if (outputProgress < 1f) {
            matrixStackIn.pushPose();
            matrixStackIn.translate((1F - (float) Math.cos(outputProgress * Math.PI)) * 0.122F + 0.25, 0, 0);
            outputLeft.render(matrixStackIn, builder, combinedLightIn, combinedOverlayIn);
            matrixStackIn.popPose();

            matrixStackIn.pushPose();
            matrixStackIn.translate((-1F + (float) Math.cos(outputProgress * Math.PI)) * 0.122F - 0.25, 0, 0);
            outputRight.render(matrixStackIn, builder, combinedLightIn, combinedOverlayIn);
            matrixStackIn.popPose();

            matrixStackIn.pushPose();
            matrixStackIn.translate(0, (1F - (float) Math.cos(outputProgress * Math.PI)) * 0.122F, 0);
            outputBottom.render(matrixStackIn, builder, combinedLightIn, combinedOverlayIn);
            matrixStackIn.popPose();

            matrixStackIn.pushPose();
            matrixStackIn.translate(0, (-1F + (float) Math.cos(outputProgress * Math.PI)) * 0.122F, 0);
            outputTop.render(matrixStackIn, builder, combinedLightIn, combinedOverlayIn);
            matrixStackIn.popPose();
        }
    }

