private static void renderIndicator(Minecraft minecraft, GuiGraphicsExtractor graphics, Gui gui, Player player, int screenWidth, int screenHeight) {
		if (minecraft.options.getCameraType().isFirstPerson() && (minecraft.gameMode.getPlayerMode() != GameType.SPECTATOR || gui.canRenderCrosshairForSpectator(minecraft.hitResult)) && minecraft.crosshairPickEntity instanceof QuestRam ram) {
			ItemStack stack = player.getInventory().getItem(player.getInventory().getSelectedSlot());
			if (!stack.isEmpty()) {
				for (var questEntry : questingRamCurrentContext.getContext().questItems().entrySet()) {
					if (questEntry.getValue().test(stack)) {
						int j = ((screenHeight - 1) / 2) - 11;
						int k = ((screenWidth - 1) / 2) - 3;
						if (!ram.isColorPresent(questEntry.getKey())) {
							graphics.blitSprite(RenderPipelines.CROSSHAIR, QUESTING_RAM_X_SPRITE, k, j, 7, 7);
						} else {
							graphics.blitSprite(RenderPipelines.CROSSHAIR, QUESTING_RAM_CHECK_SPRITE, k, j, 7, 7);
						}
						break;
					}
				}
			}
		}
	}

private static void renderHolders(GuiGraphicsExtractor graphics, Minecraft minecraft, Gui gui, Player player, List<DisplayHolder> typesToRender, int widest) {
		graphics.pose().pushMatrix();
		graphics.pose().translate(TFConfig.itemDisplayXOffs, TFConfig.itemDisplayYOffs);
		graphics.pose().scale((float) TFConfig.itemDisplayScale, (float) TFConfig.itemDisplayScale);
		typesToRender.sort(Comparator.comparing(holder -> holder.display().displayPosition()));
		for (DisplayHolder holder : typesToRender) {
			graphics.pose().pushMatrix();
			holder.display().render(holder.stack(), graphics, minecraft, gui, player, widest);
			//debug fill to see widget sizes
			//graphics.fill(holder.bounds().startX(), holder.bounds().startY(), holder.bounds().startX() + holder.bounds().width(), holder.bounds().startY() + holder.bounds().height(), 0x80FF0000);
			graphics.pose().popMatrix();
			graphics.pose().translate(0.0F, holder.bounds().height());
		}
		graphics.pose().popMatrix();
	}

@Override
	public boolean render(MapRenderState.MapDecorationRenderState decoration, PoseStack stack, SubmitNodeCollector submitNodeCollector, MapRenderState mapRenderState, TextureAtlas decorationSprites, boolean inItemFrame, int packedLight, int index) {
		if (!Boolean.TRUE.equals(mapRenderState.getRenderData(IS_MAGIC_MAP_KEY)))
			return false;

		TextureAtlasSprite textureatlassprite = decoration.atlasSprite;
		if (textureatlassprite == null)
			return false;

		stack.pushPose();
		stack.translate(decoration.x / 2.0F + 64.0F, decoration.y / 2.0F + 64.0F, -0.02F);
		stack.mulPose(Axis.ZP.rotationDegrees(decoration.rot * 360 / 16.0F));
		stack.scale(4.0F, 4.0F, 3.0F);
		stack.translate(-0.125F, 0.125F, 0.0F);
		submitNodeCollector.submitCustomGeometry(stack, RenderTypes.text(textureatlassprite.atlasLocation()), (pose, consumer) -> {
			consumer.addVertex(pose, -1.0F, 1.0F, -0.3F).setColor(-1).setUv(textureatlassprite.getU0(), textureatlassprite.getV0()).setLight(packedLight);
			consumer.addVertex(pose, 1.0F, 1.0F, -0.3F).setColor(-1).setUv(textureatlassprite.getU1(), textureatlassprite.getV0()).setLight(packedLight);
			consumer.addVertex(pose, 1.0F, -1.0F, -0.3F).setColor(-1).setUv(textureatlassprite.getU1(), textureatlassprite.getV1()).setLight(packedLight);
			consumer.addVertex(pose, -1.0F, -1.0F, -0.3F).setColor(-1).setUv(textureatlassprite.getU0(), textureatlassprite.getV1()).setLight(packedLight);
		});
		stack.popPose();
		return true;
	}

private static void renderItemInFirstPerson(AbstractClientPlayer player, EnumHand hand, float swingProgress, ItemStack stack, float equipProgress) {
		// Cherry picked from ItemRenderer.renderItemInFirstPerson
		boolean flag = hand == EnumHand.MAIN_HAND;
		EnumHandSide enumhandside = flag ? player.getPrimaryHand() : player.getPrimaryHand().opposite();
		GlStateManager.pushMatrix();
		boolean flag1 = enumhandside == EnumHandSide.RIGHT;
		float f = -0.4F * MathHelper.sin(MathHelper.sqrt(swingProgress) * (float) Math.PI);
		float f1 = 0.2F * MathHelper.sin(MathHelper.sqrt(swingProgress) * ((float) Math.PI * 2F));
		float f2 = -0.2F * MathHelper.sin(swingProgress * (float) Math.PI);
		int i = flag1 ? 1 : -1;
		GlStateManager.translate(i * f, f1, f2);
		transformSideFirstPerson(enumhandside, equipProgress);
		transformFirstPerson(enumhandside, swingProgress);
		RenderCodex.INSTANCE.doRender(enumhandside, stack);
		GlStateManager.popMatrix();
	}

private static void transformFirstPerson(EnumHandSide p_187453_1_, float p_187453_2_) {
		int i = p_187453_1_ == EnumHandSide.RIGHT ? 1 : -1;
		// Botania - added
		GlStateManager.translate(p_187453_1_ == EnumHandSide.RIGHT ? 0.2F : 0.52F, -0.125F, p_187453_1_ == EnumHandSide.RIGHT ? 0.6F : 0.25F);
		GlStateManager.rotate(p_187453_1_ == EnumHandSide.RIGHT ? 60F : 120F, 0F, 1F, 0F);
		GlStateManager.rotate(30F, 0F, 0F, -1F);
		// End add
		float f = MathHelper.sin(p_187453_2_ * p_187453_2_ * (float) Math.PI);
		GlStateManager.rotate(i * (45.0F + f * -20.0F), 0.0F, 1.0F, 0.0F);
		float f1 = MathHelper.sin(MathHelper.sqrt(p_187453_2_) * (float) Math.PI);
		GlStateManager.rotate(i * f1 * -20.0F, 0.0F, 0.0F, 1.0F);
		GlStateManager.rotate(f1 * -80.0F, 1.0F, 0.0F, 0.0F);
		GlStateManager.rotate(i * -45.0F, 0.0F, 1.0F, 0.0F);
	}

private void doRender(EnumHandSide side, ItemStack stack) {
		Minecraft mc = Minecraft.getMinecraft();

		boolean isGuiOpen = mc.currentScreen instanceof GuiBook;
		boolean rightHand = side == EnumHandSide.RIGHT;
		boolean hasSpell = NBTHelper.getBoolean(stack, "has_spell", false);

		final String openingTagRight = "openingCooldownRight";
		final String openingTagLeft = "openingCooldownLeft";

		final String openingTag = rightHand ? openingTagRight : openingTagLeft;
		if (isGuiOpen || hasSpell) {
			if (!animatingFields.contains(openingTag)) {
				animatingFields.add(openingTag);
				BasicAnimation<RenderCodex> anim = new BasicAnimation<>(INSTANCE, openingTag);
				anim.setTo(10);
				anim.setDuration(20);
				anim.setEasing(Easing.easeOutCubic);
				anim.setCompletion(() -> {
					animatingFields.remove(openingTag);
				});
				animator.add(anim);
			}

		} else {
			if (!animatingFields.contains(openingTag)) {
				animatingFields.add(openingTag);
				BasicAnimation<RenderCodex> anim = new BasicAnimation<>(INSTANCE, openingTag);
				anim.setTo(0);
				anim.setDuration(20);
				anim.setEasing(Easing.easeOutCubic);
				anim.setCompletion(() -> {
					animatingFields.remove(openingTag);
				});
				animator.add(anim);
			}
		}

		animateIdle("idleXRight");
		animateIdle("idleYRight");
		animateIdle("idleZRight");
		animateIdle("idleXLeft");
		animateIdle("idleYLeft");
		animateIdle("idleZLeft");

		GlStateManager.pushMatrix();
		GlStateManager.color(1F, 1F, 1F);

		double flip = rightHand ? 1 : -1;
		float openingCooldown = rightHand ? openingCooldownRight : openingCooldownLeft;
		float idleX = rightHand ? idleXRight : idleXLeft;
		float idleY = rightHand ? idleYRight : idleYLeft;
		float idleZ = rightHand ? idleZRight : idleZLeft;

		// X axis is Z axis
		// Z axis is X axis
		// Everything is reversed
		GlStateManager.translate(
				0.3F + 0.02F * openingCooldown + (openingCooldown / 50.0) + ((10 - openingCooldown) / 50.0F) + (rightHand ? -0.1F : 0),
				0.475F + 0.01F * openingCooldown + (!rightHand ? 0.02F : 0) + ((10 - openingCooldown) / 100.0F),
				-0.2F - (rightHand ? 0.035F : 0.01F) * openingCooldown + (flip * openingCooldown / 50.0) + (!rightHand ? ((openingCooldown / 10.0F) * 0.08F - 0.03F) : 0));

		// 87.5 rotates from facing the book's spine to the cover facing the player
		// Rotates around book spine
		GlStateManager.rotate((rightHand ? 87.5F : ((openingCooldown / 10.0F) * -20 + 90)) + openingCooldown * (rightHand ? 8 : 12) + (idleY * 5f), 0F, 1F, 0F);

		// Rotates around the CENTER of the book's spine horizontally.
		// IE: Transverse section of the book.
		// Point ur hand horizontally and slide it horizontally.
		// Will rotate the book backwards as it opens, adding a 3d effect
		GlStateManager.rotate(idleZ * 5f, 0F, 0F, 1F);

		mc.renderEngine.bindTexture(texture);
		model.render(null, 0F, 0F, pageFlipCooldownRight, openingCooldown / 12F, 0F, 1F / 16F);

		FontRenderer font = Minecraft.getMinecraft().fontRenderer;
		boolean prevFlag = font.getUnicodeFlag();

		GlStateManager.rotate(180F, 0F, 0F, 1F);

		if (openingCooldown < 3) {
			font.setUnicodeFlag(false);

			GlStateManager.pushMatrix();

			GlStateManager.disableLighting();

			GlStateManager.translate(-0.30F, -0.24F, -0.07F);
			GlStateManager.scale(0.003F, 0.003F, -0.003F);
			GlStateManager.translate(-2, 0, 0); // Yes. I'm nudging it. This is how horrible this gl state is.

			// Below logo
			GlStateManager.translate(0, 70 - font.FONT_HEIGHT, 0);

			String[] title = LibrarianLib.PROXY.translate("wizardry.book.title").split(" ");
			for (String aTitle : title) {
				GlStateManager.translate(0, font.FONT_HEIGHT, 0);

				String titleText = font.trimStringToWidth(aTitle, 80);
				int width = font.getStringWidth(titleText);
				int max = 80;
				double x = max / 2.0 - width / 2.0;
				GlStateManager.translate(x, 0, 0);
				font.drawString(titleText, 0, 0, 0x00FFFF);
				GlStateManager.translate(-x, 0, 0);
			}

			GlStateManager.translate(0, font.FONT_HEIGHT, 0);

			String subtitle = font.trimStringToWidth(LibrarianLib.PROXY.translate("wizardry.book.subtitle"), 80);
			double scale = 2.6;
			GlStateManager.translate((80F - font.getStringWidth(subtitle)) * scale, 0F, 0F);
			GlStateManager.scale(0.6F, 0.6F, 0.6F);
			font.drawString(TextFormatting.ITALIC + subtitle, 0, 0, 0x00FFFF);

			GlStateManager.enableLighting();
			GlStateManager.popMatrix();
		}

		// In both pages: 0,0 is the top left corner
		// You're welcome.
		if (hasSpell && openingCooldown > 6) {
			font.setUnicodeFlag(true);

			// LEFT PAGE
			{
				GlStateManager.pushMatrix();

				GlStateManager.rotate(60, 0, 1, 0);
				GlStateManager.translate(0, 0.1, 0);

				GlStateManager.translate(-0.30F, -0.24F, -0.07F);
				GlStateManager.scale(0.003F, 0.003F, -0.003F);

				GlStateManager.translate(-10, -30, -5);

				// Draw tooltip above page here
				if (rightHand) {
					GlStateManager.pushMatrix();
					GlStateManager.translate(-30, -25, -30);
					drawTooltip(font, LibrarianLib.PROXY.translate("wizardry.book.shift_scroll"),
							LibrarianLib.PROXY.translate("wizardry.book.open_recipe_tab"));
					GlStateManager.popMatrix();
				}

				String[] lines = getSpellStructureLines(stack);
				for (int i = 0; i < lines.length; i++)
					font.drawString(lines[i], 0, i * font.FONT_HEIGHT, 0x00);

				GlStateManager.popMatrix();
			}
			// RIGHT PAGE
			{
				GlStateManager.pushMatrix();

				GlStateManager.rotate(120, 0, 1, 0);
				GlStateManager.translate(0, 0.1, 0);

				GlStateManager.translate(-0.30F, -0.24F, -0.07F);
				GlStateManager.scale(0.003F, 0.003F, -0.003F);

				GlStateManager.translate(120, -25, 0);

				// Translate a little extra bit to fit the recipe cozily
				GlStateManager.translate(-5, -5, 0);

				// Draw tooltip above page here
				if (!rightHand)
					drawTooltip(font, LibrarianLib.PROXY.translate("wizardry.book.shift_scroll"),
							LibrarianLib.PROXY.translate("wizardry.book.open_recipe_tab"));

				List<ItemStack> inventory = getSpellInventory(stack);
				int currentPage = NBTHelper.getInt(stack, "page", 0);

				int row = 0;
				int column = 0;
				int pageNb = 0;
				for (int i = 0; i < inventory.size(); i++) {
					ItemStack recipeStack = inventory.get(i);
					if (recipeStack.isEmpty()) continue;

					if (pageNb >= currentPage) {

						GlStateManager.pushMatrix();
						GlStateManager.translate(column * 32, row * 16, -150);

						renderItemStack(recipeStack);

						GlStateManager.popMatrix();

						if (i != inventory.size() - 1 && column < 3) {
							GlStateManager.pushMatrix();
							GlStateManager.translate(32 + column * 32, row * 16 + 13, 0);

							GlStateManager.rotate(180, 0, 0, 1);
							GlStateManager.color(0, 1f, 1f, 1f);
							GlStateManager.disableLighting();

							arrowSprite.bind();
							arrowSprite.draw(0, 0, 0, 16, 8);

							GlStateManager.enableLighting();

							GlStateManager.popMatrix();
						}

					}

					if (++column >= 3) {
						column = 0;
						row++;
					}

					if (row >= 9) {
						row = 0;
						pageNb++;

						if (pageNb > currentPage) break;
					}

				}

				GlStateManager.popMatrix();
			}
		}

		font.setUnicodeFlag(prevFlag);
		GlStateManager.popMatrix();
	}

public void drawTooltip(FontRenderer font, String... text) {
		GlStateManager.pushMatrix();

		GlStateManager.translate(0, -25, 0);

		//GlStateManager.disableRescaleNormal();
		//RenderHelper.disableStandardItemLighting();
		GlStateManager.disableLighting();
		GlStateManager.disableDepth();

		boolean previousUnicode = font.getUnicodeFlag();
		font.setUnicodeFlag(false);

		int backgroundColor = 0xF0100010;
		//Color color = Color.decode("0xF0100010");
		//color = new Color(color.getRed(), color.getGreen(), color.getBlue(), (int) (tooltipCooldown / 40.0 * 255.0));
		//backgroundColor = color.getRGB();

		int longestWidth = 0;
		for (String string : text) {
			int width = font.getStringWidth(string);
			if (width > longestWidth) longestWidth = width;
		}

		int tooltipTextWidth = longestWidth;
		int tooltipHeight = 8 * text.length;
		GuiUtils.drawGradientRect(0, 0 - 3, 0 - 4, tooltipTextWidth + 3, 0 - 3, backgroundColor, backgroundColor);
		GuiUtils.drawGradientRect(0, 0 - 3, tooltipHeight + 3, tooltipTextWidth + 3, tooltipHeight + 4, backgroundColor, backgroundColor);
		GuiUtils.drawGradientRect(0, 0 - 3, 0 - 3, tooltipTextWidth + 3, tooltipHeight + 3, backgroundColor, backgroundColor);
		GuiUtils.drawGradientRect(0, 0 - 4, 0 - 3, 0 - 3, tooltipHeight + 3, backgroundColor, backgroundColor);
		GuiUtils.drawGradientRect(0, tooltipTextWidth + 3, 0 - 3, tooltipTextWidth + 4, tooltipHeight + 3, backgroundColor, backgroundColor);
		final int borderColorStart = 0x505000FF;
		final int borderColorEnd = (borderColorStart & 0xFEFEFE) >> 1 | borderColorStart & 0xFF000000;
		GuiUtils.drawGradientRect(0, 0 - 3, 0 - 3 + 1, 0 - 3 + 1, tooltipHeight + 3 - 1, borderColorStart, borderColorEnd);
		GuiUtils.drawGradientRect(0, tooltipTextWidth + 2, 0 - 3 + 1, tooltipTextWidth + 3, tooltipHeight + 3 - 1, borderColorStart, borderColorEnd);
		GuiUtils.drawGradientRect(0, 0 - 3, 0 - 3, tooltipTextWidth + 3, 0 - 3 + 1, borderColorStart, borderColorStart);
		GuiUtils.drawGradientRect(0, 0 - 3, tooltipHeight + 2, tooltipTextWidth + 3, tooltipHeight + 3, borderColorEnd, borderColorEnd);

		for (int i = 0; i < text.length; i++) {
			String string = text[i];
			font.drawStringWithShadow(string, 0, i * 8, 0xFFD700);
		}

		font.setUnicodeFlag(previousUnicode);

		GlStateManager.enableDepth();
		GlStateManager.enableAlpha();
		GlStateManager.enableBlend();
		GlStateManager.disableRescaleNormal();
		GlStateManager.enableTexture2D();
		GlStateManager.tryBlendFuncSeparate(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA, GlStateManager.SourceFactor.ONE, GlStateManager.DestFactor.ZERO);
		GlStateManager.shadeModel(GL11.GL_SMOOTH);
		GlStateManager.enableLighting();

		GlStateManager.popMatrix();
	}

public void renderItemStack(ItemStack stack) {
		GlStateManager.enableAlpha();
		GlStateManager.enableBlend();
		GlStateManager.enableRescaleNormal();

		GlStateManager.pushMatrix();

		RenderItem itemRender = Minecraft.getMinecraft().getRenderItem();
		itemRender.renderItemAndEffectIntoGUI(stack, 0, 0);

		GlStateManager.translate(0, 0, 150);

		FontRenderer font = stack.getItem().getFontRenderer(stack);
		if (font == null) font = Minecraft.getMinecraft().fontRenderer;

		if (font != null && stack.getCount() != 1) {
			GlStateManager.translate(0, 0, 5);
			GlStateManager.disableLighting();
			GlStateManager.disableBlend();
			font.drawStringWithShadow(stack.getCount() + "",
					17F - font.getStringWidth(stack.getCount() + ""),
					9F,
					0xFFFFFF);
			GlStateManager.enableDepth();
			GlStateManager.enableBlend();
			GlStateManager.translate(0, 0, -5);
		}

		if (stack.getItem().showDurabilityBar(stack)) {
			GlStateManager.disableLighting();
			GlStateManager.disableTexture2D();
			GlStateManager.disableAlpha();
			GlStateManager.disableBlend();
			Tessellator tessellator = Tessellator.getInstance();
			BufferBuilder bufferbuilder = tessellator.getBuffer();
			double health = stack.getItem().getDurabilityForDisplay(stack);
			int rgbfordisplay = stack.getItem().getRGBDurabilityForDisplay(stack);
			int i = Math.round(13.0F - (float) health * 13.0F);
			draw(bufferbuilder, 2, 13, 13, 2, 0, 0, 0, 255);
			draw(bufferbuilder, 2, 13, i, 1, rgbfordisplay >> 16 & 255, rgbfordisplay >> 8 & 255, rgbfordisplay & 255, 255);
			GlStateManager.enableBlend();
			GlStateManager.enableAlpha();
			GlStateManager.enableTexture2D();
			GlStateManager.enableLighting();
		}


		EntityPlayerSP entityplayersp = Minecraft.getMinecraft().player;
		float f3 = entityplayersp == null ? 0.0F : entityplayersp.getCooldownTracker().getCooldown(stack.getItem(), Minecraft.getMinecraft().getRenderPartialTicks());

		if (f3 > 0.0F) {
			GlStateManager.disableLighting();
			GlStateManager.disableTexture2D();
			Tessellator tessellator1 = Tessellator.getInstance();
			BufferBuilder bufferbuilder1 = tessellator1.getBuffer();
			this.draw(bufferbuilder1, 0, MathHelper.floor(16.0F * (1.0F - f3)), 16, MathHelper.ceil(16.0F * f3), 255, 255, 255, 127);
			GlStateManager.enableTexture2D();
			GlStateManager.enableLighting();
		}

		GlStateManager.popMatrix();

		GlStateManager.enableLighting();
		GlStateManager.enableAlpha();
		GlStateManager.enableBlend();
		GlStateManager.disableRescaleNormal();
	}

@Override
	public void doRenderLayer(@Nonnull EntityLivingBase entitylivingbaseIn, float limbSwing, float limbSwingAmount, float partialTicks, float ageInTicks, float netHeadYaw, float headPitch, float scale) {
		if (BaublesSupport.getItem(entitylivingbaseIn, ModItems.FAKE_HALO, ModItems.CREATIVE_HALO, ModItems.REAL_HALO).isEmpty())
			return;
		ItemStack halo = BaublesSupport.getItem(entitylivingbaseIn, ModItems.FAKE_HALO, ModItems.CREATIVE_HALO, ModItems.REAL_HALO);

		// TODO: Remove these once we have a cosmetics system
		if (halo.getItem() == ModItems.FAKE_HALO && !ClientConfigValues.renderCrudeHalo) return;
		if (halo.getItem() == ModItems.REAL_HALO && !ClientConfigValues.renderRealHalo) return;
		if (halo.getItem() == ModItems.CREATIVE_HALO && !ClientConfigValues.renderCreativeHalo) return;

		if (halo.getItem() == ModItems.FAKE_HALO) {
			GlStateManager.pushMatrix();

			if (entitylivingbaseIn.isSneaking()) GlStateManager.translate(0.0f, 0.2f, 0.0f);

			boolean flag = entitylivingbaseIn instanceof EntityVillager || entitylivingbaseIn instanceof EntityZombieVillager;

			if (entitylivingbaseIn.isChild() && !(entitylivingbaseIn instanceof EntityVillager)) {
				GlStateManager.translate(0.0f, 0.5f * scale, 0.0f);
				GlStateManager.scale(0.7f, 0.7f, 0.7f);
				GlStateManager.translate(0.0f, 16.0f * scale, 0.0f);
			}

			if (flag) GlStateManager.translate(0.0f, 0.1875f, 0.0f);

			this.modelRenderer.postRender(0.0625f);
			GlStateManager.color(1.0f, 1.0f, 1.0f, 1.0f);

			GlStateManager.translate(0.0f, -0.25f, 0.0f);
			GlStateManager.rotate(180.0f, 0.0f, 1.0f, 0.0f);
			GlStateManager.scale(0.625f, -0.625f, -0.625f);

			Minecraft.getMinecraft().getItemRenderer().renderItem(entitylivingbaseIn, halo, ItemCameraTransforms.TransformType.HEAD);

			GlStateManager.popMatrix();
		} else {
		    Entity entity = entitylivingbaseIn;

			Vec3d entityOrigin = entity.getPositionVector().add(0, entity.height + (entity.isSneaking() ? 0.2 : 0.4), 0);
			InterpCircle circle = new InterpCircle(Vec3d.ZERO, new Vec3d(0, 1, 0), 0.3f, RandUtil.nextFloat(), RandUtil.nextFloat());

			for (Vec3d origin : circle.list(5)) {
				RenderFunction baseRenderFunction = new RenderFunctionBasic(new ResourceLocation(Wizardry.MODID, NBTConstants.MISC.SPARKLE_BLURRED), false);
				ParticleBuilder glitter = new ParticleBuilder(3);
				glitter.setAlphaFunction(new InterpFloatInOut(1f, 1f));
				glitter.disableMotionCalculation();
				glitter.disableRandom();

				ParticleSpawner.spawn(glitter, entity.world, new StaticInterp<>(entityOrigin.add(origin)), 1, 0, (aFloat, particleBuilder) -> {
					if (RandUtil.nextInt(10) != 0)
						if (halo.getItem() == ModItems.CREATIVE_HALO)
							glitter.setColor(ColorUtils.changeColorAlpha(new Color(0xd600d2), RandUtil.nextInt(60, 100)));
						else glitter.setColor(ColorUtils.changeColorAlpha(Color.YELLOW, RandUtil.nextInt(60, 100)));
					else glitter.setColor(ColorUtils.changeColorAlpha(Color.WHITE, RandUtil.nextInt(60, 100)));
					glitter.setAlphaFunction(new InterpFloatInOut(0.5f, 0.5f));
					glitter.setLifetime(10);
					glitter.setScaleFunction(new InterpFloatInOut(0.5f, 0.5f));

					glitter.setRenderFunction(
							new RenderFunction(ParticleRenderManager.getLAYER_BLOCK_MAP_ADDITIVE()) {
								@Override
								public void render(float i,
												   @NotNull ParticleBase particle, @NotNull Color color, float alpha,
												   @NotNull BufferBuilder worldRendererIn, @Nullable Entity entityIn,
												   float partialTicks, float rotationX, float rotationZ,
												   float rotationYZ, float rotationXY, float rotationXZ,
												   float scale, float rotation, @NotNull Vec3d pos,
												   int skyLight, int blockLight) {

									Vec3d interpPos =
											new Vec3d(
//													ClientTickHandler.interpPartialTicks(entity.prevPosX, entity.posX) - Particle.interpPosX,
//													ClientTickHandler.interpPartialTicks(entity.prevPosY, entity.posY) - Particle.interpPosY,
//													ClientTickHandler.interpPartialTicks(entity.prevPosZ, entity.posZ) - Particle.interpPosZ
													entity.prevPosX + (entity.posX - entity.prevPosX) * ClientTickHandler.getPartialTicks() - Particle.interpPosX,
													entity.prevPosY + (entity.posY - entity.prevPosY) * ClientTickHandler.getPartialTicks() - Particle.interpPosY,
													entity.prevPosZ + (entity.posZ - entity.prevPosZ) * ClientTickHandler.getPartialTicks() - Particle.interpPosZ
											);
									Vec3d newPos = interpPos
											.add(0, entity.height + (entity.isSneaking() ? 0.2 : 0.4), 0)
											.add(origin);

									baseRenderFunction.render(i,
											particle, color, alpha,
											worldRendererIn, entityIn,
											partialTicks, rotationX, rotationZ,
											rotationYZ, rotationXY, rotationXZ,
											scale, rotation, newPos,
											skyLight, blockLight);
								}
							}
					);
				});
			}
		}
	}

