                    if (!s.startsWith("#")) {
                        return false;
                    }
                    if (s.length() > 7) {
                        return false;
                    }
                    if (s.length() < 7) {
                        return true;
                    }
                    try {
                        ParticleColor.fromHex(s);
                        return true;
                    } catch (Exception e) {
