public List<BaseProperty<?>> getProperties(ParticleTypeProperty forProp) {
            List<BaseProperty<?>> properties = new ArrayList<>();
            PropMap subPropMap = forProp.subProperties;
            if (acceptsColor) {
                ColorProperty colorProperty = subPropMap.createIfMissing(new ColorProperty(ParticleColor.defaultParticleColor(), true));
                colorProperty.isLegacyRGB = useLegacyRGB;
                properties.add(colorProperty);
            }
            if (supportsSound) {
                properties.add(subPropMap.createIfMissing(new SoundProperty(new ConfiguredSpellSound(SoundRegistry.POINTED_DRIPSTONE_WATER))));
            }

            return properties;
        }

@SubscribeEvent
    public static void renderSky(RenderLevelStageEvent event) {
        if (event.getStage().equals(RenderLevelStageEvent.Stage.AFTER_SKY)) {
            if (ArsNouveau.optifineLoaded || Config.DISABLE_SKY_SHADER.get()) {
                return;
            }
            Minecraft minecraft = Minecraft.getInstance();
            if (skyRenderTarget == null) {
                Window window = minecraft.getWindow();
                setupRenderTarget(window.getWidth(), window.getHeight());
            }
            PoseStack poseStack = event.getPoseStack();
            GameRenderer gameRenderer = minecraft.gameRenderer;
            LevelRenderer levelRenderer = minecraft.levelRenderer;
            Camera camera = gameRenderer.getMainCamera();
            Vec3 cameraPosition = camera.getPosition();
            Matrix4f projectionMatrix = event.getProjectionMatrix();

            float partialTick = event.getPartialTick().getGameTimeDeltaTicks();
            boolean isFoggy = minecraft.level.effects().isFoggyAt(Mth.floor(cameraPosition.x), Mth.floor(cameraPosition.y)) || minecraft.gui.getBossOverlay().shouldCreateWorldFog();

            //setting the render target to our sky target
            skyRenderTarget.bindWrite(true);
            //clearing what was rendered the previous frame
            RenderSystem.clear(16640, Minecraft.ON_OSX);

            FogRenderer.setupColor(camera, partialTick, minecraft.level, minecraft.options.getEffectiveRenderDistance(), gameRenderer.getDarkenWorldAmount(partialTick));
            FogRenderer.levelFogColor();
            //rendering the actual sky
            RenderSystem.setShader(GameRenderer::getPositionShader);
            levelRenderer.renderSky(event.getModelViewMatrix(), projectionMatrix, partialTick, camera, isFoggy, () -> {
                FogRenderer.setupFog(camera, FogRenderer.FogMode.FOG_SKY, gameRenderer.getRenderDistance(), isFoggy, partialTick);
            });

            Matrix4fStack modelViewStack = RenderSystem.getModelViewStack();
            modelViewStack.pushMatrix();
            modelViewStack.mul(poseStack.last().pose());
            RenderSystem.applyModelViewMatrix();

            //rendering the clouds
            if (minecraft.options.getCloudsType() != CloudStatus.OFF) {
                RenderSystem.setShaderColor(1F, 1F, 1F, 1F);
                levelRenderer.renderClouds(poseStack, event.getModelViewMatrix(), projectionMatrix, partialTick, cameraPosition.x, cameraPosition.y, cameraPosition.z);
            }

            //the rain!
            RenderSystem.depthMask(false);
            levelRenderer.renderSnowAndRain(gameRenderer.lightTexture(), partialTick, cameraPosition.x, cameraPosition.y, cameraPosition.z);
            RenderSystem.depthMask(true);

            modelViewStack.popMatrix();
            RenderSystem.applyModelViewMatrix();
            minecraft.getMainRenderTarget().bindWrite(true);
        }
    }

@Override
    public void render(GuiGraphics graphics, int mouseX, int mouseY, float partialTicks) {
        PoseStack st = graphics.pose();
        boolean flag = GLFW.glfwGetMouseButton(Minecraft.getInstance().getWindow().getWindow(), GLFW.GLFW_MOUSE_BUTTON_LEFT) != GLFW.GLFW_RELEASE;
        int i = this.leftPos;
        int j = this.topPos;
        int k = i + 187;
        int l = j + 18;
        int i1 = k + 14;
        int j1 = l + rowCount * 18;

        if (hasShiftDown()) {
            if (!noSort) {
                List<StoredItemStack> list = this.itemsSorted;
                Object2IntMap<StoredItemStack> map = new Object2IntOpenHashMap<>();
                map.defaultReturnValue(Integer.MAX_VALUE);
                for (int m = 0; m < list.size(); m++) {
                    map.put(list.get(m), m);
                }
                sortComp = Comparator.comparing(map::getInt);
                noSort = true;
            }
        } else if (noSort) {
            sortComp = null;
            noSort = false;
            refreshItemList = true;
            this.itemsUnsorted = new ArrayList<>(menu.itemList);
        }

        if (!this.wasClicking && flag && mouseX >= k && mouseY >= l && mouseX < i1 && mouseY < j1) {
            this.isScrolling = this.needsScrollBars();
        }

        if (!flag) {
            this.isScrolling = false;
        }
        this.wasClicking = flag;

        if (this.isScrolling) {
            this.currentScroll = (mouseY - l - 7.5F) / (j1 - l - 15.0F);
            this.currentScroll = Mth.clamp(this.currentScroll, 0.0F, 1.0F);
            this.scrollTo(this.currentScroll);
        }
        super.render(graphics, mouseX, mouseY, partialTicks);

        RenderSystem.setShader(GameRenderer::getPositionTexShader);
        RenderSystem.setShaderColor(1.0F, 1.0F, 1.0F, 1.0F);
        i = k;
        j = l;
        k = j1;
        graphics.blit(scrollBall, i, j + 3 + (int) ((k - j - 14) * this.currentScroll), 0, 0, 12, 12, 12, 12);


        if (this.menu.getCarried().isEmpty() && slotIDUnderMouse != -1) {
            SlotStorage slot = getMenu().storageSlotList.get(slotIDUnderMouse);
            if (slot.stack() != null) {
                if (slot.stack().getQuantity() > 9999) {
                    ClientInfo.setTooltip(Component.translatable("tooltip.ars_nouveau.amount", slot.stack().getQuantity()));
                }
                graphics.renderTooltip(font, slot.stack().getActualStack(), mouseX, mouseY);
                ClientInfo.setTooltip();
            }
        } else
            this.renderTooltip(graphics, mouseX, mouseY);

        if (buttonSortingType.isHovered()) {
            graphics.renderTooltip(font, Component.translatable("tooltip.ars_nouveau.sorting_" + buttonSortingType.state), mouseX, mouseY);
        }
        if (buttonSearchType.isHovered()) {
            graphics.renderTooltip(font, Component.translatable("tooltip.ars_nouveau.search_" + buttonSearchType.state, IAutoFillTerminal.getHandlerName()), mouseX, mouseY);
        }
        if (buttonDirection.isHovered()) {
            graphics.renderTooltip(font, Component.translatable("tooltip.ars_nouveau.direction_" + buttonDirection.state, IAutoFillTerminal.getHandlerName()), mouseX, mouseY);
        }
        for (StorageTabButton tabButton : tabButtons) {
            if (tabButton.isHovered() && tabButton.isAll) {
                graphics.renderTooltip(font, Component.translatable("tooltip.ars_nouveau.master_tab"), mouseX, mouseY);
            } else if (tabButton.isHovered() && tabButton.highlightText != null) {
                graphics.renderTooltip(font, Component.literal(tabButton.highlightText), mouseX, mouseY);
            }
        }
    }

