        } else if (bone.getName().equalsIgnoreCase("50")) {
            bone.setHidden(!(amountLeft == 5 || amountLeft == 4));
        } else if (bone.getName().equalsIgnoreCase("25")) {
            bone.setHidden(!(amountLeft == 3 || amountLeft == 2));
