public void updateCulling(MirrorWeaveTile tileEntityIn) {
        boolean disableEntireRender = true;
        tileEntityIn.renderInvalid = false;
        for (Direction direction : DIRECTIONS) {
            BlockPos blockingPos = tileEntityIn.getBlockPos().relative(direction);
            BlockState blockingState = tileEntityIn.getLevel().getBlockState(blockingPos);
            tileEntityIn.setRenderDirection(direction, false);
            if (tileEntityIn.getLevel().getBlockEntity(blockingPos) instanceof MirrorWeaveTile neighborTile) {
                blockingState = neighborTile.getStateForCulling();
            }
            var blockingShape = blockingState.getOcclusionShape(tileEntityIn.getLevel(), blockingPos);
            if (!tileEntityIn.shouldRenderFace(blockingState, tileEntityIn.getLevel(), tileEntityIn.getBlockPos(), direction, blockingPos)) {
                continue;
            }
            if (!blockingState.canOcclude()) {
                tileEntityIn.setRenderDirection(direction, true);
                disableEntireRender = false;
                continue;
            }

            if (blockingState.canOcclude() && !Shapes.blockOccudes(Shapes.block(), blockingShape, direction)) {
                tileEntityIn.setRenderDirection(direction, true);
                disableEntireRender = false;
                continue;
            }

        }
        tileEntityIn.disableRender = disableEntireRender;
    }

public void tesselateWithoutAO(
            MirrorWeaveTile tile,
            ModelBlockRenderer renderer,
            BlockAndTintGetter level,
            BakedModel model,
            BlockState state,
            BlockPos pos,
            PoseStack poseStack,
            VertexConsumer consumer,
            boolean checkSides,
            RandomSource random,
            long seed,
            int packedOverlay,
            net.neoforged.neoforge.client.model.data.ModelData modelData,
            net.minecraft.client.renderer.RenderType renderType
    ) {
        BitSet bitset = new BitSet(3);
        BlockPos.MutableBlockPos blockpos$mutableblockpos = pos.mutable();

        for (Direction direction : DIRECTIONS) {
            if (checkSides && !tile.shouldRenderDirection(direction)) {
                continue;
            }
            random.setSeed(seed);
            List<BakedQuad> list = model.getQuads(state, direction, random, modelData, renderType);
            if (!list.isEmpty()) {
                blockpos$mutableblockpos.setWithOffset(pos, direction);
                int i = LevelRenderer.getLightColor(level, state, blockpos$mutableblockpos);
                renderModelFaceFlat(renderer, level, state, pos, i, packedOverlay, false, poseStack, consumer, list, bitset);
            }
        }

        random.setSeed(seed);
        List<BakedQuad> list1 = model.getQuads(state, null, random, modelData, renderType);
        if (!list1.isEmpty()) {
            renderModelFaceFlat(renderer, level, state, pos, -1, packedOverlay, true, poseStack, consumer, list1, bitset);
        }
    }

@Override
    public void render(MobJarTile pBlockEntity, float pPartialTick, PoseStack pPoseStack, MultiBufferSource pBufferSource, int pPackedLight, int pPackedOverlay) {
        Entity entity = pBlockEntity.getEntity();
        if (entity == null)
            return;
        float f = 0.53125F;
        float f1 = Math.max(entity.getBbWidth(), entity.getBbHeight());

        if ((double) f1 > 1.0d) {
            f /= f1 * 1.0;
        }
        if (entity instanceof LightningBolt bolt) {
            if (bolt.level.getGameTime() % 20 == 0)
                bolt.seed = ClientInfo.ticksInGame;
            f = 0.0075f;
        }
        AtomicReference<Vec3> adjustedScale = new AtomicReference<>(new Vec3(0, 0, 0));
        AtomicReference<Vec3> adjustedTranslation = new AtomicReference<>(new Vec3(0, 0, 0));
        AtomicReference<Boolean> shouldParticlaTick = new AtomicReference<>(false);
        JarBehaviorRegistry.forEach(entity, jarBehavior -> {
            Vec3 customScale = jarBehavior.scaleOffset(pBlockEntity);
            adjustedScale.set(adjustedScale.get().add(customScale));
            adjustedTranslation.set(adjustedTranslation.get().add(jarBehavior.translate(pBlockEntity)));
            if (jarBehavior.shouldUsePartialTicks(pBlockEntity))
                shouldParticlaTick.set(true);
        });

        Vec3 scale = new Vec3(f, f, f).multiply(adjustedScale.get().add(1, 1, 1));
        Vec3 translate = new Vec3(0.5, 0, 0.5).add(adjustedTranslation.get());
        pPoseStack.translate(translate.x, translate.y, translate.z);
        pPoseStack.scale((float) scale.x, (float) scale.y, (float) scale.z);

        Direction direction = pBlockEntity.getBlockState().getValue(MobJar.FACING);
        if (direction == Direction.EAST) {
            pPoseStack.mulPose(Axis.ZP.rotationDegrees(90.0F));
        } else if (direction == Direction.WEST) {
            pPoseStack.mulPose(Axis.ZP.rotationDegrees(-90.0F));
        } else if (direction == Direction.NORTH) {
            pPoseStack.mulPose(Axis.XP.rotationDegrees(90.0F));
        } else if (direction == Direction.SOUTH) {
            pPoseStack.mulPose(Axis.XP.rotationDegrees(-90.0F));
        } else if (direction == Direction.DOWN) {
            pPoseStack.translate(0, entity.getBbHeight() + 0.75, 0);
        }
        pPoseStack.mulPose(pBlockEntity.getBlockState().getValue(MobJar.FACING).getRotation());
        entity.setDeltaMovement(0, 0, 0);
        if (shouldParticlaTick.get()) {
            entity.xo = entity.getX();
            entity.yo = entity.getY();
            entity.zo = entity.getZ();
            entity.xRotO = entity.xRot;
            entity.yRotO = entity.yRot;
            if (entity instanceof LivingEntity livingEntity) {
                livingEntity.yBodyRotO = livingEntity.yBodyRot;
                livingEntity.yHeadRotO = livingEntity.yHeadRot;
                // TODO: readd old animation speed for allay?
            }
        } else {
            pPartialTick = 0;
        }

        this.entityRenderer.render(entity, 0.0D, 0.0D, 0.0D, 0.0F, pPartialTick, pPoseStack, pBufferSource, pPackedLight);
        for (Entity entity1 : entity.getPassengers()) {
            this.entityRenderer.render(entity1, 0.0D, 0.0D, 0.0D, 0.0F, pPartialTick, pPoseStack, pBufferSource, pPackedLight);
        }
    }

@Override
    public void render(PlanariumTile blockEntity, float partialTick, PoseStack poseStack, MultiBufferSource bufferSource, int packedLight, int packedOverlay) {
        if (blockEntity.getTemplate() == null)
            return;
        structureRenderData.computeIfAbsent(blockEntity.key, (be) -> {
            var data = new StructureRenderData(blockEntity.getTemplate(), blockEntity.lastUpdated);
            generateRender(data, blockEntity.getLevel(), blockEntity.getBlockPos(), Minecraft.getInstance().gameRenderer.getMainCamera().getPosition());
            return data;
        });

        deferredRenders.add(new WeakReference<>(blockEntity));

        StructureRenderData renderData = structureRenderData.get(blockEntity.key);
        if (renderData != null) {
            BlockEntityRenderDispatcher dispatcher = Minecraft.getInstance().getBlockEntityRenderDispatcher();
            Level originalLevel = dispatcher.level;
            dispatcher.prepare(originalLevel, Minecraft.getInstance().getBlockEntityRenderDispatcher().camera, Minecraft.getInstance().hitResult);


            for (BlockEntity fakeTile : renderData.fakeRenderingWorld.blockEntityMap.values()) {
                BlockPos pos = fakeTile.getBlockPos();
                poseStack.pushPose();
                poseStack.translate(offset, offset, offset);

                poseStack.scale(scale, scale, scale);
                poseStack.translate(pos.getX(), 26 + pos.getY(), pos.getZ());
                BlockEntityRenderer renderer = dispatcher.getRenderer(fakeTile);
                if (fakeTile instanceof PlanariumTile planariumTile) {
                    planariumTile.key = null;
                }
                if (renderer != null) {
