@Override
    public void actuallyRender(PoseStack poseStack, RotatingTurretTile tile, BakedGeoModel model, RenderType renderType, MultiBufferSource bufferSource, VertexConsumer buffer, boolean isReRender, float partialTick, int packedLight, int packedOverlay, int color) {
        super.actuallyRender(poseStack, tile, model, renderType, bufferSource, buffer, isReRender, partialTick, packedLight, packedOverlay, color);
        float rotationX = tile.rotationX;
        float neededRotationX = tile.clientNeededX;
        float rotationY = tile.rotationY;
        float neededRotationY = tile.clientNeededY;
        float step = (0.1f + partialTick);
        if (rotationX != neededRotationX) {
            float diff = neededRotationX - rotationX;
            if (Math.abs(diff) < step) {
                tile.setRotationX(neededRotationX);
            } else {
                tile.setRotationX(rotationX + diff * step);
            }
        }
        if (rotationY != neededRotationY) {
            float diff = neededRotationY - rotationY;
            if (Math.abs(diff) < step) {
                tile.setRotationY(neededRotationY);
            } else {
                tile.setRotationY(rotationY + diff * step);
            }
        }
    }

@Override
    public void actuallyRender(PoseStack poseStack, RuneTile animatable, BakedGeoModel model, RenderType renderType, MultiBufferSource bufferSource, VertexConsumer buffer, boolean isReRender, float partialTick, int packedLight, int packedOverlay, int color) {
        poseStack.pushPose();
        Direction direction = animatable.getBlockState().getValue(BasicSpellTurret.FACING);
//        poseStack.translate(0.5, 0.5, 0);
        switch (direction) {
            case UP -> {
                poseStack.translate(0.5, 0, 0.5);
                poseStack.mulPose(Axis.XP.rotationDegrees(-90));
            }
            case DOWN -> {
                poseStack.translate(0.5, 0.98, 0.5);
                poseStack.mulPose(Axis.XP.rotationDegrees(90));
            }
            case NORTH -> {
                poseStack.translate(0.5, 0.5, 1);
                poseStack.mulPose(Axis.XP.rotationDegrees(90));
                poseStack.mulPose(Axis.ZP.rotationDegrees(180));
                poseStack.mulPose(Axis.YP.rotationDegrees(180));
            }
            case EAST -> {
                poseStack.translate(0, 0.5, 0.5);
                poseStack.mulPose(Axis.ZP.rotationDegrees(-90));
                poseStack.mulPose(Axis.YP.rotationDegrees(180));
            }
            case WEST -> {
                poseStack.translate(1, 0.5, 0.5);
                poseStack.mulPose(Axis.ZP.rotationDegrees(90));
            }
            case SOUTH -> {
                poseStack.translate(0.5, 0.5, 0);
                poseStack.mulPose(Axis.XP.rotationDegrees(-90));
                poseStack.mulPose(Axis.ZP.rotationDegrees(-180));
                poseStack.mulPose(Axis.YP.rotationDegrees(180));
            }
        }
        super.actuallyRender(poseStack, animatable, model, renderType, bufferSource, buffer, isReRender, partialTick, packedLight, packedOverlay, color);
        poseStack.popPose();
    }

public void renderPressedItem(ScribesTile tile, ItemStack itemToRender, PoseStack matrixStack, MultiBufferSource iRenderTypeBuffer, int packedLight, int packedOverlay, float partialTicks) {
        BlockState state = tile.getBlockState();
        Direction direction = state.getValue(ScribesBlock.FACING);

        matrixStack.pushPose();
        matrixStack.translate(0, 1.D, 0);
        Quaternionf quat = Axis.ZP.rotationDegrees(90f);
        Vec3 translationOffset = new Vec3(0, 0, 0);
        if (direction == Direction.WEST) {
            matrixStack.translate(1, 0, 0.5f);
            quat = Axis.ZP.rotationDegrees(90f);

            translationOffset = new Vec3(1, 0, 0.5f);
        }
        if (direction == Direction.EAST) {
            matrixStack.translate(0, 0, 0.5f);
            quat = Axis.ZP.rotationDegrees(270f);
            translationOffset = new Vec3(0, 0, 0.5f);
        }
        if (direction == Direction.SOUTH) {
            matrixStack.translate(0.5f, 0, 0);
            quat = Axis.ZP.rotationDegrees(90f);
            translationOffset = new Vec3(0.5f, 0, 0);
        }
        if (direction == Direction.NORTH) {
            matrixStack.translate(0.5f, 0, 1);
            quat = Axis.ZP.rotationDegrees(90f);
            translationOffset = new Vec3(0.5f, 0, 1);
        }

        float y = state.getValue(ScribesBlock.FACING).getClockWise().toYRot();
        matrixStack.mulPose(Axis.YP.rotationDegrees(-y + 90f));
        matrixStack.mulPose(Axis.XP.rotationDegrees(90f));
        matrixStack.mulPose(Axis.ZP.rotationDegrees(180F));
        matrixStack.mulPose(quat);
        matrixStack.scale(0.6f, 0.6f, 0.3f);
        Minecraft.getInstance().getItemRenderer().renderStatic(itemToRender, ItemDisplayContext.FIXED, packedLight, packedOverlay, matrixStack, Minecraft.getInstance().renderBuffers().bufferSource(), tile.getLevel(), (int) tile.getBlockPos().asLong());
        matrixStack.popPose();
        if (tile.recipe != null && !tile.crafting) {
            List<Ingredient> inputs = tile.getRemainingRequired();
            float ticks = (partialTicks + (float) ClientInfo.ticksInGame);
            float angleBetweenEach = 360.0f / inputs.size();
            // How far away from the center should they be.
            Vec3 distanceVec = new Vec3(1, -0.5, 1);
            for (int i = 0; i < inputs.size(); i++) {
                Ingredient ingredient = inputs.get(i);
                ItemStack stack = ingredient.getItems()[(ClientInfo.ticksInGame / 20) % ingredient.getItems().length];
                matrixStack.pushPose();
                matrixStack.translate(0, 2, 0);
                matrixStack.translate(translationOffset.x, translationOffset.y, translationOffset.z);
                matrixStack.scale(0.25f, 0.25f, 0.25f);
                // This spaces them out from each other
                matrixStack.mulPose(Axis.YP.rotationDegrees(ticks + (i * angleBetweenEach)));
                // Controls the distance from the center, also makes them float up and down
                matrixStack.translate(distanceVec.x(), distanceVec.y() + ((i % 2 == 0 ? -i : i) * Mth.sin(ticks / 60) * 0.0625), distanceVec.z());
                // This rotates the individual stacks, with every 2nd stack rotating a different direction
                matrixStack.mulPose((i % 2 == 0 ? Axis.ZP : Axis.XP).rotationDegrees(ticks));
                Minecraft.getInstance().getItemRenderer().renderStatic(stack, ItemDisplayContext.FIXED, packedLight, packedOverlay, matrixStack, Minecraft.getInstance().renderBuffers().bufferSource(), tile.getLevel(), (int) tile.getBlockPos().asLong());
                matrixStack.popPose();

            }
        }
    }

public static void renderOutline(PoseStack poseStack) {
        LocalPlayer player = Minecraft.getInstance().player;
        if (player == null) return;
        ItemStack heldItem = player.getItemInHand(InteractionHand.MAIN_HAND);

        if (!(player.getItemInHand(InteractionHand.MAIN_HAND).getItem() instanceof ICasterTool)) return;

        var caster = SpellCasterRegistry.from(heldItem);
        if (caster == null)
            return;
        Spell selectedSpell = caster.getSpell();

        if (!(selectedSpell.getCastMethod() instanceof MethodPantomime pantomime)) return;
        SpellStats stats = new SpellStats.Builder()
                .setAugments(selectedSpell.getAugments(0, player))
                .addItemsFromEntity(player)
                .build(MethodPantomime.INSTANCE, null, player.level, player, SpellContext.fromEntity(selectedSpell, player, heldItem));
        if (!stats.isSensitive()) {
            return;
        }
        BlockPos pos = pantomime.findPosition(player, stats).getBlockPos();
        poseStack.pushPose();
        Vec3 projectedView = Minecraft.getInstance().gameRenderer.getMainCamera().getPosition();
        poseStack.translate(-projectedView.x, -projectedView.y, -projectedView.z);
        poseStack.translate(pos.getX(), pos.getY(), pos.getZ());

        RenderType lineType = RenderType.lines();
        OutlineBufferSource buffer = Minecraft.getInstance().renderBuffers().outlineBufferSource();
        VertexConsumer lines = buffer.getBuffer(lineType);
        int color = selectedSpell.particleTimeline().get(ParticleTimelineRegistry.PANTOMIME_TIMELINE.get()).onResolvingEffect.particleOptions().colorProp().color().getColor();
        LevelRenderer.renderLineBox(poseStack, lines, 0, 0, 0, 1, 1, 1, FastColor.ARGB32.red(color) / 255F, FastColor.ARGB32.green(color) / 255F, FastColor.ARGB32.blue(color) / 255F, 1);

        poseStack.popPose();
    }

private AnimBlockSummon animateBlock(HitResult rayTraceResult, Vec3 pos, Level world, @NotNull LivingEntity shooter, SpellStats spellStats, SpellContext spellContext, SpellResolver resolver, BlockState state, CompoundTag data) {
        AnimBlockSummon blockSummon = state.getBlock() instanceof AbstractSkullBlock ? new AnimHeadSummon(world, state, data) : new AnimBlockSummon(world, state, data);
        blockSummon.setColor(spellContext.getColors().getColor());
        blockSummon.setPos(pos);
        int ticks = (int) (20 * (GENERIC_INT.get() + EXTEND_TIME.get() * spellStats.getDurationMultiplier()));
        blockSummon.setTicksLeft(ticks);
        blockSummon.setTarget(shooter.getLastHurtMob());
        blockSummon.setAggressive(true);
        blockSummon.setTame(true, false);
        if (shooter instanceof Player player) blockSummon.tame(player);
        summonLivingEntity(rayTraceResult, world, shooter, spellStats, spellContext, resolver, blockSummon);
        return blockSummon;
    }

@Override
    public void onResolve(HitResult rayTraceResult, Level world, @Nullable LivingEntity shooter, SpellStats spellStats, SpellContext spellContext, SpellResolver resolver) {
        if (shooter == null && spellContext.castingTile != null) {
            shooter = ANFakePlayer.getPlayer((ServerLevel) world);
            BlockPos pos = spellContext.castingTile.getBlockPos();
            shooter.setPos(pos.getX(), pos.getY(), pos.getZ());
        }

        if (shooter == null)
            return;
        Vec3 vec = rayTraceResult.getLocation();

        double damage = DAMAGE.get() + AMP_VALUE.get() * spellStats.getAmpMultiplier();
        double targetX = vec.x;
        double targetY = vec.y;
        double targetZ = vec.z;

        double d0 = Math.min(targetY, shooter.getY());
        double d1 = Math.max(targetY, shooter.getY()) + 1.0D;
        float f = (float) Mth.atan2(targetZ - shooter.getZ(), targetX - shooter.getX());
        int accelerate = spellStats.getBuffCount(AugmentAccelerate.INSTANCE); //no decelerate support atm
        double durationModifier = spellStats.getDurationMultiplier();
        // Create fangs in an AOE around the caster
        if (rayTraceResult instanceof EntityHitResult && shooter.equals(((EntityHitResult) rayTraceResult).getEntity())) {
            for (int i = 0; i < 5; ++i) {
                float f1 = f + (float) i * (float) Math.PI * 0.4F;
                int j = (int) ((i + durationModifier) / (1 + accelerate));
                spawnFangs(world, shooter.getX() + (double) Mth.cos(f1) * 1.5D, shooter.getZ() + (double) Mth.sin(f1) * 1.5D, d0, d1, f1, j, shooter, (float) damage);
            }

            for (int k = 0; k < 8; ++k) {
                float f2 = f + (float) k * (float) Math.PI * 2.0F / 8.0F + 1.2566371F;
                int j = (int) ((k + durationModifier) / (1 + accelerate));
                spawnFangs(world, shooter.getX() + (double) Mth.cos(f2) * 2.5D, shooter.getZ() + (double) Mth.sin(f2) * 2.5D, d0, d1, f2, j, shooter, (float) damage);
            }
            return;
        }
        for (int l = 0; l < 16; ++l) {
            double d2 = 1.25D * (double) (l + 1);
            int j = (int) ((l + durationModifier) / (1 + accelerate));
            this.spawnFangs(world, shooter.getX() + (double) Mth.cos(f) * d2, shooter.getZ() + (double) Mth.sin(f) * d2, d0, d1, f, j, shooter, (float) damage);
        }
    }

public @Nullable PotionContents getPotionData(Level world, @NotNull LivingEntity shooter, SpellContext spellContext) {
        PotionContents potionData = null;
        InventoryManager manager = spellContext.getCaster().getInvManager();
        ExtractedStack extractedFlask = manager.extractItem(i -> {
            IPotionProvider provider = PotionProviderRegistry.from(i);
            return provider != null && !provider.isEmpty(i);
        }, 1);
        if (!extractedFlask.isEmpty()) {
            IPotionProvider provider = PotionProviderRegistry.from(extractedFlask.stack);
            potionData = provider.getPotionData(extractedFlask.stack);

            if (extractedFlask.stack.getItem() instanceof PotionFlask potionFlask) {
                potionData = potionFlask.getModifiedPotionContents(potionData);
            }

            provider.consumeUses(extractedFlask.stack, 1, shooter);
            extractedFlask.returnOrDrop(world, shooter.getOnPos());
        } else {
            ExtractedStack potion = manager.extractItem(i -> i.getItem() instanceof PotionItem, 1);
            if (!potion.isEmpty()) {
                ItemStack stack = potion.getStack();
                potionData = stack.get(DataComponents.POTION_CONTENTS);
                if (!(shooter instanceof Player player) || !player.hasInfiniteMaterials()) {
                    stack.shrink(1);
                }
                potion.replaceAndReturnOrDrop(new ItemStack(Items.GLASS_BOTTLE), world, shooter.getOnPos());
            }
        }

        if (potionData == null) {
            BlockEntity jarEntity = spellContext.getCaster().getNearbyBlockEntity(i -> i instanceof PotionJarTile jar && jar.getAmount() > 100);
            if (jarEntity instanceof PotionJarTile jar) {
                potionData = jar.getData();
                jar.remove(100);
            }
        }
        return potionData;
    }

public void knockback(Entity target, @NotNull IWrappedCaster shooter, float strength, boolean fromCaster) {
        if (fromCaster) {
            Vec3 vec3 = shooter.getPosition().subtract(target.position());
            vec3 = vec3.normalize();
            knockback(target, strength, vec3.x, vec3.z);
            return;
        }
        float v = 0;
        if (shooter instanceof TileCaster tc) {
            BlockEntity tile = tc.getTile();
            if (tile instanceof RotatingTurretTile rotatingTurretTile) {
                v = rotatingTurretTile.getRotationY();
            } else if (tile instanceof BasicSpellTurretTile || tile instanceof RuneTile) {
                v = tile.getBlockState().getValue(FACING).toYRot();
            }
        } else if (shooter instanceof LivingCaster lc) v = lc.livingEntity.yRot;
        knockback(target, strength, Mth.sin(v * ((float) Math.PI / 180F)), -Mth.cos(v * ((float) Math.PI / 180F)));
    }

@Override
    public void onResolveEntity(EntityHitResult rayTraceResult, Level world, @NotNull LivingEntity shooter, SpellStats spellStats, SpellContext spellContext, SpellResolver resolver) {
        if (rayTraceResult.getEntity() instanceof ILightable iLightable) {
            iLightable.onLight(rayTraceResult, world, shooter, spellStats, spellContext);
        }

        if (!(rayTraceResult.getEntity() instanceof LivingEntity living))
            return;
        if (!shooter.equals(living) || spellStats.isSensitive()) {
            this.applyConfigPotion(living, MobEffects.GLOWING, spellStats);
            // apply custom color to the entity if sensitive and the effect is successfully applied
            if (living.hasEffect(MobEffects.GLOWING) && spellStats.isSensitive())
                Networking.sendToNearbyClient(world, living, new PacketUpdateGlowColor(living.getId(), spellContext.getColors() instanceof RainbowParticleColor ? -1 : spellContext.getColors().getColor()));
        }
        this.applyConfigPotion(living, MobEffects.NIGHT_VISION, spellStats);
    }

@Override
    public void onResolveBlock(BlockHitResult rayTraceResult, Level world, @NotNull LivingEntity shooter, SpellStats spellStats, SpellContext spellContext, SpellResolver resolver) {
        BlockPos pos = rayTraceResult.getBlockPos().relative(rayTraceResult.getDirection());
        Player player = getPlayer(shooter, (ServerLevel) world);
        if (!BlockUtil.destroyRespectsClaim(player, world, pos))
            return;

        if (world.getBlockEntity(rayTraceResult.getBlockPos()) instanceof ILightable lightable) {
            lightable.onLight(rayTraceResult, world, shooter, spellStats, spellContext);
            return;
        } else if (world.getBlockState(rayTraceResult.getBlockPos()).getBlock() instanceof ILightable lightable) {
            lightable.onLight(rayTraceResult, world, shooter, spellStats, spellContext);
            return;
        } else if (world.getBlockEntity(pos) instanceof SignBlockEntity sign) {
            sign.updateText((a) -> sign.getText(true).setHasGlowingText(true),
                    sign.isFacingFrontText(player)
            );
            world.gameEvent(GameEvent.BLOCK_CHANGE, sign.getBlockPos(), GameEvent.Context.of(player, sign.getBlockState()));
        }

        if (world.getBlockState(pos).canBeReplaced()
                && world.isUnobstructed(BlockRegistry.LIGHT_BLOCK.get().defaultBlockState(), pos, CollisionContext.of(ANFakePlayer.getPlayer((ServerLevel) world)))
                && world.isInWorldBounds(pos)) {
            BlockState lightBlockState = (spellStats.getDurationMultiplier() != 0 ? BlockRegistry.T_LIGHT_BLOCK.get() : BlockRegistry.LIGHT_BLOCK.get()).defaultBlockState().setValue(WATERLOGGED, world.getFluidState(pos).getType() == Fluids.WATER);
            world.setBlockAndUpdate(pos, lightBlockState.setValue(SconceBlock.LIGHT_LEVEL, Math.max(0, Math.min(15, 14 + (int) spellStats.getAmpMultiplier()))));
            if (world.getBlockEntity(pos) instanceof LightTile tile) {
                tile.setTimeline(spellContext.getParticleTimeline(ParticleTimelineRegistry.LIGHT_TIMELINE.get()));
                if (tile instanceof TempLightTile tempLightTile)
                    tempLightTile.lengthModifier = spellStats.getDurationMultiplier();
            }
            world.sendBlockUpdated(pos, world.getBlockState(pos), world.getBlockState(pos), 2);

        }
    }

@Override
    public void onResolveBlock(BlockHitResult rayTraceResult, Level world, @NotNull LivingEntity shooter, SpellStats spellStats, SpellContext spellContext, SpellResolver resolver) {
        ANFakePlayer fakePlayer = ANFakePlayer.getPlayer((ServerLevel) world);
        for (BlockPos pos : SpellUtil.calcAOEBlocks(shooter, rayTraceResult.getBlockPos(), rayTraceResult, spellStats)) {
            pos = rayTraceResult.isInside() ? pos : pos.relative((rayTraceResult).getDirection());
            if (!world.isInWorldBounds(pos))
                continue;
            if (!BlockUtil.destroyRespectsClaim(getPlayer(shooter, (ServerLevel) world), world, pos))
                continue;
            BlockState state = world.getBlockState(pos);
            if (state.canBeReplaced() && world.isUnobstructed(BlockRegistry.MAGE_BLOCK.get().defaultBlockState(), pos, CollisionContext.of(fakePlayer))) {

                world.setBlockAndUpdate(pos, BlockRegistry.MAGE_BLOCK.get().defaultBlockState().setValue(MageBlock.TEMPORARY, !spellStats.hasBuff(AugmentAmplify.INSTANCE)));
                if (world.getBlockEntity(pos) instanceof MageBlockTile tile) {
                    tile.setColor(spellContext.getParticleTimeline(ParticleTimelineRegistry.MAGEBLOCK_TIMELINE.get()).getColor());
                    tile.lengthModifier = spellStats.getDurationMultiplier();
                    tile.isPermanent = spellStats.hasBuff(AugmentAmplify.INSTANCE);
                    tile.updateBlock();
                    ShapersFocus.tryPropagateBlockSpell(new BlockHitResult(new Vec3(pos.getX() + 0.5, pos.getY() + 0.5, pos.getZ() + 0.5),
                            rayTraceResult.getDirection(), pos, false), world, shooter, spellContext, resolver);
                }
            }
        }
    }

@Override
    public void onResolveBlock(BlockHitResult rayTraceResult, Level world, @NotNull LivingEntity shooter, SpellStats spellStats, SpellContext spellContext, SpellResolver resolver) {
        List<BlockPos> posList = SpellUtil.calcAOEBlocks(shooter, rayTraceResult.getBlockPos(), rayTraceResult, spellStats);
        Player fakePlayer = ANFakePlayer.getPlayer((ServerLevel) world, shooter instanceof Player player ? player.getUUID() : null);
        var sensitiveCount = spellStats.getBuffCount(AugmentSensitive.INSTANCE);
        if (sensitiveCount > 0) {
            fakePlayer.setPos(spellContext.getUnwrappedCaster().position);
            var lookLoc = rayTraceResult.getLocation();
            if (sensitiveCount > 1) {
                fakePlayer.setPos(fakePlayer.position.subtract(fakePlayer.position.subtract(lookLoc).scale(2)));
            }
            fakePlayer.lookAt(EntityAnchorArgument.Anchor.EYES, lookLoc);
        }
        for (BlockPos pos1 : posList) {
            if (!world.isInWorldBounds(pos1))
                continue;
            pos1 = rayTraceResult.isInside() ? pos1 : pos1.relative(rayTraceResult.getDirection());
            boolean notReplaceable = !world.getBlockState(pos1).canBeReplaced();
            if (notReplaceable)
                continue;
            var event = NeoForge.EVENT_BUS.post(new BlockEvent.EntityPlaceEvent(BlockSnapshot.create(world.dimension(), world, pos1), world.getBlockState(pos1), fakePlayer));
            if (event.isCanceled())
                continue;
            place(new BlockHitResult(new Vec3(pos1.getX(), pos1.getY(), pos1.getZ()), rayTraceResult.getDirection(), pos1, false), world, shooter, spellStats, spellContext, resolver, fakePlayer);
        }
    }

@Override
    public void onResolveEntity(EntityHitResult rayTraceResult, Level world, @NotNull LivingEntity shooter, SpellStats spellStats, SpellContext spellContext, SpellResolver resolver) {
        ItemStack dyeStack = getDye(shooter, spellStats, spellContext);
        if (dyeStack.isEmpty()) return;
        DyeItem dye = (DyeItem) dyeStack.getItem();

        if (rayTraceResult.getEntity() instanceof ItemEntity itemEntity) {
            ItemStack item = itemEntity.getItem();

            if (itemEntity.getItem().has(DataComponents.BASE_COLOR)) {
                itemEntity.getItem().set(DataComponents.BASE_COLOR, dye.getDyeColor());
            } else if (item.getItem() instanceof BlockItem blockItem) {
                ItemStack result = getDyedResult((ServerLevel) world, makeContainer(dye, blockItem));
                result.setCount(itemEntity.getItem().getCount());
                if (!result.isEmpty() && result.getItem() instanceof BlockItem) {
                    itemEntity.setItem(result);
                }
            }


        } else if (rayTraceResult.getEntity() instanceof LivingEntity living) {
            if (living instanceof Sheep sheep)
                sheep.setColor(dye.getDyeColor());
            else if (spellStats.isSensitive() || living instanceof ArmorStand) {
                for (ItemStack armorStack : living.getArmorSlots()) {
                    if (!armorStack.isEmpty()) {
                        var dyeComponent = armorStack.get(DataComponents.DYED_COLOR);
                        if (dyeComponent != null) {
                            armorStack.set(DataComponents.DYED_COLOR, new DyedItemColor(dye.getDyeColor().getTextureDiffuseColor(), false));
                        } else if (armorStack.has(DataComponents.BASE_COLOR)) {
                            armorStack.set(DataComponents.BASE_COLOR, dye.getDyeColor());
                        }
                    }
                }
            } else if (living instanceof Mob mob) {
                Player player = ANFakePlayer.getPlayer((ServerLevel) world);
                player.setItemInHand(InteractionHand.MAIN_HAND, dyeStack);
                ((MobAccessor) mob).callMobInteract(player, InteractionHand.MAIN_HAND);
                player.setItemInHand(InteractionHand.MAIN_HAND, ItemStack.EMPTY);
            }
        }
        world.playSound(null, rayTraceResult.getEntity().getX(), rayTraceResult.getEntity().getY(), rayTraceResult.getEntity().getZ(), SoundEvents.EVOKER_PREPARE_WOLOLO, SoundSource.PLAYERS, 1.0f, 1.0f);
    }

@Override
    public void onResolveBlock(BlockHitResult rayTraceResult, Level world, @NotNull LivingEntity shooter, SpellStats spellStats, SpellContext spellContext, SpellResolver resolver) {
        BlockPos blockPos = rayTraceResult.getBlockPos();
        BlockEntity blockEntity = world.getBlockEntity(blockPos);
        if (blockEntity instanceof IWololoable tileToDye) {
            ParticleColor color = spellStats.isRandomized() ? ParticleColor.makeRandomColor(255, 255, 255, shooter.getRandom()) : spellContext.getSpell().particleTimeline().get(ParticleTimelineRegistry.WOLOLO_TIMELINE).getColor();
            tileToDye.setColor(color);
        } else {
            ItemStack dyeStack = getDye(shooter, spellStats, spellContext);
            if (dyeStack.isEmpty()) return;
            DyeItem dye = (DyeItem) dyeStack.getItem();

            if (blockEntity instanceof SignBlockEntity sign) {
                var player = getPlayer(shooter, (ServerLevel) world);
                dye.tryApplyToSign(world, sign, sign.isFacingFrontText(player), player);
            } else {
                // Try block + dye
                BlockState hitBlock = world.getBlockState(blockPos);
                if (hitBlock.isAir()) return;
                ItemStack result = getDyedResult((ServerLevel) world, makeContainer(dye, hitBlock.getBlock()));
                BlockItem blockItem;
                if (result.isEmpty() || !(result.getItem() instanceof BlockItem)) {
                    // Try blocks surrounding the dye
                    result = getDyedResult((ServerLevel) world, makeContainer8(dye, hitBlock.getBlock()));
                    if (result.isEmpty() || !(result.getItem() instanceof BlockItem)) return;
                }
                blockItem = (BlockItem) result.getItem();
                BlockState newState = blockItem.getBlock().withPropertiesOf(hitBlock);
                world.setBlockAndUpdate(blockPos, newState);
                //transfer tag if the block entity type is the same,
                //for shulkers-like so they keep their inventory if dyed in-world
                if (blockEntity != null) {
                    var newBlockEntity = world.getBlockEntity(blockPos);
                    if (newBlockEntity != null && newBlockEntity.getClass() == blockEntity.getClass()) {
                        newBlockEntity.loadWithComponents(blockEntity.saveWithoutMetadata(world.registryAccess()), world.registryAccess());
                    }
                }
            }
        }
    }

private static <T extends LivingEntity> void handleRender(PoseStack poseStack, MultiBufferSource bufferSource, int pPackedLight, T entity, String spellId, boolean offhand) {
        if (spellId.equals(SpellRegistry.LIGHTNING_LANCE_SPELL.get().getSpellId())) {
            poseStack.translate((double) ((float) (offhand ? -1 : 1) / 32.0F) - .125, .5, 0);
            poseStack.mulPose(Axis.YP.rotationDegrees(180.0F));
            LightningLanceRenderer.renderModel(poseStack, bufferSource, entity.tickCount);
        } else if (spellId.equals(SpellRegistry.MAGIC_ARROW_SPELL.get().getSpellId())) {
            poseStack.translate(((float) (offhand ? -1 : 1) / 32.0F), .5, 0);
            poseStack.mulPose(Axis.YP.rotationDegrees(180.0F));
            poseStack.mulPose(Axis.XP.rotationDegrees(90.0F));
            MagicArrowRenderer.renderModel(poseStack, bufferSource);
        } else if (spellId.equals(SpellRegistry.POISON_ARROW_SPELL.get().getSpellId())) {
            poseStack.translate(((float) (offhand ? -1 : 1) / 32.0F), 1, 0);
            poseStack.mulPose(Axis.YP.rotationDegrees(180.0F));
            poseStack.mulPose(Axis.XP.rotationDegrees(90.0F));
            PoisonArrowRenderer.renderModel(poseStack, bufferSource, pPackedLight);
        } else if (spellId.equals(SpellRegistry.FIRE_ARROW_SPELL.get().getSpellId())) {
            poseStack.translate(((float) (offhand ? -1 : 1) / 32.0F), .5, 0);
            poseStack.mulPose(Axis.YP.rotationDegrees(180.0F));
            poseStack.mulPose(Axis.XP.rotationDegrees(90.0F));
            FireArrowRenderer.renderModel(poseStack, bufferSource);
        }
    }

@Override
        public void renderForBone(PoseStack poseStack, AbstractSpellCastingMob animatable, GeoBone bone, RenderType renderType, MultiBufferSource bufferSource, VertexConsumer buffer, float partialTick, int packedLight, int packedOverlay) {
            super.renderForBone(poseStack, animatable, bone, renderType, bufferSource, buffer, partialTick, packedLight, packedOverlay);
            if (bone.getName().equals("right_arm")) {
                poseStack.pushPose();
                var syncedSpellData = ClientMagicData.getSyncedSpellData(animatable);
                var spellId = syncedSpellData.getCastingSpellId();
                var scaleinv = 1 / animatable.getScale();
                poseStack.translate(0,0.5,0);
                poseStack.scale(scaleinv, scaleinv, scaleinv);
                if (!spellId.equals("irons_spellbooks:lightning_lance")) {
                    poseStack.mulPose(Axis.XP.rotationDegrees(180.0F));
                }
//                                poseStack.translate(bone.getPivotX() / 16.0F, bone.getPivotY() / 16.0F, bone.getPivotZ() / 16.0F);
                handleRender(poseStack, bufferSource, packedLight, animatable, spellId, false);
                poseStack.popPose();
            }
        }

@Override
    public void render(@NotNull GuiGraphicsExtractor pGuiGraphics, @NotNull DeltaTracker pDeltaTracker) {
        var mc = Minecraft.getInstance();

        if (!(mc.hitResult instanceof BlockHitResult blockHitResult)) {
            ClientPentacleManager.reset();
            return;
        }

        var pos = blockHitResult.getBlockPos();
        if (mc.level != null && !(mc.level.getBlockEntity(pos) instanceof GoldenSacrificialBowlBlockEntity)) {
            ClientPentacleManager.reset();
            return;
        }

        ClientPentacleManager.rebuild(pos);
        if (JadeIntegration.displayPentacles() && mc.level.getBlockEntity(pos) instanceof GoldenSacrificialBowlBlockEntity bowl) {
            Font font = mc.font;

            int x = pGuiGraphics.guiWidth() / 2;
            int y = pGuiGraphics.guiHeight() / 2 + 9;

            if (bowl.ritualActive) {
                String ritualName = bowl.getCurrentRitualRecipe().value().getRitualDummy().getHoverName().getString();

                int i = Math.max(ritualName.indexOf(":"), ritualName.indexOf("："));
                pGuiGraphics.centeredText(font, Component.translatable("occultism.jade.current_ritual",
                                Component.literal(ritualName.substring(i + 2))), x, y,
                        bowl.getSignal() == 8 ? 0xFF000000 + ChatFormatting.GREEN.getColor() : 0xFF000000 + ChatFormatting.GRAY.getColor());
                y += 9;
                if (!bowl.sacrificeFulfilled()) {
                    pGuiGraphics.centeredText(font, Component.translatable("occultism.jade.no_sacrifice"), x, y, 0xFF000000 + ChatFormatting.RED.getColor());
                    y += 9;
                    pGuiGraphics.centeredText(font, Component.translatable(bowl.currentRitualRecipe.value().getEntityToSacrificeDisplayName()), x, y, -1);
                }
                if (!bowl.itemUseFulfilled()) {
                    pGuiGraphics.centeredText(font, Component.translatable("occultism.jade.no_item_use"), x, y, 0xFF000000 + ChatFormatting.RED.getColor());
                    var itemToUse = bowl.currentRitualRecipe.value().getItemToUse();
                    ItemStack[] stacks = itemToUse != null ? itemToUse.items().map(holder -> new ItemStack(holder.value())).toArray(ItemStack[]::new) : new ItemStack[0];
                    if (stacks.length > 0) {
                        y += 9;
                        int index = stacks.length == 1 ? 0 : (int) (System.currentTimeMillis() / 1000) % stacks.length;
                        pGuiGraphics.centeredText(font, Component.translatable(stacks[index].getItem().getDescriptionId()), x, y, -1);
                    }
                }
            } else {
                if (!ClientPentacleManager.lastPentacles.isEmpty()) {
                    pGuiGraphics.centeredText(font, Component.translatable(TranslationKeys.HUD_PENTACLE_FOUND), x, y,  0xFF000000 + ChatFormatting.GOLD.getColor());
                    y += 9;
                    for (var text : ClientPentacleManager.lastPentacles) {
                        pGuiGraphics.centeredText(font, text, x, y, -1);
                        y += 9;
                    }
                } else {
                    pGuiGraphics.centeredText(font, ClientPentacleManager.noPentacleFound.withStyle(ChatFormatting.YELLOW), x, y, -1);
                }
            }
        }
    }

@SubscribeEvent
    public void onRenderLevelStage(AfterTranslucentParticles event) {
        if (this.selectedBlocks.isEmpty())
            return;

        long time = System.currentTimeMillis();
        this.selectedBlocks.removeIf(info -> time > info.selectionExpireTime || info.selectedBlock == null);
        if (this.selectedBlocks.isEmpty())
            return;

        Camera camera = Minecraft.getInstance().gameRenderer.getMainCamera();
        PoseStack poseStack = event.getPoseStack();
        BufferSource buffer = Minecraft.getInstance().renderBuffers().bufferSource();

        poseStack.pushPose();
        var renderType = OccultismRenderType.overlayLines();
        this.renderSelectedBlocks(poseStack, buffer, renderType, camera);
        buffer.endBatch(renderType);
        poseStack.popPose();
    }

protected void renderSelectedBlocks(PoseStack matrixStack, BufferSource buffer, RenderType renderType, Camera camera) {
        if (!this.selectedBlocks.isEmpty()) {
            VertexConsumer builder = buffer.getBuffer(renderType);
            matrixStack.pushPose();

            Vec3 cameraPosition = camera.position();
            matrixStack.translate(-cameraPosition.x, -cameraPosition.y, -cameraPosition.z);
            var last = matrixStack.last();

            for (Iterator<SelectionInfo> it = this.selectedBlocks.iterator(); it.hasNext(); ) {
                SelectionInfo info = it.next();

                if (info.selectedBlock != null) {
                    float x0 = info.selectedBlock.getX();
                    float y0 = info.selectedBlock.getY();
                    float z0 = info.selectedBlock.getZ();
                    float x1 = x0 + 1;
                    float y1 = y0 + 1;
                    float z1 = z0 + 1;
                    float r = info.color.getRed() / 255.0f;
                    float g = info.color.getGreen() / 255.0f;
                    float b = info.color.getBlue() / 255.0f;
                    float a = info.color.getAlpha() / 255.0f;

                    this.renderFrameEdge(builder, last, x0 - EDGE_OFFSET, y0 - EDGE_OFFSET, z0 - EDGE_OFFSET, x1 + EDGE_OFFSET, y0 - EDGE_OFFSET + EDGE_THICKNESS, z0 - EDGE_OFFSET + EDGE_THICKNESS, r, g, b, a);
                    this.renderFrameEdge(builder, last, x0 - EDGE_OFFSET, y0 - EDGE_OFFSET, z1 + EDGE_OFFSET - EDGE_THICKNESS, x1 + EDGE_OFFSET, y0 - EDGE_OFFSET + EDGE_THICKNESS, z1 + EDGE_OFFSET, r, g, b, a);
                    this.renderFrameEdge(builder, last, x0 - EDGE_OFFSET, y1 + EDGE_OFFSET - EDGE_THICKNESS, z0 - EDGE_OFFSET, x1 + EDGE_OFFSET, y1 + EDGE_OFFSET, z0 - EDGE_OFFSET + EDGE_THICKNESS, r, g, b, a);
                    this.renderFrameEdge(builder, last, x0 - EDGE_OFFSET, y1 + EDGE_OFFSET - EDGE_THICKNESS, z1 + EDGE_OFFSET - EDGE_THICKNESS, x1 + EDGE_OFFSET, y1 + EDGE_OFFSET, z1 + EDGE_OFFSET, r, g, b, a);

                    this.renderFrameEdge(builder, last, x0 - EDGE_OFFSET, y0 - EDGE_OFFSET, z0 - EDGE_OFFSET, x0 - EDGE_OFFSET + EDGE_THICKNESS, y0 - EDGE_OFFSET + EDGE_THICKNESS, z1 + EDGE_OFFSET, r, g, b, a);
                    this.renderFrameEdge(builder, last, x1 + EDGE_OFFSET - EDGE_THICKNESS, y0 - EDGE_OFFSET, z0 - EDGE_OFFSET, x1 + EDGE_OFFSET, y0 - EDGE_OFFSET + EDGE_THICKNESS, z1 + EDGE_OFFSET, r, g, b, a);
                    this.renderFrameEdge(builder, last, x0 - EDGE_OFFSET, y1 + EDGE_OFFSET - EDGE_THICKNESS, z0 - EDGE_OFFSET, x0 - EDGE_OFFSET + EDGE_THICKNESS, y1 + EDGE_OFFSET, z1 + EDGE_OFFSET, r, g, b, a);
                    this.renderFrameEdge(builder, last, x1 + EDGE_OFFSET - EDGE_THICKNESS, y1 + EDGE_OFFSET - EDGE_THICKNESS, z0 - EDGE_OFFSET, x1 + EDGE_OFFSET, y1 + EDGE_OFFSET, z1 + EDGE_OFFSET, r, g, b, a);

                    this.renderFrameEdge(builder, last, x0 - EDGE_OFFSET, y0 - EDGE_OFFSET, z0 - EDGE_OFFSET, x0 - EDGE_OFFSET + EDGE_THICKNESS, y1 + EDGE_OFFSET, z0 - EDGE_OFFSET + EDGE_THICKNESS, r, g, b, a);
                    this.renderFrameEdge(builder, last, x1 + EDGE_OFFSET - EDGE_THICKNESS, y0 - EDGE_OFFSET, z0 - EDGE_OFFSET, x1 + EDGE_OFFSET, y1 + EDGE_OFFSET, z0 - EDGE_OFFSET + EDGE_THICKNESS, r, g, b, a);
                    this.renderFrameEdge(builder, last, x0 - EDGE_OFFSET, y0 - EDGE_OFFSET, z1 + EDGE_OFFSET - EDGE_THICKNESS, x0 - EDGE_OFFSET + EDGE_THICKNESS, y1 + EDGE_OFFSET, z1 + EDGE_OFFSET, r, g, b, a);
                    this.renderFrameEdge(builder, last, x1 + EDGE_OFFSET - EDGE_THICKNESS, y0 - EDGE_OFFSET, z1 + EDGE_OFFSET - EDGE_THICKNESS, x1 + EDGE_OFFSET, y1 + EDGE_OFFSET, z1 + EDGE_OFFSET, r, g, b, a);
                }
            }

            matrixStack.popPose();
        }
    }

@Override
    public void extractRenderState(EntityWormholeBlockEntity blockEntity, EntityWormholeRenderState renderState, float partialTick, Vec3 cameraPos, @Nullable CrumblingOverlay crumbling) {
        BlockEntityRenderer.super.extractRenderState(blockEntity, renderState, partialTick, cameraPos, crumbling);

        ItemStack storedStack = blockEntity.itemStackHandler.getResource(0).toStack(blockEntity.itemStackHandler.getAmountAsInt(0));
        ItemStack portalStack = storedStack.isEmpty() ? ItemStack.EMPTY : OccultismItems.WORMHOLE_PORTAL.toStack();
        ItemStack nuggetStack = OccultismItems.IESNIUM_NUGGET.toStack();
        BlockState state = blockEntity.getBlockState();

        renderState.portalStack = portalStack;
        renderState.nuggetStack = nuggetStack;
        renderState.facing = state.hasProperty(BlockStateProperties.FACING) ? state.getValue(BlockStateProperties.FACING) : Direction.UP;
        renderState.exitRotationY = state.hasProperty(EntityWormholeBlock.EXIT_ROTATION_Y) ? state.getValue(EntityWormholeBlock.EXIT_ROTATION_Y) : 0;
        renderState.exitRotationX = state.hasProperty(EntityWormholeBlock.EXIT_ROTATION_X) ? state.getValue(EntityWormholeBlock.EXIT_ROTATION_X) : 0;
        renderState.angleY = state.getBlock() instanceof EntityWormholeBlock wormholeBlock ? (int) wormholeBlock.getExitRotY(state) : 0;

        ItemStack blockStack = switch (renderState.exitRotationX) {
            case 2 -> new ItemStack(Items.IRON_BLOCK);
            case 3 -> new ItemStack(Items.REDSTONE_BLOCK);
            case 4 -> new ItemStack(Items.DIAMOND_BLOCK);
            case 5 -> new ItemStack(Items.GOLD_BLOCK);
            default -> new ItemStack(Items.EMERALD_BLOCK);
        };
        renderState.blockStack = blockStack;

        int seed = (int) (blockEntity.getBlockPos().asLong() & 0xFFFFFFFFL);
        if (!portalStack.isEmpty()) {
            this.itemModelResolver.updateForTopItem(renderState.portalRenderState, portalStack, ItemDisplayContext.FIXED, blockEntity.getLevel(), null, seed);
        }
        this.itemModelResolver.updateForTopItem(renderState.nuggetRenderState, nuggetStack, ItemDisplayContext.FIXED, blockEntity.getLevel(), null, seed + 1);
        if (renderState.exitRotationX != 0) {
            this.itemModelResolver.updateForTopItem(renderState.blockRenderState, blockStack, ItemDisplayContext.FIXED, blockEntity.getLevel(), null, seed + 2);
        }
    }

@Override
    public void submit(EntityWormholeRenderState renderState, PoseStack poseStack, SubmitNodeCollector submitCollector, CameraRenderState cameraRenderState) {
        if (renderState.portalStack.isEmpty()) {
            return;
        }

        Direction facing = renderState.facing;
        int exitY = renderState.exitRotationY;
        int exitX = renderState.exitRotationX;
        int angleY = renderState.angleY;

        poseStack.pushPose();
        poseStack.pushPose();

        double xOffset = facing.getAxis() == Direction.Axis.X ? (facing.getAxisDirection() == AxisDirection.POSITIVE ? 0.03 : 0.97) : 0.5;
        double yOffset = facing.getAxis() == Direction.Axis.Y ? (facing.getAxisDirection() == AxisDirection.POSITIVE ? 0.03 : 0.97) : 0.5;
        double zOffset = facing.getAxis() == Direction.Axis.Z ? (facing.getAxisDirection() == AxisDirection.POSITIVE ? 0.03 : 0.97) : 0.5;

        poseStack.translate(xOffset, yOffset, zOffset);

        float angle = facing.getAxis() == Direction.Axis.X ? 90 : 0;
        poseStack.mulPose(Axis.YP.rotationDegrees(angle));

        float angle2 = facing.getAxis() == Direction.Axis.Y ? 90 : 0;
        poseStack.mulPose(Axis.XP.rotationDegrees(angle2));

        poseStack.scale(0.1F, 0.1F, 0.1F);

        if (exitY != 0) {
            Vec3 vec3;
            if (facing.getAxis() == Direction.Axis.Y) {
                vec3 = Vec3.directionFromRotation(0, (angleY + 180) * 0.002F);
                poseStack.mulPose(Axis.ZP.rotationDegrees((angleY + 180)));
            } else {
                vec3 = Vec3.directionFromRotation(0, angleY * 0.002F);
                poseStack.mulPose(Axis.ZN.rotationDegrees(angleY));
            }
            float nuggetOffset = facing.getAxis() == Direction.Axis.Y ?
                    facing.getAxisDirection() == AxisDirection.POSITIVE ? -0.3F : 0.3F :
                    facing.getAxisDirection() == AxisDirection.POSITIVE ? 0.3F : -0.3F;
            poseStack.translate(-4 * vec3.x, -4 * vec3.z, nuggetOffset);
            renderState.nuggetRenderState.submit(poseStack, submitCollector, renderState.lightCoords, OverlayTexture.NO_OVERLAY, 0);
            poseStack.translate(4 * vec3.x, 4 * vec3.z, -nuggetOffset);
        }

        if (exitX != 0) {
            poseStack.scale(0.25F, 0.25F, 0.25F);
            float blockOffset = facing.getAxis() == Direction.Axis.Y ?
                    facing.getAxisDirection() == AxisDirection.POSITIVE ? -0.7F : 0.7F :
                    facing.getAxisDirection() == AxisDirection.POSITIVE ? 0.7F : -0.7F;
            poseStack.translate(0, 0, blockOffset);
            renderState.blockRenderState.submit(poseStack, submitCollector, renderState.lightCoords, OverlayTexture.NO_OVERLAY, 0);
            poseStack.mulPose(Axis.ZP.rotationDegrees(45));
            renderState.blockRenderState.submit(poseStack, submitCollector, renderState.lightCoords, OverlayTexture.NO_OVERLAY, 0);
            poseStack.translate(0, 0, -blockOffset);
            poseStack.scale(4F, 4F, 4F);
        }

        long systemTime = System.currentTimeMillis();
        float angle3 = (systemTime / 16) % 360;
        poseStack.mulPose(Axis.ZP.rotationDegrees(angle3));
        poseStack.scale(7F, 7F, 7F);
        renderState.portalRenderState.submit(poseStack, submitCollector, renderState.lightCoords, OverlayTexture.NO_OVERLAY, 0);

        poseStack.popPose();
        poseStack.mulPose(facing.getRotation());
        poseStack.popPose();
    }

@Override
    public void extractRenderState(SacrificialBowlBlockEntity blockEntity, GoldenSacrificialBowlRenderState renderState, float partialTick, Vec3 cameraPos, @Nullable CrumblingOverlay crumbling) {
        BlockEntityRenderer.super.extractRenderState(blockEntity, renderState, partialTick, cameraPos, crumbling);

        ItemStack stack = blockEntity.itemStackHandler.getResource(0).toStack();
        Direction facing = blockEntity.getBlockState().hasProperty(BlockStateProperties.FACING) ?
                blockEntity.getBlockState().getValue(BlockStateProperties.FACING) : Direction.UP;
        long gameTime = blockEntity.getLevel() != null ? blockEntity.getLevel().getGameTime() : 0L;
        long lastChangeTime = blockEntity.lastChangeTime;

        renderState.itemStack = stack;
        renderState.facing = facing;
        renderState.gameTime = gameTime;
        renderState.lastChangeTime = lastChangeTime;

        // Update the pre-initialized ItemStackRenderState with the current item
        if (!stack.isEmpty()) {
            int seed = (int) (blockEntity.getBlockPos().asLong() & 0xFFFFFFFFL);
            this.itemModelResolver.updateForTopItem(renderState.itemStackRenderState, stack, ItemDisplayContext.FIXED, blockEntity.getLevel(), null, seed);
        }

        // GoldenSacrificialBowl-specific data
        if (blockEntity instanceof GoldenSacrificialBowlBlockEntity goldenBowl) {
            renderState.isGoldenBowl = true;

            var recipe = goldenBowl.getCurrentRitualRecipe();
            if (recipe != null) {
                renderState.itemUseFulfilled = goldenBowl.itemUseFulfilled();
                renderState.sacrificeFulfilled = goldenBowl.sacrificeFulfilled();
                renderState.recipeId = recipe.id().toString();
                renderState.requiresItemUse = recipe.value().requiresItemUse();
                renderState.requiresSacrifice = recipe.value().requiresSacrifice();
                renderState.sacrificeEntityType = null;
                renderState.sacrificeEntityRenderState = null;
                renderState.sacrificeEntityScale = 1.0F;

                // Get item to use for cycling animation
                if (renderState.requiresItemUse) {
                    // Cache invalidation: only rebuild if recipe changed
                    boolean recipeChanged = !Objects.equals(renderState.recipeId, renderState.cachedRecipeId);

                    if (recipeChanged) {
                        var items = recipe.value().getItemToUse().items().toList();
                        if (!items.isEmpty()) {
                            renderState.itemToUseStacks = items.stream()
                                    .map(holder -> new ItemStack(holder.value()))
                                    .toArray(ItemStack[]::new);
                            renderState.cachedRecipeId = renderState.recipeId;
                        }
                    }

                    // Compute cycling index in extract (called every frame)
                    if (renderState.itemToUseStacks != null && renderState.itemToUseStacks.length > 0) {
                        renderState.itemToUseIndex = renderState.itemToUseStacks.length == 1 ? 0 : (int) ((System.currentTimeMillis() / 2880) % renderState.itemToUseStacks.length);

                        // Pre-update render state for current index
                        if (!renderState.itemToUseStacks[renderState.itemToUseIndex].isEmpty()) {
                            this.itemModelResolver.updateForTopItem(renderState.itemToUseRenderState, renderState.itemToUseStacks[renderState.itemToUseIndex], ItemDisplayContext.FIXED, blockEntity.getLevel(), null, renderState.itemToUseIndex + 1);
                        }
                    }
                }

                if (renderState.requiresSacrifice && !renderState.sacrificeFulfilled) {
                    var entityType = EntityUtil.getEntityInTag(blockEntity.getLevel(), recipe.value().getEntityToSacrifice());
                    renderState.sacrificeEntityType = entityType;
                    LivingEntity entity = this.getSacrificePreviewEntity(entityType, blockEntity.getLevel());
                    if (entity != null) {
                        entity.setYRot(0);
                        entity.yRotO = 0;
                        entity.setYBodyRot(0);
                        entity.yBodyRotO = 0;
                        entity.setYHeadRot(0);
                        entity.yHeadRotO = 0;

                        BlockPos previewPos = blockEntity.getBlockPos().relative(facing, 2).above(3);
                        entity.setPos(previewPos.getX() + 0.5, previewPos.getY(), previewPos.getZ() + 0.5);

                        float maxSize = Math.max(entity.getBbWidth(), Math.max(entity.getBbHeight(), entity.getBbWidth()));
                        renderState.sacrificeEntityScale = maxSize > 0 ? 0.5F / maxSize : 1.0F;
                        renderState.sacrificeEntityRenderState = Minecraft.getInstance().getEntityRenderDispatcher().extractEntity(entity, partialTick);
                        renderState.sacrificeEntityRenderState.lightCoords = LevelRenderer.getLightCoords(blockEntity.getLevel(), previewPos);
                    }
                }
            } else {
                renderState.itemUseFulfilled = true;
                renderState.sacrificeFulfilled = true;
                renderState.requiresItemUse = false;
                renderState.requiresSacrifice = false;
                renderState.sacrificeEntityType = null;
                renderState.sacrificeEntityRenderState = null;
                renderState.sacrificeEntityScale = 1.0F;
            }
        } else {
            renderState.isGoldenBowl = false;
        }
    }

@Override
    public void submit(GoldenSacrificialBowlRenderState renderState, PoseStack poseStack, SubmitNodeCollector submitCollector, CameraRenderState cameraRenderState) {
        ItemStack stack = renderState.itemStack;
        ItemStackRenderState stackRenderState = renderState.itemStackRenderState;
        Direction facing = renderState.facing;
        long gameTime = renderState.gameTime;
        long lastChangeTime = renderState.lastChangeTime;

        if (stack == null || stack.isEmpty() || facing == null || gameTime == 0) {
            return;
        }

        poseStack.pushPose();
        poseStack.pushPose();

        // Calculate bobbing offset
        double offset = Math.sin((gameTime - lastChangeTime) / 16.0) * 0.5 + 0.5;
        offset = offset / 4.0;

        double fixedOffset = 0.2;

        double xOffset = facing.getAxis() == Direction.Axis.X ? (facing.getAxisDirection() == AxisDirection.POSITIVE ? offset + fixedOffset : -offset - fixedOffset) : 0.0;
        double yOffset = facing.getAxis() == Direction.Axis.Y ? (facing.getAxisDirection() == AxisDirection.POSITIVE ? offset + fixedOffset : -offset - fixedOffset) : 0.0;
        double zOffset = facing.getAxis() == Direction.Axis.Z ? (facing.getAxisDirection() == AxisDirection.POSITIVE ? offset + fixedOffset : -offset - fixedOffset) : 0.0;

        poseStack.translate(0.5 + xOffset, 0.5 + yOffset, 0.5 + zOffset);

        // Rotate item around Y axis using system time
        long systemTime = System.currentTimeMillis();
        float angle = (systemTime / 16) % 360;
        poseStack.mulPose(Axis.YP.rotationDegrees(angle));

        // Scale
        float scale = getScale(stack) * 0.5f;
        poseStack.scale(scale, scale, scale);

        // Render the main item using the pre-created ItemStackRenderState
        stackRenderState.submit(poseStack, submitCollector, renderState.lightCoords, OverlayTexture.NO_OVERLAY, 0);

        // Render item-to-use indicator for GoldenSacrificialBowl
        if (renderState.isGoldenBowl && !stack.isEmpty() && renderState.itemToUseStacks != null && renderState.itemToUseStacks.length > 0) {
            poseStack.pushPose();
            poseStack.translate(0, 3.2 - (0.5 + yOffset) / scale, 0);
            if (!renderState.itemUseFulfilled && renderState.requiresItemUse) {
                int index = renderState.itemToUseIndex;
                ItemStack itemStack = renderState.itemToUseStacks[index];
                if (!itemStack.isEmpty()) {
                    float scaleUse = getScale(itemStack) * 0.5F;
                    poseStack.scale(scaleUse, scaleUse, scaleUse);
                    renderState.itemToUseRenderState.submit(poseStack, submitCollector, renderState.lightCoords, OverlayTexture.NO_OVERLAY, 0);
                }
            }
            poseStack.popPose();
        }

        if (renderState.isGoldenBowl && renderState.requiresSacrifice && !renderState.sacrificeFulfilled && renderState.sacrificeEntityRenderState != null) {
            poseStack.pushPose();
            poseStack.translate(0, 3.2 - (0.5 + yOffset) / scale, 0);
            poseStack.scale(renderState.sacrificeEntityScale, renderState.sacrificeEntityScale, renderState.sacrificeEntityScale);
            EntityRenderDispatcher dispatcher = Minecraft.getInstance().getEntityRenderDispatcher();
            dispatcher.submit(renderState.sacrificeEntityRenderState, cameraRenderState, 0, 0, 0, poseStack, submitCollector);
            poseStack.popPose();
        }

        poseStack.popPose();

        poseStack.mulPose(facing.getRotation());

        poseStack.popPose();
    }

