@Override
        public void submit(PoseStack poseStack, SubmitNodeCollector submitNodeCollector, int lightCoords, MummyFamiliarRenderState state, float yRot, float xRot) {
            if (state.fightPose == -1)
                return;

            Float alpha = state.getRenderData(MummyFamiliarRenderer.CAPOW_ALPHA);
            Vec3 capowPos = state.getRenderData(MummyFamiliarRenderer.CAPOW_POSITION);
            if (alpha == null || capowPos == null)
                return;

            poseStack.pushPose();
            float scale = 0.5f;
            poseStack.scale(scale, scale, scale);
            poseStack.translate(capowPos.x, -0.4 + capowPos.y, capowPos.z);

            // Render kapow sprite using bufferSource workaround for alpha-blended model
            BufferSource bufferSource = Minecraft.getInstance().renderBuffers().bufferSource();
            VertexConsumer kapowBuffer = bufferSource.getBuffer(model.renderType(KAPOW_TEXTURE));
            model.kapow.render(poseStack, kapowBuffer, lightCoords, OverlayTexture.NO_OVERLAY,
                    ((int) (alpha * 255) << 24) | 0x00FFFFFF);
            bufferSource.endBatch(model.renderType(KAPOW_TEXTURE));

            poseStack.pushPose();
            poseStack.scale(0.07f, 0.07f, 0.07f);
            poseStack.translate(0, -2.5, 0);
            poseStack.mulPose(new Quaternionf().rotateXYZ(0, 0, 20 * ((float) Math.PI / 180F)));
            Font font = this.renderer.getFont();
            int textColor = 0xff0000 | ((int) (alpha * 255) << 24);

            poseStack.pushPose();
            poseStack.translate(0, 0, -0.01);
            var matrix = poseStack.last().pose();
            font.drawInBatch(KAPOW_TEXT, -font.width(KAPOW_TEXT) / 2f, 0, textColor, true,
                    matrix, bufferSource, DisplayMode.NORMAL, 0, lightCoords);
            poseStack.popPose();

            poseStack.pushPose();
            poseStack.translate(0, 0, 0.01);
            poseStack.mulPose(new Quaternionf().rotateXYZ(0, 180 * ((float) Math.PI / 180F), 0));
            matrix = poseStack.last().pose();
            font.drawInBatch(KAPOW_TEXT, -font.width(KAPOW_TEXT) / 2f, 0, textColor, true,
                    matrix, bufferSource, DisplayMode.NORMAL, 0, lightCoords);
            poseStack.popPose();

            bufferSource.endBatch();

            poseStack.popPose();
            poseStack.popPose();
        }

@Override
    public boolean render(BlockOutlineRenderState state, SubmitNodeCollector nodeCollector, PoseStack poseStack, LevelRenderState levelRenderState) {
        poseStack.pushPose();
        Vec3 viewPosition = levelRenderState.cameraRenderState.pos;
        poseStack.translate(pos.getX() - viewPosition.x, pos.getY() - viewPosition.y, pos.getZ() - viewPosition.z);

        //if top/bottom face, try to rotate so the bottom is as close to screen bottom as we can get
        if (face == Direction.UP || face == Direction.DOWN) {
            Direction cameraFacing = Direction.fromYRot(levelRenderState.cameraRenderState.yRot);
            if (cameraFacing != Direction.NORTH) {
                poseStack.rotateAround(V_ROT[cameraFacing.ordinal() - V_ROT_OFFSET], 0.5F, 1, 0.5F);
            }
        }

        if (isDiversion) {
            poseStack.scale(0.5F, 0.5F, 0.5F);
            poseStack.translate(0.5, 0.5, 0.5);
        }
        RenderPhaseKey<SubmitNode> phase = state.isTranslucent() ? RenderPhaseKeys.AFTER_TERRAIN : RenderPhaseKeys.SHAPE_OUTLINES;
        nodeCollector.submitSpecial(phase, new CustomFeatureRenderer.Submit(poseStack.last().copy(), RenderTypes.eyes(sprite.atlasLocation()), this));
        poseStack.popPose();
        return !isDiversion;
    }

@Override
    public void render(Pose pose, VertexConsumer buffer) {
        Vector3f normal = pose.transformNormal(face.getUnitVec3f(), new Vector3f());
        Matrix4f matrix = pose.pose();
        //face draw code donated by XFactHD
        FaceInfo faceInfo = FaceInfo.fromFacing(face);
        for (int vertex = 0; vertex < 4; vertex++) {
            FaceInfo.VertexInfo vertInfo = faceInfo.getVertexInfo(vertex);
            float x = vertInfo.xFace().select(0, 0, 0, 1, 1, 1) + face.getStepX() * 0.01F;
            float y = vertInfo.yFace().select(0, 0, 0, 1, 1, 1) + face.getStepY() * 0.01F;
            float z = vertInfo.zFace().select(0, 0, 0, 1, 1, 1) + face.getStepZ() * 0.01F;
            float u = vertex < 2 ? 0 : 1;
            float v = vertex == 0 || vertex == 3 ? 0 : 1;
            buffer.addVertex(matrix, x, y, z)
                  .setColor(transmissionColor)
                  .setUv(sprite.getU(u), sprite.getV(v))
                  .setOverlay(OverlayTexture.NO_OVERLAY)
                  .setLight(LightCoordsUtil.FULL_BRIGHT)
                  .setNormal(normal.x, normal.y, normal.z);
        }
    }

public void renderHUD(Minecraft minecraft, Player player, GuiGraphicsExtractor guiGraphics, Font font, DeltaTracker delta, int screenWidth, int screenHeight,
          int maxTextHeight, boolean reverseHud) {
        update(minecraft.level, player);
        if (MekanismConfig.client.hudOpacity.get() < 0.05F) {
            return;
        }
        Matrix3x2fStack matrix = guiGraphics.pose();
        matrix.pushMatrix();
        float yawJitter = -absSqrt(player.yHeadRot - prevRotationYaw);
        float pitchJitter = -absSqrt(player.getXRot() - prevRotationPitch);
        matrix.translate(yawJitter, pitchJitter);
        int audibleSubtitlesWidth = MekanismConfig.client.hudAvoidSoundSubtitleOverlay.get() ? getAudibleSubtitlesWidth(minecraft, font) : 0;
        if (MekanismConfig.client.hudCompassEnabled.get()) {
            matrix.pushMatrix();
            //Reversed hud causes the compass to render on the right side of the screen
            int posX = reverseHud ? screenWidth - 125 - audibleSubtitlesWidth : 25;
            //Pin the compass above the bottom of the screen and also above the text hud that may render below it
            int posY = Math.min(screenHeight - 20, maxTextHeight) - 80;
            matrix.translate(posX - 125, posY - 125);
            guiGraphics.submitPictureInPictureRenderState(new CompassPiP.State(new Matrix3x2f(matrix), guiGraphics.peekScissorStack(),
                  MekanismLang.GENERIC_BLOCK_POS.translate(player.getBlockX(), player.getBlockY(), player.getBlockZ()),
                  Mth.PI - Mth.DEG_TO_RAD * player.getViewYRot(delta.getGameTimeDeltaPartialTick(true))
            ));
            matrix.popMatrix();
        }

        renderMekaSuitEnergyIcons(player, font, guiGraphics);
        renderMekaSuitModuleIcons(player, font, guiGraphics, screenWidth, screenHeight, reverseHud, audibleSubtitlesWidth);

        matrix.popMatrix();
    }

private void renderMekaSuitEnergyIcons(Player player, Font font, GuiGraphicsExtractor guiGraphics) {
        Matrix3x2fStack pose = guiGraphics.pose();
        pose.pushMatrix();
        pose.translate(10, 10);
        int posX = 0;
        Predicate<TypedInstance<Item>> showArmorPercent = item -> item.is(MekanismAPITags.Items.MODULE_CONTAINERS_ARMOR);
        for (int i = 0; i < ARMOR_SLOTS.length; i++) {
            posX += renderEnergyIcon(player, font, guiGraphics, posX, ARMOR_ICONS[i], ARMOR_SLOTS[i], showArmorPercent);
        }
        Predicate<TypedInstance<Item>> showToolPercent = item -> item.is(MekanismAPITags.Items.MODULE_CONTAINERS_HELD);
        for (EquipmentSlot hand : EquipmentSlotGroup.HAND) {
            posX += renderEnergyIcon(player, font, guiGraphics, posX, TOOL_ICON, hand, showToolPercent);
        }
        pose.popMatrix();
    }

@Override
    public void render(GuiGraphicsExtractor graphics, DeltaTracker delta) {
        Minecraft minecraft = Minecraft.getInstance();
        Player player = minecraft.player;
        if (player != null && !player.isSpectator() && !minecraft.gui.hud.isHidden() && MekanismConfig.client.enableHUD.get()) {
            int count = 0;
            List<List<Component>> renderStrings = new ArrayList<>();
            for (EquipmentSlot slotType : EQUIPMENT_ORDER) {
                ItemStack stack = player.getItemBySlot(slotType);
                IItemHUDProvider hudProvider = getHudProvider(stack);
                if (hudProvider != null) {
                    //noinspection RedundantTypeArguments - Causes nullability warnings
                    count += this.<EquipmentSlot>makeComponent(hudProvider, player, stack, slotType, renderStrings, IItemHUDProvider::addHUDStrings);
                }
            }
            ResourceHandler<ItemResource> curiosInventory = Mekanism.hooks.getCuriosInventory(player);
            if (curiosInventory != null) {
                for (int i = 0, slots = curiosInventory.size(); i < slots; i++) {
                    ItemResource stack = curiosInventory.getResource(i);
                    IItemHUDProvider hudProvider = getHudProvider(stack);
                    if (hudProvider != null) {
                        count += makeComponent(hudProvider, player, stack.toStack(), null, renderStrings,
                              (provider, l, plyr, s, _) -> provider.addCurioHUDStrings(l, plyr, s));
                    }
                }
            }
            Font font = minecraft.font;

            boolean reverseHud = MekanismConfig.client.reverseHUD.get();
            int maxTextHeight = graphics.guiHeight();
            if (count > 0) {
                float hudScale = MekanismConfig.client.hudScale.get();
                int xScale = (int) (graphics.guiWidth() / hudScale);
                int yScale = (int) (graphics.guiHeight() / hudScale);
                int start = (renderStrings.size() * 2) + (count * 9);
                int y = yScale - start;
                maxTextHeight = (int) (y * hudScale);
                Matrix3x2fStack pose = graphics.pose();
                pose.pushMatrix();
                pose.scale(hudScale, hudScale);

                int backgroundColor = minecraft.options.getBackgroundColor(0.0F);
                if (backgroundColor != 0) {
                    //If we need to render the background behind it based on accessibility options
                    // calculate how big an area we need and draw it
                    int maxTextWidth = 0;
                    for (List<Component> group : renderStrings) {
                        for (Component text : group) {
                            int textWidth = font.width(text);
                            if (textWidth > maxTextWidth) {
                                maxTextWidth = textWidth;
                            }
                        }
                    }
                    int x = reverseHud ? xScale - maxTextWidth - 2 : 2;
                    GuiUtils.drawBackdrop(graphics, Minecraft.getInstance(), x, y, maxTextWidth, maxTextHeight, 1);
                }

                for (List<Component> group : renderStrings) {
                    for (Component text : group) {
                        int textWidth = font.width(text);
                        //Align text to right if hud is reversed, otherwise align to the left
                        //Note: that we always offset by 2 pixels from the edge of the screen regardless of how it is aligned
                        int x = reverseHud ? xScale - textWidth - 2 : 2;
                        graphics.text(font, text, x, y, 0xFFC8C8C8);
                        y += 9;
                    }
                    y += 2;
                }
                pose.popMatrix();
            }

            if (player.getItemBySlot(EquipmentSlot.HEAD).is(MekanismAPITags.Items.MEKASUIT_HUD_RENDERER)) {
                hudRenderer.renderHUD(minecraft, player, graphics, font, delta, graphics.guiWidth(), graphics.guiHeight(), maxTextHeight, reverseHud);
            }
        }
    }

protected static <RESOURCE extends Resource> boolean renderBars(GuiGraphicsExtractor guiGraphics, int xOffset, int yOffset,
          ResourceHandler<RESOURCE> handler, int index, ToIntFunction<RESOURCE> color) {
        if (index != -1) {
            RESOURCE resource = handler.getResource(index);
            renderBar(guiGraphics, xOffset, yOffset, handler.getAmountAsLong(index), handler.getCapacityAsLong(index, resource), color.applyAsInt(resource));
        } else if (handler.size() == 0) {
            renderBar(guiGraphics, xOffset, yOffset, 0, 1, CommonColors.WHITE);
        } else {
            return false;
        }
        return true;
    }

@Override
    public void submit(@Nullable CubeState state, PoseStack poseStack, SubmitNodeCollector nodeCollector, int lightCoords, int overlayCoords, boolean hasFoil, int outlineColor) {
        if (state == null) {
            return;
        }
        if (hasFoil) {
            state.blockRenderState.submit(poseStack, nodeCollector, lightCoords, overlayCoords, outlineColor, true);
        } else {
            //Use vanilla's normal rendering submit chain so that if something breaks when updating, we only have things break when using glint
            state.blockRenderState.submit(poseStack, nodeCollector, lightCoords, overlayCoords, outlineColor);
        }
        if (state.coreTint != null) {
            float scaledTicks = 4 * state.ticks();
            poseStack.pushPose();
            poseStack.translate(0.5, 0.5, 0.5);
            poseStack.scale(0.4F, 0.4F, 0.4F);
            poseStack.translate(0, Math.sin(Math.toRadians(3 * state.ticks())) / 7, 0);
            poseStack.rotateDegrees(Axis.YP, scaledTicks);
            poseStack.rotateDegrees(RenderEnergyCube.coreVec, 36F + scaledTicks);
            nodeCollector.submitBlockModel(poseStack, Sheets.translucentBlockItemSheet(), MekanismModelCache.INSTANCE.ENERGY_CORE.getBakedModel(),
              new int[]{state.coreTint}, LightCoordsUtil.FULL_BRIGHT, OverlayTexture.NO_OVERLAY, EntityRenderState.NO_OUTLINE);
            poseStack.popPose();
        }
    }

@Nullable
    @Override
    public CubeState extractArgument(ItemStack stack) {
        EnergyCubeTier tier = stack.get(MekanismDataComponents.ENERGY_CUBE_TIER);
        if (tier == null) {
            return null;
        }
        CubeSideState[] sideStates = new CubeSideState[RelativeSide.VALUES.size()];
        AttachedSideConfig fallback = tier.isCreative() ? ItemBlockEnergyCube.ALL_OUTPUT : ItemBlockEnergyCube.SIDE_CONFIG;
        IPersistentConfigInfo sideConfig = AttachedSideConfig.getStoredConfigInfo(stack, fallback, TransmissionType.ENERGY);
        for (RelativeSide side : RelativeSide.VALUES) {
            DataType dataType = sideConfig.getDataType(side);
            CubeSideState state = CubeSideState.INACTIVE;
            if (dataType != DataType.NONE) {
                state = dataType.canOutput() ? CubeSideState.ACTIVE_LIT : CubeSideState.ACTIVE_UNLIT;
            }
            sideStates[side.ordinal()] = state;
        }

        FoilableBlockModelRenderState modelRenderState = new FoilableBlockModelRenderState();
        BlockItem itemBlock = (BlockItem) stack.getItem();
        BlockState blockState = itemBlock.getBlock().defaultBlockState();
        BlockStateModel blockStateModel = models().getBlockStateModelSet().get(blockState);
        if (blockStateModel instanceof EnergyCubeModel energyCubeModel) {
            List<BlockStateModelPart> partList = modelRenderState.setupModel(ModelUtil.IDENTITY, (energyCubeModel.materialFlags() & BakedQuad.FLAG_TRANSLUCENT) != 0);
            energyCubeModel.collectParts(partList, sideStates);
            modelRenderState.tintLayers().add(tier.getBaseTier().getPackedColor());
        } else {
            //weird, but ok, try to render something
            mc().getBlockModelResolver().update(modelRenderState, blockState, ModelUtil.BLOCK_DISPLAY_NO_CONTEXT);
        }

        float ticks = mc().gameRenderer.gameRenderState().levelRenderState.gameTime + MekanismRenderer.getPartialTick();
        float energyRatio = (float) ContainerType.ENERGY.getRatio(stack);

        return new CubeState(
              energyRatio > 0 ? tier.getBaseTier().getPackedColor(ARGB.as8BitChannel(energyRatio)) : null,
              ticks,
              modelRenderState
        );
    }

@Nullable
    @Override
    public TankRenderState extractArgument(ItemStack stack) {
        ResourceHandler<FluidResource> handler = Capabilities.FLUID.getCapability(ItemAccessUtils.sideEffectFreeAccess(stack));
        int fluidLight = 0;
        int fluidColor = 0;
        float contentsMaxY = 0;
        TexturePicker fluidTexture = null;
        if (handler != null) {
            FluidResource fluid = handler.getResource(0);
            if (!fluid.isEmpty()) {
                float fluidScale = (float) handler.getAmountAsLong(0) / handler.getCapacityAsLong(0, fluid);
                contentsMaxY = fluidScale > 0 ? RenderFluidTank.contentsMaxY(fluidScale, MekanismUtils.lighterThanAirGas(fluid)) : 0;
                fluidLight = fluid.getFluidType().getLightLevel();
                fluidColor = MekanismRenderer.getColorARGB(fluid, fluidScale);
                fluidTexture = MekanismRenderer.getSinglePicker(MekanismRenderer.getFluidTexture(fluid, MekanismRenderer.FluidTextureType.STILL));
            }
        }
        //TODO - 26.3: do this with the block model from model manager (copy Energy cube item)
        BlockState blockState = ((BlockItem) stack.getItem()).getBlock().defaultBlockState();
        FoilableBlockModelRenderState modelRenderState = new FoilableBlockModelRenderState();
        mc().getBlockModelResolver().update(modelRenderState, blockState, ModelUtil.BLOCK_DISPLAY_NO_CONTEXT);
        //blockModel.tintLayers().add(tierTint);
        return new TankRenderState(fluidLight, fluidColor, contentsMaxY, fluidTexture, modelRenderState);
    }
